window.__TOPIC_JS=window.__TOPIC_JS||{};window.__TOPIC_JS["漢文・古い漢字"]={
"_note": "09. 漢文・古い漢字 — mỗi mục một dòng. LEVEL: p1 → p3 = 3 nhóm của chuyên đề (giữ nguyên nhãn gốc). THỨ TỰ: các nhóm xếp p1, p2, p3, không trộn lẫn; trong mỗi nhóm giữ nguyên thứ tự gốc. ĐỊNH DẠNG MỖI TỪ: word, reading, meaning, hanviet, note, chars, poem, example, example_reading, example_meaning, examples, level. TRƯỜNG antonym (tuỳ chọn): từ trái nghĩa, dạng \"từ（cách đọc）: nghĩa\", nhiều từ cách nhau bằng \" / \". TRƯỜNG antonym_hanviet (tuỳ chọn, đi kèm antonym): âm Hán Việt của từng từ trái nghĩa, viết thường như trường hanviet, cùng thứ tự và cách nhau bằng \" / \" (từ chỉ có kana, không có chữ Hán, để trống). SỐ LƯỢNG: p1 60, p2 84, p3 56; tổng 200 mục.",
"id": "9. 漢文・古い漢字",
"title": "漢文・古い漢字",
"icon": "🖌️",
"category": "ref",
"kind": "proverb",
"vocab": [
{"word":"四面楚歌","reading":"しめんそか","meaning":"bốn bề thọ địch, bị cô lập hoàn toàn, không ai giúp đỡ.\n(Dùng khi rơi vào tình thế bị mọi phía chỉ trích hoặc vây ép.)","hanviet":"tứ diện sở ca","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ: năm 202 TCN, Hạng Vũ bị quân Hán vây ở Cai Hạ, đêm nghe quanh mình vang lên toàn bài ca nước Sở, hoảng sợ nói «Hán đã chiếm hết đất Sở rồi sao? Sao người Sở nhiều thế!». 💡 Thú vị: Thực ra đó là quân Hán hát để làm nhụt chí quân Sở (Sử ký không nói ai bày mưu, dân gian thường gán cho Trương Lương). Sau đêm đó Hạng Vũ làm bài «Cai Hạ ca», từ biệt Ngu Cơ, rồi tự vẫn bên Ô Giang.","chars":[{"c":"四","h":"tứ"},{"c":"面","h":"diện"},{"c":"楚","h":"sở"},{"c":"歌","h":"ca"}],"poem":{"han":"垓下夜深聞楚調／重圍四合月無光","hv":"Cai hạ dạ thâm văn Sở điệu / Trùng vi tứ hợp nguyệt vô quang","vi":"Đêm sâu ở Cai Hạ nghe điệu Sở, vòng vây bốn phía, trăng chẳng còn sáng."},"example":"反対派に囲まれ、会議で四面楚歌の状態になった。","example_reading":"はんたいはにかこまれ、かいぎでしめんそかのじょうたいになった。","example_meaning":"Bị phe phản đối vây quanh, tôi rơi vào cảnh bốn bề thọ địch trong cuộc họp.","examples":[{"example":"反対派に囲まれ、会議で四面楚歌の状態になった。","example_reading":"はんたいはにかこまれ、かいぎでしめんそかのじょうたいになった。","example_meaning":"Bị phe phản đối vây quanh, tôi rơi vào cảnh bốn bề thọ địch trong cuộc họp."},{"example":"不祥事が発覚して、社長は四面楚歌に陥った。","example_reading":"ふしょうじがはっかくして、しゃちょうはしめんそかにおちいった。","example_meaning":"Bê bối bị phanh phui, giám đốc rơi vào tình cảnh cô lập hoàn toàn."}],"level":"p1"},
{"word":"朝三暮四","reading":"ちょうさんぼし","meaning":"sáng ba chiều bốn; bị lừa bằng mánh nhỏ, hoặc chỉ mải lợi trước mắt mà không thấy thực chất như nhau.\n(Cũng chỉ người hay thay đổi, lời nói trước sau bất nhất.)","hanviet":"triêu tam mộ tứ","note":"📜 Lịch sử: Trang Tử - Tề vật luận (Liệt Tử cũng có): ông già nuôi khỉ (狙公) giảm hạt dẻ, nói «sáng ba chiều bốn» thì bầy khỉ giận; đổi thành «sáng bốn chiều ba» thì khỉ mừng rỡ. 💡 Thú vị: Trang Tử vốn dùng chuyện này để nói: đừng cố chấp vào danh nghĩa khi thực chất không đổi (tổng vẫn là 7 hạt). Về sau tiếng Trung dùng với nghĩa 'hay thay đổi', còn tiếng Nhật thiên về 'bị lừa bằng cái lợi nhỏ trước mắt'.","chars":[{"c":"朝","h":"triêu"},{"c":"三","h":"tam"},{"c":"暮","h":"mộ"},{"c":"四","h":"tứ"}],"poem":{"han":"朝三暮四狙公語／名異實同莫苦嗔","hv":"Triêu tam mộ tứ thư công ngữ / Danh dị thực đồng mạc khổ sân","vi":"Lời ông nuôi khỉ: sáng ba chiều bốn; tên khác mà thực giống nhau, chớ giận làm chi."},"example":"目先の得に飛びつくのは、朝三暮四と同じだ。","example_reading":"めさきのとくにとびつくのは、ちょうさんぼしとおなじだ。","example_meaning":"Lao vào lợi nhỏ trước mắt thì chẳng khác gì chuyện sáng ba chiều bốn.","examples":[{"example":"目先の得に飛びつくのは、朝三暮四と同じだ。","example_reading":"めさきのとくにとびつくのは、ちょうさんぼしとおなじだ。","example_meaning":"Lao vào lợi nhỏ trước mắt thì chẳng khác gì chuyện sáng ba chiều bốn."},{"example":"上司の方針が毎回変わって、朝三暮四で部下が困っている。","example_reading":"じょうしのほうしんがまいかいかわって、ちょうさんぼしでぶかがこまっている。","example_meaning":"Chủ trương của sếp lần nào cũng đổi, sớm nắng chiều mưa nên cấp dưới rất khó xử."}],"level":"p1"},
{"word":"酒池肉林","reading":"しゅちにくりん","meaning":"tiệc tùng xa hoa tột độ; rượu thành ao, thịt thành rừng.\n(Chỉ yến tiệc phô trương, phóng túng; thường mang sắc thái chê trách.)","hanviet":"tửu trì nhục lâm","note":"📜 Lịch sử: Sử ký - Ân bản kỷ: vua Trụ nhà Ân cho đào hồ đổ đầy rượu, treo thịt thành rừng, để nam nữ đuổi nhau giữa đó và uống suốt đêm không dứt (長夜の飲). 💡 Thú vị: Trụ Vương là bạo quân mất nước, nên từ này luôn gắn với điềm 'xa hoa dẫn đến diệt vong'. Ngày nay người Nhật còn dùng đùa để tả tiệc buffet ê hề.","chars":[{"c":"酒","h":"tửu"},{"c":"池","h":"trì"},{"c":"肉","h":"nhục"},{"c":"林","h":"lâm"}],"poem":{"han":"酒作長池肉作林／朝歌夜夜醉成荒","hv":"Tửu tác trường trì nhục tác lâm / Triêu Ca dạ dạ túy thành hoang","vi":"Rượu thành ao dài, thịt thành rừng; đêm đêm say sưa ở Triêu Ca rồi thành hoang phế."},"example":"豪華な宴会は、まるで酒池肉林のようだった。","example_reading":"ごうかなえんかいは、まるでしゅちにくりんのようだった。","example_meaning":"Bữa tiệc xa hoa cứ như cảnh rượu thịt ê hề.","examples":[{"example":"豪華な宴会は、まるで酒池肉林のようだった。","example_reading":"ごうかなえんかいは、まるでしゅちにくりんのようだった。","example_meaning":"Bữa tiệc xa hoa cứ như cảnh rượu thịt ê hề."},{"example":"バブル期の接待は、酒池肉林と呼ばれるほど派手だった。","example_reading":"バブルきのせったいは、しゅちにくりんとよばれるほどはでだった。","example_meaning":"Việc chiêu đãi thời bong bóng kinh tế phô trương đến mức bị gọi là rượu thịt ê hề."}],"level":"p1"},
{"word":"国士無双","reading":"こくしむそう","meaning":"nhân tài số một thiên hạ, không ai sánh bằng.\n(Lời khen dành cho người xuất chúng, hiếm có trong cả nước.)","hanviet":"quốc sĩ vô song","note":"📜 Lịch sử: Sử ký - Hoài Âm hầu liệt truyện: Hàn Tín bỏ Lưu Bang ra đi, Tiêu Hà đuổi theo giữa đêm. Ông nói với Lưu Bang rằng Hàn Tín là «quốc sĩ vô song»: nếu muốn tranh thiên hạ thì không thể thiếu người này. 💡 Thú vị: Trong mạt chược Nhật, 国士無双 (Thirteen Orphans) là yaku cực hiếm: phải gom đủ 13 loại quân đầu mút và quân chữ, cộng thêm một quân trùng. Tên gọi hợp với độ hiếm của nó.","chars":[{"c":"国","h":"quốc"},{"c":"士","h":"sĩ"},{"c":"無","h":"vô"},{"c":"双","h":"song"}],"poem":{"han":"蕭何月下追韓信／國士無雙名自傳","hv":"Tiêu Hà nguyệt hạ truy Hàn Tín / Quốc sĩ vô song danh tự truyền","vi":"Tiêu Hà dưới trăng đuổi theo Hàn Tín, danh «quốc sĩ vô song» tự nhiên truyền mãi."},"example":"彼は将棋界で国士無双と呼ばれている。","example_reading":"かれはしょうぎかいでこくしむそうとよばれている。","example_meaning":"Anh ấy được gọi là nhân tài số một của làng cờ shogi.","examples":[{"example":"彼は将棋界で国士無双と呼ばれている。","example_reading":"かれはしょうぎかいでこくしむそうとよばれている。","example_meaning":"Anh ấy được gọi là nhân tài số một của làng cờ shogi."},{"example":"国士無双の人材を得て、会社は大きく成長した。","example_reading":"こくしむそうのじんざいをえて、かいしゃはおおきくせいちょうした。","example_meaning":"Có được nhân tài hiếm có, công ty đã phát triển mạnh."}],"level":"p1"},
{"word":"勧善懲悪","reading":"かんぜんちょうあく","meaning":"khuyến khích điều thiện, trừng trị điều ác.\n(Chỉ mô-típ truyện, kịch: người tốt được đền, kẻ xấu bị phạt.)","hanviet":"khuyến thiện trừng ác","note":"📜 Lịch sử: Xuân Thu Tả truyện - Thành công năm 14: khi bàn về bút pháp của sách Xuân Thu, Tả truyện nói rằng mục đích là «trừng ác mà khuyến thiện». 💡 Thú vị: Ở Nhật, đây là 'công thức vàng' của văn học Edo như «Nam Tổng Lý Kiến bát khuyển truyện» của Takizawa Bakin, và của phim cổ trang kiểu Mito Kōmon: cuối phim luôn có cảnh giơ ấn lệnh, kẻ ác bị trị.","chars":[{"c":"勧","h":"khuyến"},{"c":"善","h":"thiện"},{"c":"懲","h":"trừng"},{"c":"悪","h":"ác"}],"poem":{"han":"勸善懲邪天道在／春秋筆下有權衡","hv":"Khuyến thiện trừng tà thiên đạo tại / Xuân Thu bút hạ hữu quyền hành","vi":"Khuyên điều thiện, trị điều tà, đạo trời còn đó; dưới ngọn bút Xuân Thu có cán cân phải trái."},"example":"時代劇は勧善懲悪の物語が多い。","example_reading":"じだいげきはかんぜんちょうあくのものがたりがおおい。","example_meaning":"Phim cổ trang có nhiều câu chuyện thiện thắng ác bại.","examples":[{"example":"時代劇は勧善懲悪の物語が多い。","example_reading":"じだいげきはかんぜんちょうあくのものがたりがおおい。","example_meaning":"Phim cổ trang có nhiều câu chuyện thiện thắng ác bại."},{"example":"子どもの絵本は、勧善懲悪の話がわかりやすい。","example_reading":"こどものえほんは、かんぜんちょうあくのはなしがわかりやすい。","example_meaning":"Với sách tranh trẻ em, truyện thiện thưởng ác phạt dễ hiểu."}],"level":"p1"},
{"word":"九死一生","reading":"きゅうしいっしょう","meaning":"chín phần chết, một phần sống; thoát chết trong gang tấc.\n(Dùng khi vượt qua hiểm nguy cực lớn mà vẫn còn sống.)","hanviet":"cửu tử nhất sinh","note":"📜 Lịch sử: Gốc ở Khuất Nguyên - Ly Tao: «dẫu chín lần chết ta cũng chưa hối». Ở đây 九 là số nhiều chứ không phải con số cụ thể, ý nói 'dù chết bao lần'. 💡 Thú vị: Ban đầu 九死 nói về 'quyết chí dù chết', về sau ghép với 一生 thành nghĩa 'thoát chết'. Tiếng Nhật còn có mẫu 九死に一生を得る (nhặt được một phần sống trong chín phần chết).","chars":[{"c":"九","h":"cửu"},{"c":"死","h":"tử"},{"c":"一","h":"nhất"},{"c":"生","h":"sinh"}],"poem":{"han":"九死未悔離騷客／一線生機渡險川","hv":"Cửu tử vị hối Ly Tao khách / Nhất tuyến sinh cơ độ hiểm xuyên","vi":"Khách Ly Tao chín lần chết chưa hối; một tia sống sót vượt qua sông hiểm."},"example":"山で遭難したが、九死一生を得て帰ってきた。","example_reading":"やまでそうなんしたが、きゅうしいっしょうをえてかえってきた。","example_meaning":"Gặp nạn trên núi nhưng may mắn thoát chết trở về.","examples":[{"example":"山で遭難したが、九死一生を得て帰ってきた。","example_reading":"やまでそうなんしたが、きゅうしいっしょうをえてかえってきた。","example_meaning":"Gặp nạn trên núi nhưng may mắn thoát chết trở về."},{"example":"大きな事故で、九死一生の思いをした。","example_reading":"おおきなじこで、きゅうしいっしょうのおもいをした。","example_meaning":"Trong tai nạn lớn, tôi đã có cảm giác thoát chết trong gang tấc."}],"level":"p1"},
{"word":"諸行無常","reading":"しょぎょうむじょう","meaning":"vạn vật trên đời đều biến đổi, không có gì tồn tại mãi.\n(Triết lý Phật giáo về vô thường, thường gợi nỗi buồn man mác của sự phù du.)","hanviet":"chư hành vô thường","note":"📜 Lịch sử: Kinh Niết Bàn: «chư hành vô thường, thị sinh diệt pháp». Ở Nhật nổi tiếng nhờ câu mở đầu «Heike Monogatari», nói tiếng chuông Kỳ Viên tinh xá vang lên âm vô thường. 💡 Thú vị: Đêm giao thừa, chuông chùa Nhật vang 108 tiếng (除夜の鐘), tượng trưng cho 108 phiền não. Bài ca Iroha cổ cũng xoay quanh ý vô thường này.","chars":[{"c":"諸","h":"chư"},{"c":"行","h":"hành"},{"c":"無","h":"vô"},{"c":"常","h":"thường"}],"poem":{"han":"祇園鐘響諸行幻／沙羅花落一夢空","hv":"Kỳ Viên chung hưởng chư hành huyễn / Sa la hoa lạc nhất mộng không","vi":"Chuông Kỳ Viên vang lên, muôn sự đều huyễn; hoa sa la rụng, một giấc mộng không."},"example":"栄えた城も今は跡だけ。まさに諸行無常だ。","example_reading":"さかえたしろもいまはあとだけ。まさにしょぎょうむじょうだ。","example_meaning":"Tòa thành từng hưng thịnh nay chỉ còn dấu tích, đúng là vô thường.","examples":[{"example":"栄えた城も今は跡だけ。まさに諸行無常だ。","example_reading":"さかえたしろもいまはあとだけ。まさにしょぎょうむじょうだ。","example_meaning":"Tòa thành từng hưng thịnh nay chỉ còn dấu tích, đúng là vô thường."},{"example":"桜が散るのを見ると、諸行無常を感じる。","example_reading":"さくらがちるのをみると、しょぎょうむじょうをかんじる。","example_meaning":"Nhìn hoa anh đào rụng, tôi cảm nhận sự vô thường."}],"level":"p1"},
{"word":"馬耳東風","reading":"ばじとうふう","meaning":"gió đông thổi qua tai ngựa; nghe mà như không nghe, mặc kệ lời khuyên.\n(Dùng khi lời góp ý, lời nhắc không lọt vào tai người nghe.)","hanviet":"mã nhĩ đông phong","note":"📜 Lịch sử: Thơ Lý Bạch «Đáp Vương thập nhị hàn dạ độc chước hữu hoài»: «thế nhân văn thử giai trạo đầu, hữu như đông phong xạ mã nhĩ» (người đời nghe thơ chỉ lắc đầu, như gió đông thổi vào tai ngựa). 💡 Thú vị: Gió đông là gió xuân, vốn được người ta mừng đón, vậy mà ngựa chẳng động lòng. Lý Bạch viết để than rằng thi nhân không được đời trọng. Tiếng Nhật còn có tục ngữ gần nghĩa 馬の耳に念仏 (đã có ở chủ đề ことわざ).","chars":[{"c":"馬","h":"mã"},{"c":"耳","h":"nhĩ"},{"c":"東","h":"đông"},{"c":"風","h":"phong"}],"poem":{"han":"東風過耳馬無覺／詩句千篇不入聽","hv":"Đông phong quá nhĩ mã vô giác / Thi cú thiên thiên bất nhập thính","vi":"Gió đông qua tai ngựa mà ngựa chẳng hay; nghìn bài thơ cũng chẳng lọt vào tai."},"example":"何度注意しても、彼には馬耳東風だ。","example_reading":"なんどちゅういしても、かれにはばじとうふうだ。","example_meaning":"Nhắc bao nhiêu lần anh ấy cũng như nước đổ lá khoai.","examples":[{"example":"何度注意しても、彼には馬耳東風だ。","example_reading":"なんどちゅういしても、かれにはばじとうふうだ。","example_meaning":"Nhắc bao nhiêu lần anh ấy cũng như nước đổ lá khoai."},{"example":"親の忠告も馬耳東風で、息子は夜遊びをやめない。","example_reading":"おやのちゅうこくもばじとうふうで、むすこはよあそびをやめない。","example_meaning":"Lời khuyên của bố mẹ như gió thoảng qua tai, con trai vẫn đi chơi đêm."}],"level":"p1"},
{"word":"比翼連理","reading":"ひよくれんり","meaning":"chim liền cánh, cây liền cành; vợ chồng, tình nhân gắn bó khăng khít không rời.\n(Dùng trong lời chúc hôn nhân, tình yêu thủy chung.)","hanviet":"tỉ dực liên lý","note":"📜 Lịch sử: Bạch Cư Dị - Trường hận ca: «tại thiên nguyện tác tỉ dực điểu, tại địa nguyện vi liên lý chi», lời thề của Đường Minh Hoàng và Dương Quý Phi. 💡 Thú vị: Tỉ dực điểu là loài chim thần thoại chỉ có một mắt một cánh, phải ghép đôi mới bay được; liên lý là hai cây khác gốc mà cành nối liền nhau. Trường hận ca được yêu thích ở Nhật từ thời Heian và ảnh hưởng tới «Genji Monogatari».","chars":[{"c":"比","h":"tỉ"},{"c":"翼","h":"dực"},{"c":"連","h":"liên"},{"c":"理","h":"lý"}],"poem":{"han":"在天共翼同雲渡／在地交枝並蒂開","hv":"Tại thiên cộng dực đồng vân độ / Tại địa giao chi tịnh đế khai","vi":"Trên trời chung cánh bay qua mây, dưới đất cành giao nhau, hoa nở chung cuống."},"example":"二人は比翼連理の夫婦として知られている。","example_reading":"ふたりはひよくれんりのふうふとしてしられている。","example_meaning":"Hai người được biết đến là cặp vợ chồng gắn bó khăng khít.","examples":[{"example":"二人は比翼連理の夫婦として知られている。","example_reading":"ふたりはひよくれんりのふうふとしてしられている。","example_meaning":"Hai người được biết đến là cặp vợ chồng gắn bó khăng khít."},{"example":"結婚式で、比翼連理の誓いを立てた。","example_reading":"けっこんしきで、ひよくれんりのちかいをたてた。","example_meaning":"Trong lễ cưới, họ thề nguyện gắn bó trọn đời."}],"level":"p1"},
{"word":"風林火山","reading":"ふうりんかざん","meaning":"nhanh như gió, lặng như rừng, mạnh như lửa, vững như núi; bốn phẩm chất của một đội quân.\n(Ngày nay dùng cho chiến lược 'biết lúc nào nhanh, chậm, tấn công, đứng yên'.)","hanviet":"phong lâm hỏa sơn","note":"📜 Lịch sử: Tôn Tử - Quân tranh: «kỳ tật như phong, kỳ từ như lâm, xâm lược như hỏa, bất động như sơn». Nguyên văn còn thêm «khó biết như bóng tối, động như sấm sét». 💡 Thú vị: Takeda Shingen (thời Sengoku) thêu bốn vế đầu lên quân kỳ «Tôn Tử chi kỳ», tương truyền do cao tăng Kaisen Jōki viết. Ngày nay nó là biểu tượng của tỉnh Yamanashi.","chars":[{"c":"風","h":"phong"},{"c":"林","h":"lâm"},{"c":"火","h":"hỏa"},{"c":"山","h":"sơn"}],"poem":{"han":"疾風徐林隨勢轉／烈火如侵靜若山","hv":"Tật phong từ lâm tùy thế chuyển / Liệt hỏa như xâm tĩnh nhược sơn","vi":"Nhanh như gió, chậm như rừng, tùy thế mà đổi; mạnh như lửa tràn, tĩnh như núi."},"example":"監督は「風林火山」の戦術で試合に臨んだ。","example_reading":"かんとくは「ふうりんかざん」のせんじゅつでしあいにのぞんだ。","example_meaning":"Huấn luyện viên bước vào trận với chiến thuật phong lâm hỏa sơn.","examples":[{"example":"監督は「風林火山」の戦術で試合に臨んだ。","example_reading":"かんとくは「ふうりんかざん」のせんじゅつでしあいにのぞんだ。","example_meaning":"Huấn luyện viên bước vào trận với chiến thuật phong lâm hỏa sơn."},{"example":"武田信玄の軍旗には、風林火山の文字が書かれていた。","example_reading":"たけだしんげんのぐんきには、ふうりんかざんのもじがかかれていた。","example_meaning":"Trên quân kỳ của Takeda Shingen có viết chữ phong lâm hỏa sơn."}],"level":"p1"},
{"word":"孟母三遷","reading":"もうぼさんせん","meaning":"mẹ Mạnh Tử ba lần dời nhà; chọn môi trường tốt để con trưởng thành.\n(Nhấn mạnh ảnh hưởng của môi trường sống lên việc giáo dục trẻ.)","hanviet":"mạnh mẫu tam thiên","note":"📜 Lịch sử: Liệt nữ truyện - Mẫu nghi: nhà ở gần nghĩa địa thì cậu bé Mạnh Kha bắt chước lễ chôn cất; dời đến cạnh chợ thì bắt chước buôn bán; cuối cùng dời gần trường học thì cậu học theo lễ nghi. 💡 Thú vị: Còn có chuyện «Mạnh mẫu đoạn cơ»: bà cắt đứt tấm vải đang dệt để dạy con đừng bỏ học nửa chừng. Ở Nhật, 孟母三遷 hay xuất hiện khi bàn chuyện chọn nơi ở theo trường học.","chars":[{"c":"孟","h":"mạnh"},{"c":"母","h":"mẫu"},{"c":"三","h":"tam"},{"c":"遷","h":"thiên"}],"poem":{"han":"墓畔市邊終擇學／慈親三徙為成賢","hv":"Mộ bạn thị biên chung trạch học / Từ thân tam tỉ vi thành hiền","vi":"Bên mộ, cạnh chợ, cuối cùng chọn gần trường học; mẹ hiền ba lần dời nhà để con nên người hiền."},"example":"孟母三遷の教えで、学校の近くに引っ越した。","example_reading":"もうぼさんせんのおしえで、がっこうのちかくにひっこした。","example_meaning":"Theo tích mẹ Mạnh Tử dời nhà, chúng tôi chuyển đến gần trường.","examples":[{"example":"孟母三遷の教えで、学校の近くに引っ越した。","example_reading":"もうぼさんせんのおしえで、がっこうのちかくにひっこした。","example_meaning":"Theo tích mẹ Mạnh Tử dời nhà, chúng tôi chuyển đến gần trường."},{"example":"子どものために環境を選ぶのは、孟母三遷の心だ。","example_reading":"こどものためにかんきょうをえらぶのは、もうぼさんせんのこころだ。","example_meaning":"Chọn môi trường cho con là tâm thế của mẹ Mạnh Tử."}],"level":"p1"},
{"word":"一日千秋","reading":"いちじつせんしゅう","meaning":"một ngày dài như nghìn thu; mong chờ, nhớ nhung đến nóng ruột.\n(Dùng khi sốt ruột chờ ai đó hoặc chờ một sự kiện.)","hanviet":"nhất nhật thiên thu","note":"📜 Lịch sử: Kinh Thi - Vương phong - Thái cát: «nhất nhật bất kiến, như tam thu hề» (một ngày không gặp như ba mùa thu). 'Tam thu' được hiểu là ba mùa thu (ba năm) hoặc ba tháng mùa thu. 💡 Thú vị: Tiếng Nhật đổi 三秋 thành 千秋 (nghìn năm) cho mạnh hơn, thường dùng dạng 一日千秋の思いで待つ; tiếng Trung vẫn quen nói 一日三秋. 千秋 còn là tên người và tên tiệc mừng thọ (千秋楽 = ngày diễn cuối của sumo, kịch).","chars":[{"c":"一","h":"nhất"},{"c":"日","h":"nhật"},{"c":"千","h":"thiên"},{"c":"秋","h":"thu"}],"poem":{"han":"采葛思君無一見／一朝如隔萬千秋","hv":"Thái cát tư quân vô nhất kiến / Nhất triêu như cách vạn thiên thu","vi":"Hái dây sắn mà nhớ người, không gặp một ngày mà tựa như xa cách muôn thu."},"example":"合格発表の日を、一日千秋の思いで待っている。","example_reading":"ごうかくはっぴょうのひを、いちじつせんしゅうのおもいでまっている。","example_meaning":"Tôi nóng lòng chờ ngày công bố kết quả, mỗi ngày dài như nghìn thu.","examples":[{"example":"合格発表の日を、一日千秋の思いで待っている。","example_reading":"ごうかくはっぴょうのひを、いちじつせんしゅうのおもいでまっている。","example_meaning":"Tôi nóng lòng chờ ngày công bố kết quả, mỗi ngày dài như nghìn thu."},{"example":"彼女からの返事を、一日千秋の思いで待った。","example_reading":"かのじょからのへんじを、いちじつせんしゅうのおもいでまった。","example_meaning":"Tôi sốt ruột chờ hồi âm của cô ấy."}],"level":"p1"},
{"word":"三寒四温","reading":"さんかんしおん","meaning":"ba ngày lạnh rồi bốn ngày ấm, lặp đi lặp lại; thời tiết chuyển mùa thất thường.\n(Trong tiếng Nhật thường dùng để tả cuối đông đầu xuân, lúc rét ấm đan xen.)","hanviet":"tam hàn tứ ôn","note":"📜 Lịch sử: Vốn là hiện tượng thời tiết mùa đông ở vùng đông bắc Trung Quốc và bán đảo Triều Tiên: chu kỳ khoảng ba ngày lạnh rồi bốn ngày ấm theo sự thay đổi của khối khí lạnh. 💡 Thú vị: Sang Nhật, từ này được dùng rộng cho cuối đông đầu xuân, nên nhiều người tưởng nó là hiện tượng mùa xuân dù nguyên nghĩa là mùa đông. Chu kỳ '3+4 ngày' cũng chỉ là cách nói quen, không chính xác tuyệt đối.","chars":[{"c":"三","h":"tam"},{"c":"寒","h":"hàn"},{"c":"四","h":"tứ"},{"c":"温","h":"ôn"}],"poem":{"han":"三日風寒四日暖／春來冬去兩相催","hv":"Tam nhật phong hàn tứ nhật noãn / Xuân lai đông khứ lưỡng tương thôi","vi":"Ba ngày gió lạnh, bốn ngày ấm áp; xuân đến đông đi thúc giục lẫn nhau."},"example":"三寒四温で、服装選びが難しい季節だ。","example_reading":"さんかんしおんで、ふくそうえらびがむずかしいきせつだ。","example_meaning":"Trời lúc lạnh lúc ấm, mùa này khó chọn quần áo.","examples":[{"example":"三寒四温で、服装選びが難しい季節だ。","example_reading":"さんかんしおんで、ふくそうえらびがむずかしいきせつだ。","example_meaning":"Trời lúc lạnh lúc ấm, mùa này khó chọn quần áo."},{"example":"三寒四温を繰り返しながら、春が近づいてくる。","example_reading":"さんかんしおんをくりかえしながら、はるがちかづいてくる。","example_meaning":"Trời lặp đi lặp lại cảnh lạnh rồi ấm, và mùa xuân dần đến gần."}],"level":"p1"},
{"word":"色即是空","reading":"しきそくぜくう","meaning":"sắc tức là không; mọi hình tướng vật chất đều không có tự tính cố định.\n(Giáo lý Bát nhã: hiện tượng nhìn thấy được vốn do duyên hợp, không tồn tại độc lập.)","hanviet":"sắc tức thị không","note":"📜 Lịch sử: Bát nhã Tâm kinh bản dịch của Huyền Trang: «sắc bất dị không, không bất dị sắc, sắc tức thị không, không tức thị sắc». 💡 Thú vị: Toàn bài kinh chỉ khoảng 260 chữ nhưng được tụng ở hầu hết các tông phái Phật giáo Đông Á. Chữ 色 ở đây là «vật chất, hình tướng» chứ không phải «sắc dục» như cách hiểu đùa thường gặp ở Nhật.","chars":[{"c":"色","h":"sắc"},{"c":"即","h":"tức"},{"c":"是","h":"thị"},{"c":"空","h":"không"}],"poem":{"han":"色空不二觀心照／萬相皆從一念空","hv":"Sắc không bất nhị quán tâm chiếu / Vạn tướng giai tùng nhất niệm không","vi":"Sắc và không chẳng hai, soi chiếu bằng tâm quán; muôn tướng đều từ một niệm mà về không."},"example":"お金も地位も、色即是空だと思うと気が楽になる。","example_reading":"おかねもちいも、しきそくぜくうだとおもうときがらくになる。","example_meaning":"Nghĩ rằng tiền bạc, địa vị cũng chỉ là sắc tức thị không thì lòng nhẹ nhõm hẳn.","examples":[{"example":"お金も地位も、色即是空だと思うと気が楽になる。","example_reading":"おかねもちいも、しきそくぜくうだとおもうときがらくになる。","example_meaning":"Nghĩ rằng tiền bạc, địa vị cũng chỉ là sắc tức thị không thì lòng nhẹ nhõm hẳn."},{"example":"お寺で般若心経を聞いて、色即是空の意味を考えた。","example_reading":"おてらではんにゃしんぎょうをきいて、しきそくぜくうのいみをかんがえた。","example_meaning":"Nghe Bát nhã Tâm kinh ở chùa, tôi suy nghĩ về ý nghĩa của sắc tức thị không."}],"level":"p1"},
{"word":"起承転結","reading":"きしょうてんけつ","meaning":"khởi - thừa - chuyển - kết; bố cục bốn phần của bài văn, bài thơ, câu chuyện.\n(Cũng dùng để nói về cách dẫn dắt một câu chuyện cho mạch lạc.)","hanviet":"khởi thừa chuyển kết","note":"📜 Lịch sử: Xuất phát từ cách bố cục thơ tuyệt cú: câu 1 mở đề (khởi), câu 2 tiếp nối (thừa), câu 3 chuyển ý (chuyển), câu 4 kết lại (kết). Sách thi pháp Trung Quốc cổ viết «khởi thừa chuyển hợp» (起承轉合), tiếng Nhật đổi «hợp» thành «kết». 💡 Thú vị: Ở Nhật nó thành khuôn mẫu của truyện tranh 4 khung (四コマ漫画). Có câu nói vui về «cô con gái tiệm tơ» (糸屋の娘) dùng để nhớ bốn bước, tương truyền gắn với nhà Hán học Rai San'yō.","chars":[{"c":"起","h":"khởi"},{"c":"承","h":"thừa"},{"c":"転","h":"chuyển"},{"c":"結","h":"kết"}],"poem":{"han":"起句如門承接路／轉為峰迴結成圓","hv":"Khởi cú như môn thừa tiếp lộ / Chuyển vi phong hồi kết thành viên","vi":"Câu khởi như cửa mở, câu thừa nối đường; câu chuyển như đỉnh núi quay, câu kết khép thành vòng."},"example":"この物語は起承転結がはっきりしていて読みやすい。","example_reading":"このものがたりはきしょうてんけつがはっきりしていてよみやすい。","example_meaning":"Câu chuyện này có bố cục khởi thừa chuyển kết rõ ràng nên dễ đọc.","examples":[{"example":"この物語は起承転結がはっきりしていて読みやすい。","example_reading":"このものがたりはきしょうてんけつがはっきりしていてよみやすい。","example_meaning":"Câu chuyện này có bố cục khởi thừa chuyển kết rõ ràng nên dễ đọc."},{"example":"作文は起承転結を意識して書くといい。","example_reading":"さくぶんはきしょうてんけつをいしきしてかくといい。","example_meaning":"Viết văn nên chú ý bố cục khởi thừa chuyển kết."}],"level":"p1"},
{"word":"漁夫之利","reading":"ぎょふのり","meaning":"người đánh cá hưởng lợi; hai bên tranh nhau thì kẻ thứ ba ngồi không hưởng lợi.\n(Dùng khi hai đối thủ đấu đá nhau, người thứ ba được lợi.)","hanviet":"ngư phủ chi lợi","note":"📜 Lịch sử: Chiến quốc sách - Yên sách: Triệu định đánh Yên, Tô Đại thay Yên đi thuyết phục Triệu Huệ Văn vương bằng chuyện con trai há miệng phơi nắng, con cò mổ vào thịt; trai khép vỏ kẹp chặt mỏ cò, hai bên không bên nào chịu thả, ngư ông đi qua bắt gọn cả hai. Tô Đại nói: nếu Triệu và Yên đánh nhau thì nước Tần hùng mạnh sẽ là ngư ông; Triệu vương bèn bỏ ý định đánh Yên. 💡 Thú vị: Tiếng Nhật còn có dạng 鷸蚌の争い (cò trai tranh nhau), tiếng Việt có câu «ngao cò tranh nhau, ngư ông đắc lợi».","chars":[{"c":"漁","h":"ngư"},{"c":"夫","h":"phủ"},{"c":"之","h":"chi"},{"c":"利","h":"lợi"}],"poem":{"han":"鷸啄蚌肉蚌鉗喙／漁父拱手兩俱收","hv":"Duật trác bạng nhục bạng kiềm mỏ / Ngư phủ củng thủ lưỡng câu thu","vi":"Cò mổ thịt trai, trai kẹp mỏ cò; ngư ông khoanh tay thu cả hai."},"example":"二社が争っている間に、第三の会社が漁夫の利を得た。","example_reading":"にしゃがあらそっているあいだに、だいさんのかいしゃがぎょふのりをえた。","example_meaning":"Trong lúc hai công ty tranh nhau, công ty thứ ba đã hưởng lợi ngư ông.","examples":[{"example":"二社が争っている間に、第三の会社が漁夫の利を得た。","example_reading":"にしゃがあらそっているあいだに、だいさんのかいしゃがぎょふのりをえた。","example_meaning":"Trong lúc hai công ty tranh nhau, công ty thứ ba đã hưởng lợi ngư ông."},{"example":"両党の対立は、第三党に漁夫の利を与えかねない。","example_reading":"りょうとうのたいりつは、だいさんとうにぎょふのりをあたえかねない。","example_meaning":"Sự đối đầu giữa hai đảng có thể mang lại lợi ích cho đảng thứ ba."}],"level":"p1"},
{"word":"背水之陣","reading":"はいすいのじん","meaning":"bày trận quay lưng ra sông; tự đặt mình vào đường cùng, không còn đường lui để dốc toàn lực.\n(Dùng khi quyết tâm làm hết sức, không có lối thoát.)","hanviet":"bối thủy chi trận","note":"📜 Lịch sử: Sử ký - Hoài Âm hầu liệt truyện: năm 204 TCN, Hàn Tín đánh nước Triệu ở ải Tỉnh Hình, cho một vạn quân bày trận quay lưng ra sông; quân Triệu cười chê. Quân Hán không còn đường lui nên liều chết chiến đấu, trong khi kỳ binh lẻn vào trại Triệu nhổ cờ Triệu cắm cờ Hán, khiến quân Triệu hoảng loạn mà thua. 💡 Thú vị: Sau trận, Hàn Tín giải thích binh pháp rằng đặt quân vào chỗ chết thì họ mới tìm ra đường sống; đây là cách đánh vào tâm lý chứ không chỉ là liều.","chars":[{"c":"背","h":"bối"},{"c":"水","h":"thủy"},{"c":"之","h":"chi"},{"c":"陣","h":"trận"}],"poem":{"han":"兵背長河無去路／士皆死戰破趙營","hv":"Binh bối trường hà vô khứ lộ / Sĩ giai tử chiến phá Triệu doanh","vi":"Quân quay lưng sông dài, không đường lui; ai nấy liều chết, phá được trại Triệu."},"example":"今回の試験は背水の陣で臨む。","example_reading":"こんかいのしけんははいすいのじんでのぞむ。","example_meaning":"Kỳ thi lần này tôi sẽ dốc hết sức, không còn đường lui.","examples":[{"example":"今回の試験は背水の陣で臨む。","example_reading":"こんかいのしけんははいすいのじんでのぞむ。","example_meaning":"Kỳ thi lần này tôi sẽ dốc hết sức, không còn đường lui."},{"example":"会社は倒産寸前で、新商品に背水の陣を敷いた。","example_reading":"かいしゃはとうさんすんぜんで、しんしょうひんにはいすいのじんをしいた。","example_meaning":"Công ty sắp phá sản nên đã đặt cược tất cả vào sản phẩm mới."}],"level":"p1"},
{"word":"破竹之勢","reading":"はちくのいきおい","meaning":"thế chẻ tre; khí thế mạnh mẽ, tiến lên không gì cản nổi.\n(Dùng cho đà thắng liên tiếp hoặc sự phát triển vũ bão.)","hanviet":"phá trúc chi thế","note":"📜 Lịch sử: Tấn thư - Đỗ Dự truyện: năm 280, sau khi chiếm Giang Lăng, Đỗ Dự chuẩn bị đánh Đông Ngô; có người khuyên đợi sang mùa đông, ông nói quân ta uy thế đã lên, như chẻ tre, vài đốt đầu chẻ xong thì các đốt sau tự tách theo lưỡi dao. Quân Tấn tiến thẳng đến Kiến Nghiệp và diệt Ngô. 💡 Thú vị: Thành ngữ 迎刃而解 (gặp lưỡi dao là tách ra, tức việc khó được giải quyết dễ dàng) cũng bắt nguồn từ câu nói này.","chars":[{"c":"破","h":"phá"},{"c":"竹","h":"trúc"},{"c":"之","h":"chi"},{"c":"勢","h":"thế"}],"poem":{"han":"譬如破竹迎刃解／直下金陵一鼓平","hv":"Thí như phá trúc nghênh nhận giải / Trực hạ Kim Lăng nhất cổ bình","vi":"Ví như chẻ tre, gặp dao là tách; thẳng xuống Kim Lăng, một hồi trống là yên."},"example":"新チームは破竹の勢いで勝ち進んだ。","example_reading":"しんチームははちくのいきおいでかちすすんだ。","example_meaning":"Đội mới thắng liên tiếp với khí thế chẻ tre.","examples":[{"example":"新チームは破竹の勢いで勝ち進んだ。","example_reading":"しんチームははちくのいきおいでかちすすんだ。","example_meaning":"Đội mới thắng liên tiếp với khí thế chẻ tre."},{"example":"その歌手は破竹の勢いでヒット曲を飛ばしている。","example_reading":"そのかしゅははちくのいきおいでヒットきょくをとばしている。","example_meaning":"Ca sĩ đó đang tung hit liên tục với đà không gì cản nổi."}],"level":"p1"},
{"word":"水魚之交","reading":"すいぎょのまじわり","meaning":"tình giao kết như cá với nước; quan hệ khăng khít, không thể thiếu nhau.\n(Dùng cho cặp quân thần, bạn bè, vợ chồng cực kỳ thân thiết.)","hanviet":"thủy ngư chi giao","note":"📜 Lịch sử: Tam quốc chí - Thục thư - Gia Cát Lượng truyện: Quan Vũ và Trương Phi không vui vì Lưu Bị quá thân với Gia Cát Lượng; Lưu Bị nói: «Ta có Khổng Minh như cá có nước, mong các ngươi đừng nói nữa». Hai người liền thôi. 💡 Thú vị: Trước đó Lưu Bị đã ba lần đến lều tranh mời Khổng Minh ra giúp (三顧の礼), nên mối quan hệ này được xem là mẫu mực giữa chủ và tôi.","chars":[{"c":"水","h":"thủy"},{"c":"魚","h":"ngư"},{"c":"之","h":"chi"},{"c":"交","h":"giao"}],"poem":{"han":"劉備得亮猶魚水／莫使關張怨語生","hv":"Lưu Bị đắc Lượng do ngư thủy / Mạc sử Quan Trương oán ngữ sinh","vi":"Lưu Bị có Khổng Minh như cá gặp nước; đừng để Quan, Trương sinh lời oán trách."},"example":"二人は水魚の交わりで、互いに欠かせない存在だ。","example_reading":"ふたりはすいぎょのまじわりで、たがいにかかせないそんざいだ。","example_meaning":"Hai người gắn bó như cá với nước, không thể thiếu nhau.","examples":[{"example":"二人は水魚の交わりで、互いに欠かせない存在だ。","example_reading":"ふたりはすいぎょのまじわりで、たがいにかかせないそんざいだ。","example_meaning":"Hai người gắn bó như cá với nước, không thể thiếu nhau."},{"example":"社長と専務は水魚の交わりを結んで会社を育てた。","example_reading":"しゃちょうとせんむはすいぎょのまじわりをむすんでかいしゃをそだてた。","example_meaning":"Giám đốc và phó giám đốc gắn bó khăng khít, cùng xây dựng công ty."}],"level":"p1"},
{"word":"三顧之礼","reading":"さんこのれい","meaning":"lễ ba lần đến mời; hết lòng, hạ mình nhiều lần để mời người tài về giúp.\n(Dùng khi tha thiết mời một nhân tài, người có năng lực.)","hanviet":"tam cố chi lễ","note":"📜 Lịch sử: Xuất sư biểu của Gia Cát Lượng (năm 227): «Tiên đế không cho thần là hèn kém, hạ mình ba lần đến lều tranh của thần để hỏi việc thiên hạ». Lưu Bị ba lần đến Long Trung mời Lượng ra giúp, lần thứ ba mới gặp được. 💡 Thú vị: Lúc ấy Lưu Bị hơn Lượng khoảng 20 tuổi và đã là người có danh vọng, vậy mà vẫn hạ mình đến ba lần; cuộc bàn mưu hôm đó nổi tiếng là «Long Trung đối».","chars":[{"c":"三","h":"tam"},{"c":"顧","h":"cố"},{"c":"之","h":"chi"},{"c":"礼","h":"lễ"}],"poem":{"han":"草廬三顧問天下／一表忠貞報主恩","hv":"Thảo lư tam cố vấn thiên hạ / Nhất biểu trung trinh báo chủ ân","vi":"Ba lần đến lều tranh hỏi việc thiên hạ; một bản biểu trung trinh đền ơn chúa."},"example":"優秀な技術者を三顧の礼で迎えた。","example_reading":"ゆうしゅうなぎじゅつしゃをさんこのれいでむかえた。","example_meaning":"Chúng tôi đã mời kỹ sư giỏi về với tất cả sự trọng thị.","examples":[{"example":"優秀な技術者を三顧の礼で迎えた。","example_reading":"ゆうしゅうなぎじゅつしゃをさんこのれいでむかえた。","example_meaning":"Chúng tôi đã mời kỹ sư giỏi về với tất cả sự trọng thị."},{"example":"監督は三顧の礼を尽くして、そのコーチに就任を頼んだ。","example_reading":"かんとくはさんこのれいをつくして、そのコーチにしゅうにんをたのんだ。","example_meaning":"Huấn luyện viên trưởng hết lòng mời vị trợ lý đó nhận chức."}],"level":"p1"},
{"word":"刎頸之交","reading":"ふんけいのまじわり","meaning":"tình bạn sẵn sàng chém cổ vì nhau; bạn sinh tử, đồng cam cộng khổ.\n(Chỉ người bạn thân đến mức có thể hy sinh cả mạng sống.)","hanviet":"vẫn cảnh chi giao","note":"📜 Lịch sử: Sử ký - Liêm Pha Lạn Tương Như liệt truyện: Lạn Tương Như nhờ công mang ngọc bích về nguyên vẹn mà được phong thượng khanh, chức cao hơn Liêm Pha, nên Liêm Pha bực tức đòi làm nhục. Tương Như cứ tránh mặt vì không muốn hai người tài đấu nhau làm lợi cho nước Tần. Nghe vậy, Liêm Pha cởi trần vác roi mây đến nhà tạ tội, hai người kết làm bạn sinh tử. 💡 Thú vị: Cùng truyện này còn sinh ra hai thành ngữ khác là 完璧 (hoàn bích) và 負荊請罪 (vác roi xin tội).","chars":[{"c":"刎","h":"vẫn"},{"c":"頸","h":"cảnh"},{"c":"之","h":"chi"},{"c":"交","h":"giao"}],"poem":{"han":"負荊肉袒來門謝／刎頸同心保趙邦","hv":"Phụ kinh nhục đản lai môn tạ / Vẫn cảnh đồng tâm bảo Triệu bang","vi":"Cởi trần vác roi mây đến cửa tạ tội; sống chết cùng lòng giữ nước Triệu."},"example":"彼とは刎頸の交わりを結んだ仲だ。","example_reading":"かれとはふんけいのまじわりをむすんだなかだ。","example_meaning":"Tôi và anh ấy là bạn sinh tử.","examples":[{"example":"彼とは刎頸の交わりを結んだ仲だ。","example_reading":"かれとはふんけいのまじわりをむすんだなかだ。","example_meaning":"Tôi và anh ấy là bạn sinh tử."},{"example":"創業時から支え合った二人は、刎頸の交わりと呼ばれた。","example_reading":"そうぎょうじからささえあったふたりは、ふんけいのまじわりとよばれた。","example_meaning":"Hai người nâng đỡ nhau từ lúc lập nghiệp được gọi là bạn sinh tử."}],"level":"p1"},
{"word":"管鮑之交","reading":"かんぽうのまじわり","meaning":"tình bạn Quản Trọng và Bão Thúc Nha; bạn bè hiểu nhau sâu sắc, tin nhau trọn vẹn.\n(Dùng cho tình bạn chân thành, không tính toán thiệt hơn.)","hanviet":"Quản Bão chi giao","note":"📜 Lịch sử: Sử ký - Quản Yến liệt truyện: Quản Trọng kể rằng thuở nghèo buôn chung với Bão Thúc, chia lãi ông lấy nhiều hơn mà Bão Thúc không cho là tham vì biết ông nghèo; ông nói: «Người sinh ra ta là cha mẹ, người hiểu ta là Bão tử». Bão Thúc còn tiến cử Quản Trọng lên Tề Hoàn Công, giúp Hoàn Công làm bá chủ chư hầu. 💡 Thú vị: Bão Thúc cam chịu ở dưới Quản Trọng suốt đời mà không oán, nên người đời còn gọi tình bạn tri kỷ là «quản bão».","chars":[{"c":"管","h":"Quản"},{"c":"鮑","h":"Bão"},{"c":"之","h":"chi"},{"c":"交","h":"giao"}],"poem":{"han":"分金不吝知吾貧／薦相無私霸業成","hv":"Phân kim bất lận tri ngô bần / Tiến tướng vô tư bá nghiệp thành","vi":"Chia vàng chẳng tiếc vì biết ta nghèo; tiến cử không tư lợi nên dựng nên nghiệp bá."},"example":"二人は管鮑の交わりと言えるほど信頼し合っている。","example_reading":"ふたりはかんぽうのまじわりといえるほどしんらいしあっている。","example_meaning":"Hai người tin nhau đến mức có thể gọi là tri kỷ kiểu Quản - Bão.","examples":[{"example":"二人は管鮑の交わりと言えるほど信頼し合っている。","example_reading":"ふたりはかんぽうのまじわりといえるほどしんらいしあっている。","example_meaning":"Hai người tin nhau đến mức có thể gọi là tri kỷ kiểu Quản - Bão."},{"example":"長年の親友とは、管鮑の交わりを続けている。","example_reading":"ながねんのしんゆうとは、かんぽうのまじわりをつづけている。","example_meaning":"Tôi vẫn giữ tình bạn tri kỷ với người bạn thân lâu năm."}],"level":"p1"},
{"word":"蛍雪之功","reading":"けいせつのこう","meaning":"công lao đèn đom đóm, ánh tuyết; chăm chỉ học tập trong gian khổ và gặt hái thành quả.\n(Dùng cho thành quả của việc học hành vất vả.)","hanviet":"huỳnh tuyết chi công","note":"📜 Lịch sử: Ghép từ hai tích: Xa Dận (Tấn thư - Xa Dận truyện) nhà nghèo không có dầu thắp đèn, bắt đom đóm bỏ vào túi lụa để lấy sáng đọc sách; Tôn Khang (ghi trong Sơ học ký) nhờ ánh tuyết phản chiếu mà đọc sách. Cả hai về sau đều làm quan lớn. 💡 Thú vị: Bài hát tốt nghiệp quen thuộc ở Nhật «Hotaru no Hikari» (蛍の光) cũng lấy hình ảnh đom đóm và tuyết từ tích này.","chars":[{"c":"蛍","h":"huỳnh"},{"c":"雪","h":"tuyết"},{"c":"之","h":"chi"},{"c":"功","h":"công"}],"poem":{"han":"囊螢映雪勤燈火／十載寒窗志不移","hv":"Nang huỳnh ánh tuyết cần đăng hỏa / Thập tải hàn song chí bất di","vi":"Túi đom đóm, ánh tuyết thay đèn; mười năm cửa sổ lạnh, chí chẳng đổi."},"example":"蛍雪の功が実り、難関大学に合格した。","example_reading":"けいせつのこうがみのり、なんかんだいがくにごうかくした。","example_meaning":"Nhờ công đèn sách, tôi đã đỗ trường đại học khó vào.","examples":[{"example":"蛍雪の功が実り、難関大学に合格した。","example_reading":"けいせつのこうがみのり、なんかんだいがくにごうかくした。","example_meaning":"Nhờ công đèn sách, tôi đã đỗ trường đại học khó vào."},{"example":"毎晩遅くまで学んだ蛍雪の功で、資格を取得した。","example_reading":"まいばんおそくまでまなんだけいせつのこうで、しかくをしゅとくした。","example_meaning":"Nhờ công học đến khuya mỗi đêm, tôi đã lấy được chứng chỉ."}],"level":"p1"},
{"word":"塞翁失馬（塞翁が馬）","reading":"さいおうしつば（さいおうがうま）","meaning":"ông già ở biên ải mất ngựa; họa phúc khó đoán, may rủi có thể đổi chiều nên đừng vội mừng hay buồn.\n(Tiếng Nhật thường nói 塞翁が馬.)","hanviet":"tái ông thất mã","note":"📜 Lịch sử: Hoài Nam Tử - Nhân gian huấn: ông già gần biên ải mất ngựa, người ta đến an ủi thì ông nói «biết đâu lại là phúc». Mấy tháng sau con ngựa dắt về thêm một con ngựa tốt của người Hồ; người ta chúc mừng thì ông nói «biết đâu lại là họa». Con trai ông cưỡi ngựa ngã gãy đùi, rồi giặc Hồ kéo đến, thanh niên bị gọi ra trận chết gần hết, riêng con ông vì què mà thoát. 💡 Thú vị: Câu Hán Việt quen thuộc «Tái ông thất mã, an tri phi phúc» cũng từ tích này.","chars":[{"c":"塞","h":"tái"},{"c":"翁","h":"ông"},{"c":"失","h":"thất"},{"c":"馬","h":"mã"}],"poem":{"han":"失馬非災得馬喜／福禍相倚本無常","hv":"Thất mã phi tai đắc mã hỉ / Phúc họa tương ỷ bản vô thường","vi":"Mất ngựa chưa hẳn là họa, được ngựa chưa chắc là mừng; phúc họa nương nhau vốn vô thường."},"example":"人生は塞翁が馬だから、失敗しても落ち込みすぎるな。","example_reading":"じんせいはさいおうがうまだから、しっぱいしてもおちこみすぎるな。","example_meaning":"Đời người họa phúc khó lường nên có thất bại cũng đừng quá buồn.","examples":[{"example":"人生は塞翁が馬だから、失敗しても落ち込みすぎるな。","example_reading":"じんせいはさいおうがうまだから、しっぱいしてもおちこみすぎるな。","example_meaning":"Đời người họa phúc khó lường nên có thất bại cũng đừng quá buồn."},{"example":"転勤は嫌だったが、結果的に塞翁が馬で良い出会いがあった。","example_reading":"てんきんはいやだったが、けっかてきにさいおうがうまでいいであいがあった。","example_meaning":"Tôi không muốn bị điều chuyển nhưng rốt cuộc lại gặp được người tốt, đúng là họa phúc khôn lường."}],"level":"p1"},
{"word":"過猶不及","reading":"かゆうふきゅう","meaning":"quá cũng như chưa tới; làm quá mức cũng chẳng hơn làm thiếu.\n(Dùng để nhắc phải điều độ, không nên cực đoan.)","hanviet":"quá do bất cập","note":"📜 Lịch sử: Luận ngữ - Tiên tiến: Tử Cống hỏi Khổng Tử trong hai học trò Tử Trương và Tử Hạ ai giỏi hơn; Khổng Tử đáp: «Sư (Tử Trương) thì quá, Thương (Tử Hạ) thì chưa tới». Tử Cống hỏi: «Vậy Sư hơn chăng?» Khổng Tử đáp: «Quá cũng như chưa tới». 💡 Thú vị: Đây là tinh thần «trung dung» của Nho gia; tiếng Nhật còn có câu tục ngữ tương đương 過ぎたるは猶及ばざるが如し.","chars":[{"c":"過","h":"quá"},{"c":"猶","h":"do"},{"c":"不","h":"bất"},{"c":"及","h":"cập"}],"poem":{"han":"師也過兮商不及／中庸之道貴持衡","hv":"Sư dã quá hề Thương bất cập / Trung dung chi đạo quý trì hoành","vi":"Sư thì quá, Thương lại chưa tới; đạo trung dung quý ở giữ thăng bằng."},"example":"ダイエットも過猶不及で、やりすぎは体に悪い。","example_reading":"ダイエットもかゆうふきゅうで、やりすぎはからだにわるい。","example_meaning":"Ăn kiêng cũng vậy, làm quá mức thì hại sức khỏe.","examples":[{"example":"ダイエットも過猶不及で、やりすぎは体に悪い。","example_reading":"ダイエットもかゆうふきゅうで、やりすぎはからだにわるい。","example_meaning":"Ăn kiêng cũng vậy, làm quá mức thì hại sức khỏe."},{"example":"親の愛情も過猶不及、与えすぎれば子供のためにならない。","example_reading":"おやのあいじょうもかゆうふきゅう、あたえすぎればこどものためにならない。","example_meaning":"Tình thương của cha mẹ cũng quá thì chẳng bằng thiếu, cho quá nhiều thì không tốt cho con."}],"level":"p1"},
{"word":"井底之蛙","reading":"せいていのあ","meaning":"ếch đáy giếng; người hiểu biết hạn hẹp, chỉ biết thế giới nhỏ của mình.\n(Tiếng Nhật thường nói 井の中の蛙大海を知らず.)","hanviet":"tỉnh để chi oa","note":"📜 Lịch sử: Trang Tử - Thu thủy: thần biển Bắc nói với Hà Bá rằng không thể bàn chuyện biển với con ếch giếng, vì nó bị giới hạn bởi chỗ ở. Cũng trong thiên này có chuyện ếch giếng khoe cái giếng với con rùa biển Đông, nghe tả biển cả thì ngẩn ngơ. 💡 Thú vị: Vế «không biết biển lớn» (大海を知らず) là phần tiếng Nhật thêm vào, nghe quen thuộc hơn bản gốc; tiếng Việt có câu «ếch ngồi đáy giếng».","chars":[{"c":"井","h":"tỉnh"},{"c":"底","h":"để"},{"c":"之","h":"chi"},{"c":"蛙","h":"oa"}],"poem":{"han":"井蛙拘虛不語海／坐井觀天言天小","hv":"Tỉnh oa câu hư bất ngữ hải / Tọa tỉnh quan thiên ngôn thiên tiểu","vi":"Ếch giếng bị chỗ ở trói buộc nên chẳng bàn được chuyện biển; ngồi đáy giếng nhìn trời bảo trời nhỏ."},"example":"留学して、自分が井の中の蛙だったと気づいた。","example_reading":"りゅうがくして、じぶんがいのなかのかわずだったときづいた。","example_meaning":"Đi du học tôi mới nhận ra mình chỉ là ếch đáy giếng.","examples":[{"example":"留学して、自分が井の中の蛙だったと気づいた。","example_reading":"りゅうがくして、じぶんがいのなかのかわずだったときづいた。","example_meaning":"Đi du học tôi mới nhận ra mình chỉ là ếch đáy giếng."},{"example":"国内の成績だけで満足するのは、井の中の蛙になりかねない。","example_reading":"こくないのせいせきだけでまんぞくするのは、いのなかのかわずになりかねない。","example_meaning":"Chỉ hài lòng với thành tích trong nước thì dễ thành ếch đáy giếng."}],"level":"p1"},
{"word":"邯鄲之夢","reading":"かんたんのゆめ","meaning":"giấc mộng Hàm Đan; vinh hoa phú quý ngắn ngủi như một giấc mơ.\n(Còn gọi 一炊の夢, 盧生の夢; dùng khi cảm thán đời người phù du.)","hanviet":"Hàm Đan chi mộng","note":"📜 Lịch sử: Chẩm trung ký (Thẩm Ký Tế, đời Đường): chàng Lư Sinh ở Hàm Đan được đạo sĩ cho mượn chiếc gối; ngủ mơ thấy thi đỗ, làm quan to, hưởng vinh hoa mấy chục năm. Tỉnh dậy thì nồi cơm kê của chủ quán còn chưa chín. 💡 Thú vị: Tích này được dựng thành vở Nô «Kantan» của Nhật; tiếng Việt gọi là «giấc kê vàng» hay «Hoàng lương mộng».","chars":[{"c":"邯","h":"Hàm"},{"c":"鄲","h":"Đan"},{"c":"之","h":"chi"},{"c":"夢","h":"mộng"}],"poem":{"han":"枕上黃粱炊未熟／一生榮辱夢中過","hv":"Chẩm thượng hoàng lương xuy vị thục / Nhất sinh vinh nhục mộng trung qua","vi":"Trên gối, nồi cơm kê vàng chưa chín; cả đời vinh nhục trôi qua trong mộng."},"example":"巨万の富も、邯鄲の夢にすぎなかった。","example_reading":"きょまんのとみも、かんたんのゆめにすぎなかった。","example_meaning":"Khối tài sản khổng lồ rốt cuộc cũng chỉ là giấc mộng Hàm Đan.","examples":[{"example":"巨万の富も、邯鄲の夢にすぎなかった。","example_reading":"きょまんのとみも、かんたんのゆめにすぎなかった。","example_meaning":"Khối tài sản khổng lồ rốt cuộc cũng chỉ là giấc mộng Hàm Đan."},{"example":"バブルの栄華は邯鄲の夢のようにはかなく消えた。","example_reading":"バブルのえいがはかんたんのゆめのようにはかなくきえた。","example_meaning":"Vinh hoa thời bong bóng kinh tế tan biến phù du như giấc mộng Hàm Đan."}],"level":"p1"},
{"word":"胡蝶之夢","reading":"こちょうのゆめ","meaning":"giấc mộng bướm; không phân biệt được mộng với thực, ta với vật; cũng chỉ đời người phù du.\n(Dùng trong văn chương, triết học khi nghi ngờ ranh giới giữa mộng và thực.)","hanviet":"hồ điệp chi mộng","note":"📜 Lịch sử: Trang Tử - Tề vật luận: Trang Chu mơ thấy mình hóa bướm, bay lượn thích thú, quên mất mình là Chu; tỉnh dậy thấy mình vẫn là Chu, không biết Chu mơ làm bướm hay bướm mơ làm Chu. Trang Tử kết luận giữa Chu và bướm ắt có phân biệt, và gọi đó là «vật hóa». 💡 Thú vị: Câu hỏi này gần với những nghi vấn triết học hiện đại về việc làm sao chắc rằng ta đang tỉnh chứ không phải đang mơ.","chars":[{"c":"胡","h":"hồ"},{"c":"蝶","h":"điệp"},{"c":"之","h":"chi"},{"c":"夢","h":"mộng"}],"poem":{"han":"莊周夢蝶翩翩舞／覺後誰知我是誰","hv":"Trang Chu mộng điệp phiên phiên vũ / Giác hậu thùy tri ngã thị thùy","vi":"Trang Chu mơ làm bướm bay phấp phới; tỉnh dậy ai biết ta là ai."},"example":"夢か現実か分からない、まるで胡蝶の夢のような体験だった。","example_reading":"ゆめかげんじつかわからない、まるでこちょうのゆめのようなたいけんだった。","example_meaning":"Một trải nghiệm không biết là mơ hay thực, chẳng khác giấc mộng bướm.","examples":[{"example":"夢か現実か分からない、まるで胡蝶の夢のような体験だった。","example_reading":"ゆめかげんじつかわからない、まるでこちょうのゆめのようなたいけんだった。","example_meaning":"Một trải nghiệm không biết là mơ hay thực, chẳng khác giấc mộng bướm."},{"example":"この小説は胡蝶の夢をモチーフに、現実と幻想の境を描く。","example_reading":"このしょうせつはこちょうのゆめをモチーフに、げんじつとげんそうのさかいをえがく。","example_meaning":"Tiểu thuyết lấy giấc mộng bướm làm mô-típ, miêu tả ranh giới giữa thực và ảo."}],"level":"p1"},
{"word":"他山之石","reading":"たざんのいし","meaning":"đá núi khác; lời nói hay hoặc sai lầm của người khác cũng giúp mình sửa mình, học hỏi.\n(Thường dùng 他山の石とする: rút bài học từ chuyện của người ngoài.)","hanviet":"tha sơn chi thạch","note":"📜 Lịch sử: Kinh Thi - Tiểu nhã - Hạc minh: «Đá ở núi khác, có thể dùng để mài ngọc» (他山之石、可以攻玉). Ý là dù chỉ là hòn đá xoàng ở nơi khác cũng giúp mài giũa viên ngọc là bản thân mình. 💡 Thú vị: Trong tiếng Nhật hiện đại, cụm này hay mang nghĩa lấy sai lầm của người khác làm gương để tránh, hẹp hơn nghĩa gốc.","chars":[{"c":"他","h":"tha"},{"c":"山","h":"sơn"},{"c":"之","h":"chi"},{"c":"石","h":"thạch"}],"poem":{"han":"他山片石可攻玉／鑑彼前愆正我身","hv":"Tha sơn phiến thạch khả công ngọc / Giám bỉ tiền khiên chính ngã thân","vi":"Mảnh đá núi khác có thể mài ngọc; soi lỗi người trước để sửa thân mình."},"example":"他社の不祥事を他山の石とし、管理を徹底する。","example_reading":"たしゃのふしょうじをたざんのいしとし、かんりをてっていする。","example_meaning":"Lấy vụ bê bối của công ty khác làm bài học, chúng tôi sẽ quản lý chặt chẽ.","examples":[{"example":"他社の不祥事を他山の石とし、管理を徹底する。","example_reading":"たしゃのふしょうじをたざんのいしとし、かんりをてっていする。","example_meaning":"Lấy vụ bê bối của công ty khác làm bài học, chúng tôi sẽ quản lý chặt chẽ."},{"example":"友人の失敗を他山の石として、慎重に進めよう。","example_reading":"ゆうじんのしっぱいをたざんのいしとして、しんちょうにすすめよう。","example_meaning":"Lấy thất bại của bạn làm bài học, tôi sẽ tiến hành thận trọng."}],"level":"p1"},
{"word":"一鼓作気","reading":"いっこさっき","meaning":"một hồi trống làm dậy khí thế; làm việc một mạch khi khí thế đang lên.\n(Dùng khi muốn hoàn thành nhanh trong một hơi.)","hanviet":"nhất cổ tác khí","note":"📜 Lịch sử: Tả truyện - Trang công năm 10 (trận Trường Chước, năm 684 TCN): Tề đánh Lỗ, Tào Quế khuyên Lỗ Trang công đợi quân Tề đánh ba hồi trống mới phản công. Ông giải thích: đánh trận là dựa vào dũng khí; hồi trống đầu khí thế dâng cao, hồi hai thì giảm, hồi ba thì cạn. Lỗ thắng. 💡 Thú vị: Trong truyện gốc, Tào Quế dùng điều này để chờ địch kiệt sức, còn nghĩa hiện nay lại là mình tranh thủ lúc khí thế đang lên để làm một mạch.","chars":[{"c":"一","h":"nhất"},{"c":"鼓","h":"cổ"},{"c":"作","h":"tác"},{"c":"気","h":"khí"}],"poem":{"han":"鼓動三聲氣有竭／曹劌待衰一擊成","hv":"Cổ động tam thanh khí hữu kiệt / Tào Quế đãi suy nhất kích thành","vi":"Trống ba hồi thì khí cạn; Tào Quế đợi lúc địch suy, một đòn là xong."},"example":"休まず一鼓作気に仕上げた。","example_reading":"やすまずいっこさっきにしあげた。","example_meaning":"Tôi làm một mạch không nghỉ cho xong.","examples":[{"example":"休まず一鼓作気に仕上げた。","example_reading":"やすまずいっこさっきにしあげた。","example_meaning":"Tôi làm một mạch không nghỉ cho xong."},{"example":"最後の山場は一鼓作気に駆け上がった。","example_reading":"さいごのやまばはいっこさっきにかけあがった。","example_meaning":"Chặng cuối tôi leo một hơi lên tới đỉnh."}],"level":"p1"},
{"word":"完璧帰趙","reading":"かんぺききちょう","meaning":"đem ngọc bích về nguyên vẹn trả lại nước Triệu; hoàn thành trọn vẹn trọng trách, trả lại nguyên vẹn vật đã mượn.\n(Từ 完璧 «hoàn hảo, không tì vết» bắt nguồn từ tích này.)","hanviet":"hoàn bích quy Triệu","note":"📜 Lịch sử: Sử ký - Liêm Pha Lạn Tương Như liệt truyện: nước Triệu có viên ngọc Hòa thị bích, vua Tần đề nghị đổi bằng 15 thành. Lạn Tương Như mang ngọc vào Tần, thấy vua Tần không có ý trả thành, bèn dọa đập ngọc cùng đầu mình vào cột, rồi bí mật cho người đem ngọc về Triệu. 💡 Thú vị: Chữ 璧 là ngọc bích; từ 完璧 (かんぺき) trong tiếng Nhật nghĩa là hoàn hảo cũng từ chính tích này mà ra.","chars":[{"c":"完","h":"hoàn"},{"c":"璧","h":"bích"},{"c":"帰","h":"quy"},{"c":"趙","h":"Triệu"}],"poem":{"han":"懷璧入秦機智勇／怒髮倚柱護連城","hv":"Hoài bích nhập Tần cơ trí dũng / Nộ phát ỷ trụ hộ liên thành","vi":"Mang ngọc vào Tần vừa mưu trí vừa dũng cảm; tóc dựng tựa cột bảo vệ báu vật liên thành."},"example":"貸した本が、傷一つなく完璧帰趙で戻ってきた。","example_reading":"かしたほんが、きずひとつなくかんぺききちょうでもどってきた。","example_meaning":"Cuốn sách tôi cho mượn được trả về nguyên vẹn, không một vết xước.","examples":[{"example":"貸した本が、傷一つなく完璧帰趙で戻ってきた。","example_reading":"かしたほんが、きずひとつなくかんぺききちょうでもどってきた。","example_meaning":"Cuốn sách tôi cho mượn được trả về nguyên vẹn, không một vết xước."},{"example":"預かった資料を完璧帰趙で持ち主に返した。","example_reading":"あずかったしりょうをかんぺききちょうでもちぬしにかえした。","example_meaning":"Tôi trả lại nguyên vẹn tài liệu được nhờ giữ cho chủ của nó."}],"level":"p1"},
{"word":"負荊請罪","reading":"ふけいせいざい","meaning":"vác roi mây xin chịu tội; thành khẩn nhận lỗi, tự xin bị trừng phạt.","hanviet":"phụ kinh thỉnh tội","note":"📜 Lịch sử: Sử ký - Liêm Pha Lạn Tương Như liệt truyện (cùng tích 刎頸之交): biết Lạn Tương Như tránh mặt là vì lo cho nước, Liêm Pha hổ thẹn, cởi áo trần, vác roi mây đến cửa nhà Tương Như xin chịu tội. 💡 Thú vị: Chữ 荊 là loại cây dùng làm roi; ngày nay cụm từ dùng cho việc nhận lỗi công khai và chân thành.","chars":[{"c":"負","h":"phụ"},{"c":"荊","h":"kinh"},{"c":"請","h":"thỉnh"},{"c":"罪","h":"tội"}],"poem":{"han":"肉袒負荊門下拜／將軍折節謝同僚","hv":"Nhục đản phụ kinh môn hạ bái / Tướng quân chiết tiết tạ đồng liêu","vi":"Cởi trần vác roi mây lạy dưới cửa; vị tướng hạ mình tạ lỗi với đồng liêu."},"example":"失敗を認め、負荊請罪の覚悟で上司に報告した。","example_reading":"しっぱいをみとめ、ふけいせいざいのかくごでじょうしにほうこくした。","example_meaning":"Tôi nhận lỗi và báo cáo với sếp với quyết tâm xin chịu tội.","examples":[{"example":"失敗を認め、負荊請罪の覚悟で上司に報告した。","example_reading":"しっぱいをみとめ、ふけいせいざいのかくごでじょうしにほうこくした。","example_meaning":"Tôi nhận lỗi và báo cáo với sếp với quyết tâm xin chịu tội."},{"example":"彼は負荊請罪して、取引先に深く頭を下げた。","example_reading":"かれはふけいせいざいして、とりひきさきにふかくあたまをさげた。","example_meaning":"Anh ấy thành khẩn xin lỗi, cúi đầu thật sâu trước đối tác."}],"level":"p1"},
{"word":"怒髪衝冠","reading":"どはつしょうかん","meaning":"tóc dựng đội mũ lên; giận dữ đến cực điểm.","hanviet":"nộ phát xung quan","note":"📜 Lịch sử: Sử ký - Liêm Pha Lạn Tương Như liệt truyện: tại điện nước Tần, thấy vua Tần không có ý trả thành, Lạn Tương Như cầm ngọc đứng tựa cột, giận đến tóc dựng đội cả mũ lên, nói sẽ đập ngọc cùng đầu mình vào cột. 💡 Thú vị: Bài từ «Mãn giang hồng» được gán cho Nhạc Phi cũng mở đầu bằng «Nộ phát xung quan» (怒髮衝冠).","chars":[{"c":"怒","h":"nộ"},{"c":"髪","h":"phát"},{"c":"衝","h":"xung"},{"c":"冠","h":"quan"}],"poem":{"han":"玉璧倚柱雙目裂／怒髮衝冠秦王驚","hv":"Ngọc bích ỷ trụ song mục liệt / Nộ phát xung quan Tần vương kinh","vi":"Cầm ngọc tựa cột, mắt trợn tròn; tóc dựng đội mũ, vua Tần cũng kinh hãi."},"example":"不正を知り、彼は怒髪衝冠の勢いで抗議した。","example_reading":"ふせいをしり、かれはどはつしょうかんのいきおいでこうぎした。","example_meaning":"Biết có gian lận, anh ta giận dữ phản đối.","examples":[{"example":"不正を知り、彼は怒髪衝冠の勢いで抗議した。","example_reading":"ふせいをしり、かれはどはつしょうかんのいきおいでこうぎした。","example_meaning":"Biết có gian lận, anh ta giận dữ phản đối."},{"example":"理不尽な扱いに、怒髪衝冠となった。","example_reading":"りふじんなあつかいに、どはつしょうかんとなった。","example_meaning":"Bị đối xử vô lý, tôi giận sôi người."}],"level":"p1"},
{"word":"紙上談兵","reading":"しじょうだんぺい","meaning":"bàn binh trên giấy; lý thuyết suông, không có thực chiến.","hanviet":"chỉ thượng đàm binh","note":"📜 Lịch sử: Sử ký - Liêm Pha Lạn Tương Như liệt truyện: Triệu Quát đọc nhiều binh thư, bàn việc binh thì ngay cả cha cũng không bắt bí được, nhưng mẹ ông lo ngại. Năm 260 TCN (trận Trường Bình), vua Triệu thay Liêm Pha bằng Triệu Quát; Quát bày binh theo sách, bị quân Tần vây, hơn bốn mươi vạn quân Triệu bị tiêu diệt. 💡 Thú vị: Mẹ của Triệu Quát đã dâng thư xin vua đừng dùng con mình, nhờ vậy khi thua trận bà không bị liên lụy.","chars":[{"c":"紙","h":"chỉ"},{"c":"上","h":"thượng"},{"c":"談","h":"đàm"},{"c":"兵","h":"binh"}],"poem":{"han":"熟讀兵書談勝算／長平一敗四十萬","hv":"Thục độc binh thư đàm thắng toán / Trường Bình nhất bại tứ thập vạn","vi":"Đọc thuộc binh thư bàn chuyện thắng; Trường Bình một trận thua mất bốn mươi vạn quân."},"example":"経験のない理論だけの計画は紙上談兵だ。","example_reading":"けいけんのないりろんだけのけいかくはしじょうだんぺいだ。","example_meaning":"Kế hoạch chỉ có lý thuyết mà thiếu kinh nghiệm chỉ là bàn binh trên giấy.","examples":[{"example":"経験のない理論だけの計画は紙上談兵だ。","example_reading":"けいけんのないりろんだけのけいかくはしじょうだんぺいだ。","example_meaning":"Kế hoạch chỉ có lý thuyết mà thiếu kinh nghiệm chỉ là bàn binh trên giấy."},{"example":"現場を知らない彼の提案は紙上談兵に終わった。","example_reading":"げんばをしらないかれのていあんはしじょうだんぺいにおわった。","example_meaning":"Đề xuất của anh ta, người không biết hiện trường, rốt cuộc chỉ là lý thuyết suông."}],"level":"p1"},
{"word":"多多益善（多々益々弁ず）","reading":"たたえきぜん（たたますますべんず）","meaning":"càng nhiều càng tốt; càng nhiều việc, người càng xử lý giỏi.","hanviet":"đa đa ích thiện","note":"📜 Lịch sử: Sử ký - Hoài Âm hầu liệt truyện: Hán Cao Tổ hỏi Hàn Tín: «Như ta thì cầm được bao nhiêu quân?» Tín đáp: «Bệ hạ cầm được mười vạn.» Hỏi: «Còn ngươi?» Đáp: «Thần càng nhiều càng tốt.» Cao Tổ cười hỏi sao lại bị ta bắt; Tín đáp bệ hạ không giỏi cầm quân nhưng giỏi cầm tướng. 💡 Thú vị: Trong tiếng Nhật còn có dạng 多々益々弁ず, nghĩa là càng nhiều việc càng làm tốt.","chars":[{"c":"多","h":"đa"},{"c":"多","h":"đa"},{"c":"益","h":"ích"},{"c":"善","h":"thiện"}],"poem":{"han":"將兵十萬帝所限／多多益善信無窮","hv":"Tương binh thập vạn đế sở hạn / Đa đa ích thiện Tín vô cùng","vi":"Cầm quân mười vạn là hạn của vua; còn Hàn Tín càng nhiều càng tốt, không giới hạn."},"example":"データは多多益善で、多いほど分析の精度が上がる。","example_reading":"データはたたえきぜんで、おおいほどぶんせきのせいどがあがる。","example_meaning":"Dữ liệu càng nhiều càng tốt, càng nhiều thì phân tích càng chính xác.","examples":[{"example":"データは多多益善で、多いほど分析の精度が上がる。","example_reading":"データはたたえきぜんで、おおいほどぶんせきのせいどがあがる。","example_meaning":"Dữ liệu càng nhiều càng tốt, càng nhiều thì phân tích càng chính xác."},{"example":"資金は多多益善だが、使い道が大切だ。","example_reading":"しきんはたたえきぜんだが、つかいみちがたいせつだ。","example_meaning":"Vốn thì càng nhiều càng tốt, nhưng cách dùng mới quan trọng."}],"level":"p1"},
{"word":"指鹿為馬","reading":"しかをさしてうまとなす","meaning":"chỉ hươu bảo là ngựa; cố ý nói trắng thành đen, ép người khác thừa nhận điều sai.","hanviet":"chỉ lộc vi mã","note":"📜 Lịch sử: Sử ký - Tần Thủy Hoàng bản kỷ: Triệu Cao muốn thử xem quần thần ai theo mình, bèn dâng một con hươu cho Tần Nhị Thế mà bảo là ngựa. Vua cười, hỏi quần thần; có người im lặng, có người nói ngựa để a dua, có người nói thật là hươu. Sau đó Triệu Cao ngầm hãm hại những người nói hươu. 💡 Thú vị: Có thuyết dân gian cho rằng từ 馬鹿 (baka) bắt nguồn từ tích này, nhưng đó chỉ là giả thuyết, chưa có chứng cứ chắc chắn.","chars":[{"c":"指","h":"chỉ"},{"c":"鹿","h":"lộc"},{"c":"為","h":"vi"},{"c":"馬","h":"mã"}],"poem":{"han":"獻鹿稱馬試群臣／順逆分明禍已生","hv":"Hiến lộc xưng mã thí quần thần / Thuận nghịch phân minh họa dĩ sinh","vi":"Dâng hươu gọi là ngựa để thử quần thần; kẻ theo người cưỡng đã rõ, họa liền sinh ra."},"example":"彼は鹿を指して馬と為すような言い訳を続けた。","example_reading":"かれはしかをさしてうまとなすようないいわけをつづけた。","example_meaning":"Anh ta cứ tiếp tục biện bạch theo kiểu chỉ hươu bảo ngựa.","examples":[{"example":"彼は鹿を指して馬と為すような言い訳を続けた。","example_reading":"かれはしかをさしてうまとなすようないいわけをつづけた。","example_meaning":"Anh ta cứ tiếp tục biện bạch theo kiểu chỉ hươu bảo ngựa."},{"example":"権力者が鹿を指して馬と為せば、周囲は黙るしかなかった。","example_reading":"けんりょくしゃがしかをさしてうまとなせば、しゅういはだまるしかなかった。","example_meaning":"Khi kẻ quyền thế chỉ hươu bảo ngựa, xung quanh chỉ biết im lặng."}],"level":"p1"},
{"word":"燕雀鴻鵠","reading":"えんじゃくこうこく","meaning":"chim én, chim sẻ sao hiểu chí của hồng hộc; kẻ tầm thường không hiểu chí lớn của bậc anh hùng.","hanviet":"yến tước hồng hộc","note":"📜 Lịch sử: Sử ký - Trần Thiệp thế gia: Trần Thiệp lúc trẻ làm thuê cày ruộng, nghỉ bên bờ ruộng thở dài nói «nếu sau này phú quý thì đừng quên nhau». Bạn làm thuê cười: «làm thuê mà đòi giàu sang?». Trần Thiệp than: «Én sẻ sao hiểu được chí hồng hộc!» Năm 209 TCN ông cầm đầu cuộc khởi nghĩa chống Tần. 💡 Thú vị: Cùng cuộc khởi nghĩa ấy có câu nổi tiếng «Vương hầu tướng tướng há có giống nòi gì sao?».","chars":[{"c":"燕","h":"yến"},{"c":"雀","h":"tước"},{"c":"鴻","h":"hồng"},{"c":"鵠","h":"hộc"}],"poem":{"han":"傭耕壟上長歎息／燕雀安知鴻鵠心","hv":"Dong canh lũng thượng trường thán tức / Yến tước an tri hồng hộc tâm","vi":"Làm thuê cày ruộng thở dài mãi; én sẻ nào hay lòng hồng hộc."},"example":"燕雀安んぞ鴻鵠の志を知らんやと、彼は黙って起業の準備を進めた。","example_reading":"えんじゃくいずくんぞこうこくのこころざしをしらんやと、かれはだまってきぎょうのじゅんびをすすめた。","example_meaning":"Nghĩ rằng én sẻ sao hiểu chí hồng hộc, anh lặng lẽ chuẩn bị khởi nghiệp.","examples":[{"example":"燕雀安んぞ鴻鵠の志を知らんやと、彼は黙って起業の準備を進めた。","example_reading":"えんじゃくいずくんぞこうこくのこころざしをしらんやと、かれはだまってきぎょうのじゅんびをすすめた。","example_meaning":"Nghĩ rằng én sẻ sao hiểu chí hồng hộc, anh lặng lẽ chuẩn bị khởi nghiệp."},{"example":"凡人には理解できない、燕雀鴻鵠の差があった。","example_reading":"ぼんじんにはりかいできない、えんじゃくこうこくのさがあった。","example_meaning":"Có khoảng cách giữa én sẻ và hồng hộc mà người thường không hiểu nổi."}],"level":"p1"},
{"word":"焚書坑儒","reading":"ふんしょこうじゅ","meaning":"đốt sách chôn nho; đàn áp học thuật và tư tưởng.","hanviet":"phần thư khanh nho","note":"📜 Lịch sử: Sử ký - Tần Thủy Hoàng bản kỷ: năm 213 TCN, theo đề nghị của Lý Tư, Thủy Hoàng cho đốt sách trong thiên hạ, trừ sách y, bói toán, trồng trọt và sử của nước Tần; năm 212 TCN hơn 460 nho sinh và phương sĩ bị chôn sống ở Hàm Dương. 💡 Thú vị: Phần lớn những người bị chôn là phương sĩ chứ không chỉ riêng nho sinh; sử gia hiện đại vẫn tranh luận về quy mô thật sự của sự kiện.","chars":[{"c":"焚","h":"phần"},{"c":"書","h":"thư"},{"c":"坑","h":"khanh"},{"c":"儒","h":"nho"}],"poem":{"han":"咸陽火起書成燼／長坑埋盡讀書人","hv":"Hàm Dương hỏa khởi thư thành tẫn / Trường khanh mai tận độc thư nhân","vi":"Hàm Dương lửa nổi, sách thành tro; hố dài chôn hết kẻ đọc sách."},"example":"独裁政権は焚書坑儒のように言論を弾圧した。","example_reading":"どくさいせいけんはふんしょこうじゅのようにげんろんをだんあつした。","example_meaning":"Chính quyền độc tài đàn áp ngôn luận như đốt sách chôn nho.","examples":[{"example":"独裁政権は焚書坑儒のように言論を弾圧した。","example_reading":"どくさいせいけんはふんしょこうじゅのようにげんろんをだんあつした。","example_meaning":"Chính quyền độc tài đàn áp ngôn luận như đốt sách chôn nho."},{"example":"焚書坑儒は、始皇帝の思想統制の象徴だ。","example_reading":"ふんしょこうじゅは、しこうていのしそうとうせいのしょうちょうだ。","example_meaning":"Đốt sách chôn nho là biểu tượng cho việc Tần Thủy Hoàng kiểm soát tư tưởng."}],"level":"p1"},
{"word":"破釜沈舟","reading":"はふちんしゅう","meaning":"đập nồi, đánh chìm thuyền; quyết tâm một mất một còn, không cho mình đường lui.","hanviet":"phá phủ trầm chu","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ: năm 207 TCN, trong trận Cự Lộc, Hạng Vũ cho quân qua sông Chương Thủy rồi đục chìm thuyền, đập nồi, đốt trại, chỉ mang lương ba ngày để quân biết chỉ có tiến lên. Quân Sở đánh áp đảo quân Tần. 💡 Thú vị: Cách làm giống 背水之陣 của Hàn Tín nhưng sớm hơn khoảng ba năm; tiếng Việt gọi là «đập nồi dìm thuyền».","chars":[{"c":"破","h":"phá"},{"c":"釜","h":"phủ"},{"c":"沈","h":"trầm"},{"c":"舟","h":"chu"}],"poem":{"han":"渡河沈舟釜盡破／三日糧攜決死爭","hv":"Độ hà trầm chu phủ tận phá / Tam nhật lương huề quyết tử tranh","vi":"Qua sông đánh chìm thuyền, đập hết nồi; mang lương ba ngày, quyết tử chiến."},"example":"破釜沈舟の覚悟で事業に挑んだ。","example_reading":"はふちんしゅうのかくごでじぎょうにいどんだ。","example_meaning":"Tôi lao vào kinh doanh với quyết tâm đập nồi dìm thuyền.","examples":[{"example":"破釜沈舟の覚悟で事業に挑んだ。","example_reading":"はふちんしゅうのかくごでじぎょうにいどんだ。","example_meaning":"Tôi lao vào kinh doanh với quyết tâm đập nồi dìm thuyền."},{"example":"退路を断つ破釜沈舟の姿勢が成功を呼んだ。","example_reading":"たいろをたつはふちんしゅうのしせいがせいこうをよんだ。","example_meaning":"Thái độ cắt đứt đường lui đã mang lại thành công."}],"level":"p1"},
{"word":"錦衣夜行","reading":"きんいやこう","meaning":"mặc áo gấm đi đêm; có thành công, giàu sang mà không ai biết, vô ích.","hanviet":"cẩm y dạ hành","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ: sau khi vào Hàm Dương, có người khuyên Hạng Vũ đóng đô ở Quan Trung, nhưng ông muốn về quê, nói: «Giàu sang mà không về quê, như mặc áo gấm đi đêm, ai biết cho». Người khuyên lui ra than: «Người ta bảo người Sở là khỉ đội mũ, quả đúng thế». 💡 Thú vị: Hạng Vũ nghe được liền cho nấu sống người ấy; chính câu chê này là nguồn của thành ngữ 沐猴而冠.","chars":[{"c":"錦","h":"cẩm"},{"c":"衣","h":"y"},{"c":"夜","h":"dạ"},{"c":"行","h":"hành"}],"poem":{"han":"富貴不歸如夜行／繡衣誰識故鄉情","hv":"Phú quý bất quy như dạ hành / Tú y thùy thức cố hương tình","vi":"Giàu sang không về như đi đêm; áo thêu ai biết tình quê."},"example":"せっかくの成果も、報告しなければ錦衣夜行だ。","example_reading":"せっかくのせいかも、ほうこくしなければきんいやこうだ。","example_meaning":"Thành quả có tốt đến đâu mà không báo cáo thì cũng như mặc áo gấm đi đêm.","examples":[{"example":"せっかくの成果も、報告しなければ錦衣夜行だ。","example_reading":"せっかくのせいかも、ほうこくしなければきんいやこうだ。","example_meaning":"Thành quả có tốt đến đâu mà không báo cáo thì cũng như mặc áo gấm đi đêm."},{"example":"宣伝しないのは錦衣夜行のようなものだ。","example_reading":"せんでんしないのはきんいやこうのようなものだ。","example_meaning":"Không quảng bá thì chẳng khác nào mặc áo gấm đi đêm."}],"level":"p1"},
{"word":"約法三章","reading":"やくほうさんしょう","meaning":"giao ước ba điều luật; luật lệ đơn giản, rõ ràng để dân dễ theo.","hanviet":"ước pháp tam chương","note":"📜 Lịch sử: Sử ký - Cao Tổ bản kỷ: năm 206 TCN, Lưu Bang vào Hàm Dương, họp các bô lão nói luật Tần quá hà khắc, ông chỉ ước ba điều: giết người thì chết, làm người bị thương và trộm cắp thì bị trị tội, còn lại bỏ hết luật Tần. Dân chúng rất mừng. 💡 Thú vị: Ngày nay cụm từ này được dùng khi đặt ra một vài quy tắc ngắn gọn dễ hiểu cho tập thể.","chars":[{"c":"約","h":"ước"},{"c":"法","h":"pháp"},{"c":"三","h":"tam"},{"c":"章","h":"chương"}],"poem":{"han":"秦苛法密民多怨／約止三章萬戶歡","hv":"Tần hà pháp mật dân đa oán / Ước chỉ tam chương vạn hộ hoan","vi":"Luật Tần khắc nghiệt dày đặc, dân nhiều oán; chỉ ước ba điều, muôn nhà vui mừng."},"example":"新しい寮では約法三章で、簡単なルールだけを決めた。","example_reading":"あたらしいりょうではやくほうさんしょうで、かんたんなルールだけをきめた。","example_meaning":"Ở ký túc xá mới, chúng tôi chỉ đặt vài quy tắc đơn giản.","examples":[{"example":"新しい寮では約法三章で、簡単なルールだけを決めた。","example_reading":"あたらしいりょうではやくほうさんしょうで、かんたんなルールだけをきめた。","example_meaning":"Ở ký túc xá mới, chúng tôi chỉ đặt vài quy tắc đơn giản."},{"example":"約法三章を守って、共同生活を始めた。","example_reading":"やくほうさんしょうをまもって、きょうどうせいかつをはじめた。","example_meaning":"Chúng tôi giữ ba điều giao ước và bắt đầu cuộc sống chung."}],"level":"p1"},
{"word":"合従連衡","reading":"がっしょうれんこう","meaning":"liên minh và liên kết giữa các thế lực; thay đổi quan hệ liên hợp theo lợi ích.","hanviet":"hợp tung liên hoành","note":"📜 Lịch sử: Sử ký - Tô Tần liệt truyện và Trương Nghi liệt truyện: Tô Tần thuyết phục sáu nước (Yên, Triệu, Hàn, Ngụy, Tề, Sở) liên minh theo chiều nam bắc (hợp tung) để chống Tần; Trương Nghi lại thuyết phục từng nước liên kết theo chiều đông tây (liên hoành) để thờ Tần. 💡 Thú vị: «Tung» là dọc, «hoành» là ngang; trong tiếng Nhật hiện đại cụm từ này thường dùng để nói về liên minh, tái cấu trúc của các đảng phái hoặc doanh nghiệp.","chars":[{"c":"合","h":"hợp"},{"c":"従","h":"tung"},{"c":"連","h":"liên"},{"c":"衡","h":"hoành"}],"poem":{"han":"蘇秦合縱連六國／張儀連橫破其盟","hv":"Tô Tần hợp tung liên lục quốc / Trương Nghi liên hoành phá kỳ minh","vi":"Tô Tần hợp tung nối sáu nước; Trương Nghi liên hoành phá minh ước đó."},"example":"政界では合従連衡が繰り返されている。","example_reading":"せいかいではがっしょうれんこうがくりかえされている。","example_meaning":"Trong giới chính trị, các liên minh liên tục hợp rồi tan.","examples":[{"example":"政界では合従連衡が繰り返されている。","example_reading":"せいかいではがっしょうれんこうがくりかえされている。","example_meaning":"Trong giới chính trị, các liên minh liên tục hợp rồi tan."},{"example":"企業は生き残りのため、合従連衡を進めた。","example_reading":"きぎょうはいきのこりのため、がっしょうれんこうをすすめた。","example_meaning":"Các doanh nghiệp thúc đẩy liên kết để tồn tại."}],"level":"p1"},
{"word":"遠交近攻","reading":"えんこうきんこう","meaning":"giao hảo với nước xa, đánh nước gần; chiến lược ngoại giao kết hợp quân sự.","hanviet":"viễn giao cận công","note":"📜 Lịch sử: Sử ký - Phạm Thư Sái Trạch liệt truyện: Phạm Tuy khuyên Tần Chiêu vương không nên vượt qua Hàn, Ngụy để đánh Tề ở xa, mà nên đánh Hàn, Ngụy ở gần, vì đánh được tấc đất nào thì đó là tấc đất của vua. Đây là cơ sở chiến lược để Tần thôn tính sáu nước. 💡 Thú vị: Phạm Tuy từng bị vu oan, giả chết trốn sang Tần, đổi tên thành Trương Lộc rồi trở thành tướng quốc nước Tần.","chars":[{"c":"遠","h":"viễn"},{"c":"交","h":"giao"},{"c":"近","h":"cận"},{"c":"攻","h":"công"}],"poem":{"han":"捨遠攻近尺寸得／秦併六國藉良謀","hv":"Xả viễn công cận xích thốn đắc / Tần tịnh lục quốc tạ lương mưu","vi":"Bỏ xa đánh gần, được tấc đất là của mình; Tần thôn tính sáu nước nhờ kế hay."},"example":"遠交近攻の外交戦略で、周辺国と同盟を結んだ。","example_reading":"えんこうきんこうのがいこうせんりゃくで、しゅうへんこくとどうめいをむすんだ。","example_meaning":"Bằng chiến lược viễn giao cận công, họ ký liên minh với các nước xung quanh.","examples":[{"example":"遠交近攻の外交戦略で、周辺国と同盟を結んだ。","example_reading":"えんこうきんこうのがいこうせんりゃくで、しゅうへんこくとどうめいをむすんだ。","example_meaning":"Bằng chiến lược viễn giao cận công, họ ký liên minh với các nước xung quanh."},{"example":"企業間でも遠交近攻の戦略がとられることがある。","example_reading":"きぎょうかんでもえんこうきんこうのせんりゃくがとられることがある。","example_meaning":"Giữa các doanh nghiệp đôi khi cũng dùng chiến lược này."}],"level":"p1"},
{"word":"狐仮虎威","reading":"こかこい","meaning":"cáo mượn oai hổ; nhờ thế lực người khác để dọa nạt kẻ yếu.\n(Tiếng Nhật: 虎の威を借る狐.)","hanviet":"hồ giả hổ uy","note":"📜 Lịch sử: Chiến quốc sách - Sở sách: cáo bị hổ bắt, bèn nói mình là sứ giả của Thiên đế, nếu không tin thì cứ đi theo sau xem muôn thú có sợ không. Hổ đi theo, thấy thú đều bỏ chạy, tưởng chúng sợ cáo mà không biết chúng sợ chính mình. Giang Nhất kể chuyện này cho Sở Tuyên vương để nói các nước sợ Sở là sợ quân đội của vua chứ không phải sợ tướng Chiêu Hề Tuất. 💡 Thú vị: Tiếng Việt có câu «cáo mượn oai hùm».","chars":[{"c":"狐","h":"hồ"},{"c":"仮","h":"giả"},{"c":"虎","h":"hổ"},{"c":"威","h":"uy"}],"poem":{"han":"狐稱天使行林下／百獸驚逃誤虎威","hv":"Hồ xưng thiên sứ hành lâm hạ / Bách thú kinh đào ngộ hổ uy","vi":"Cáo xưng sứ trời đi dưới rừng; trăm thú hoảng chạy, nhầm là oai hổ."},"example":"社長の名前を出して威張るのは虎の威を借る狐だ。","example_reading":"しゃちょうのなまえをだしていばるのはとらのいをかるきつねだ。","example_meaning":"Mượn tên giám đốc ra oai là cáo mượn oai hùm.","examples":[{"example":"社長の名前を出して威張るのは虎の威を借る狐だ。","example_reading":"しゃちょうのなまえをだしていばるのはとらのいをかるきつねだ。","example_meaning":"Mượn tên giám đốc ra oai là cáo mượn oai hùm."},{"example":"彼は先輩の力を笠に着る狐仮虎威の人だ。","example_reading":"かれはせんぱいのちからをかさにきるこかこいのひとだ。","example_meaning":"Anh ta là kiểu cáo mượn oai hùm, ỷ vào thế của đàn anh."}],"level":"p1"},
{"word":"亡羊補牢","reading":"ぼうようほろう","meaning":"mất cừu mới sửa chuồng; biết sai thì sửa vẫn chưa muộn.","hanviet":"vong dương bổ lao","note":"📜 Lịch sử: Chiến quốc sách - Sở sách: Trang Tân khuyên Sở Tương vương, dẫn tục ngữ: «Thấy thỏ mới ngoảnh nhìn chó vẫn chưa muộn, mất cừu mới sửa chuồng vẫn chưa muộn» (見兔而顧犬，未為晚也；亡羊而補牢，未為遲也). 💡 Thú vị: Nghĩa gốc là khuyến khích sửa sai kịp thời, trong khi câu tiếng Việt tương tự «mất bò mới lo làm chuồng» lại mang sắc thái chê trách.","chars":[{"c":"亡","h":"vong"},{"c":"羊","h":"dương"},{"c":"補","h":"bổ"},{"c":"牢","h":"lao"}],"poem":{"han":"亡羊補牢猶非晚／見兔顧犬未為遲","hv":"Vong dương bổ lao do phi vãn / Kiến thố cố khuyển vị vi trì","vi":"Mất cừu sửa chuồng chưa phải muộn; thấy thỏ ngoảnh nhìn chó cũng chưa chậm."},"example":"事故の後だが、亡羊補牢で再発防止策を講じた。","example_reading":"じこのあとだが、ぼうようほろうでさいはつぼうしさくをこうじた。","example_meaning":"Dù đã sau tai nạn, chúng tôi vẫn lập biện pháp ngăn tái phát, sửa sai vẫn chưa muộn.","examples":[{"example":"事故の後だが、亡羊補牢で再発防止策を講じた。","example_reading":"じこのあとだが、ぼうようほろうでさいはつぼうしさくをこうじた。","example_meaning":"Dù đã sau tai nạn, chúng tôi vẫn lập biện pháp ngăn tái phát, sửa sai vẫn chưa muộn."},{"example":"失敗してからでも、亡羊補牢は遅くない。","example_reading":"しっぱいしてからでも、ぼうようほろうはおそくない。","example_meaning":"Dù đã thất bại, sửa sai vẫn chưa muộn."}],"level":"p1"},
{"word":"杞人憂天","reading":"きじんゆうてん","meaning":"người nước Kỷ lo trời sập; lo lắng vô cớ về những điều không thể xảy ra.\n(Tiếng Nhật rút gọn là 杞憂.)","hanviet":"Kỷ nhân ưu thiên","note":"📜 Lịch sử: Liệt Tử - Thiên thoại: người nước Kỷ lo trời sập đất lở không chỗ nương thân, lo đến ăn ngủ không yên. Có người đến khuyên: trời chỉ là khí tích tụ, mặt trời, trăng, sao cũng là khí sáng, có rơi xuống cũng không làm ai bị thương. 💡 Thú vị: Từ 杞憂 (きゆう, lo thừa) trong tiếng Nhật là dạng rút gọn rất thông dụng; tiếng Việt tương đương là «lo bò trắng răng».","chars":[{"c":"杞","h":"Kỷ"},{"c":"人","h":"nhân"},{"c":"憂","h":"ưu"},{"c":"天","h":"thiên"}],"poem":{"han":"杞國有人憂墜天／寢食俱廢枉自憐","hv":"Kỷ quốc hữu nhân ưu trụy thiên / Tẩm thực câu phế uổng tự liên","vi":"Nước Kỷ có người lo trời sập; ăn ngủ đều bỏ, uổng công thương thân."},"example":"その心配は杞人憂天にすぎなかった。","example_reading":"そのしんぱいはきじんゆうてんにすぎなかった。","example_meaning":"Nỗi lo đó chỉ là lo thừa vô cớ.","examples":[{"example":"その心配は杞人憂天にすぎなかった。","example_reading":"そのしんぱいはきじんゆうてんにすぎなかった。","example_meaning":"Nỗi lo đó chỉ là lo thừa vô cớ."},{"example":"杞憂に終わったが、備えるのは悪くない。","example_reading":"きゆうにおわったが、そなえるのはわるくない。","example_meaning":"Dù hóa ra là lo thừa, chuẩn bị cũng không có gì xấu."}],"level":"p1"},
{"word":"自相矛盾","reading":"じそうむじゅん","meaning":"tự mâu thuẫn; lời nói trước sau không ăn khớp.","hanviet":"tự tương mâu thuẫn","note":"📜 Lịch sử: Hàn Phi Tử - Nan nhất: người nước Sở bán khiên và giáo, khoe khiên của mình không gì đâm thủng, rồi lại khoe giáo của mình đâm thủng mọi thứ. Có người hỏi «lấy giáo của ông đâm khiên của ông thì sao?», ông ta không đáp được. 💡 Thú vị: Từ 矛盾 (mâu thuẫn) trong tiếng Nhật, Hán, Việt đều bắt nguồn từ tích này.","chars":[{"c":"自","h":"tự"},{"c":"相","h":"tương"},{"c":"矛","h":"mâu"},{"c":"盾","h":"thuẫn"}],"poem":{"han":"楚人誇盾又誇矛／一問無言語自拘","hv":"Sở nhân khoa thuẫn hựu khoa mâu / Nhất vấn vô ngôn ngữ tự câu","vi":"Người Sở khoe khiên rồi lại khoe giáo; một câu hỏi, không đáp nổi, lời tự trói mình."},"example":"彼の主張は前後で自相矛盾している。","example_reading":"かれのしゅちょうはぜんごでじそうむじゅんしている。","example_meaning":"Lập luận của anh ta trước sau mâu thuẫn nhau.","examples":[{"example":"彼の主張は前後で自相矛盾している。","example_reading":"かれのしゅちょうはぜんごでじそうむじゅんしている。","example_meaning":"Lập luận của anh ta trước sau mâu thuẫn nhau."},{"example":"安全第一と言いながら無理をさせるのは自相矛盾だ。","example_reading":"あんぜんだいいちといいながらむりをさせるのはじそうむじゅんだ。","example_meaning":"Nói an toàn là trên hết mà vẫn ép làm quá sức là tự mâu thuẫn."}],"level":"p1"},
{"word":"濫竽充数","reading":"らんうじゅうすう","meaning":"thổi sáo vu cho đủ số; không có thực tài mà chen vào đám đông cho đủ số lượng.","hanviet":"lạm vu sung số","note":"📜 Lịch sử: Hàn Phi Tử - Nội trữ thuyết thượng: Tề Tuyên vương thích nghe ba trăm người cùng thổi sáo vu; Nam Quách xử sĩ không biết thổi vẫn xin vào dàn nhạc và được lĩnh lương. Khi Tề Mẫn vương lên thay, chỉ thích nghe từng người độc tấu, Nam Quách liền bỏ trốn. 💡 Thú vị: Trong tiếng Nhật, 濫竽 còn được dùng làm cách nói khiêm tốn về mình: «tôi chỉ như kẻ thổi sáo cho đủ số».","chars":[{"c":"濫","h":"lạm"},{"c":"竽","h":"vu"},{"c":"充","h":"sung"},{"c":"数","h":"số"}],"poem":{"han":"三百吹竽隨衆奏／獨吹一曲客先逃","hv":"Tam bách xuy vu tùy chúng tấu / Độc xuy nhất khúc khách tiên đào","vi":"Ba trăm người thổi sáo, theo đám đông mà tấu; đến lượt độc tấu, người khách chạy trước."},"example":"実力がないのに濫竽充数で採用された。","example_reading":"じつりょくがないのにらんうじゅうすうでさいようされた。","example_meaning":"Không có thực lực mà vẫn được nhận cho đủ số.","examples":[{"example":"実力がないのに濫竽充数で採用された。","example_reading":"じつりょくがないのにらんうじゅうすうでさいようされた。","example_meaning":"Không có thực lực mà vẫn được nhận cho đủ số."},{"example":"名ばかりの委員が濫竽充数を果たしているだけだ。","example_reading":"なばかりのいいんがらんうじゅうすうをはたしているだけだ。","example_meaning":"Các ủy viên chỉ có danh, chẳng khác kẻ thổi sáo cho đủ số."}],"level":"p1"},
{"word":"縁木求魚","reading":"えんぼくきゅうぎょ","meaning":"trèo cây tìm cá; dùng cách sai thì không bao giờ đạt được mục đích.","hanviet":"duyên mộc cầu ngư","note":"📜 Lịch sử: Mạnh Tử - Lương Huệ vương thượng: Mạnh Tử nói với Tề Tuyên vương rằng nếu muốn làm bá chủ mà dựa vào chiến tranh thì chẳng khác trèo cây tìm cá; tìm cá trên cây thì thôi, nhưng làm thế sẽ rước tai họa lớn. 💡 Thú vị: Tiếng Nhật đọc theo lối văn ngôn là 木に縁りて魚を求む.","chars":[{"c":"縁","h":"duyên"},{"c":"木","h":"mộc"},{"c":"求","h":"cầu"},{"c":"魚","h":"ngư"}],"poem":{"han":"緣木求魚終不得／錯途何日達初衷","hv":"Duyên mộc cầu ngư chung bất đắc / Thác đồ hà nhật đạt sơ trung","vi":"Trèo cây tìm cá rốt chẳng được; đi nhầm đường, bao giờ đạt chí ban đầu."},"example":"その方法で成果を求めるのは縁木求魚だ。","example_reading":"そのほうほうでせいかをもとめるのはえんぼくきゅうぎょだ。","example_meaning":"Tìm thành quả bằng cách đó là trèo cây tìm cá.","examples":[{"example":"その方法で成果を求めるのは縁木求魚だ。","example_reading":"そのほうほうでせいかをもとめるのはえんぼくきゅうぎょだ。","example_meaning":"Tìm thành quả bằng cách đó là trèo cây tìm cá."},{"example":"安易な近道では縁木求魚に終わる。","example_reading":"あんいなちかみちではえんぼくきゅうぎょにおわる。","example_meaning":"Đi đường tắt dễ dãi sẽ chỉ như trèo cây tìm cá."}],"level":"p1"},
{"word":"浩然之気","reading":"こうぜんのき","meaning":"khí hạo nhiên; khí phách chính trực, rộng lớn của người quân tử.","hanviet":"hạo nhiên chi khí","note":"📜 Lịch sử: Mạnh Tử - Công Tôn Sửu thượng: Mạnh Tử nói «ta khéo nuôi hạo nhiên chi khí», giải thích đó là thứ khí cực lớn cực mạnh, nuôi bằng chính trực mà không làm hại thì đầy khắp trời đất, phải đi cùng nghĩa và đạo. 💡 Thú vị: Trong tiếng Nhật, 浩然の気を養う ngày nay còn có nghĩa là thư giãn, hít thở không khí thoáng đãng cho tâm hồn khoáng đạt.","chars":[{"c":"浩","h":"hạo"},{"c":"然","h":"nhiên"},{"c":"之","h":"chi"},{"c":"気","h":"khí"}],"poem":{"han":"至大至剛塞天地／以直養之氣自充","hv":"Chí đại chí cương tắc thiên địa / Dĩ trực dưỡng chi khí tự sung","vi":"Rất lớn rất mạnh, đầy khắp trời đất; lấy chính trực mà nuôi thì khí tự đầy."},"example":"山に登って浩然の気を養った。","example_reading":"やまにのぼってこうぜんのきをやしなった。","example_meaning":"Tôi leo núi để thư thái, nuôi dưỡng tâm khí.","examples":[{"example":"山に登って浩然の気を養った。","example_reading":"やまにのぼってこうぜんのきをやしなった。","example_meaning":"Tôi leo núi để thư thái, nuôi dưỡng tâm khí."},{"example":"彼は浩然の気に満ちた立派な人物だ。","example_reading":"かれはこうぜんのきにみちたりっぱなじんぶつだ。","example_meaning":"Ông ấy là người đầy chính khí, đáng kính."}],"level":"p1"},
{"word":"君子不器","reading":"くんしはうつわならず","meaning":"quân tử không như đồ dùng; người quân tử không chỉ giỏi một việc mà toàn diện, linh hoạt.","hanviet":"quân tử bất khí","note":"📜 Lịch sử: Luận ngữ - Vi chính: «Quân tử bất khí» (君子不器). «Khí» là đồ dùng, mỗi thứ chỉ dùng cho một việc; quân tử là người có đức, trí rộng, dùng được trong nhiều việc. 💡 Thú vị: Trong Luận ngữ - Công Dã Tràng, Khổng Tử từng ví Tử Cống là «hồ liễn» (đồ quý dùng trong cúng tế), nghĩa là vẫn là một «khí» đáng quý nhưng chưa phải bậc quân tử toàn diện.","chars":[{"c":"君","h":"quân"},{"c":"子","h":"tử"},{"c":"不","h":"bất"},{"c":"器","h":"khí"}],"poem":{"han":"器各一用難周備／君子通才應萬方","hv":"Khí các nhất dụng nan chu bị / Quân tử thông tài ứng vạn phương","vi":"Đồ vật mỗi cái một dụng, khó đủ mọi việc; quân tử thông tài, ứng được muôn nơi."},"example":"専門に偏らず、君子不器を心がけて学んでいる。","example_reading":"せんもんにかたよらず、くんしふきをこころがけてまなんでいる。","example_meaning":"Tôi học không thiên lệch chuyên môn, hướng tới người toàn diện.","examples":[{"example":"専門に偏らず、君子不器を心がけて学んでいる。","example_reading":"せんもんにかたよらず、くんしふきをこころがけてまなんでいる。","example_meaning":"Tôi học không thiên lệch chuyên môn, hướng tới người toàn diện."},{"example":"君子不器というように、幅広い経験を積もう。","example_reading":"くんしふきというように、はばひろいけいけんをつもう。","example_meaning":"Như người ta nói quân tử không như đồ vật, hãy tích lũy trải nghiệm rộng."}],"level":"p1"},
{"word":"後生可畏","reading":"こうせいおそるべし","meaning":"lớp sau đáng sợ; người trẻ có thể vượt người đi trước, nên không được coi thường.","hanviet":"hậu sinh khả úy","note":"📜 Lịch sử: Luận ngữ - Tử Hãn: «Hậu sinh khả úy, yên tri lai giả chi bất như kim dã» (後生可畏、焉知來者之不如今也): người sinh sau đáng sợ, sao biết người đến sau không bằng người hiện nay? Nhưng nếu đến bốn mươi, năm mươi tuổi mà vẫn chưa có tiếng tăm thì cũng chẳng đáng sợ. 💡 Thú vị: Vế sau thường bị bỏ quên, nhưng chính nó nhắc rằng tiềm năng của người trẻ chỉ thành hiện thực khi họ nỗ lực.","chars":[{"c":"後","h":"hậu"},{"c":"生","h":"sinh"},{"c":"可","h":"khả"},{"c":"畏","h":"úy"}],"poem":{"han":"後生可畏英才起／四十無聞亦不足","hv":"Hậu sinh khả úy anh tài khởi / Tứ thập vô văn diệc bất túc","vi":"Hậu sinh đáng sợ vì anh tài nổi lên; bốn mươi tuổi vô danh thì cũng chẳng đáng sợ."},"example":"新人の成長ぶりに、後生畏るべしと感じた。","example_reading":"しんじんのせいちょうぶりに、こうせいおそるべしとかんじた。","example_meaning":"Thấy sự trưởng thành của người mới, tôi nhận ra lớp trẻ thật đáng gờm.","examples":[{"example":"新人の成長ぶりに、後生畏るべしと感じた。","example_reading":"しんじんのせいちょうぶりに、こうせいおそるべしとかんじた。","example_meaning":"Thấy sự trưởng thành của người mới, tôi nhận ra lớp trẻ thật đáng gờm."},{"example":"後生畏るべし、若手に負けないよう努力しよう。","example_reading":"こうせいおそるべし、わかてにまけないようどりょくしよう。","example_meaning":"Lớp trẻ đáng gờm, tôi sẽ cố gắng để không thua họ."}],"level":"p1"},
{"word":"上善若水","reading":"じょうぜんじゃくすい","meaning":"điều thiện cao nhất như nước; sống như nước, làm lợi cho vạn vật mà không tranh giành.","hanviet":"thượng thiện nhược thủy","note":"📜 Lịch sử: Lão Tử - chương 8: «Thượng thiện nhược thủy; thủy thiện lợi vạn vật nhi bất tranh, xử chúng nhân chi sở ố, cố cơ ư đạo» (上善若水，水善利萬物而不爭，處眾人之所惡，故幾於道): nước làm lợi cho vạn vật mà không tranh, ở nơi người ta chê (chỗ thấp), nên gần với Đạo. 💡 Thú vị: Một thương hiệu sake nổi tiếng của Nhật viết là 上善如水 với cùng ý nghĩa này.","chars":[{"c":"上","h":"thượng"},{"c":"善","h":"thiện"},{"c":"若","h":"nhược"},{"c":"水","h":"thủy"}],"poem":{"han":"水利萬物而不爭／處下居卑道自成","hv":"Thủy lợi vạn vật nhi bất tranh / Xử hạ cư ti đạo tự thành","vi":"Nước lợi cho vạn vật mà chẳng tranh; ở chỗ thấp, đạo tự nên."},"example":"上善若水を座右の銘に、柔軟に生きたい。","example_reading":"じょうぜんじゃくすいをざゆうのめいに、じゅうなんにいきたい。","example_meaning":"Lấy «thượng thiện nhược thủy» làm châm ngôn, tôi muốn sống mềm dẻo.","examples":[{"example":"上善若水を座右の銘に、柔軟に生きたい。","example_reading":"じょうぜんじゃくすいをざゆうのめいに、じゅうなんにいきたい。","example_meaning":"Lấy «thượng thiện nhược thủy» làm châm ngôn, tôi muốn sống mềm dẻo."},{"example":"争わず周囲を助ける姿は、まさに上善若水だ。","example_reading":"あらそわずしゅういをたすけるすがたは、まさにじょうぜんじゃくすいだ。","example_meaning":"Hình ảnh không tranh giành mà giúp mọi người đúng là thượng thiện nhược thủy."}],"level":"p1"},
{"word":"庖丁解牛","reading":"ほうていかいぎゅう","meaning":"đầu bếp Đinh mổ trâu; kỹ thuật điêu luyện đến mức thuận theo quy luật tự nhiên.","hanviet":"bào đinh giải ngưu","note":"📜 Lịch sử: Trang Tử - Dưỡng sinh chủ: đầu bếp tên Đinh mổ trâu cho Văn Huệ quân, động tác nhịp nhàng, dao chạy theo khe xương, mười chín năm mổ mấy nghìn con mà lưỡi dao vẫn như mới mài. Ông nói: «Lúc đầu tôi thấy toàn con trâu, sau ba năm không còn thấy con trâu nguyên vẹn nữa». Văn Huệ quân nghe xong nói đã hiểu được đạo dưỡng sinh. 💡 Thú vị: Từ 包丁 (ほうちょう, dao làm bếp) trong tiếng Nhật bắt nguồn từ chữ 庖丁, tức «đầu bếp Đinh».","chars":[{"c":"庖","h":"bào"},{"c":"丁","h":"đinh"},{"c":"解","h":"giải"},{"c":"牛","h":"ngưu"}],"poem":{"han":"目無全牛神遇刃／遊刃有餘十九年","hv":"Mục vô toàn ngưu thần ngộ nhận / Du nhận hữu dư thập cửu niên","vi":"Mắt không thấy trâu nguyên con, thần gặp lưỡi dao; lưỡi dao thong dong còn dư suốt mười chín năm."},"example":"職人の庖丁解牛のような手際に見とれた。","example_reading":"しょくにんのほうていかいぎゅうのようなてぎわにみとれた。","example_meaning":"Tôi nhìn say mê tay nghề điêu luyện như đầu bếp Đinh của người thợ.","examples":[{"example":"職人の庖丁解牛のような手際に見とれた。","example_reading":"しょくにんのほうていかいぎゅうのようなてぎわにみとれた。","example_meaning":"Tôi nhìn say mê tay nghề điêu luyện như đầu bếp Đinh của người thợ."},{"example":"熟練の技はまさに庖丁解牛の域に達している。","example_reading":"じゅくれんのわざはまさにほうていかいぎゅうのいきにたっしている。","example_meaning":"Kỹ thuật thành thạo đã đạt tới mức của đầu bếp Đinh."}],"level":"p1"},
{"word":"良薬苦口","reading":"りょうやくくちににがし","meaning":"thuốc hay đắng miệng; lời khuyên chân thành thường khó nghe.","hanviet":"lương dược khổ khẩu","note":"📜 Lịch sử: Sử ký - Lưu hầu thế gia: Trương Lương khuyên Lưu Bang: «Thuốc hay đắng miệng nhưng lợi cho bệnh, lời ngay trái tai nhưng lợi cho việc làm» (良藥苦於口而利於病，忠言逆於耳而利於行). Lúc ấy Lưu Bang vào Hàm Dương, mê cung điện và mỹ nữ, nhờ Phàn Khoái và Trương Lương can mà chịu rút về Bá Thượng. 💡 Thú vị: Câu này cũng xuất hiện trong Khổng tử gia ngữ.","chars":[{"c":"良","h":"lương"},{"c":"薬","h":"dược"},{"c":"苦","h":"khổ"},{"c":"口","h":"khẩu"}],"poem":{"han":"良藥苦口能利病／忠言逆耳可匡身","hv":"Lương dược khổ khẩu năng lợi bệnh / Trung ngôn nghịch nhĩ khả khuông thân","vi":"Thuốc hay đắng miệng chữa được bệnh; lời ngay trái tai giúp sửa mình."},"example":"上司の厳しい指摘は良薬口に苦しだ。","example_reading":"じょうしのきびしいしてきはりょうやくくちににがしだ。","example_meaning":"Lời chỉ ra nghiêm khắc của sếp là thuốc đắng dã tật.","examples":[{"example":"上司の厳しい指摘は良薬口に苦しだ。","example_reading":"じょうしのきびしいしてきはりょうやくくちににがしだ。","example_meaning":"Lời chỉ ra nghiêm khắc của sếp là thuốc đắng dã tật."},{"example":"良薬口に苦しというように、耳が痛い助言ほど役に立つ。","example_reading":"りょうやくくちににがしというように、みみがいたいじょげんほどやくにたつ。","example_meaning":"Như người ta nói thuốc hay đắng miệng, lời khuyên khó nghe lại càng có ích."}],"level":"p1"},
{"word":"傾城傾国","reading":"けいせいけいこく","meaning":"làm nghiêng thành, nghiêng nước; người đẹp tuyệt sắc khiến vua say mê mà mất nước.","hanviet":"khuynh thành khuynh quốc","note":"📜 Lịch sử: Hán thư - Ngoại thích truyện: nhạc sư Lý Diên Niên hát cho Hán Vũ Đế nghe: «Phương bắc có giai nhân, tuyệt thế mà đứng một mình, liếc một lần làm nghiêng thành, liếc lần hai làm nghiêng nước». Vũ Đế hỏi có người đẹp như thế không, công chúa Bình Dương nói đó là em gái Diên Niên, tức Lý phu nhân. 💡 Thú vị: Bài «Trường hận ca» của Bạch Cư Dị mở đầu bằng «Hán hoàng trọng sắc tư khuynh quốc», cũng dựa vào ý này.","chars":[{"c":"傾","h":"khuynh"},{"c":"城","h":"thành"},{"c":"傾","h":"khuynh"},{"c":"国","h":"quốc"}],"poem":{"han":"絕世佳人立北方／一顧傾城再傾邦","hv":"Tuyệt thế giai nhân lập bắc phương / Nhất cố khuynh thành tái khuynh bang","vi":"Giai nhân tuyệt thế đứng ở phương bắc; liếc một lần nghiêng thành, liếc lần nữa nghiêng nước."},"example":"彼女は傾城傾国と言われるほどの美女だった。","example_reading":"かのじょはけいせいけいこくといわれるほどのびじょだった。","example_meaning":"Cô ấy đẹp đến mức được gọi là nghiêng nước nghiêng thành.","examples":[{"example":"彼女は傾城傾国と言われるほどの美女だった。","example_reading":"かのじょはけいせいけいこくといわれるほどのびじょだった。","example_meaning":"Cô ấy đẹp đến mức được gọi là nghiêng nước nghiêng thành."},{"example":"傾城傾国の美女が歴史を動かすこともあった。","example_reading":"けいせいけいこくのびじょがれきしをうごかすこともあった。","example_meaning":"Có khi người đẹp nghiêng nước nghiêng thành lại làm thay đổi lịch sử."}],"level":"p1"},
{"word":"破鏡重円","reading":"はきょうちょうえん","meaning":"gương vỡ lại tròn; vợ chồng chia lìa rồi đoàn tụ.","hanviet":"phá kính trùng viên","note":"📜 Lịch sử: Bản sự thi (Mạnh Khải, đời Đường): Từ Đức Ngôn, phò mã nhà Trần, biết nước sắp mất bèn bẻ chiếc gương làm đôi, hẹn vợ là công chúa Nhạc Xương mỗi người giữ một nửa, rằm tháng giêng sẽ đem nửa gương ra chợ bán làm tín. Nhà Trần mất, công chúa bị ban cho Dương Tố; Đức Ngôn lên kinh, gặp người bán nửa gương, ghép lại vừa khít, đề thơ. Dương Tố cảm động trả công chúa cho ông. 💡 Thú vị: Tiếng Việt có câu «gương vỡ lại lành» cùng ý.","chars":[{"c":"破","h":"phá"},{"c":"鏡","h":"kính"},{"c":"重","h":"trùng"},{"c":"円","h":"viên"}],"poem":{"han":"破鏡分藏期上元／重圓一夕淚潸然","hv":"Phá kính phân tàng kỳ thượng nguyên / Trùng viên nhất tịch lệ san nhiên","vi":"Gương vỡ chia giữ hẹn rằm tháng giêng; một đêm đoàn tụ, lệ rơi."},"example":"長い別居の末、二人は破鏡重円を果たした。","example_reading":"ながいべっきょのすえ、ふたりははきょうちょうえんをはたした。","example_meaning":"Sau thời gian dài ly thân, hai người đã hàn gắn trở lại.","examples":[{"example":"長い別居の末、二人は破鏡重円を果たした。","example_reading":"ながいべっきょのすえ、ふたりははきょうちょうえんをはたした。","example_meaning":"Sau thời gian dài ly thân, hai người đã hàn gắn trở lại."},{"example":"喧嘩別れした友人と破鏡重円できて嬉しい。","example_reading":"けんかわかれしたゆうじんとはきょうちょうえんできてうれしい。","example_meaning":"Tôi vui vì hàn gắn lại được với người bạn từng cãi nhau chia tay."}],"level":"p1"},
{"word":"泣斬馬謖","reading":"きゅうざんばしょく","meaning":"rơi nước mắt chém Mã Tốc; vì kỷ luật chung mà phải xử nghiêm cả người mình yêu quý.\n(Tiếng Nhật: 泣いて馬謖を斬る.)","hanviet":"khấp trảm Mã Tốc","note":"📜 Lịch sử: Tam quốc chí - Thục thư (Mã Lương truyện): trong lần Bắc phạt đầu tiên (năm 228), Mã Tốc được Gia Cát Lượng giao giữ Nhai Đình nhưng trái lệnh, bỏ nguồn nước đóng quân trên núi, bị Trương Cáp vây đánh đại bại. Lượng khóc mà xử trảm Mã Tốc, đồng thời tự giáng chức vì dùng người sai. 💡 Thú vị: Mã Tốc là người Lượng rất quý trọng, nên câu này trở thành hình mẫu của việc giữ kỷ luật công bằng bất chấp tình riêng.","chars":[{"c":"泣","h":"khấp"},{"c":"斬","h":"trảm"},{"c":"馬","h":"Mã"},{"c":"謖","h":"Tốc"}],"poem":{"han":"街亭失守違軍令／揮淚誅親正國綱","hv":"Nhai Đình thất thủ vi quân lệnh / Huy lệ tru thân chính quốc cương","vi":"Nhai Đình thất thủ vì trái quân lệnh; gạt lệ giết người thân để giữ kỷ cương."},"example":"規律を守るため、泣いて馬謖を斬る決断をした。","example_reading":"きりつをまもるため、ないてばしょくをきるけつだんをした。","example_meaning":"Để giữ kỷ luật, tôi quyết định xử nghiêm dù đau lòng.","examples":[{"example":"規律を守るため、泣いて馬謖を斬る決断をした。","example_reading":"きりつをまもるため、ないてばしょくをきるけつだんをした。","example_meaning":"Để giữ kỷ luật, tôi quyết định xử nghiêm dù đau lòng."},{"example":"部下の不正を、泣いて馬謖を斬る思いで処分した。","example_reading":"ぶかのふせいを、ないてばしょくをきるおもいでしょぶんした。","example_meaning":"Tôi xử lý gian lận của cấp dưới với tâm trạng rơi nước mắt."}],"level":"p1"},
{"word":"鞠躬尽瘁","reading":"きっきゅうじんすい","meaning":"cúi mình hết sức, tận tụy đến chết.","hanviet":"cúc cung tận tụy","note":"📜 Lịch sử: Hậu xuất sư biểu của Gia Cát Lượng (dù tính xác thực của văn bản còn bị tranh luận): «Thần cúc cung tận lực, tử nhi hậu dĩ» (臣鞠躬盡力，死而後已), nghĩa là cúi mình dốc hết sức, chết rồi mới thôi. Dạng 盡瘁 là cách nói về sau. 💡 Thú vị: Gia Cát Lượng mất năm 234 ở Ngũ Trượng Nguyên ngay trong cuộc Bắc phạt, đúng như «chết rồi mới thôi».","chars":[{"c":"鞠","h":"cúc"},{"c":"躬","h":"cung"},{"c":"尽","h":"tận"},{"c":"瘁","h":"tụy"}],"poem":{"han":"鞠躬盡瘁輔幼主／五丈原頭星墜時","hv":"Cúc cung tận tụy phụ ấu chủ / Ngũ Trượng nguyên đầu tinh trụy thời","vi":"Cúc cung tận tụy phò ấu chúa; trên đồng Ngũ Trượng lúc sao rụng."},"example":"彼は会社のために鞠躬尽瘁して働いてきた。","example_reading":"かれはかいしゃのためにきっきゅうじんすいしてはたらいてきた。","example_meaning":"Ông ấy đã làm việc tận tụy hết mình vì công ty.","examples":[{"example":"彼は会社のために鞠躬尽瘁して働いてきた。","example_reading":"かれはかいしゃのためにきっきゅうじんすいしてはたらいてきた。","example_meaning":"Ông ấy đã làm việc tận tụy hết mình vì công ty."},{"example":"鞠躬尽瘁の姿勢に、周囲は頭が下がった。","example_reading":"きっきゅうじんすいのしせいに、しゅういはあたまがさがった。","example_meaning":"Thái độ tận tụy khiến mọi người đều khâm phục."}],"level":"p1"},
{"word":"高山流水","reading":"こうざんりゅうすい","meaning":"núi cao nước chảy; tri âm tri kỷ; cũng chỉ khúc nhạc tuyệt diệu.","hanviet":"cao sơn lưu thủy","note":"📜 Lịch sử: Liệt Tử - Thang vấn: Bá Nha gảy đàn, ý nghĩ về núi cao thì Chung Tử Kỳ khen «nguy nga như núi Thái Sơn», ý nghĩ về dòng nước thì Tử Kỳ khen «mênh mông như sông Giang, sông Hà». 💡 Thú vị: Tử Kỳ chết, Bá Nha bẻ đàn không gảy nữa (伯牙絶絃), và từ «tri âm» (知音) cũng từ đây mà ra.","chars":[{"c":"高","h":"cao"},{"c":"山","h":"sơn"},{"c":"流","h":"lưu"},{"c":"水","h":"thủy"}],"poem":{"han":"志在高山鍾子賞／心存流水解弦音","hv":"Chí tại cao sơn Chung tử thưởng / Tâm tồn lưu thủy giải huyền âm","vi":"Chí ở núi cao, Tử Kỳ khen; lòng nghĩ dòng nước, hiểu tiếng đàn."},"example":"彼とは高山流水の友だ。","example_reading":"かれとはこうざんりゅうすいのともだ。","example_meaning":"Tôi và anh ấy là bạn tri âm tri kỷ.","examples":[{"example":"彼とは高山流水の友だ。","example_reading":"かれとはこうざんりゅうすいのともだ。","example_meaning":"Tôi và anh ấy là bạn tri âm tri kỷ."},{"example":"琴の調べに高山流水の趣があった。","example_reading":"ことのしらべにこうざんりゅうすいのおもむきがあった。","example_meaning":"Tiếng đàn có nét núi cao nước chảy."}],"level":"p1"},
{"word":"守株待兎","reading":"しゅしゅたいと","meaning":"ôm cây đợi thỏ; trông chờ may rủi, không chịu thay đổi cách làm.\n(Chê người bảo thủ, cứ bám vào một thành công ngẫu nhiên trong quá khứ.)","hanviet":"thủ chu đãi thố","note":"📜 Lịch sử: Hàn Phi Tử - Ngũ đố: một nông dân nước Tống thấy con thỏ chạy đâm vào gốc cây chết, bèn bỏ cày ngồi canh gốc cây chờ thỏ, rồi bị cả nước cười. Hàn Phi dùng chuyện này để chê kẻ cứ muốn theo phép của vua xưa mà không biết thời thế đã đổi. 💡 Thú vị: Người nước Tống là 'nhân vật hề' quen thuộc trong ngụ ngôn thời Tiên Tần (như chuyện nhổ mạ cho cao 揠苗助長). Trong tiếng Nhật, chữ 株 (kabu) còn có nghĩa 'cổ phiếu', nên có người đùa 'giữ cổ phiếu chờ lên giá' cũng là 守株.","chars":[{"c":"守","h":"thủ"},{"c":"株","h":"chu"},{"c":"待","h":"đãi"},{"c":"兎","h":"thố"}],"poem":{"han":"宋人荷耒守枯株／日日空看野兔趨","hv":"Tống nhân hà lỗi thủ khô chu / Nhật nhật không khan dã thố xu","vi":"Người Tống vác cày đứng giữ gốc cây khô, ngày ngày chỉ ngóng thỏ rừng chạy qua."},"example":"運に頼るだけでは守株待兎だ。努力しよう。","example_reading":"うんにたよるだけではしゅしゅたいとだ。どりょくしよう。","example_meaning":"Chỉ trông vào vận may thì thành ôm cây đợi thỏ. Hãy nỗ lực.","examples":[{"example":"運に頼るだけでは守株待兎だ。努力しよう。","example_reading":"うんにたよるだけではしゅしゅたいとだ。どりょくしよう。","example_meaning":"Chỉ trông vào vận may thì thành ôm cây đợi thỏ. Hãy nỗ lực."},{"example":"昔の成功に頼る経営は、守株待兎に近い。","example_reading":"むかしのせいこうにたよるけいえいは、しゅしゅたいとにちかい。","example_meaning":"Cách kinh doanh dựa vào thành công cũ gần như là ôm cây đợi thỏ."}],"level":"p2"},
{"word":"鶏口牛後","reading":"けいこうぎゅうご","meaning":"thà làm đầu gà còn hơn làm đuôi trâu; thà đứng đầu nhóm nhỏ còn hơn đứng cuối nhóm lớn.\n(Dùng khi cân nhắc giữa 'đầu gà nhỏ' và 'đuôi trâu lớn'.)","hanviet":"kê khẩu ngưu hậu","note":"📜 Lịch sử: Sử ký - Tô Tần liệt truyện (Chiến quốc sách cũng có): Tô Tần thuyết phục vua Hàn đừng thần phục nước Tần hùng mạnh, bằng câu «thà làm miệng gà, đừng làm hậu môn trâu». 💡 Thú vị: Theo chú giải cổ, 牛後 vốn là hậu môn của trâu, cách nói thô hơn nhiều; tiếng Nhật làm nhẹ thành 'đuôi trâu'. Câu này gắn với kế «hợp tung» của Tô Tần, liên kết sáu nước chống Tần.","chars":[{"c":"鶏","h":"kê"},{"c":"口","h":"khẩu"},{"c":"牛","h":"ngưu"},{"c":"後","h":"hậu"}],"poem":{"han":"寧為雞口鳴天曉／莫作牛後隨衆行","hv":"Ninh vi kê khẩu minh thiên hiểu / Mạc tác ngưu hậu tùy chúng hành","vi":"Thà làm miệng gà gáy báo sáng, đừng làm đuôi trâu theo đám đông mà đi."},"example":"大企業の下っ端より小さな会社の社長。鶏口牛後の気持ちだ。","example_reading":"だいきぎょうのしたっぱよりちいさなかいしゃのしゃちょう。けいこうぎゅうごのきもちだ。","example_meaning":"Thà làm giám đốc công ty nhỏ còn hơn nhân viên quèn ở tập đoàn lớn; đúng là tâm thế đầu gà hơn đuôi trâu.","examples":[{"example":"大企業の下っ端より小さな会社の社長。鶏口牛後の気持ちだ。","example_reading":"だいきぎょうのしたっぱよりちいさなかいしゃのしゃちょう。けいこうぎゅうごのきもちだ。","example_meaning":"Thà làm giám đốc công ty nhỏ còn hơn nhân viên quèn ở tập đoàn lớn; đúng là tâm thế đầu gà hơn đuôi trâu."},{"example":"鶏口牛後というが、大きな組織で学ぶ価値もある。","example_reading":"けいこうぎゅうごというが、おおきなそしきでまなぶかちもある。","example_meaning":"Tuy nói thà làm đầu gà, nhưng học trong tổ chức lớn cũng có giá trị."}],"level":"p2"},
{"word":"虎視眈々（虎視眈眈）","reading":"こしたんたん","meaning":"hổ nhìn chằm chằm; âm thầm rình thời cơ để ra tay.\n(Dùng cho người, tổ chức đang chờ cơ hội giành lấy vị trí, mục tiêu.)","hanviet":"hổ thị đam đam","note":"📜 Lịch sử: Kinh Dịch - quẻ Di, hào lục tứ: «hổ thị đam đam, kỳ dục trục trục, vô cữu» (hổ nhìn đăm đăm, lòng muốn đuổi theo liên tục, nhưng không bị lỗi). 💡 Thú vị: Trong Kinh Dịch câu này mang nghĩa tốt: người ở địa vị cao nhìn xuống để nuôi dưỡng kẻ dưới. Về sau mới đổi sang nghĩa 'rình mồi' và hay đi với động từ 狙う (nhắm tới) như 首位を虎視眈々と狙う.","chars":[{"c":"虎","h":"hổ"},{"c":"視","h":"thị"},{"c":"眈","h":"đam"},{"c":"眈","h":"đam"}],"poem":{"han":"眈眈虎視伺風動／一躍乘時出翠嵐","hv":"Đam đam hổ thị tứ phong động / Nhất dược thừa thời xuất thúy lam","vi":"Hổ nhìn chằm chằm rình lúc gió động, một cú vọt nhân thời cơ lao ra khỏi làn khói núi."},"example":"彼は社長の座を虎視眈々と狙っている。","example_reading":"かれはしゃちょうのざをこしたんたんとねらっている。","example_meaning":"Anh ta đang âm thầm rình chiếc ghế giám đốc.","examples":[{"example":"彼は社長の座を虎視眈々と狙っている。","example_reading":"かれはしゃちょうのざをこしたんたんとねらっている。","example_meaning":"Anh ta đang âm thầm rình chiếc ghế giám đốc."},{"example":"優勝候補は、虎視眈々とチャンスを待っていた。","example_reading":"ゆうしょうこうほは、こしたんたんとチャンスをまっていた。","example_meaning":"Ứng viên vô địch đang lặng lẽ chờ cơ hội."}],"level":"p2"},
{"word":"玉石混交","reading":"ぎょくせきこんこう","meaning":"ngọc lẫn với đá; vật quý và vật tầm thường, thật và giả lẫn lộn.\n(Dùng cho thông tin, nhân tài, sản phẩm có tốt có xấu lẫn nhau.)","hanviet":"ngọc thạch hỗn giao","note":"📜 Lịch sử: Bão Phác Tử - Ngoại thiên (Cát Hồng, thời Tấn): «chân ngụy điên đảo, ngọc thạch đồng quỹ» (thật giả đảo lộn, ngọc và đá để chung một hòm). 💡 Thú vị: Tiếng Nhật có hai cách viết 玉石混交 và 玉石混淆; 混交 là dạng được dùng rộng hơn. Cụm này hay xuất hiện khi nói về thông tin trên Internet (ネットの情報は玉石混交).","chars":[{"c":"玉","h":"ngọc"},{"c":"石","h":"thạch"},{"c":"混","h":"hỗn"},{"c":"交","h":"giao"}],"poem":{"han":"玉石同匱真偽雜／披沙揀得一珠光","hv":"Ngọc thạch đồng quỹ chân ngụy tạp / Phi sa giản đắc nhất châu quang","vi":"Ngọc đá chung một hòm, thật giả lẫn lộn; gạn cát mới lượm được một hạt sáng."},"example":"ネットの情報は玉石混交だから、注意が必要だ。","example_reading":"ネットのじょうほうはぎょくせきこんこうだから、ちゅういがひつようだ。","example_meaning":"Thông tin trên mạng thật giả lẫn lộn nên cần cẩn thận.","examples":[{"example":"ネットの情報は玉石混交だから、注意が必要だ。","example_reading":"ネットのじょうほうはぎょくせきこんこうだから、ちゅういがひつようだ。","example_meaning":"Thông tin trên mạng thật giả lẫn lộn nên cần cẩn thận."},{"example":"応募者は玉石混交で、選ぶのが大変だった。","example_reading":"おうぼしゃはぎょくせきこんこうで、えらぶのがたいへんだった。","example_meaning":"Ứng viên có người giỏi người kém lẫn lộn nên chọn rất vất vả."}],"level":"p2"},
{"word":"天衣無縫","reading":"てんいむほう","meaning":"áo tiên không đường may; hồn nhiên, tự nhiên, hoàn mỹ không chút gượng ép.\n(Khen tính cách ngây thơ thẳng thắn hoặc văn chương, tác phẩm hoàn hảo không dấu đẽo gọt.)","hanviet":"thiên y vô phùng","note":"📜 Lịch sử: Thái bình quảng ký (dẫn «Linh quái lục»): Quách Hãn gặp Chức Nữ từ trời xuống, thấy áo nàng không có đường kim mũi chỉ; nàng đáp «áo trời vốn không phải dùng kim chỉ mà thành». 💡 Thú vị: Nghĩa gốc nói về sự hoàn hảo không dấu vết; tiếng Nhật mở rộng sang tính cách hồn nhiên không toan tính (天衣無縫な人柄). Đây còn là chữ nằm trong tên nhiều tác phẩm văn học và truyện tranh.","chars":[{"c":"天","h":"thiên"},{"c":"衣","h":"y"},{"c":"無","h":"vô"},{"c":"縫","h":"phùng"}],"poem":{"han":"織女衣成無線跡／渾然天巧不由針","hv":"Chức Nữ y thành vô tuyến tích / Hồn nhiên thiên xảo bất do châm","vi":"Áo Chức Nữ may xong không dấu chỉ, khéo léo tự nhiên như trời, chẳng nhờ kim."},"example":"彼女の天衣無縫な笑顔に、みんなが元気づけられた。","example_reading":"かのじょのてんいむほうなえがおに、みんながげんきづけられた。","example_meaning":"Nụ cười hồn nhiên của cô ấy tiếp thêm sức sống cho mọi người.","examples":[{"example":"彼女の天衣無縫な笑顔に、みんなが元気づけられた。","example_reading":"かのじょのてんいむほうなえがおに、みんながげんきづけられた。","example_meaning":"Nụ cười hồn nhiên của cô ấy tiếp thêm sức sống cho mọi người."},{"example":"この詩は天衣無縫で、技巧の跡が全く見えない。","example_reading":"このしはてんいむほうで、ぎこうのあとがまったくみえない。","example_meaning":"Bài thơ này tự nhiên không chút gò ép, chẳng thấy dấu vết gọt giũa."}],"level":"p2"},
{"word":"付和雷同","reading":"ふわらいどう","meaning":"theo số đông một cách mù quáng, không có chính kiến.\n(Chê người a dua, thấy người ta nói gì thì nói theo.)","hanviet":"phụ họa lôi đồng","note":"📜 Lịch sử: Chữ 雷同 có từ Lễ ký - Khúc lễ thượng: «vô tiễu thuyết, vô lôi đồng» (đừng chép lời người khác, đừng ứng theo như sấm). Sấm vang thì muôn vật cùng ứng, nên 'lôi đồng' là hùa theo. 💡 Thú vị: Chữ 付和 (bám theo, hùa theo) được ghép thêm về sau để nhấn mạnh sự a dua. Ngày nay người Nhật hay dùng nó khi nói về tâm lý đám đông trên mạng xã hội.","chars":[{"c":"付","h":"phụ"},{"c":"和","h":"họa"},{"c":"雷","h":"lôi"},{"c":"同","h":"đồng"}],"poem":{"han":"雷動萬物同響應／無端隨衆失其真","hv":"Lôi động vạn vật đồng hưởng ứng / Vô đoan tùy chúng thất kỳ chân","vi":"Sấm động muôn vật cùng vang theo; vô cớ theo số đông mà mất cái chân thật của mình."},"example":"周りに付和雷同せず、自分の意見を持とう。","example_reading":"まわりにふわらいどうせず、じぶんのいけんをもとう。","example_meaning":"Đừng a dua theo xung quanh, hãy có chính kiến của mình.","examples":[{"example":"周りに付和雷同せず、自分の意見を持とう。","example_reading":"まわりにふわらいどうせず、じぶんのいけんをもとう。","example_meaning":"Đừng a dua theo xung quanh, hãy có chính kiến của mình."},{"example":"SNSの噂に付和雷同して、人を責めてはいけない。","example_reading":"エスエヌエスのうわさにふわらいどうして、ひとをせめてはいけない。","example_meaning":"Không nên a dua theo tin đồn trên mạng xã hội mà chỉ trích người khác."}],"level":"p2"},
{"word":"内憂外患","reading":"ないゆうがいかん","meaning":"lo bên trong, họa bên ngoài; khó khăn chồng chất cả trong lẫn ngoài.\n(Dùng cho quốc gia, tổ chức vừa rối loạn nội bộ vừa bị áp lực từ bên ngoài.)","hanviet":"nội ưu ngoại hoạn","note":"📜 Lịch sử: Quốc ngữ - Tấn ngữ (lời Phạm Văn Tử, thời Xuân Thu): «ngoại ninh tất hữu nội ưu» (ngoài yên thì trong ắt có lo). Ông khuyên cứ để lại một mối đe dọa bên ngoài để người trong nước còn biết đề phòng. 💡 Thú vị: Sau này cụm từ thường gắn với cuối đời Thanh và cuối Mạc phủ Edo, khi Nhật cũng vừa rối ren trong nước vừa chịu sức ép từ 'tàu đen' phương Tây (内憂外患の時代).","chars":[{"c":"内","h":"nội"},{"c":"憂","h":"ưu"},{"c":"外","h":"ngoại"},{"c":"患","h":"hoạn"}],"poem":{"han":"外寧必有內憂在／四境雖安未可眠","hv":"Ngoại ninh tất hữu nội ưu tại / Tứ cảnh tuy an vị khả miên","vi":"Ngoài yên ắt có lo bên trong; bốn cõi tuy yên vẫn chưa thể ngủ ngon."},"example":"その国は内憂外患で、政治が不安定だ。","example_reading":"そのくにはないゆうがいかんで、せいじがふあんていだ。","example_meaning":"Nước đó vừa rối loạn trong vừa bị áp lực ngoài, chính trị bất ổn.","examples":[{"example":"その国は内憂外患で、政治が不安定だ。","example_reading":"そのくにはないゆうがいかんで、せいじがふあんていだ。","example_meaning":"Nước đó vừa rối loạn trong vừa bị áp lực ngoài, chính trị bất ổn."},{"example":"経営不振と新規参入が重なり、会社は内憂外患の状況だ。","example_reading":"けいえいふしんとしんきさんにゅうがかさなり、かいしゃはないゆうがいかんのじょうきょうだ。","example_meaning":"Kinh doanh sa sút lại thêm đối thủ mới, công ty rơi vào cảnh trong lo ngoài họa."}],"level":"p2"},
{"word":"沈魚落雁","reading":"ちんぎょらくがん","meaning":"cá thấy phải chìm, nhạn thấy phải rơi; vẻ đẹp tuyệt sắc của người phụ nữ.\n(Dùng để tả mỹ nhân đẹp đến mức khiến muôn vật say mê.)","hanviet":"trầm ngư lạc nhạn","note":"📜 Lịch sử: Trang Tử - Tề vật luận: «Mao Tường, Ly Cơ, người đời cho là đẹp; cá thấy thì lặn sâu, chim thấy thì bay cao». 💡 Thú vị: Ý Trang Tử lại ngược hẳn: cá chim sợ chứ không mê, để nói 'đẹp hay không là tùy phía nhìn'. Về sau người đời gán ra «tứ đại mỹ nhân»: Tây Thi (trầm ngư), Vương Chiêu Quân (lạc nhạn), Điêu Thuyền (bế nguyệt), Dương Quý Phi (tu hoa).","chars":[{"c":"沈","h":"trầm"},{"c":"魚","h":"ngư"},{"c":"落","h":"lạc"},{"c":"雁","h":"nhạn"}],"poem":{"han":"西子臨溪魚影沒／昭君出塞雁行低","hv":"Tây Tử lâm khê ngư ảnh một / Chiêu Quân xuất tái nhạn hàng đê","vi":"Tây Thi bên suối, bóng cá chìm; Chiêu Quân ra ải, đàn nhạn bay thấp xuống."},"example":"沈魚落雁の美女と評判の女優だ。","example_reading":"ちんぎょらくがんのびじょとひょうばんのじょゆうだ。","example_meaning":"Cô diễn viên nổi tiếng là mỹ nhân sắc nước hương trời.","examples":[{"example":"沈魚落雁の美女と評判の女優だ。","example_reading":"ちんぎょらくがんのびじょとひょうばんのじょゆうだ。","example_meaning":"Cô diễn viên nổi tiếng là mỹ nhân sắc nước hương trời."},{"example":"昔の詩では、美しい女性を沈魚落雁と表現した。","example_reading":"むかしのしでは、うつくしいじょせいをちんぎょらくがんとひょうげんした。","example_meaning":"Trong thơ xưa, người ta ví phụ nữ đẹp là trầm ngư lạc nhạn."}],"level":"p2"},
{"word":"羊頭狗肉","reading":"ようとうくにく","meaning":"treo đầu dê bán thịt chó; bề ngoài đẹp đẽ nhưng bên trong không xứng.\n(Dùng khi quảng cáo, danh nghĩa không đúng với thực chất.)","hanviet":"dương đầu cẩu nhục","note":"📜 Lịch sử: Gốc ở «Yến tử xuân thu»: vua Tề Linh Công cấm phụ nữ mặc đồ nam, Yến Tử ví việc ấy như «treo đầu bò ngoài cửa mà bán thịt ngựa bên trong». Sau đó sách nhà Thiền thời Tống (như Vô Môn quan) đổi thành «đầu dê thịt chó». 💡 Thú vị: Tiếng Nhật 羊頭狗肉 theo dạng đầu dê thịt chó. Tiếng Việt có hẳn thành ngữ tương ứng «treo đầu dê bán thịt chó», rất dễ nhớ.","chars":[{"c":"羊","h":"dương"},{"c":"頭","h":"đầu"},{"c":"狗","h":"cẩu"},{"c":"肉","h":"nhục"}],"poem":{"han":"門懸羊首誇良品／案上所陳實犬肉","hv":"Môn huyền dương thủ khoa lương phẩm / Án thượng sở trần thực khuyển nhục","vi":"Treo đầu dê trước cửa khoe hàng tốt, mà thứ bày trên mâm thực ra là thịt chó."},"example":"広告は立派だが、中身は羊頭狗肉だった。","example_reading":"こうこくはりっぱだが、なかみはようとうくにくだった。","example_meaning":"Quảng cáo hoành tráng nhưng bên trong treo đầu dê bán thịt chó.","examples":[{"example":"広告は立派だが、中身は羊頭狗肉だった。","example_reading":"こうこくはりっぱだが、なかみはようとうくにくだった。","example_meaning":"Quảng cáo hoành tráng nhưng bên trong treo đầu dê bán thịt chó."},{"example":"高級店と言いながら味は普通とは、羊頭狗肉だ。","example_reading":"こうきゅうてんといいながらあじはふつうとは、ようとうくにくだ。","example_meaning":"Nói là tiệm cao cấp mà vị bình thường, đúng là treo đầu dê bán thịt chó."}],"level":"p2"},
{"word":"君子豹変","reading":"くんしひょうへん","meaning":"quân tử đổi thay rõ rệt như vằn báo; bậc có đức biết sửa sai và thay đổi dứt khoát.\n(Ngày nay thường bị dùng với nghĩa tiêu cực: đột ngột trở mặt, đổi thái độ.)","hanviet":"quân tử báo biến","note":"📜 Lịch sử: Kinh Dịch - quẻ Cách, thượng lục: «quân tử báo biến, tiểu nhân cách diện». Vằn báo sau khi thay lông trở nên rực rỡ, nên quân tử sửa mình thì thay đổi rõ ràng, còn tiểu nhân chỉ đổi nét mặt bên ngoài. 💡 Thú vị: Nghĩa gốc là khen, nhưng ngày nay thường bị hiểu theo nghĩa xấu ('đổi thái độ chớp nhoáng'). Khi gặp trong văn viết hoặc báo chí, nên kiểm tra ngữ cảnh xem tác giả dùng nghĩa khen hay chê.","chars":[{"c":"君","h":"quân"},{"c":"子","h":"tử"},{"c":"豹","h":"báo"},{"c":"変","h":"biến"}],"poem":{"han":"君子豹變文彪炳／小人革面順風移","hv":"Quân tử báo biến văn bưu bỉnh / Tiểu nhân cách diện thuận phong di","vi":"Quân tử đổi mình như báo, vằn vện rực rỡ; tiểu nhân chỉ đổi vẻ mặt, thuận gió mà dời."},"example":"君子豹変すというが、彼は誤りに気づいてすぐ方針を改めた。","example_reading":"くんしひょうへんすというが、かれはあやまりにきづいてすぐほうしんをあらためた。","example_meaning":"Người ta nói quân tử biết sửa mình; anh ấy nhận ra sai liền đổi phương châm.","examples":[{"example":"君子豹変すというが、彼は誤りに気づいてすぐ方針を改めた。","example_reading":"くんしひょうへんすというが、かれはあやまりにきづいてすぐほうしんをあらためた。","example_meaning":"Người ta nói quân tử biết sửa mình; anh ấy nhận ra sai liền đổi phương châm."},{"example":"選挙のあと君子豹変して、公約を変えた議員がいる。","example_reading":"せんきょのあとくんしひょうへんして、こうやくをかえたぎいんがいる。","example_meaning":"Có nghị sĩ sau bầu cử đột ngột trở mặt, thay đổi cam kết."}],"level":"p2"},
{"word":"酔生夢死","reading":"すいせいむし","meaning":"sống như say, chết như mơ; sống lơ mơ, uổng phí cả đời, không làm nên điều gì.\n(Chê lối sống buông thả, không mục đích.)","hanviet":"túy sinh mộng tử","note":"📜 Lịch sử: Xuất hiện trong ngữ lục của Nhị Trình thời Tống (tương truyền do Trình Hạo nói): ông than rằng nhiều người «túy sinh mộng tử», cả đời chẳng biết mình sống vì điều gì. 💡 Thú vị: Chữ 酔 và 夢 gợi hình ảnh nửa say nửa mơ. Ở Nhật, cụm này hay dùng trong lời răn dạy sinh viên: hãy sống có mục đích. Nó trái nghĩa với tinh thần 一生懸命.","chars":[{"c":"酔","h":"túy"},{"c":"生","h":"sinh"},{"c":"夢","h":"mộng"},{"c":"死","h":"tử"}],"poem":{"han":"醉裏光陰虛過日／夢中歲月不知秋","hv":"Túy lý quang âm hư quá nhật / Mộng trung tuế nguyệt bất tri thu","vi":"Say sưa, ngày tháng trôi qua vô ích; trong mộng năm tháng đi mà chẳng hay thu đến."},"example":"目標もなく酔生夢死の日々を送ってはいけない。","example_reading":"もくひょうもなくすいせいむしのひびをおくってはいけない。","example_meaning":"Không nên sống những ngày lơ mơ, không mục tiêu.","examples":[{"example":"目標もなく酔生夢死の日々を送ってはいけない。","example_reading":"もくひょうもなくすいせいむしのひびをおくってはいけない。","example_meaning":"Không nên sống những ngày lơ mơ, không mục tiêu."},{"example":"先生は、酔生夢死の人生にならないよう学生に語った。","example_reading":"せんせいは、すいせいむしのじんせいにならないようがくせいにかたった。","example_meaning":"Thầy nói với sinh viên đừng để cuộc đời trôi qua lơ mơ."}],"level":"p2"},
{"word":"琴瑟相和","reading":"きんしつそうわ","meaning":"đàn cầm đàn sắt hòa tiếng; vợ chồng hòa thuận, tình cảm êm đềm.\n(Hay dùng trong lời chúc đám cưới.)","hanviet":"cầm sắt tương hòa","note":"📜 Lịch sử: Kinh Thi - Tiểu nhã - Thường đệ: «thê tử hảo hợp, như cổ sắt cầm» (vợ con hòa hợp như tiếng đàn sắt đàn cầm cùng vang). 💡 Thú vị: Cầm (琴) là đàn dây ít hơn, sắt (瑟) là đàn lớn hơn nhiều dây; hai loại hợp tấu nghe rất êm nên thành biểu tượng của vợ chồng. Tiếng Nhật còn đọc là きんしつあいわす; cụm này rất hay gặp trong bài phát biểu đám cưới.","chars":[{"c":"琴","h":"cầm"},{"c":"瑟","h":"sắt"},{"c":"相","h":"tương"},{"c":"和","h":"hòa"}],"poem":{"han":"瑟鳴琴應調相協／白首同心樂有餘","hv":"Sắt minh cầm ứng điệu tương hiệp / Bạch thủ đồng tâm lạc hữu dư","vi":"Đàn sắt vang, đàn cầm đáp, điệu hòa hợp; đầu bạc vẫn đồng lòng, niềm vui còn dư."},"example":"ご両親は琴瑟相和の仲睦まじいご夫婦です。","example_reading":"ごりょうしんはきんしつそうわのなかむつまじいごふうふです。","example_meaning":"Bố mẹ bạn là cặp vợ chồng hòa thuận, đầm ấm.","examples":[{"example":"ご両親は琴瑟相和の仲睦まじいご夫婦です。","example_reading":"ごりょうしんはきんしつそうわのなかむつまじいごふうふです。","example_meaning":"Bố mẹ bạn là cặp vợ chồng hòa thuận, đầm ấm."},{"example":"琴瑟相和した五十年間だった。","example_reading":"きんしつそうわしたごじゅうねんかんだった。","example_meaning":"Năm mươi năm sống hòa thuận đầm ấm."}],"level":"p2"},
{"word":"天網恢恢","reading":"てんもうかいかい","meaning":"lưới trời rộng lớn, thưa mà không lọt; kẻ ác khó thoát khỏi quả báo.\n(Dùng khi tội lỗi cuối cùng cũng bị phát hiện, dù tưởng đã trốn được.)","hanviet":"thiên võng khôi khôi","note":"📜 Lịch sử: Lão Tử, chương 73: «thiên võng khôi khôi, sơ nhi bất thất». Chữ 恢恢 là rộng lớn; lưới nhìn có vẻ thưa nhưng thực tế không để sót điều gì. 💡 Thú vị: Tiếng Nhật thường nói trọn câu 天網恢恢疎にして漏らさず, đổi 失 thành 漏 (lọt). Tiếng Việt có câu tương đương «lưới trời lồng lộng, thưa mà khó lọt».","chars":[{"c":"天","h":"thiên"},{"c":"網","h":"võng"},{"c":"恢","h":"khôi"},{"c":"恢","h":"khôi"}],"poem":{"han":"天網恢恢疏不失／善惡終須有報時","hv":"Thiên võng khôi khôi sơ bất thất / Thiện ác chung tu hữu báo thì","vi":"Lưới trời mênh mông, thưa mà chẳng lọt; thiện ác rốt cuộc cũng có lúc báo ứng."},"example":"悪事はいつか露見する。天網恢恢疎にして漏らさずだ。","example_reading":"あくじはいつかろけんする。てんもうかいかいそにしてもらさずだ。","example_meaning":"Việc ác sớm muộn cũng bị lộ. Lưới trời lồng lộng, thưa mà không lọt.","examples":[{"example":"悪事はいつか露見する。天網恢恢疎にして漏らさずだ。","example_reading":"あくじはいつかろけんする。てんもうかいかいそにしてもらさずだ。","example_meaning":"Việc ác sớm muộn cũng bị lộ. Lưới trời lồng lộng, thưa mà không lọt."},{"example":"逃げ続けた犯人も、ついに捕まった。天網恢恢だ。","example_reading":"にげつづけたはんにんも、ついにつかまった。てんもうかいかいだ。","example_meaning":"Tên tội phạm trốn mãi cuối cùng cũng bị bắt. Lưới trời lồng lộng."}],"level":"p2"},
{"word":"不倶戴天","reading":"ふぐたいてん","meaning":"không đội chung một bầu trời; thù sâu như biển, không thể cùng tồn tại.\n(Dùng cho mối hận thù cực lớn, đặc biệt là thù giết cha.)","hanviet":"bất câu đới thiên","note":"📜 Lịch sử: Lễ ký - Khúc lễ thượng: «phụ chi thù, phất dữ cộng đới thiên» (thù của cha thì không sống chung dưới một bầu trời). 💡 Thú vị: Lễ ký còn xếp bậc cả các loại thù: thù anh em thì phải mang sẵn binh khí bên mình, thù bạn bè thì không chung một nước. Ở Nhật, cụm này hay gặp trong chuyện báo thù (仇討ち) thời Edo.","chars":[{"c":"不","h":"bất"},{"c":"倶","h":"câu"},{"c":"戴","h":"đới"},{"c":"天","h":"thiên"}],"poem":{"han":"父仇切骨誓無赦／不與共戴一重天","hv":"Phụ cừu thiết cốt thệ vô xá / Bất dữ cộng đới nhất trùng thiên","vi":"Thù cha khắc cốt, thề không tha; không cùng đội chung một bầu trời."},"example":"二人は不倶戴天の敵として争ってきた。","example_reading":"ふたりはふぐたいてんのてきとしてあらそってきた。","example_meaning":"Hai người đã đối đầu nhau như kẻ thù không đội trời chung.","examples":[{"example":"二人は不倶戴天の敵として争ってきた。","example_reading":"ふたりはふぐたいてんのてきとしてあらそってきた。","example_meaning":"Hai người đã đối đầu nhau như kẻ thù không đội trời chung."},{"example":"親の仇を不倶戴天の敵と見なして、探し続けた。","example_reading":"おやのかたきをふぐたいてんのてきとみなして、さがしつづけた。","example_meaning":"Coi kẻ giết cha là kẻ thù không đội trời chung, anh ta tìm kiếm mãi."}],"level":"p2"},
{"word":"一敗塗地","reading":"いっぱいとち","meaning":"thua một trận là nát tan; thất bại hoàn toàn, không gượng dậy nổi.\n(Dùng cho thất bại thảm hại, khó hồi phục.)","hanviet":"nhất bại đồ địa","note":"📜 Lịch sử: Sử ký - Cao Tổ bản kỷ: khi Trần Thiệp nổi dậy, các bô lão huyện Bái muốn lập Lưu Bang làm Bái công. Lưu Bang từ chối: «nay đặt tướng không khéo thì một lần thua là xác nát lầy đất», vì sợ mình không đủ tài. 💡 Thú vị: Sau đó bị bô lão và Tiêu Hà, Tào Tham thuyết phục, ông mới nhận; đây là bước đầu của nhà Hán. Chữ 塗地 nghĩa là 'bôi xuống đất', hình ảnh máu thịt tung ra đất.","chars":[{"c":"一","h":"nhất"},{"c":"敗","h":"bại"},{"c":"塗","h":"đồ"},{"c":"地","h":"địa"}],"poem":{"han":"一朝兵敗無遺甲／肝腦塗泥滿故原","hv":"Nhất triêu binh bại vô di giáp / Can não đồ nê mãn cố nguyên","vi":"Một sớm quân thua, chẳng còn giáp sót; gan óc lẫn bùn phủ khắp đồng xưa."},"example":"初戦で大敗し、チームは一敗塗地となった。","example_reading":"しょせんでたいはいし、チームはいっぱいとちとなった。","example_meaning":"Thua đậm ngay trận đầu, đội rơi vào thảm bại.","examples":[{"example":"初戦で大敗し、チームは一敗塗地となった。","example_reading":"しょせんでたいはいし、チームはいっぱいとちとなった。","example_meaning":"Thua đậm ngay trận đầu, đội rơi vào thảm bại."},{"example":"株で大損して、一敗塗地の状態だ。","example_reading":"かぶでおおぞんして、いっぱいとちのじょうたいだ。","example_meaning":"Lỗ nặng vì cổ phiếu, tôi rơi vào tình trạng sạt nghiệp."}],"level":"p2"},
{"word":"刮目相待","reading":"かつもくそうたい","meaning":"lau mắt mà nhìn lại; thấy người đã tiến bộ vượt bậc, phải nhìn họ bằng con mắt khác.\n(Dùng sau một thời gian xa cách khi người kia trưởng thành rõ rệt.)","hanviet":"quát mục tương đãi","note":"📜 Lịch sử: Tam quốc chí - Ngô chí - Lã Mông truyện (chú dẫn «Giang biểu truyện»): Tôn Quyền khuyên Lã Mông chăm học. Sau này Lỗ Túc gặp lại, kinh ngạc vì Mông học rộng; Mông đáp «kẻ sĩ xa ba ngày đã phải lau mắt mà nhìn lại». 💡 Thú vị: Trước đó Lã Mông bị chê là 呉下の阿蒙 (A Mông ở đất Ngô), ý chỉ kẻ ít học. Tiếng Nhật thường dùng thể 刮目して待つ / 刮目して見よ để 'hãy chờ xem'.","chars":[{"c":"刮","h":"quát"},{"c":"目","h":"mục"},{"c":"相","h":"tương"},{"c":"待","h":"đãi"}],"poem":{"han":"士別三日須刮目／書中歲月換新人","hv":"Sĩ biệt tam nhật tu quát mục / Thư trung tuế nguyệt hoán tân nhân","vi":"Kẻ sĩ xa ba ngày phải lau mắt mà nhìn lại; năm tháng trong sách vở đã đổi thành người mới."},"example":"三年ぶりに会った彼は別人のようで、刮目相待の思いだった。","example_reading":"さんねんぶりにあったかれはべつじんのようで、かつもくそうたいのおもいだった。","example_meaning":"Gặp lại sau ba năm, anh ấy như người khác, tôi phải nhìn bằng con mắt khác.","examples":[{"example":"三年ぶりに会った彼は別人のようで、刮目相待の思いだった。","example_reading":"さんねんぶりにあったかれはべつじんのようで、かつもくそうたいのおもいだった。","example_meaning":"Gặp lại sau ba năm, anh ấy như người khác, tôi phải nhìn bằng con mắt khác."},{"example":"若手の活躍には、刮目して待ちたい。","example_reading":"わかてのかつやくには、かつもくしてまちたい。","example_meaning":"Tôi háo hức chờ xem các bạn trẻ thể hiện."}],"level":"p2"},
{"word":"青天白日","reading":"せいてんはくじつ","meaning":"trời xanh ngày sáng; trong sạch, không điều khuất tất; hoặc được minh oan hoàn toàn.\n(Dùng cho người vô tội được rửa sạch nghi ngờ hoặc tấm lòng ngay thẳng.)","hanviet":"thanh thiên bạch nhật","note":"📜 Lịch sử: Hàn Dũ - Dữ Thôi Quần thư: ông ca ngợi bạn là Thôi Quần trong sáng như «thanh thiên bạch nhật», trong sáng đến mức ai cũng thấy rõ. 💡 Thú vị: Trong tiếng Nhật còn có nghĩa 'ngày đẹp trời'. «Thanh thiên bạch nhật» cũng là tên huy hiệu mặt trời trắng trên nền trời xanh, nằm trong quốc kỳ Trung Hoa Dân Quốc (Đài Loan).","chars":[{"c":"青","h":"thanh"},{"c":"天","h":"thiên"},{"c":"白","h":"bạch"},{"c":"日","h":"nhật"}],"poem":{"han":"青天白日無纖翳／心跡分明照九州","hv":"Thanh thiên bạch nhật vô tiêm ế / Tâm tích phân minh chiếu cửu châu","vi":"Trời xanh ngày sáng không chút bụi mờ, tâm và dấu vết rõ ràng soi khắp chín châu."},"example":"裁判で無罪となり、青天白日の身になった。","example_reading":"さいばんでむざいとなり、せいてんはくじつのみになった。","example_meaning":"Được tuyên vô tội, anh ta được rửa sạch hoàn toàn.","examples":[{"example":"裁判で無罪となり、青天白日の身になった。","example_reading":"さいばんでむざいとなり、せいてんはくじつのみになった。","example_meaning":"Được tuyên vô tội, anh ta được rửa sạch hoàn toàn."},{"example":"やましいことは何もなく、青天白日の心境だ。","example_reading":"やましいことはなにもなく、せいてんはくじつのしんきょうだ。","example_meaning":"Chẳng có gì khuất tất, lòng tôi thanh thản."}],"level":"p2"},
{"word":"閑話休題","reading":"かんわきゅうだい","meaning":"thôi, gác chuyện phiếm sang một bên; quay lại đề tài chính.\n(Cách chuyển mạch khi nói hoặc viết: 'nói chuyện vui đủ rồi, trở lại chuyện chính nhé'.)","hanviet":"nhàn thoại hưu đề","note":"📜 Lịch sử: Là câu quen thuộc của người kể chuyện trong tiểu thuyết bạch thoại và chương hồi Trung Quốc, dùng khi rẽ từ đoạn phụ trở về tuyến chính của câu chuyện. 💡 Thú vị: Nhiều người Nhật hiểu nhầm là 'nhân tiện' (ところで), tức mở đầu một chuyện phụ. Thực ra nghĩa đúng là 'hết chuyện phiếm, về chính đề' (それはさておき). Nhà văn Natsume Sōseki cũng dùng cụm này trong tiểu thuyết.","chars":[{"c":"閑","h":"nhàn"},{"c":"話","h":"thoại"},{"c":"休","h":"hưu"},{"c":"題","h":"đề"}],"poem":{"han":"說到閒談須暫歇／且回正傳聽新章","hv":"Thuyết đáo nhàn đàm tu tạm yết / Thả hồi chính truyện thính tân chương","vi":"Nói đến chuyện phiếm thì nên tạm dừng, hãy quay về chính truyện, nghe chương mới."},"example":"閑話休題、本題に戻りましょう。","example_reading":"かんわきゅうだい、ほんだいにもどりましょう。","example_meaning":"Thôi, gác chuyện phiếm, quay lại chủ đề chính nào.","examples":[{"example":"閑話休題、本題に戻りましょう。","example_reading":"かんわきゅうだい、ほんだいにもどりましょう。","example_meaning":"Thôi, gác chuyện phiếm, quay lại chủ đề chính nào."},{"example":"雑談が長くなったが、閑話休題、会議を続けます。","example_reading":"ざつだんがながくなったが、かんわきゅうだい、かいぎをつづけます。","example_meaning":"Chuyện phiếm hơi dài, nhưng xin gác lại và tiếp tục cuộc họp."}],"level":"p2"},
{"word":"先憂後楽","reading":"せんゆうこうらく","meaning":"lo trước thiên hạ, vui sau thiên hạ; người lãnh đạo lo cho dân trước, hưởng vui sau.\n(Biểu tượng của tinh thần trách nhiệm, đặt lợi ích chung lên trên bản thân.)","hanviet":"tiên ưu hậu lạc","note":"📜 Lịch sử: Phạm Trọng Yêm - Nhạc Dương lâu ký (đời Tống): «tiên thiên hạ chi ưu nhi ưu, hậu thiên hạ chi lạc nhi lạc». Ông viết bài này khi bị giáng chức, nhân dịp tu sửa lầu Nhạc Dương. 💡 Thú vị: Vườn Kōrakuen (後楽園) ở Tokyo và ở Okayama đều lấy tên từ câu này; tương truyền Tokugawa Mitsukuni, chủ vườn Tokyo, đã đặt tên theo ý ấy. Sân bóng chày Kōrakuen cũ ở Tokyo cũng mang tên vườn.","chars":[{"c":"先","h":"tiên"},{"c":"憂","h":"ưu"},{"c":"後","h":"hậu"},{"c":"楽","h":"lạc"}],"poem":{"han":"憂先天下民猶困／樂後蒼生我始安","hv":"Ưu tiên thiên hạ dân do khốn / Lạc hậu thương sinh ngã thủy an","vi":"Lo trước thiên hạ khi dân còn khốn; vui sau muôn dân rồi ta mới yên."},"example":"政治家は先憂後楽の精神を持つべきだ。","example_reading":"せいじかはせんゆうこうらくのせいしんをもつべきだ。","example_meaning":"Chính trị gia nên có tinh thần lo trước vui sau.","examples":[{"example":"政治家は先憂後楽の精神を持つべきだ。","example_reading":"せいじかはせんゆうこうらくのせいしんをもつべきだ。","example_meaning":"Chính trị gia nên có tinh thần lo trước vui sau."},{"example":"校長先生は先憂後楽の姿勢で学校を支えた。","example_reading":"こうちょうせんせいはせんゆうこうらくのしせいでがっこうをささえた。","example_meaning":"Thầy hiệu trưởng nâng đỡ nhà trường với tinh thần lo trước vui sau."}],"level":"p2"},
{"word":"大義滅親","reading":"たいぎめっしん","meaning":"vì đại nghĩa mà dứt tình thân; đặt lẽ phải, đạo nghĩa lên trên tình riêng với người thân.\n(Dùng khi phải trừng phạt hay tố cáo cả người thân vì lẽ phải.)","hanviet":"đại nghĩa diệt thân","note":"📜 Lịch sử: Xuân Thu Tả truyện - Ẩn công năm 4: Thạch Thạc của nước Vệ thấy con trai Thạch Hậu giúp Châu Hu giết vua, bèn nhờ nước Trần bắt rồi sai người xử tử cả hai. Tả truyện khen đó là «đại nghĩa diệt thân». 💡 Thú vị: Chữ 滅 ở đây là 'dứt, diệt' tình cảm riêng chứ không có nghĩa giết ngay người thân theo từng chữ. Trong tiếng Nhật, cụm này thường dùng khi nói về việc tố giác người nhà phạm tội.","chars":[{"c":"大","h":"đại"},{"c":"義","h":"nghĩa"},{"c":"滅","h":"diệt"},{"c":"親","h":"thân"}],"poem":{"han":"大義當前忘骨肉／寸心如鐵斷恩情","hv":"Đại nghĩa đương tiền vong cốt nhục / Thốn tâm như thiết đoạn ân tình","vi":"Đại nghĩa trước mắt, quên cả ruột thịt; lòng như sắt, dứt tình riêng."},"example":"彼は大義滅親の覚悟で、兄の不正を告発した。","example_reading":"かれはたいぎめっしんのかくごで、あにのふせいをこくはつした。","example_meaning":"Anh ấy quyết tâm vì đại nghĩa, tố cáo sai phạm của anh trai.","examples":[{"example":"彼は大義滅親の覚悟で、兄の不正を告発した。","example_reading":"かれはたいぎめっしんのかくごで、あにのふせいをこくはつした。","example_meaning":"Anh ấy quyết tâm vì đại nghĩa, tố cáo sai phạm của anh trai."},{"example":"大義滅親とはいえ、家族を訴えるのは辛い。","example_reading":"たいぎめっしんとはいえ、かぞくをうったえるのはつらい。","example_meaning":"Dù là vì đại nghĩa, kiện chính người nhà vẫn rất đau lòng."}],"level":"p2"},
{"word":"一蓮托生","reading":"いちれんたくしょう","meaning":"cùng sinh trên một đài sen; cùng chung số phận, dù tốt hay xấu.\n(Nghĩa hiện đại: đã cùng chung nhóm thì thành công hay thất bại đều cùng chịu.)","hanviet":"nhất liên thác sinh","note":"📜 Lịch sử: Từ Tịnh độ giáo: người niệm Phật được vãng sinh về Cực Lạc, ngồi chung một đài sen (蓮台). Vì thế 一蓮托生 vốn là nghĩa tốt: cùng nhau được sinh về cõi lành. 💡 Thú vị: Trong tiếng Nhật hiện đại, nghĩa đổi thành 'đồng cam cộng khổ, thậm chí cùng chìm', hay dùng ở thể 一蓮托生だ khi nói về nhóm tội phạm hoặc chính trị. Chữ 托生 vốn nghĩa 'gửi mình tái sinh'.","chars":[{"c":"一","h":"nhất"},{"c":"蓮","h":"liên"},{"c":"托","h":"thác"},{"c":"生","h":"sinh"}],"poem":{"han":"同登蓮座生西土／共渡慈航過苦津","hv":"Đồng đăng liên tòa sinh Tây thổ / Cộng độ từ hàng quá khổ tân","vi":"Cùng lên tòa sen sinh về cõi Tây, cùng đi thuyền từ vượt bến khổ."},"example":"私たちは一蓮托生だ。成功も失敗も一緒だ。","example_reading":"わたしたちはいちれんたくしょうだ。せいこうもしっぱいもいっしょだ。","example_meaning":"Chúng ta cùng chung số phận; thành hay bại đều cùng nhau.","examples":[{"example":"私たちは一蓮托生だ。成功も失敗も一緒だ。","example_reading":"わたしたちはいちれんたくしょうだ。せいこうもしっぱいもいっしょだ。","example_meaning":"Chúng ta cùng chung số phận; thành hay bại đều cùng nhau."},{"example":"彼とは一蓮托生の関係で、離れることはできない。","example_reading":"かれとはいちれんたくしょうのかんけいで、はなれることはできない。","example_meaning":"Tôi và anh ấy cùng chung vận mệnh nên không thể tách ra."}],"level":"p2"},
{"word":"得隴望蜀","reading":"とくろうぼうしょく","meaning":"được Lũng lại muốn Thục; lòng tham không đáy, được rồi còn đòi thêm.\n(Dùng với sắc thái chê tham vọng vô độ.)","hanviet":"đắc Lũng vọng Thục","note":"📜 Lịch sử: Hậu Hán thư - Sầm Bành truyện: Hán Quang Vũ Đế viết thư cho tướng Sầm Bành: «Người ta khổ vì không biết đủ, đã dẹp được Lũng lại mong cả Thục». Lũng là vùng Cam Túc, Thục là vùng Tứ Xuyên ngày nay. 💡 Thú vị: Tương truyền Tào Tháo cũng dẫn lại ý này khi quyết định không tiến đánh Thục sau khi chiếm Hán Trung. Tiếng Việt tương đương là «được voi đòi tiên».","chars":[{"c":"得","h":"đắc"},{"c":"隴","h":"Lũng"},{"c":"望","h":"vọng"},{"c":"蜀","h":"Thục"}],"poem":{"han":"已定隴西還望蜀／人心不足似蛇吞","hv":"Dĩ định Lũng Tây hoàn vọng Thục / Nhân tâm bất túc tự xà thôn","vi":"Đã dẹp Lũng Tây lại ngó sang Thục; lòng người không đủ như rắn muốn nuốt voi."},"example":"成功しても満足せず、得隴望蜀の欲を出した。","example_reading":"せいこうしてもまんぞくせず、とくろうぼうしょくのよくをだした。","example_meaning":"Thành công rồi vẫn không thỏa mãn, nảy sinh lòng tham được voi đòi tiên.","examples":[{"example":"成功しても満足せず、得隴望蜀の欲を出した。","example_reading":"せいこうしてもまんぞくせず、とくろうぼうしょくのよくをだした。","example_meaning":"Thành công rồi vẫn không thỏa mãn, nảy sinh lòng tham được voi đòi tiên."},{"example":"隴を得て蜀を望むように、彼の要求はとどまることを知らない。","example_reading":"ろうをえてしょくをのぞむように、かれのようきゅうはとどまることをしらない。","example_meaning":"Được Lũng lại đòi Thục, yêu cầu của anh ta không biết dừng ở đâu."}],"level":"p2"},
{"word":"洛陽紙貴（洛陽の紙価）","reading":"らくようしき（らくようのしか）","meaning":"giấy ở Lạc Dương đắt lên; tác phẩm được hoan nghênh, bán chạy, người người tranh nhau chép và mua.\n(Dùng khi khen sách hay, nổi tiếng vượt mức bình thường.)","hanviet":"Lạc Dương chỉ quý","note":"📜 Lịch sử: Tấn thư - Văn uyển truyện: Tả Tư (đời Tấn) tướng xấu, nói lắp nhưng văn tài xuất chúng, mất khoảng mười năm viết xong «Tam đô phú» (Ngụy đô, Ngô đô, Thục đô). Ban đầu bị chê, sau khi các danh sĩ như Trương Hoa khen ngợi, người ở Lạc Dương đua nhau chép lại, khiến giấy trở nên đắt đỏ. 💡 Thú vị: Tiếng Nhật thường dùng dạng 洛陽の紙価を高める (làm giá giấy Lạc Dương tăng) để khen một tác phẩm bán chạy.","chars":[{"c":"洛","h":"Lạc"},{"c":"陽","h":"Dương"},{"c":"紙","h":"chỉ"},{"c":"貴","h":"quý"}],"poem":{"han":"十載構思成三賦／洛陽爭寫紙價騰","hv":"Thập tải cấu tư thành tam phú / Lạc Dương tranh tả chỉ giá đằng","vi":"Mười năm dày công mới thành ba bài phú; Lạc Dương tranh nhau chép, giá giấy tăng vọt."},"example":"その小説は洛陽の紙価を高めるほどの人気だった。","example_reading":"そのしょうせつはらくようのしかをたかめるほどのにんきだった。","example_meaning":"Cuốn tiểu thuyết đó nổi tiếng đến mức làm giá giấy tăng lên.","examples":[{"example":"その小説は洛陽の紙価を高めるほどの人気だった。","example_reading":"そのしょうせつはらくようのしかをたかめるほどのにんきだった。","example_meaning":"Cuốn tiểu thuyết đó nổi tiếng đến mức làm giá giấy tăng lên."},{"example":"新作は洛陽紙貴の大ベストセラーとなった。","example_reading":"しんさくはらくようしきのだいベストセラーとなった。","example_meaning":"Tác phẩm mới trở thành sách bán chạy lớn."}],"level":"p2"},
{"word":"解衣推食","reading":"かいいすいしょく","meaning":"cởi áo cho mặc, nhường cơm cho ăn; ân huệ sâu nặng, hết lòng giúp đỡ và quan tâm người khác.\n(Dùng khi nói về ơn nghĩa lớn của người trên.)","hanviet":"giải y thôi thực","note":"📜 Lịch sử: Sử ký - Hoài Âm hầu liệt truyện: sứ giả của Hạng Vũ là Vũ Thiệp đến khuyên Hàn Tín bỏ Hán. Hàn Tín từ chối, nói Hán vương đã trao ấn thượng tướng, giao mấy vạn quân, cởi áo cho ta mặc, nhường cơm cho ta ăn, nghe lời ta và dùng kế của ta; bội nghĩa thì sẽ không lành. 💡 Thú vị: Dù từ chối vì ơn nghĩa như thế, về sau Hàn Tín vẫn bị giáng chức rồi bị Lữ hậu giết, nên tích này có chút chua chát.","chars":[{"c":"解","h":"giải"},{"c":"衣","h":"y"},{"c":"推","h":"thôi"},{"c":"食","h":"thực"}],"poem":{"han":"解衣推食恩何重／肯背漢王負舊盟","hv":"Giải y thôi thực ân hà trọng / Khẳng bội Hán vương phụ cựu minh","vi":"Cởi áo nhường cơm ơn sao nặng thế; sao nỡ phản Hán vương, phụ lời thề cũ."},"example":"社長は解衣推食で、部下の面倒を見てきた。","example_reading":"しゃちょうはかいいすいしょくで、ぶかのめんどうをみてきた。","example_meaning":"Giám đốc luôn hết lòng lo cho cấp dưới.","examples":[{"example":"社長は解衣推食で、部下の面倒を見てきた。","example_reading":"しゃちょうはかいいすいしょくで、ぶかのめんどうをみてきた。","example_meaning":"Giám đốc luôn hết lòng lo cho cấp dưới."},{"example":"恩師には解衣推食の恩を受け、今も頭が上がらない。","example_reading":"おんしにはかいいすいしょくのおんをうけ、いまもあたまがあがらない。","example_meaning":"Tôi mang ơn sâu nặng của thầy, đến giờ vẫn không dám ngẩng mặt."}],"level":"p2"},
{"word":"揠苗助長","reading":"あつびょうじょちょう","meaning":"nhổ mạ cho cao; nóng vội can thiệp mà làm hỏng việc.\n(Chữ 助長 trong tiếng Nhật ngày nay thường mang nghĩa «làm trầm trọng thêm».)","hanviet":"yết miêu trợ trưởng","note":"📜 Lịch sử: Mạnh Tử - Công Tôn Sửu thượng: người nước Tống lo mạ lớn chậm, nhổ từng cây cho cao lên, về nhà nói «hôm nay mệt quá, ta giúp mạ lớn rồi». Con trai chạy ra đồng xem thì mạ đã héo hết. Mạnh Tử dùng chuyện này để dạy: nuôi dưỡng «hạo nhiên chi khí» không được ép buộc. 💡 Thú vị: Từ 助長 (trợ trưởng) trong tiếng Nhật hiện đại, như 不安を助長する, bắt nguồn từ điển tích này.","chars":[{"c":"揠","h":"yết"},{"c":"苗","h":"miêu"},{"c":"助","h":"trợ"},{"c":"長","h":"trưởng"}],"poem":{"han":"宋人憂苗遲長大／拔高盡槁枉勞功","hv":"Tống nhân ưu miêu trì trưởng đại / Bạt cao tận cảo uổng lao công","vi":"Người Tống lo mạ lớn chậm; nhổ cao lên thì héo hết, uổng công."},"example":"子供の早期教育に焦りすぎるのは、揠苗助長になりかねない。","example_reading":"こどものそうききょういくにあせりすぎるのは、あつびょうじょちょうになりかねない。","example_meaning":"Quá nóng vội dạy sớm cho con có thể thành nhổ mạ cho cao.","examples":[{"example":"子供の早期教育に焦りすぎるのは、揠苗助長になりかねない。","example_reading":"こどものそうききょういくにあせりすぎるのは、あつびょうじょちょうになりかねない。","example_meaning":"Quá nóng vội dạy sớm cho con có thể thành nhổ mạ cho cao."},{"example":"成果を急いで部下に口出しすると、揠苗助長になる。","example_reading":"せいかをいそいでぶかにくちだしすると、あつびょうじょちょうになる。","example_meaning":"Vì nóng lòng đòi kết quả mà can thiệp vào cấp dưới thì sẽ thành nhổ mạ cho cao."}],"level":"p2"},
{"word":"鶏鳴狗盗","reading":"けいめいくとう","meaning":"gà gáy, chó trộm; tài vặt hèn mọn nhưng có lúc cứu nguy; cũng chỉ kẻ tầm thường, trộm cắp.","hanviet":"kê minh cẩu đạo","note":"📜 Lịch sử: Sử ký - Mạnh Thường Quân liệt truyện: Mạnh Thường Quân của nước Tề bị giam ở Tần, nhờ ái thiếp của vua Tần xin tha thì bà đòi chiếc áo hồ cừu trắng (đã tặng vua). Một thực khách giỏi trộm chó chui vào kho lấy được áo. Đến ải Hàm Cốc lúc nửa đêm, ải chỉ mở khi gà gáy; một thực khách giả tiếng gà, gà thật gáy theo, ải mở, nhóm thoát trước khi quân Tần đuổi tới. 💡 Thú vị: Vương An Thạch đời Tống chê Mạnh Thường Quân chỉ dùng được hạng gà gáy chó trộm nên không thu hút được kẻ sĩ thực tài.","chars":[{"c":"鶏","h":"kê"},{"c":"鳴","h":"minh"},{"c":"狗","h":"cẩu"},{"c":"盗","h":"đạo"}],"poem":{"han":"函谷夜深雞假唱／狐裘暗取狗潛行","hv":"Hàm Cốc dạ thâm kê giả xướng / Hồ cừu ám thủ cẩu tiềm hành","vi":"Hàm Cốc đêm khuya, gà gáy giả; áo hồ cừu bị kẻ giả chó lẻn vào lấy trộm."},"example":"鶏鳴狗盗の才でも、役に立つ時はある。","example_reading":"けいめいくとうのさいでも、やくにたつときはある。","example_meaning":"Dù chỉ là tài vặt, đôi khi cũng có lúc hữu dụng.","examples":[{"example":"鶏鳴狗盗の才でも、役に立つ時はある。","example_reading":"けいめいくとうのさいでも、やくにたつときはある。","example_meaning":"Dù chỉ là tài vặt, đôi khi cũng có lúc hữu dụng."},{"example":"彼は鶏鳴狗盗のような小細工しかできない。","example_reading":"かれはけいめいくとうのようなこざいくしかできない。","example_meaning":"Anh ta chỉ biết mấy mánh khóe vặt vãnh."}],"level":"p2"},
{"word":"桃李成蹊","reading":"とうりせいけい","meaning":"đào mận không nói mà dưới gốc thành lối đi; người đức độ chân thành, không phô trương vẫn được người ta quy phục.\n(Dùng khen người có nhân cách khiến người khác tự tìm đến.)","hanviet":"đào lý thành hề","note":"📜 Lịch sử: Sử ký - Lý tướng quân liệt truyện: Tư Mã Thiên bình về Lý Quảng bằng câu tục ngữ «đào mận không nói, dưới gốc tự thành lối» (桃李不言，下自成蹊). Lý Quảng ít lời, nhưng khi ông mất, cả quân sĩ lẫn dân đều khóc thương. 💡 Thú vị: Tên trường Đại học Seikei (成蹊大学) ở Nhật lấy từ câu này, ngụ ý đào tạo người có đức tự khắc được kính trọng.","chars":[{"c":"桃","h":"đào"},{"c":"李","h":"lý"},{"c":"成","h":"thành"},{"c":"蹊","h":"hề"}],"poem":{"han":"桃李無言春自滿／蹊成樹下客爭來","hv":"Đào lý vô ngôn xuân tự mãn / Hề thành thụ hạ khách tranh lai","vi":"Đào mận không lời, xuân tự tràn đầy; dưới gốc thành lối, khách tranh nhau tới."},"example":"桃李成蹊で、徳のある先生の周りには自然と人が集まる。","example_reading":"とうりせいけいで、とくのあるせんせいのまわりにはしぜんとひとがあつまる。","example_meaning":"Như đào mận thành lối, quanh người thầy có đức tự nhiên có người tụ tập.","examples":[{"example":"桃李成蹊で、徳のある先生の周りには自然と人が集まる。","example_reading":"とうりせいけいで、とくのあるせんせいのまわりにはしぜんとひとがあつまる。","example_meaning":"Như đào mận thành lối, quanh người thầy có đức tự nhiên có người tụ tập."},{"example":"彼の誠実さは桃李成蹊で、自然と周囲の信頼を集めた。","example_reading":"かれのせいじつさはとうりせいけいで、しぜんとしゅういのしんらいをあつめた。","example_meaning":"Sự chân thành của anh ấy tự nhiên thu hút lòng tin của mọi người xung quanh."}],"level":"p2"},
{"word":"毛遂自薦","reading":"もうすいじせん","meaning":"mao Toại tự giới thiệu; tự tiến cử bản thân, xung phong đảm nhận việc.\n(Dùng khi ai đó mạnh dạn tự đề cử.)","hanviet":"Mao Toại tự tiến","note":"📜 Lịch sử: Sử ký - Bình Nguyên Quân Ngu Khanh liệt truyện: Tần vây Hàm Đan, Bình Nguyên Quân chọn 20 người đi cầu viện nước Sở, còn thiếu một thì Mao Toại tự xin đi. Bình Nguyên Quân nói người tài như cái dùi trong túi, mũi lòi ra ngay, mà ông ở đây ba năm chưa ai khen. Mao Toại đáp: nếu sớm được bỏ vào túi thì cả cán cũng lòi ra chứ không chỉ mũi. Tại nước Sở, ông cầm kiếm ép vua Sở ký liên minh. 💡 Thú vị: Cụm 嚢中の錐 (cái dùi trong túi) cũng xuất phát từ cuộc đối đáp này.","chars":[{"c":"毛","h":"Mao"},{"c":"遂","h":"Toại"},{"c":"自","h":"tự"},{"c":"薦","h":"tiến"}],"poem":{"han":"囊錐一露鋒芒現／按劍堂前定楚盟","hv":"Nang chùy nhất lộ phong mang hiện / Án kiếm đường tiền định Sở minh","vi":"Dùi trong túi vừa lộ mũi nhọn; tay đặt chuôi kiếm trước điện, định xong minh ước với Sở."},"example":"新プロジェクトのリーダーに、毛遂自薦で立候補した。","example_reading":"しんプロジェクトのリーダーに、もうすいじせんでりっこうほした。","example_meaning":"Tôi tự ứng cử làm trưởng dự án mới.","examples":[{"example":"新プロジェクトのリーダーに、毛遂自薦で立候補した。","example_reading":"しんプロジェクトのリーダーに、もうすいじせんでりっこうほした。","example_meaning":"Tôi tự ứng cử làm trưởng dự án mới."},{"example":"毛遂自薦のつもりで、彼女は難しい交渉役を買って出た。","example_reading":"もうすいじせんのつもりで、かのじょはむずかしいこうしょうやくをかってでた。","example_meaning":"Với tinh thần tự tiến cử, cô ấy xung phong nhận vai đàm phán khó."}],"level":"p2"},
{"word":"刻舟求剣","reading":"こくしゅうきゅうけん","meaning":"khắc dấu lên thuyền để tìm kiếm; cứng nhắc, không biết biến thông theo hoàn cảnh đã đổi thay.","hanviet":"khắc chu cầu kiếm","note":"📜 Lịch sử: Lã thị Xuân Thu - Sát kim: người nước Sở qua sông, đánh rơi kiếm xuống nước, bèn khắc dấu lên mạn thuyền nói «chỗ này là nơi kiếm rơi». Thuyền cập bờ, anh ta mới nhảy xuống nước tìm theo dấu khắc. Lã thị bình: thuyền đã đi mà kiếm thì không đi, tìm như vậy chẳng phải lầm sao; ý nói lấy phép cũ để trị đời nay. 💡 Thú vị: Tiếng Nhật còn đọc dạng văn ngôn 舟に刻みて剣を求む; tích này thường được đặt cạnh 守株待兎 vì cùng chê sự cố chấp.","chars":[{"c":"刻","h":"khắc"},{"c":"舟","h":"chu"},{"c":"求","h":"cầu"},{"c":"剣","h":"kiếm"}],"poem":{"han":"劍墜中流刻舟側／舟行劍止覓無蹤","hv":"Kiếm trụy trung lưu khắc chu trắc / Chu hành kiếm chỉ mịch vô tung","vi":"Kiếm rơi giữa dòng, khắc dấu mạn thuyền; thuyền đi kiếm đứng, tìm chẳng thấy tăm."},"example":"昔の成功体験にこだわるのは刻舟求剣だ。","example_reading":"むかしのせいこうたいけんにこだわるのはこくしゅうきゅうけんだ。","example_meaning":"Bám chặt vào thành công ngày xưa là khắc thuyền tìm kiếm.","examples":[{"example":"昔の成功体験にこだわるのは刻舟求剣だ。","example_reading":"むかしのせいこうたいけんにこだわるのはこくしゅうきゅうけんだ。","example_meaning":"Bám chặt vào thành công ngày xưa là khắc thuyền tìm kiếm."},{"example":"市場が変わったのに同じ手法を使うのは刻舟求剣に等しい。","example_reading":"しじょうがかわったのにおなじしゅほうをつかうのはこくしゅうきゅうけんにひとしい。","example_meaning":"Thị trường đã đổi mà vẫn dùng cách cũ thì chẳng khác khắc thuyền tìm kiếm."}],"level":"p2"},
{"word":"螳螂之斧（蟷螂の斧）","reading":"とうろうのおの（とうろうのおの）","meaning":"rìu của bọ ngựa; không lượng sức mình mà đương đầu với kẻ mạnh hơn rất nhiều.\n(Tương đương «châu chấu đá xe» trong tiếng Việt.)","hanviet":"đường lang chi phủ","note":"📜 Lịch sử: Trang Tử - Nhân gian thế có câu bọ ngựa giận dữ giơ càng chặn bánh xe mà không biết mình không chống nổi. Hàn thi ngoại truyện kể Tề Trang công đi săn thấy bọ ngựa giơ chân định chặn bánh xe; vua khen nếu là người thì ắt là dũng sĩ thiên hạ, rồi cho xe tránh nó. 💡 Thú vị: Ở nguồn thứ hai, hành động này lại được khen là dũng cảm, nên cụm từ có hai sắc thái: chê thiếu tự lượng sức và khen dám đối đầu.","chars":[{"c":"螳","h":"đường"},{"c":"螂","h":"lang"},{"c":"之","h":"chi"},{"c":"斧","h":"phủ"}],"poem":{"han":"螳螂怒臂當車轍／不量其力勇堪嗟","hv":"Đường lang nộ tý đương xa triệt / Bất lượng kỳ lực dũng kham ta","vi":"Bọ ngựa giận giơ càng chặn bánh xe; chẳng lượng sức mình, dũng cảm mà đáng thương."},"example":"大企業に挑むのは蟷螂の斧かもしれないが、挑戦したい。","example_reading":"だいきぎょうにいどむのはとうろうのおのかもしれないが、ちょうせんしたい。","example_meaning":"Thách thức tập đoàn lớn có thể là châu chấu đá xe, nhưng tôi vẫn muốn thử.","examples":[{"example":"大企業に挑むのは蟷螂の斧かもしれないが、挑戦したい。","example_reading":"だいきぎょうにいどむのはとうろうのおのかもしれないが、ちょうせんしたい。","example_meaning":"Thách thức tập đoàn lớn có thể là châu chấu đá xe, nhưng tôi vẫn muốn thử."},{"example":"強豪に挑む彼らの姿は、まるで蟷螂の斧だった。","example_reading":"きょうごうにいどむかれらのすがたは、まるでとうろうのおのだった。","example_meaning":"Hình ảnh họ thách đấu đội mạnh chẳng khác châu chấu đá xe."}],"level":"p2"},
{"word":"蝸牛角上","reading":"かぎゅうかくじょう","meaning":"trên sừng ốc sên; tranh giành nhỏ nhặt, vô nghĩa.\n(Thường dùng dạng 蝸牛角上の争い.)","hanviet":"oa ngưu giác thượng","note":"📜 Lịch sử: Trang Tử - Tắc dương: Đới Tấn Nhân kể cho Ngụy Huệ vương nghe rằng trên sừng trái của con ốc sên có nước Xúc, sừng phải có nước Man, hai bên tranh đất đánh nhau, chết hàng vạn người, đuổi địch mười lăm ngày mới về. Ông dùng chuyện này để nói trong vũ trụ rộng lớn, cuộc tranh chấp giữa Ngụy và Tề cũng nhỏ bé như vậy. 💡 Thú vị: Bạch Cư Dị có câu thơ «Oa ngưu giác thượng tranh hà sự, thạch hỏa quang trung ký thử thân» (蝸牛角上爭何事，石火光中寄此身), nghĩa là tranh gì trên sừng ốc sên, thân ta gửi trong chớp lửa đá.","chars":[{"c":"蝸","h":"oa"},{"c":"牛","h":"ngưu"},{"c":"角","h":"giác"},{"c":"上","h":"thượng"}],"poem":{"han":"蝸角觸蠻爭尺土／伏屍萬計笑蒼穹","hv":"Oa giác Xúc Man tranh xích thổ / Phục thi vạn kế tiếu thương khung","vi":"Xúc, Man tranh thước đất trên sừng ốc; thây nằm hàng vạn, trời xanh cười."},"example":"社内の派閥争いは蝸牛角上の争いにすぎない。","example_reading":"しゃないのはばつあらそいはかぎゅうかくじょうのあらそいにすぎない。","example_meaning":"Tranh chấp phe phái trong công ty chỉ là chuyện nhỏ nhặt.","examples":[{"example":"社内の派閥争いは蝸牛角上の争いにすぎない。","example_reading":"しゃないのはばつあらそいはかぎゅうかくじょうのあらそいにすぎない。","example_meaning":"Tranh chấp phe phái trong công ty chỉ là chuyện nhỏ nhặt."},{"example":"隣人との境界争いは蝸牛角上の争いだと気づいた。","example_reading":"りんじんとのきょうかいあらそいはかぎゅうかくじょうのあらそいだときづいた。","example_meaning":"Tôi nhận ra việc tranh ranh giới với hàng xóm chỉ là chuyện vặt."}],"level":"p2"},
{"word":"風声鶴唳","reading":"ふうせいかくれい","meaning":"tiếng gió, tiếng hạc kêu; kẻ thua trận hoảng sợ, nghe gì cũng tưởng là quân địch đuổi tới.","hanviet":"phong thanh hạc lệ","note":"📜 Lịch sử: Tấn thư - Tạ Huyền truyện: trong trận Phì Thủy (năm 383), quân Tiền Tần của Phù Kiên thua trước quân Đông Tấn. Tàn binh bỏ chạy, nghe tiếng gió và tiếng hạc kêu đều tưởng quân Tấn đang đuổi theo. 💡 Thú vị: Trước trận, Phù Kiên khoe quân đông đến mức ném roi xuống sông cũng chặn được dòng nước, vậy mà thua tan tác; trận này cũng sinh ra thành ngữ 草木皆兵.","chars":[{"c":"風","h":"phong"},{"c":"声","h":"thanh"},{"c":"鶴","h":"hạc"},{"c":"唳","h":"lệ"}],"poem":{"han":"淝水兵潰驚鶴唳／風聲入耳亦疑追","hv":"Phì Thủy binh hội kinh hạc lệ / Phong thanh nhập nhĩ diệc nghi truy","vi":"Quân tan ở sông Phì, giật mình vì tiếng hạc; gió vào tai cũng ngờ quân truy đuổi."},"example":"不祥事の後、社内は風声鶴唳の状態だった。","example_reading":"ふしょうじのあと、しゃないはふうせいかくれいのじょうたいだった。","example_meaning":"Sau vụ bê bối, trong công ty ai cũng thấp thỏm lo sợ.","examples":[{"example":"不祥事の後、社内は風声鶴唳の状態だった。","example_reading":"ふしょうじのあと、しゃないはふうせいかくれいのじょうたいだった。","example_meaning":"Sau vụ bê bối, trong công ty ai cũng thấp thỏm lo sợ."},{"example":"選挙に敗れた党は、風声鶴唳に怯えていた。","example_reading":"せんきょにやぶれたとうは、ふうせいかくれいにおびえていた。","example_meaning":"Đảng thua cử sợ hãi cả những động tĩnh nhỏ."}],"level":"p2"},
{"word":"草木皆兵","reading":"そうもくかいへい","meaning":"cây cỏ cũng thành quân địch; vì quá sợ hãi nên nhìn gì cũng tưởng là địch.","hanviet":"thảo mộc giai binh","note":"📜 Lịch sử: Tấn thư - Phù Kiên tái ký: cùng trận Phì Thủy, Phù Kiên lên thành Thọ Dương nhìn quân Tấn bày trận chỉnh tề, nhìn sang núi Bát Công thấy cây cỏ đều tưởng là quân Tấn, bèn nói đây cũng là kình địch, sao lại bảo là ít quân. Từ đó ông mất tự tin. 💡 Thú vị: Thành ngữ này thường đi cặp với 風声鶴唳 vì cùng sinh ra từ một trận đánh.","chars":[{"c":"草","h":"thảo"},{"c":"木","h":"mộc"},{"c":"皆","h":"giai"},{"c":"兵","h":"binh"}],"poem":{"han":"八公山色連營影／草木搖風盡是兵","hv":"Bát Công sơn sắc liên doanh ảnh / Thảo mộc dao phong tận thị binh","vi":"Màu núi Bát Công nối thành bóng doanh trại; cỏ cây lay gió đều tưởng là quân."},"example":"詐欺に遭ってから、草木皆兵で誰も信用できない。","example_reading":"さぎにあってから、そうもくかいへいでだれもしんようできない。","example_meaning":"Từ khi bị lừa, tôi sợ đến mức không dám tin ai.","examples":[{"example":"詐欺に遭ってから、草木皆兵で誰も信用できない。","example_reading":"さぎにあってから、そうもくかいへいでだれもしんようできない。","example_meaning":"Từ khi bị lừa, tôi sợ đến mức không dám tin ai."},{"example":"受験前は草木皆兵で、小さな物音にもびくびくした。","example_reading":"じゅけんまえはそうもくかいへいで、ちいさなものおとにもびくびくした。","example_meaning":"Trước kỳ thi tôi nhạy cảm sợ sệt cả với tiếng động nhỏ."}],"level":"p2"},
{"word":"殷鑑不遠","reading":"いんかんとおからず","meaning":"tấm gương nhà Ân không xa; bài học thất bại của người đi trước ở ngay trước mắt, nên rút kinh nghiệm.","hanviet":"Ân giám bất viễn","note":"📜 Lịch sử: Kinh Thi - Đại nhã - Đãng: «Ân giám bất viễn, tại Hạ hậu chi thế» (殷鑑不遠，在夏后之世), mượn lời Văn Vương cảnh báo vua nhà Ân: tấm gương soi của ngươi không xa, chính là đời vua nhà Hạ (Kiệt) đã mất nước. 💡 Thú vị: Tiếng Nhật thường nói 殷鑑遠からず; điển tích cho thấy nhà Ân sau này cũng đi vào vết xe đổ của nhà Hạ.","chars":[{"c":"殷","h":"Ân"},{"c":"鑑","h":"giám"},{"c":"不","h":"bất"},{"c":"遠","h":"viễn"}],"poem":{"han":"夏桀亡國殷當鑑／前車覆轍後車師","hv":"Hạ Kiệt vong quốc Ân đương giám / Tiền xa phúc triệt hậu xa sư","vi":"Hạ Kiệt mất nước, nhà Ân nên lấy làm gương; xe trước đổ vệt, xe sau lấy làm thầy."},"example":"殷鑑遠からず、先行企業の失敗を教訓にすべきだ。","example_reading":"いんかんとおからず、せんこうきぎょうのしっぱいをきょうくんにすべきだ。","example_meaning":"Gương xưa không xa, nên lấy thất bại của các công ty đi trước làm bài học.","examples":[{"example":"殷鑑遠からず、先行企業の失敗を教訓にすべきだ。","example_reading":"いんかんとおからず、せんこうきぎょうのしっぱいをきょうくんにすべきだ。","example_meaning":"Gương xưa không xa, nên lấy thất bại của các công ty đi trước làm bài học."},{"example":"殷鑑遠からずというように、前任者の失敗を繰り返さないようにしよう。","example_reading":"いんかんとおからずというように、ぜんにんしゃのしっぱいをくりかえさないようにしよう。","example_meaning":"Như người ta nói gương xưa không xa, hãy tránh lặp lại thất bại của người tiền nhiệm."}],"level":"p2"},
{"word":"戦戦兢々（戦々恐々）","reading":"せんせんきょうきょう（せんせんきょうきょう）","meaning":"run rẩy, lo sợ, hết sức thận trọng.\n(Dùng khi rón rén, lo âu trong tình huống nguy hiểm; viết 戦々恐々 là dạng quen dùng ở Nhật.)","hanviet":"chiến chiến căng căng","note":"📜 Lịch sử: Kinh Thi - Tiểu nhã - Tiểu mân: «Chiến chiến căng căng, như lâm thâm uyên, như lý bạc băng» (戰戰兢兢，如臨深淵，如履薄冰), nghĩa là run run như đứng bên vực sâu, như giẫm trên băng mỏng. Luận ngữ - Thái Bá: Tăng Tử lúc ốm nặng gọi học trò xem tay chân mình, trích câu này để nói cả đời mình đã giữ gìn thân thể cẩn trọng. 💡 Thú vị: Trong tiếng Nhật dạng 戦戦恐々 (dùng chữ 恐 sợ) còn phổ biến hơn dạng gốc dùng chữ 兢 (cẩn trọng).","chars":[{"c":"戦","h":"chiến"},{"c":"戦","h":"chiến"},{"c":"兢","h":"căng"},{"c":"兢","h":"căng"}],"poem":{"han":"如臨深淵如履冰／曾子臨終啟足看","hv":"Như lâm thâm uyên như lý băng / Tăng tử lâm chung khải túc khan","vi":"Như đứng bên vực sâu, như giẫm trên băng; Tăng Tử lúc lâm chung bảo xem chân tay mình."},"example":"試験の結果を戦々兢々として待っている。","example_reading":"しけんのけっかをせんせんきょうきょうとしてまっている。","example_meaning":"Tôi hồi hộp lo âu chờ kết quả kỳ thi.","examples":[{"example":"試験の結果を戦々兢々として待っている。","example_reading":"しけんのけっかをせんせんきょうきょうとしてまっている。","example_meaning":"Tôi hồi hộp lo âu chờ kết quả kỳ thi."},{"example":"リストラの噂に、社員は戦々恐々としていた。","example_reading":"リストラのうわさに、しゃいんはせんせんきょうきょうとしていた。","example_meaning":"Trước tin đồn cắt giảm nhân sự, nhân viên ai cũng thấp thỏm."}],"level":"p2"},
{"word":"一葉知秋","reading":"いちようあきをしる","meaning":"thấy một chiếc lá rụng biết thu đến; nhìn dấu hiệu nhỏ mà đoán được xu thế lớn.\n(Tiếng Nhật thường nói 一葉落ちて天下の秋を知る.)","hanviet":"nhất diệp tri thu","note":"📜 Lịch sử: Hoài Nam Tử - Thuyết sơn huấn: «Thấy một chiếc lá rụng mà biết năm sắp hết, thấy băng trong bình mà biết thiên hạ đã lạnh» (見一葉落而知歲之將暮，睹瓶中之冰而知天下之寒). Ý là từ chi tiết nhỏ suy ra xu thế lớn. 💡 Thú vị: Trong tiếng Nhật, cách nói «一葉落ちて天下の秋を知る» có nhịp điệu rất quen thuộc, hay xuất hiện trong văn bình luận kinh tế khi nói về dấu hiệu đầu tiên của suy thoái.","chars":[{"c":"一","h":"nhất"},{"c":"葉","h":"diệp"},{"c":"知","h":"tri"},{"c":"秋","h":"thu"}],"poem":{"han":"一葉飄庭知歲暮／窺微知著見天機","hv":"Nhất diệp phiêu đình tri tuế mộ / Khuy vi tri trứ kiến thiên cơ","vi":"Một lá rơi sân biết năm tàn; xem điều nhỏ thấy được điều lớn, thấy thiên cơ."},"example":"客足の減少は、一葉落ちて天下の秋を知るの兆しだった。","example_reading":"きゃくあしのげんしょうは、いちようおちててんかのあきをしるのきざしだった。","example_meaning":"Khách giảm là dấu hiệu báo trước xu hướng lớn, như thấy một chiếc lá rụng biết thu sang.","examples":[{"example":"客足の減少は、一葉落ちて天下の秋を知るの兆しだった。","example_reading":"きゃくあしのげんしょうは、いちようおちててんかのあきをしるのきざしだった。","example_meaning":"Khách giảm là dấu hiệu báo trước xu hướng lớn, như thấy một chiếc lá rụng biết thu sang."},{"example":"新人の態度を見て、一葉落ちて天下の秋を知る思いがした。","example_reading":"しんじんのたいどをみて、いちようおちててんかのあきをしるおもいがした。","example_meaning":"Nhìn thái độ của nhân viên mới, tôi có cảm giác thấy chiếc lá rụng là biết cả mùa thu."}],"level":"p2"},
{"word":"老馬之智","reading":"ろうばのち","meaning":"trí tuệ của ngựa già; người lão luyện, giàu kinh nghiệm có thể dẫn đường cho người khác.","hanviet":"lão mã chi trí","note":"📜 Lịch sử: Hàn Phi Tử - Thuyết lâm thượng: Quản Trọng và Thấp Bằng theo Tề Hoàn Công đánh Cô Trúc, lúc về mùa đông thì bị lạc đường. Quản Trọng nói trí của ngựa già dùng được, bèn thả ngựa già đi trước, quân đi theo thì tìm ra đường. Thấp Bằng lại dạy tìm tổ kiến để tìm nước uống. 💡 Thú vị: Hàn Phi Tử kết luận người nay không biết lấy cái ngu của mình làm học trò của trí tuệ bậc thánh, và ngay cả Quản Trọng, Thấp Bằng cũng không xấu hổ khi học từ ngựa và kiến.","chars":[{"c":"老","h":"lão"},{"c":"馬","h":"mã"},{"c":"之","h":"chi"},{"c":"智","h":"trí"}],"poem":{"han":"迷途雪暗放老馬／隨蹄尋路出重圍","hv":"Mê đồ tuyết ám phóng lão mã / Tùy đề tầm lộ xuất trùng vi","vi":"Lạc đường tuyết mờ, thả ngựa già; theo vó tìm đường, thoát vòng vây."},"example":"新人の指導は、老馬の智を持つベテランに任せた。","example_reading":"しんじんのしどうは、ろうばのちをもつベテランにまかせた。","example_meaning":"Tôi giao việc hướng dẫn người mới cho người kỳ cựu giàu kinh nghiệm.","examples":[{"example":"新人の指導は、老馬の智を持つベテランに任せた。","example_reading":"しんじんのしどうは、ろうばのちをもつベテランにまかせた。","example_meaning":"Tôi giao việc hướng dẫn người mới cho người kỳ cựu giàu kinh nghiệm."},{"example":"老馬の智というように、経験豊かな先輩の助言が役立った。","example_reading":"ろうばのちというように、けいけんゆたかなせんぱいのじょげんがやくだった。","example_meaning":"Đúng là trí ngựa già, lời khuyên của đàn anh nhiều kinh nghiệm rất hữu ích."}],"level":"p2"},
{"word":"殺身成仁","reading":"さっしんせいじん","meaning":"hy sinh thân mình để thành điều nhân; vì đạo nghĩa mà sẵn sàng chết.\n(Tinh thần của người quân tử trong Nho giáo.)","hanviet":"sát thân thành nhân","note":"📜 Lịch sử: Luận ngữ - Vệ Linh Công: «Bậc chí sĩ nhân đức không vì cầu sống mà hại điều nhân; có khi hy sinh thân mình để thành điều nhân» (志士仁人，無求生以害仁，有殺身以成仁). 💡 Thú vị: Mạnh Tử có câu cùng ý là «xả sinh thủ nghĩa» (捨生取義), bỏ mạng để giữ nghĩa; hai câu này thường được dẫn đôi.","chars":[{"c":"殺","h":"sát"},{"c":"身","h":"thân"},{"c":"成","h":"thành"},{"c":"仁","h":"nhân"}],"poem":{"han":"志士求仁輕七尺／捨生取義見丹心","hv":"Chí sĩ cầu nhân khinh thất xích / Xả sinh thủ nghĩa kiến đan tâm","vi":"Chí sĩ cầu nhân coi nhẹ thân bảy thước; bỏ sống giữ nghĩa, thấy tấm lòng son."},"example":"彼は殺身成仁の覚悟で内部告発に踏み切った。","example_reading":"かれはさっしんせいじんのかくごでないぶこくはつにふみきった。","example_meaning":"Anh ấy quyết tâm tố giác nội bộ, sẵn sàng hy sinh vì chính nghĩa.","examples":[{"example":"彼は殺身成仁の覚悟で内部告発に踏み切った。","example_reading":"かれはさっしんせいじんのかくごでないぶこくはつにふみきった。","example_meaning":"Anh ấy quyết tâm tố giác nội bộ, sẵn sàng hy sinh vì chính nghĩa."},{"example":"殺身成仁を貫いた志士たちの姿に胸を打たれた。","example_reading":"さっしんせいじんをつらぬいたししたちのすがたにむねをうたれた。","example_meaning":"Tôi xúc động trước hình ảnh các chí sĩ hy sinh vì nghĩa."}],"level":"p2"},
{"word":"知行合一","reading":"ちこうごういつ","meaning":"biết và làm là một; hiểu biết thật sự phải thể hiện bằng hành động.\n(Tư tưởng trung tâm của Vương Dương Minh.)","hanviet":"tri hành hợp nhất","note":"📜 Lịch sử: Vương Dương Minh (Vương Thủ Nhân, đời Minh) đề xướng, được ghi trong Truyền tập lục. Ông bị đày đến Long Trường (Quý Châu) rồi «đại ngộ» năm 1508, nhận ra đạo lý nằm ngay trong tâm và biết với làm không tách rời. 💡 Thú vị: Dương Minh học du nhập vào Nhật Bản và ảnh hưởng đến nhiều chí sĩ cuối thời Edo như Yoshida Shōin, Saigō Takamori.","chars":[{"c":"知","h":"tri"},{"c":"行","h":"hành"},{"c":"合","h":"hợp"},{"c":"一","h":"nhất"}],"poem":{"han":"知為行始行為成／一念發動即是行","hv":"Tri vi hành thủy hành vi thành / Nhất niệm phát động tức thị hành","vi":"Biết là khởi đầu của làm, làm là hoàn thành của biết; một ý niệm nảy ra đã là làm."},"example":"知行合一を信条に、学んだことをすぐ実践している。","example_reading":"ちこうごういつをしんじょうに、まなんだことをすぐじっせんしている。","example_meaning":"Lấy tri hành hợp nhất làm phương châm, tôi áp dụng ngay những điều đã học.","examples":[{"example":"知行合一を信条に、学んだことをすぐ実践している。","example_reading":"ちこうごういつをしんじょうに、まなんだことをすぐじっせんしている。","example_meaning":"Lấy tri hành hợp nhất làm phương châm, tôi áp dụng ngay những điều đã học."},{"example":"知識だけでなく行動が伴う知行合一が大切だ。","example_reading":"ちしきだけでなくこうどうがともなうちこうごういつがたいせつだ。","example_meaning":"Không chỉ có kiến thức, tri hành hợp nhất mới là điều quan trọng."}],"level":"p2"},
{"word":"隔靴掻痒","reading":"かっかそうよう","meaning":"gãi ngứa qua lớp giày; làm không tới nơi, bực bội vì không chạm đúng chỗ.\n(Dùng cho lời nói, cách giải quyết không đúng trọng tâm.)","hanviet":"cách ngoa tao dương","note":"📜 Lịch sử: Cụm từ xuất hiện trong ngữ lục Thiền tông thời Tống, ví việc tu hành, giảng giải không nắm trúng cốt lõi như gãi ngứa qua giày. 💡 Thú vị: Trong tiếng Nhật hay dùng với chữ 感 thành 隔靴掻痒の感, diễn tả cảm giác ngứa ngáy khó chịu vì chưa đạt đến mức mình muốn.","chars":[{"c":"隔","h":"cách"},{"c":"靴","h":"ngoa"},{"c":"掻","h":"tao"},{"c":"痒","h":"dương"}],"poem":{"han":"靴外搔痒終難到／語不中機徒自煩","hv":"Ngoa ngoại tao dương chung nan đáo / Ngữ bất trúng cơ đồ tự phiền","vi":"Gãi ngoài giày rốt cuộc khó chạm chỗ ngứa; lời nói chẳng trúng cơ, chỉ thêm bực mình."},"example":"その説明は隔靴掻痒の感があった。","example_reading":"そのせつめいはかっかそうようのかんがあった。","example_meaning":"Lời giải thích đó khiến người nghe thấy ngứa ngáy vì không đúng trọng tâm.","examples":[{"example":"その説明は隔靴掻痒の感があった。","example_reading":"そのせつめいはかっかそうようのかんがあった。","example_meaning":"Lời giải thích đó khiến người nghe thấy ngứa ngáy vì không đúng trọng tâm."},{"example":"対策が隔靴掻痒で、問題の根本は解決していない。","example_reading":"たいさくがかっかそうようで、もんだいのこんぽんはかいけつしていない。","example_meaning":"Đối sách chỉ như gãi ngứa qua giày, gốc rễ vấn đề vẫn chưa giải quyết."}],"level":"p2"},
{"word":"一衣帯水","reading":"いちいたいすい","meaning":"một dải nước hẹp như vạt áo; hai bên chỉ cách một con sông, quan hệ gần gũi.\n(Dùng cho hai nước láng giềng sát nhau.)","hanviet":"nhất y đới thủy","note":"📜 Lịch sử: Nam sử - Trần Hậu Chủ kỷ: Tùy Văn Đế (Dương Kiên) nói mình là cha mẹ của dân, há lại vì một dải nước hẹp như vạt áo mà không cứu giúp họ, ý nói sẽ vượt Trường Giang diệt nhà Trần. 💡 Thú vị: Trong tiếng Nhật, cụm 一衣帯水の隣国 thường dùng để nói về quan hệ giữa Nhật Bản với các nước láng giềng như Trung Quốc, Hàn Quốc.","chars":[{"c":"一","h":"nhất"},{"c":"衣","h":"y"},{"c":"帯","h":"đới"},{"c":"水","h":"thủy"}],"poem":{"han":"長江一帶如衣縷／南北相望咫尺間","hv":"Trường Giang nhất đới như y lũ / Nam bắc tương vọng chỉ xích gian","vi":"Trường Giang một dải như vạt áo; nam bắc nhìn nhau chỉ cách gang tấc."},"example":"日本と韓国は一衣帯水の隣国だ。","example_reading":"にほんとかんこくはいちいたいすいのりんごくだ。","example_meaning":"Nhật Bản và Hàn Quốc là hai nước láng giềng sát nhau.","examples":[{"example":"日本と韓国は一衣帯水の隣国だ。","example_reading":"にほんとかんこくはいちいたいすいのりんごくだ。","example_meaning":"Nhật Bản và Hàn Quốc là hai nước láng giềng sát nhau."},{"example":"一衣帯水の関係にある両国は、文化交流が盛んだ。","example_reading":"いちいたいすいのかんけいにあるりょうこくは、ぶんかこうりゅうがさかんだ。","example_meaning":"Hai nước gần gũi này có giao lưu văn hóa sôi nổi."}],"level":"p2"},
{"word":"白駒過隙","reading":"はっくかげき","meaning":"ngựa trắng vụt qua khe cửa; thời gian trôi nhanh, đời người ngắn ngủi.","hanviet":"bạch câu quá khích","note":"📜 Lịch sử: Trang Tử - Tri bắc du: «Người ta sống giữa trời đất, như bóng bạch câu chạy qua khe hở, thoắt cái đã qua» (人生天地之間，若白駒之過郤，忽然而已). 💡 Thú vị: Tiếng Việt có hình ảnh tương đương «bóng câu qua cửa sổ»; trong tiếng Nhật, 駒 (ngựa non) ở đây là ngựa chạy nhanh.","chars":[{"c":"白","h":"bạch"},{"c":"駒","h":"câu"},{"c":"過","h":"quá"},{"c":"隙","h":"khích"}],"poem":{"han":"人生天地如駒隙／忽爾流光逝不留","hv":"Nhân sinh thiên địa như câu khích / Hốt nhĩ lưu quang thệ bất lưu","vi":"Đời người giữa trời đất như bóng ngựa qua khe; thoắt cái ánh sáng trôi đi chẳng lưu."},"example":"白駒過隙というが、もう一年が終わろうとしている。","example_reading":"はっくかげきというが、もういちねんがおわろうとしている。","example_meaning":"Người ta nói thời gian như bóng câu qua cửa sổ, một năm nữa sắp hết rồi.","examples":[{"example":"白駒過隙というが、もう一年が終わろうとしている。","example_reading":"はっくかげきというが、もういちねんがおわろうとしている。","example_meaning":"Người ta nói thời gian như bóng câu qua cửa sổ, một năm nữa sắp hết rồi."},{"example":"子供の成長は白駒過隙のように早い。","example_reading":"こどものせいちょうははっくかげきのようにはやい。","example_meaning":"Con trẻ lớn lên nhanh như bóng câu qua cửa sổ."}],"level":"p2"},
{"word":"同病相憐","reading":"どうびょうあいあわれむ","meaning":"cùng bệnh thương nhau; người cùng cảnh ngộ thông cảm với nhau.","hanviet":"đồng bệnh tương lân","note":"📜 Lịch sử: Ngô Việt xuân thu - Hạp Lư nội truyện: Ngũ Tử Tư chạy sang Ngô, gặp Bá Hĩ cũng có cha bị Sở giết. Có người can rằng Bá Hĩ tướng mắt hổ, bước đi như ngựa, không đáng tin. Ngũ Tử Tư đáp: «Ta với Bá Hĩ cùng oán thù, như cùng bệnh mà thương nhau». 💡 Thú vị: Về sau Bá Hĩ làm thái tể nước Ngô, gièm pha khiến Ngũ Tử Tư bị ép tự tử, đúng như lời cảnh báo ban đầu.","chars":[{"c":"同","h":"đồng"},{"c":"病","h":"bệnh"},{"c":"相","h":"tương"},{"c":"憐","h":"lân"}],"poem":{"han":"同病相憐君與我／後來讒口卻傷身","hv":"Đồng bệnh tương lân quân dữ ngã / Hậu lai sàm khẩu khước thương thân","vi":"Cùng bệnh thương nhau, ngươi và ta; về sau miệng sàm lại hại thân."},"example":"同じ病気を持つ者同士、同病相憐れむ気持ちで支え合った。","example_reading":"おなじびょうきをもつものどうし、どうびょうあいあわれむきもちでささえあった。","example_meaning":"Những người cùng bệnh nâng đỡ nhau với tấm lòng cảm thông.","examples":[{"example":"同じ病気を持つ者同士、同病相憐れむ気持ちで支え合った。","example_reading":"おなじびょうきをもつものどうし、どうびょうあいあわれむきもちでささえあった。","example_meaning":"Những người cùng bệnh nâng đỡ nhau với tấm lòng cảm thông."},{"example":"失業した者同士、同病相憐れんで酒を酌み交わした。","example_reading":"しつぎょうしたものどうし、どうびょうあいあわれんでさけをくみかわした。","example_meaning":"Những người cùng thất nghiệp cảm thông nhau, cùng nâng chén tâm sự."}],"level":"p2"},
{"word":"倒行逆施","reading":"とうこうぎゃくし","meaning":"làm ngược đường lẽ; hành động trái đạo lý, làm ngang ngược.","hanviet":"đảo hành nghịch thi","note":"📜 Lịch sử: Sử ký - Ngũ Tử Tư liệt truyện: Ngũ Tử Tư đánh vào kinh đô Sở, quật mộ Bình vương lên đánh roi vào thây; bạn cũ là Thân Bao Tư trách ông quá đáng. Tử Tư đáp: «Ta như người đi đường khi trời đã tối mà đường còn xa, nên phải làm trái lẽ». 💡 Thú vị: Câu «nhật mộ đồ viễn» trong lời đáp này cũng thành một thành ngữ riêng (日暮途遠).","chars":[{"c":"倒","h":"đảo"},{"c":"行","h":"hành"},{"c":"逆","h":"nghịch"},{"c":"施","h":"thi"}],"poem":{"han":"日暮途遙仇未報／倒行逆施鞭王屍","hv":"Nhật mộ đồ dao cừu vị báo / Đảo hành nghịch thi tiên vương thi","vi":"Trời tối đường xa, thù chưa báo; làm trái lẽ, quất roi lên thây vua."},"example":"強引な手法は倒行逆施と批判された。","example_reading":"ごういんなしゅほうはとうこうぎゃくしとひはんされた。","example_meaning":"Cách làm cưỡng ép bị chỉ trích là làm trái đạo lý.","examples":[{"example":"強引な手法は倒行逆施と批判された。","example_reading":"ごういんなしゅほうはとうこうぎゃくしとひはんされた。","example_meaning":"Cách làm cưỡng ép bị chỉ trích là làm trái đạo lý."},{"example":"民意に背く倒行逆施は長続きしない。","example_reading":"みんいにそむくとうこうぎゃくしはながつづきしない。","example_meaning":"Việc làm trái ý dân sẽ không bền lâu."}],"level":"p2"},
{"word":"日暮途遠","reading":"にちぼとえん","meaning":"ngày tàn đường xa; tuổi già mà việc còn nhiều, thời gian không đủ.\n(Tiếng Nhật: 日暮れて道遠し.)","hanviet":"nhật mộ đồ viễn","note":"📜 Lịch sử: Sử ký - Ngũ Tử Tư liệt truyện, cùng đoạn với 倒行逆施: Ngũ Tử Tư tự ví mình như người đi đường khi trời đã tối mà còn xa đích, nên không thể làm theo lẽ thường. 💡 Thú vị: Trong tiếng Nhật, câu 日暮れて道遠し còn dùng khi ý chí vẫn còn nhưng thời gian không còn nhiều.","chars":[{"c":"日","h":"nhật"},{"c":"暮","h":"mộ"},{"c":"途","h":"đồ"},{"c":"遠","h":"viễn"}],"poem":{"han":"年邁事繁心尚壯／日西路遠志猶存","hv":"Niên mại sự phồn tâm thượng tráng / Nhật tây lộ viễn chí do tồn","vi":"Tuổi cao việc nhiều, lòng còn mạnh; trời xế đường xa, chí vẫn còn."},"example":"もう還暦だが、やりたいことが多く日暮途遠の感がある。","example_reading":"もうかんれきだが、やりたいことがおおくにちぼとえんのかんがある。","example_meaning":"Đã sáu mươi tuổi nhưng muốn làm nhiều việc, có cảm giác ngày tàn đường xa.","examples":[{"example":"もう還暦だが、やりたいことが多く日暮途遠の感がある。","example_reading":"もうかんれきだが、やりたいことがおおくにちぼとえんのかんがある。","example_meaning":"Đã sáu mươi tuổi nhưng muốn làm nhiều việc, có cảm giác ngày tàn đường xa."},{"example":"日暮れて道遠しの思いで、残された時間を使う。","example_reading":"ひくれてみちとおしのおもいで、のこされたじかんをつかう。","example_meaning":"Tôi dùng thời gian còn lại với cảm giác ngày tàn đường xa."}],"level":"p2"},
{"word":"沐猴而冠","reading":"もっこうにしてかんす","meaning":"khỉ đội mũ; người có vẻ ngoài sang trọng nhưng bản chất thô lỗ, không xứng với địa vị.","hanviet":"mộc hầu nhi quan","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ: một thuyết sĩ khuyên Hạng Vũ đóng đô ở Quan Trung nhưng bị từ chối, bèn ra ngoài nói «người ta bảo người Sở là khỉ đội mũ, quả đúng». Hạng Vũ nghe được, cho nấu sống người đó. 💡 Thú vị: Câu chuyện đi cặp với 錦衣夜行; về sau thành thành ngữ chế giễu kẻ có chức vị mà thiếu phẩm cách.","chars":[{"c":"沐","h":"mộc"},{"c":"猴","h":"hầu"},{"c":"而","h":"nhi"},{"c":"冠","h":"quan"}],"poem":{"han":"猴冠楚俗人爭笑／烹說何曾掩實情","hv":"Hầu quan Sở tục nhân tranh tiếu / Phanh thuyết hà tằng yểm thực tình","vi":"Khỉ đội mũ, người Sở bị chê cười; nấu sống kẻ nói, sao che được sự thật."},"example":"地位だけで中身のない人は沐猴而冠だと言われる。","example_reading":"ちいだけでなかみのないひとはもっこうにしてかんすだといわれる。","example_meaning":"Người chỉ có địa vị mà thiếu thực chất bị gọi là khỉ đội mũ.","examples":[{"example":"地位だけで中身のない人は沐猴而冠だと言われる。","example_reading":"ちいだけでなかみのないひとはもっこうにしてかんすだといわれる。","example_meaning":"Người chỉ có địa vị mà thiếu thực chất bị gọi là khỉ đội mũ."},{"example":"高価なスーツを着ても沐猴而冠のようでは意味がない。","example_reading":"こうかなスーツをきてももっこうにしてかんすのようではいみがない。","example_meaning":"Có mặc vest đắt tiền mà như khỉ đội mũ thì cũng vô nghĩa."}],"level":"p2"},
{"word":"退避三舎","reading":"たいひさんしゃ","meaning":"lui ba xá (90 dặm) để nhường; chủ động nhường bước trước đối phương, hoặc tránh né.","hanviet":"thoái tị tam xá","note":"📜 Lịch sử: Tả truyện - Hy công năm 23 và 28: công tử Trùng Nhĩ (sau là Tấn Văn công) lưu vong, được Sở Thành vương tiếp đãi, hứa nếu sau này hai nước giao chiến thì sẽ lui quân ba xá (mỗi xá 30 dặm). Trận Thành Bộc (632 TCN), ông giữ lời lui ba xá rồi đánh bại quân Sở. 💡 Thú vị: Tiếng Nhật 三舎を避く còn dùng khi chịu thua kém, không dám tranh với ai.","chars":[{"c":"退","h":"thoái"},{"c":"避","h":"tị"},{"c":"三","h":"tam"},{"c":"舎","h":"xá"}],"poem":{"han":"重耳逃亡蒙楚惠／三舍遵諾破城濮","hv":"Trùng Nhĩ đào vong mông Sở huệ / Tam xá tuân nặc phá Thành Bộc","vi":"Trùng Nhĩ lưu vong chịu ơn Sở; giữ lời lui ba xá, rồi phá quân ở Thành Bộc."},"example":"実力の差は明らかで、他社は退避三舎した。","example_reading":"じつりょくのさはあきらかで、たしゃはたいひさんしゃした。","example_meaning":"Chênh lệch thực lực rõ ràng nên các công ty khác đành nhường bước.","examples":[{"example":"実力の差は明らかで、他社は退避三舎した。","example_reading":"じつりょくのさはあきらかで、たしゃはたいひさんしゃした。","example_meaning":"Chênh lệch thực lực rõ ràng nên các công ty khác đành nhường bước."},{"example":"彼の弁論には、さすがの私も三舎を避けた。","example_reading":"かれのべんろんには、さすがのわたしもさんしゃをさけた。","example_meaning":"Trước tài ăn nói của anh ấy, ngay cả tôi cũng phải nhường."}],"level":"p2"},
{"word":"楚材晋用","reading":"そざいしんよう","meaning":"nhân tài nước Sở được nước Tấn dùng; nhân tài bị chảy sang nước khác.","hanviet":"Sở tài Tấn dụng","note":"📜 Lịch sử: Tả truyện - Tương công năm 26: câu nói của Thanh Tử «Tuy Sở có nhiều nhân tài, nhưng thực ra Tấn mới là nước dùng họ» (雖楚有材，晉實用之). Chuyện bắt đầu từ việc quan Sở bị vu oan phải chạy sang Tấn, rồi giúp Tấn chống lại Sở. 💡 Thú vị: Ngày nay cụm từ này thường được dùng để nói về hiện tượng «chảy máu chất xám».","chars":[{"c":"楚","h":"Sở"},{"c":"材","h":"tài"},{"c":"晋","h":"Tấn"},{"c":"用","h":"dụng"}],"poem":{"han":"楚地良材歸晉室／賢才一去國勢移","hv":"Sở địa lương tài quy Tấn thất / Hiền tài nhất khứ quốc thế di","vi":"Nhân tài đất Sở về nhà Tấn; hiền tài đã đi, thế nước đổi dời."},"example":"優秀な研究者が海外へ流出するのは楚材晋用だ。","example_reading":"ゆうしゅうなけんきゅうしゃがかいがいへりゅうしゅつするのはそざいしんようだ。","example_meaning":"Nhà nghiên cứu giỏi chảy ra nước ngoài là tài Sở nước Tấn dùng.","examples":[{"example":"優秀な研究者が海外へ流出するのは楚材晋用だ。","example_reading":"ゆうしゅうなけんきゅうしゃがかいがいへりゅうしゅつするのはそざいしんようだ。","example_meaning":"Nhà nghiên cứu giỏi chảy ra nước ngoài là tài Sở nước Tấn dùng."},{"example":"楚材晋用にならないよう、人材の待遇を改善した。","example_reading":"そざいしんようにならないよう、じんざいのたいぐうをかいぜんした。","example_meaning":"Để tránh chảy máu chất xám, chúng tôi đã cải thiện đãi ngộ nhân tài."}],"level":"p2"},
{"word":"作法自弊","reading":"さくほうじへい","meaning":"tự đặt ra luật rồi tự chịu hại; bị trói bởi chính cái do mình tạo ra.","hanviet":"tác pháp tự tệ","note":"📜 Lịch sử: Sử ký - Thương Quân liệt truyện: Thương Ưởng biến pháp ở Tần được Hiếu công trọng dụng. Sau khi Hiếu công mất, ông bị thù địch vu tội mưu phản, chạy trốn đến quán trọ thì bị từ chối vì luật Thương quân cấm chứa người không có giấy tờ; ông than: «Than ôi, tác pháp tự tệ đến thế này!» 💡 Thú vị: Về sau Thương Ưởng bị bắt và bị xử bằng cách xé xác bằng xe (xa liệt) dưới thời Tần Huệ vương.","chars":[{"c":"作","h":"tác"},{"c":"法","h":"pháp"},{"c":"自","h":"tự"},{"c":"弊","h":"tệ"}],"poem":{"han":"立法嚴刑民懼畏／無憑投宿自傷嗟","hv":"Lập pháp nghiêm hình dân cụ úy / Vô bằng đầu túc tự thương ta","vi":"Đặt luật hình nghiêm, dân sợ hãi; không giấy tờ xin trọ, tự than thở."},"example":"厳しい規則を作った彼が、自らその規則で罰せられ、作法自弊となった。","example_reading":"きびしいきそくをつくったかれが、みずからそのきそくでばっせられ、さくほうじへいとなった。","example_meaning":"Chính người đặt ra quy tắc nghiêm khắc lại bị phạt theo nó, đúng là tự làm tự chịu.","examples":[{"example":"厳しい規則を作った彼が、自らその規則で罰せられ、作法自弊となった。","example_reading":"きびしいきそくをつくったかれが、みずからそのきそくでばっせられ、さくほうじへいとなった。","example_meaning":"Chính người đặt ra quy tắc nghiêm khắc lại bị phạt theo nó, đúng là tự làm tự chịu."},{"example":"作法自弊にならないよう、ルールは慎重に決めよう。","example_reading":"さくほうじへいにならないよう、ルールはしんちょうにきめよう。","example_meaning":"Để khỏi tự trói mình, hãy đặt quy tắc một cách thận trọng."}],"level":"p2"},
{"word":"抱薪救火","reading":"ほうしんきゅうか","meaning":"ôm củi chữa cháy; cách làm sai khiến tai họa càng lớn thêm.","hanviet":"bão tân cứu hỏa","note":"📜 Lịch sử: Chiến quốc sách - Ngụy sách: Tô Đại khuyên Ngụy An Ly vương đừng cắt đất cho Tần để cầu hòa, vì dùng đất để thờ Tần chẳng khác ôm củi đi chữa cháy, củi chưa hết thì lửa chưa tắt. Sử ký - Ngụy thế gia cũng chép ý này. 💡 Thú vị: Tiếng Việt có hình ảnh tương đương «đổ dầu vào lửa».","chars":[{"c":"抱","h":"bão"},{"c":"薪","h":"tân"},{"c":"救","h":"cứu"},{"c":"火","h":"hỏa"}],"poem":{"han":"割地事秦求苟安／抱薪救火火愈燃","hv":"Cát địa sự Tần cầu cẩu an / Bão tân cứu hỏa hỏa dũ nhiên","vi":"Cắt đất thờ Tần để cầu tạm yên; ôm củi chữa cháy, lửa càng cháy mạnh."},"example":"借金で借金を返すのは抱薪救火だ。","example_reading":"しゃっきんでしゃっきんをかえすのはほうしんきゅうかだ。","example_meaning":"Vay tiền trả nợ là ôm củi chữa cháy.","examples":[{"example":"借金で借金を返すのは抱薪救火だ。","example_reading":"しゃっきんでしゃっきんをかえすのはほうしんきゅうかだ。","example_meaning":"Vay tiền trả nợ là ôm củi chữa cháy."},{"example":"その対策は抱薪救火になりかねない。","example_reading":"そのたいさくはほうしんきゅうかになりかねない。","example_meaning":"Đối sách đó có thể thành ôm củi chữa cháy."}],"level":"p2"},
{"word":"懸頭刺股","reading":"けんとうしこ","meaning":"buộc tóc lên xà, đâm dùi vào đùi; học hành khổ luyện, chống buồn ngủ.","hanviet":"huyền đầu thích cổ","note":"📜 Lịch sử: Hai tích ghép lại: Chiến quốc sách - Tần sách kể Tô Tần du thuyết Tần thất bại, về nhà bị vợ và chị dâu coi thường, ông phát phẫn đọc sách, buồn ngủ thì lấy dùi đâm vào đùi cho chảy máu; còn Tôn Kính (đời Hán) buộc tóc mình lên xà nhà để khỏi ngủ gật khi đọc sách. 💡 Thú vị: Tô Tần sau làm tướng quốc sáu nước, nên tích này thường được dạy như tấm gương học vượt khó, cùng nhóm với 蛍雪之功 và 鑿壁偸光.","chars":[{"c":"懸","h":"huyền"},{"c":"頭","h":"đầu"},{"c":"刺","h":"thích"},{"c":"股","h":"cổ"}],"poem":{"han":"錐刺股流猶苦讀／髮懸梁上不敢眠","hv":"Chùy thích cổ lưu do khổ độc / Phát huyền lương thượng bất cảm miên","vi":"Dùi đâm đùi chảy máu vẫn khổ đọc; tóc buộc trên xà chẳng dám ngủ."},"example":"懸頭刺股の思いで受験勉強に励んだ。","example_reading":"けんとうしこのおもいでじゅけんべんきょうにはげんだ。","example_meaning":"Tôi học thi miệt mài như người buộc tóc đâm dùi.","examples":[{"example":"懸頭刺股の思いで受験勉強に励んだ。","example_reading":"けんとうしこのおもいでじゅけんべんきょうにはげんだ。","example_meaning":"Tôi học thi miệt mài như người buộc tóc đâm dùi."},{"example":"懸頭刺股して資格試験に合格した。","example_reading":"けんとうしこしてしかくしけんにごうかくした。","example_meaning":"Tôi học khổ luyện rồi đỗ kỳ thi chứng chỉ."}],"level":"p2"},
{"word":"白虹貫日","reading":"はっこうかんじつ","meaning":"cầu vồng trắng xuyên mặt trời; điềm báo chuyện lớn sắp xảy ra (nhất là việc nghĩa hiệp hay biến loạn).","hanviet":"bạch hồng quán nhật","note":"📜 Lịch sử: Sử ký - Trâu Dương liệt truyện dẫn tích Kinh Kha mộ nghĩa Thái tử Đan nước Yên, đến mức «bạch hồng quán nhật», điềm lạ báo việc lớn sắp xảy ra. 💡 Thú vị: Ở Nhật, «Vụ Bạch hồng» (白虹事件) năm 1918 xảy ra khi báo Asahi dùng cụm này trong bài viết về vụ bạo loạn gạo, bị chính phủ coi là ám chỉ khởi nghĩa nên bị đàn áp.","chars":[{"c":"白","h":"bạch"},{"c":"虹","h":"hồng"},{"c":"貫","h":"quán"},{"c":"日","h":"nhật"}],"poem":{"han":"荊卿慕義丹心赤／白虹貫日天為驚","hv":"Kinh khanh mộ nghĩa đan tâm xích / Bạch hồng quán nhật thiên vi kinh","vi":"Kinh Kha mộ nghĩa lòng son đỏ; cầu vồng trắng xuyên mặt trời, trời cũng kinh."},"example":"白虹日を貫くという不吉な言葉が見出しに使われ、問題となった。","example_reading":"はっこうひをつらぬくというふきつなことばがみだしにつかわれ、もんだいとなった。","example_meaning":"Cụm từ điềm gở đó được dùng làm tít báo và gây rắc rối.","examples":[{"example":"白虹日を貫くという不吉な言葉が見出しに使われ、問題となった。","example_reading":"はっこうひをつらぬくというふきつなことばがみだしにつかわれ、もんだいとなった。","example_meaning":"Cụm từ điềm gở đó được dùng làm tít báo và gây rắc rối."},{"example":"白虹貫日を、大事件の前兆とみる人もいた。","example_reading":"はっこうかんじつを、だいじけんのぜんちょうとみるひともいた。","example_meaning":"Cũng có người xem bạch hồng quán nhật là điềm báo biến lớn."}],"level":"p2"},
{"word":"図窮匕見","reading":"ずきゅうひくんけん","meaning":"cuộn bản đồ mở hết thì lộ ra chủy thủ; sự thật hay ý đồ thật lộ ra khi sự việc đến cuối.","hanviet":"đồ cùng chủy hiện","note":"📜 Lịch sử: Sử ký - Thích khách liệt truyện: Kinh Kha mang bản đồ đất Đốc Kháng và đầu Phàn Ô Kỳ vào cung Tần, mở cuộn bản đồ đến cuối thì lộ ra chủy thủ giấu bên trong, rồi đâm Tần vương nhưng trượt; năm 227 TCN Kinh Kha bị giết. 💡 Thú vị: Tiếng Nhật đọc là 図窮まりて匕首見る, nghĩa hiện nay là «cuối cùng bản chất thật cũng lộ ra».","chars":[{"c":"図","h":"đồ"},{"c":"窮","h":"cùng"},{"c":"匕","h":"chủy"},{"c":"見","h":"hiện"}],"poem":{"han":"圖展終端藏寶刃／秦庭一擲事難成","hv":"Đồ triển chung đoan tàng bảo nhận / Tần đình nhất trịch sự nan thành","vi":"Mở bản đồ đến cuối, lộ lưỡi dao giấu; điện Tần ném một nhát, việc khó thành."},"example":"交渉が進むにつれ、図窮匕見で相手の本音が見えた。","example_reading":"こうしょうがすすむにつれ、ずきゅうひくんけんであいてのほんねがみえた。","example_meaning":"Càng đàm phán, ý đồ thật của đối phương càng lộ ra.","examples":[{"example":"交渉が進むにつれ、図窮匕見で相手の本音が見えた。","example_reading":"こうしょうがすすむにつれ、ずきゅうひくんけんであいてのほんねがみえた。","example_meaning":"Càng đàm phán, ý đồ thật của đối phương càng lộ ra."},{"example":"調査が進んで図窮匕見、不正の実態が明らかになった。","example_reading":"ちょうさがすすんでずきゅうひくんけん、ふせいのじったいがあきらかになった。","example_meaning":"Cuộc điều tra tiến triển, thực trạng gian lận đã lộ ra."}],"level":"p2"},
{"word":"臨淵羨魚","reading":"りんえんせんぎょ","meaning":"đứng bên vực thèm cá; chỉ mong mà không hành động thì vô ích, không bằng về đan lưới.","hanviet":"lâm uyên tiện ngư","note":"📜 Lịch sử: Hán thư - Đổng Trọng Thư truyện: «Lâm uyên tiện ngư, bất như thoái nhi kết võng» (臨淵羨魚、不如退而結網): đứng bên vực thèm cá chẳng bằng lui về đan lưới. Hoài Nam Tử - Thuyết lâm huấn cũng có ý tương tự. 💡 Thú vị: Tiếng Việt có câu «thèm cá thì phải đan lưới» với ý khuyên hành động thay vì chỉ ao ước.","chars":[{"c":"臨","h":"lâm"},{"c":"淵","h":"uyên"},{"c":"羨","h":"tiện"},{"c":"魚","h":"ngư"}],"poem":{"han":"臨淵空羨游魚樂／不若歸家結網勤","hv":"Lâm uyên không tiện du ngư lạc / Bất nhược quy gia kết võng cần","vi":"Đứng bên vực thèm cá bơi vui; chẳng bằng về nhà chăm đan lưới."},"example":"成功を羨むだけでは臨淵羨魚で終わる。","example_reading":"せいこうをうらやむだけではりんえんせんぎょでおわる。","example_meaning":"Chỉ ghen tị với thành công thì mãi chỉ là đứng bên vực thèm cá.","examples":[{"example":"成功を羨むだけでは臨淵羨魚で終わる。","example_reading":"せいこうをうらやむだけではりんえんせんぎょでおわる。","example_meaning":"Chỉ ghen tị với thành công thì mãi chỉ là đứng bên vực thèm cá."},{"example":"臨淵羨魚をやめて、退いて網を結ぶ努力を始めよう。","example_reading":"りんえんせんぎょをやめて、しりぞいてあみをむすぶどりょくをはじめよう。","example_meaning":"Hãy thôi đứng thèm cá và bắt đầu nỗ lực đan lưới."}],"level":"p2"},
{"word":"買櫝還珠","reading":"ばいとくかんじゅ","meaning":"mua hộp trả ngọc; chọn cái bề ngoài mà bỏ cái giá trị thật, bỏ gốc theo ngọn.","hanviet":"mãi độc hoàn châu","note":"📜 Lịch sử: Hàn Phi Tử - Ngoại trữ thuyết tả thượng: người nước Sở bán ngọc châu ở nước Trịnh, làm hộp bằng gỗ mộc lan, xông hương, đính ngọc quý. Người Trịnh mua hộp rồi trả lại viên ngọc châu. 💡 Thú vị: Hàn Phi Tử kể chuyện để chê người đời chỉ trọng lời hoa mỹ mà bỏ qua nội dung thật sự.","chars":[{"c":"買","h":"mãi"},{"c":"櫝","h":"độc"},{"c":"還","h":"hoàn"},{"c":"珠","h":"châu"}],"poem":{"han":"木蘭為匣薰香飾／鄭客買匣卻還珠","hv":"Mộc lan vi giáp huân hương sức / Trịnh khách mãi giáp khước hoàn châu","vi":"Hộp mộc lan xông hương trang sức; khách Trịnh mua hộp lại trả ngọc."},"example":"見た目の包装ばかり重視するのは買櫝還珠だ。","example_reading":"みためのほうそうばかりじゅうしするのはばいとくかんじゅだ。","example_meaning":"Chỉ coi trọng bao bì bên ngoài là mua hộp trả ngọc.","examples":[{"example":"見た目の包装ばかり重視するのは買櫝還珠だ。","example_reading":"みためのほうそうばかりじゅうしするのはばいとくかんじゅだ。","example_meaning":"Chỉ coi trọng bao bì bên ngoài là mua hộp trả ngọc."},{"example":"安さだけで選ぶと買櫝還珠になる。","example_reading":"やすさだけでえらぶとばいとくかんじゅになる。","example_meaning":"Chỉ chọn theo giá rẻ sẽ thành mua hộp trả ngọc."}],"level":"p2"},
{"word":"鄭人買履","reading":"ていじんばいり","meaning":"người Trịnh mua giày; câu nệ khuôn mẫu, tin vào số đo hơn thực tế.","hanviet":"Trịnh nhân mãi lý","note":"📜 Lịch sử: Hàn Phi Tử - Ngoại trữ thuyết tả thượng: một người Trịnh định mua giày, đo chân xong để quên số đo ở nhà. Đến chợ mới nhớ ra, chạy về lấy, khi quay lại thì chợ đã tan. Người ta hỏi sao không thử giày bằng chân, ông đáp «thà tin số đo, chứ không tin chân mình». 💡 Thú vị: Tích này có cùng tinh thần chê sự cứng nhắc như 刻舟求剣.","chars":[{"c":"鄭","h":"Trịnh"},{"c":"人","h":"nhân"},{"c":"買","h":"mãi"},{"c":"履","h":"lý"}],"poem":{"han":"度足忘攜歸取尺／市罷空嗟履未成","hv":"Độ túc vong huề quy thủ xích / Thị bãi không ta lý vị thành","vi":"Đo chân quên mang, về lấy thước; chợ tan than uổng, giày chưa mua được."},"example":"マニュアルに縛られて動けないのは鄭人買履だ。","example_reading":"マニュアルにしばられてうごけないのはていじんばいりだ。","example_meaning":"Bị cẩm nang trói buộc mà không dám hành động là người Trịnh mua giày.","examples":[{"example":"マニュアルに縛られて動けないのは鄭人買履だ。","example_reading":"マニュアルにしばられてうごけないのはていじんばいりだ。","example_meaning":"Bị cẩm nang trói buộc mà không dám hành động là người Trịnh mua giày."},{"example":"現場を見ず資料だけで決めるのは鄭人買履に似ている。","example_reading":"げんばをみずしりょうだけできめるのはていじんばいりににている。","example_meaning":"Quyết định chỉ dựa tài liệu mà không xem hiện trường giống người Trịnh mua giày."}],"level":"p2"},
{"word":"老驥伏櫪","reading":"ろうきふくれき","meaning":"ngựa già nằm chuồng; tuổi già mà chí lớn vẫn còn.","hanviet":"lão ký phục lịch","note":"📜 Lịch sử: Tào Tháo - Bộ xuất Hạ môn hành (Quy tuy thọ): «Lão ký phục lịch, chí tại thiên lý; liệt sĩ mộ niên, tráng tâm bất dĩ» (老驥伏櫪，志在千里；烈士暮年，壯心不已): ngựa già nằm chuồng mà chí vẫn ở nghìn dặm, liệt sĩ tuổi muộn, tráng chí chưa nguôi. 💡 Thú vị: Bài «Quy tuy thọ» được viết khi Tào Tháo hành quân đánh Ô Hoàn, và câu này thường dùng để khích lệ người cao tuổi.","chars":[{"c":"老","h":"lão"},{"c":"驥","h":"ký"},{"c":"伏","h":"phục"},{"c":"櫪","h":"lịch"}],"poem":{"han":"驥老伏櫪志千里／烈士暮年壯不休","hv":"Ký lão phục lịch chí thiên lý / Liệt sĩ mộ niên tráng bất hưu","vi":"Ngựa kỳ già nằm chuồng, chí nghìn dặm; liệt sĩ tuổi muộn, tráng chí chẳng ngơi."},"example":"定年後も老驥伏櫪の気概で働いている。","example_reading":"ていねんごもろうきふくれきのきがいではたらいている。","example_meaning":"Sau khi nghỉ hưu, ông vẫn làm việc với chí khí của ngựa già.","examples":[{"example":"定年後も老驥伏櫪の気概で働いている。","example_reading":"ていねんごもろうきふくれきのきがいではたらいている。","example_meaning":"Sau khi nghỉ hưu, ông vẫn làm việc với chí khí của ngựa già."},{"example":"祖父は老驥伏櫪、八十を過ぎても学び続けている。","example_reading":"そふはろうきふくれき、はちじゅうをすぎてもまなびつづけている。","example_meaning":"Ông tôi chí lớn không già, qua tám mươi vẫn học tiếp."}],"level":"p2"},
{"word":"髀肉之嘆","reading":"ひにくのたん","meaning":"than thở vì thịt đùi nở ra; than tiếc không có dịp lập công, uổng phí thời gian.","hanviet":"bễ nhục chi thán","note":"📜 Lịch sử: Tam quốc chí - Thục thư - Tiên chủ truyện (chú dẫn Cửu châu xuân thu): Lưu Bị ở Kinh Châu nương nhờ Lưu Biểu, đi vệ sinh thấy thịt đùi nở ra thì khóc, nói: «Xưa không rời yên ngựa, thịt đùi tiêu hết; nay không cưỡi ngựa, thịt đùi lại nở. Ngày tháng trôi qua, tuổi già sắp đến mà công nghiệp chưa lập.» 💡 Thú vị: Tiếng Nhật thường dùng dạng 髀肉の嘆をかこつ (than thở vì không có dịp thể hiện).","chars":[{"c":"髀","h":"bễ"},{"c":"肉","h":"nhục"},{"c":"之","h":"chi"},{"c":"嘆","h":"thán"}],"poem":{"han":"久不騎鞍髀肉長／英雄歎老業難成","hv":"Cửu bất kỵ an bễ nhục trưởng / Anh hùng thán lão nghiệp nan thành","vi":"Lâu không cưỡi ngựa, thịt đùi nở; anh hùng than già, nghiệp khó thành."},"example":"実力を発揮する機会がなく、髀肉の嘆をかこっている。","example_reading":"じつりょくをはっきするきかいがなく、ひにくのたんをかこっている。","example_meaning":"Không có cơ hội thể hiện thực lực nên đang than thở.","examples":[{"example":"実力を発揮する機会がなく、髀肉の嘆をかこっている。","example_reading":"じつりょくをはっきするきかいがなく、ひにくのたんをかこっている。","example_meaning":"Không có cơ hội thể hiện thực lực nên đang than thở."},{"example":"若手は髀肉の嘆を抱かず、挑戦の場を求めてほしい。","example_reading":"わかてはひにくのたんをいだかず、ちょうせんのばをもとめてほしい。","example_meaning":"Mong lớp trẻ đừng than thở mà hãy tìm nơi để thử thách."}],"level":"p2"},
{"word":"乱臣賊子","reading":"らんしんぞくし","meaning":"bề tôi làm loạn, con cái bất hiếu; kẻ phản nghịch trái đạo luân thường.","hanviet":"loạn thần tặc tử","note":"📜 Lịch sử: Mạnh Tử - Đằng Văn công hạ: Mạnh Tử nói thời loạn đạo thánh suy, bề tôi giết vua, con giết cha; Khổng Tử soạn sách Xuân Thu khiến loạn thần tặc tử phải sợ (孔子成春秋而亂臣賊子懼). 💡 Thú vị: Câu này nói lên sức mạnh của việc ghi chép lịch sử: lời phán xét của sử bút làm kẻ phản nghịch phải e sợ.","chars":[{"c":"乱","h":"loạn"},{"c":"臣","h":"thần"},{"c":"賊","h":"tặc"},{"c":"子","h":"tử"}],"poem":{"han":"春秋一部權衡筆／亂賊聞之膽盡寒","hv":"Xuân Thu nhất bộ quyền hành bút / Loạn tặc văn chi đảm tận hàn","vi":"Một bộ Xuân Thu là ngòi bút cân nhắc; loạn tặc nghe tới, mật đều lạnh."},"example":"歴史書は乱臣賊子を厳しく批判している。","example_reading":"れきししょはらんしんぞくしをきびしくひはんしている。","example_meaning":"Sử sách phê phán nghiêm khắc bọn loạn thần tặc tử.","examples":[{"example":"歴史書は乱臣賊子を厳しく批判している。","example_reading":"れきししょはらんしんぞくしをきびしくひはんしている。","example_meaning":"Sử sách phê phán nghiêm khắc bọn loạn thần tặc tử."},{"example":"乱臣賊子とされた人物にも、再評価が進んでいる。","example_reading":"らんしんぞくしとされたじんぶつにも、さいひょうかがすすんでいる。","example_meaning":"Những nhân vật từng bị xem là loạn thần tặc tử cũng đang được đánh giá lại."}],"level":"p2"},
{"word":"一暴十寒","reading":"いちばくじっかん","meaning":"một ngày nắng, mười ngày lạnh; làm ít bỏ nhiều, không kiên trì thì khó thành.\n(Còn viết 一曝十寒.)","hanviet":"nhất bộc thập hàn","note":"📜 Lịch sử: Mạnh Tử - Cáo Tử thượng: Mạnh Tử nói dù là loại cây dễ sống nhất, phơi nắng một ngày rồi để lạnh mười ngày thì cũng không sống được. Ông dùng để ví việc vua Tề ít khi gặp người hiền, phần lớn thời gian lại ở bên kẻ nịnh. 💡 Thú vị: Chữ 曝 nghĩa là phơi nắng, nên dạng viết 一曝十寒 cũng thường được dùng.","chars":[{"c":"一","h":"nhất"},{"c":"暴","h":"bộc"},{"c":"十","h":"thập"},{"c":"寒","h":"hàn"}],"poem":{"han":"一日曝陽十日凍／易生之物亦難榮","hv":"Nhất nhật bộc dương thập nhật đống / Dị sinh chi vật diệc nan vinh","vi":"Một ngày phơi nắng, mười ngày đóng băng; cây dễ sống cũng khó thịnh."},"example":"三日坊主の勉強は一暴十寒で身につかない。","example_reading":"みっかぼうずのべんきょうはいちばくじっかんでみにつかない。","example_meaning":"Học ba ngày bỏ mười ngày thì không thấm.","examples":[{"example":"三日坊主の勉強は一暴十寒で身につかない。","example_reading":"みっかぼうずのべんきょうはいちばくじっかんでみにつかない。","example_meaning":"Học ba ngày bỏ mười ngày thì không thấm."},{"example":"一暴十寒にならないよう、毎日少しずつ続けよう。","example_reading":"いちばくじっかんにならないよう、まいにちすこしずつつづけよう。","example_meaning":"Hãy làm mỗi ngày một ít để khỏi thành làm ít bỏ nhiều."}],"level":"p2"},
{"word":"朽木糞牆","reading":"きゅうぼくふんしょう","meaning":"gỗ mục không khắc được, tường phân không trát được; người lười biếng, không thể dạy dỗ.","hanviet":"hủ mộc phẩn tường","note":"📜 Lịch sử: Luận ngữ - Công Dã Tràng: Tể Dư ban ngày ngủ; Khổng Tử nói «Gỗ mục không thể chạm khắc, tường phân không thể trát; đối với Dư, ta còn trách làm gì?» (朽木不可雕也，糞土之牆不可杇也). 💡 Thú vị: Khổng Tử còn nói thêm: «Trước đây ta nghe lời mà tin hành vi, nay ta nghe lời lại phải xem hành vi»; lời này cũng do chuyện Tể Dư mà ra.","chars":[{"c":"朽","h":"hủ"},{"c":"木","h":"mộc"},{"c":"糞","h":"phẩn"},{"c":"牆","h":"tường"}],"poem":{"han":"朽木難雕牆難圬／晝眠宰予聖人嗟","hv":"Hủ mộc nan điêu tường nan ô / Trú miên Tể Dư thánh nhân ta","vi":"Gỗ mục khó khắc, tường khó trát; Tể Dư ngủ ngày, bậc thánh than."},"example":"やる気のない態度に、先生は朽木糞牆と嘆いた。","example_reading":"やるきのないたいどに、せんせいはきゅうぼくふんしょうとなげいた。","example_meaning":"Trước thái độ thiếu chí tiến thủ, thầy than rằng không thể dạy nổi.","examples":[{"example":"やる気のない態度に、先生は朽木糞牆と嘆いた。","example_reading":"やるきのないたいどに、せんせいはきゅうぼくふんしょうとなげいた。","example_meaning":"Trước thái độ thiếu chí tiến thủ, thầy than rằng không thể dạy nổi."},{"example":"朽木糞牆と見放されても、彼は努力を続けた。","example_reading":"きゅうぼくふんしょうとみはなされても、かれはどりょくをつづけた。","example_meaning":"Dù bị bỏ rơi như gỗ mục, anh vẫn tiếp tục cố gắng."}],"level":"p2"},
{"word":"一以貫之","reading":"いちいかんし","meaning":"dùng một nguyên tắc xuyên suốt mọi việc; giữ lập trường, lý niệm nhất quán.","hanviet":"nhất dĩ quán chi","note":"📜 Lịch sử: Luận ngữ - Vệ Linh Công: Khổng Tử hỏi Tử Cống: «Ngươi cho ta là người học nhiều mà nhớ hết sao?» Tử Cống đáp: «Phải, chẳng phải vậy sao?» Khổng Tử nói: «Không phải, ta dùng một (nguyên lý) để quán xuyến tất cả». Trong Luận ngữ - Lý nhân, Tăng Tử giải thích «đạo của thầy chỉ là trung và thứ mà thôi». 💡 Thú vị: Chữ «một» ở đây là chủ đề tranh luận của nhiều đời học giả: là «trung thứ», hay là «nhân», hay là điều khác.","chars":[{"c":"一","h":"nhất"},{"c":"以","h":"dĩ"},{"c":"貫","h":"quán"},{"c":"之","h":"chi"}],"poem":{"han":"多學而識非夫子／一以貫之道自明","hv":"Đa học nhi thức phi phu tử / Nhất dĩ quán chi đạo tự minh","vi":"Học nhiều nhớ nhiều chẳng phải thầy; một lẽ xuyên suốt, đạo tự sáng."},"example":"彼は理念を一以貫之して会社を経営してきた。","example_reading":"かれはりねんをいちいかんしてかいしゃをけいえいしてきた。","example_meaning":"Ông điều hành công ty bằng một lý niệm nhất quán.","examples":[{"example":"彼は理念を一以貫之して会社を経営してきた。","example_reading":"かれはりねんをいちいかんしてかいしゃをけいえいしてきた。","example_meaning":"Ông điều hành công ty bằng một lý niệm nhất quán."},{"example":"一以貫之の姿勢が周囲の信頼を生んだ。","example_reading":"いちいかんしのしせいがしゅういのしんらいをうんだ。","example_meaning":"Thái độ nhất quán đã tạo nên lòng tin của mọi người."}],"level":"p2"},
{"word":"苛政猛虎","reading":"かせいもうこ（かせいはとらよりもたけし）","meaning":"chính sách hà khắc còn dữ hơn hổ.","hanviet":"hà chính mãnh hổ","note":"📜 Lịch sử: Lễ ký - Đàn cung hạ: Khổng Tử đi qua núi Thái, thấy một người phụ nữ khóc bên mộ; hỏi ra thì cha chồng, chồng rồi con trai bà đều chết vì hổ. Hỏi sao không rời đi, bà đáp «ở đây không có chính sách hà khắc». Khổng Tử bảo học trò: «Chính sách hà khắc còn dữ hơn hổ!» (苛政猛於虎也). 💡 Thú vị: Liễu Tông Nguyên trong «Bổ xà giả thuyết» cũng dùng ý này để tố cáo thuế khóa nặng nề.","chars":[{"c":"苛","h":"hà"},{"c":"政","h":"chính"},{"c":"猛","h":"mãnh"},{"c":"虎","h":"hổ"}],"poem":{"han":"泰山婦哭親亡虎／猛不如苛政害民","hv":"Thái sơn phụ khốc thân vong hổ / Mãnh bất như hà chính hại dân","vi":"Người đàn bà núi Thái khóc người thân chết vì hổ; hổ dữ chẳng bằng chính sách hà khắc hại dân."},"example":"重税や厳罰は苛政猛虎と批判された。","example_reading":"じゅうぜいやげんばつはかせいもうことひはんされた。","example_meaning":"Thuế nặng và hình phạt nghiêm bị chỉ trích là hà chính dữ hơn hổ.","examples":[{"example":"重税や厳罰は苛政猛虎と批判された。","example_reading":"じゅうぜいやげんばつはかせいもうことひはんされた。","example_meaning":"Thuế nặng và hình phạt nghiêm bị chỉ trích là hà chính dữ hơn hổ."},{"example":"苛政は虎よりも猛しというが、民の暮らしを苦しめる政策は避けたい。","example_reading":"かせいはとらよりもたけしというが、たみのくらしをくるしめるせいさくはさけたい。","example_meaning":"Hà chính dữ hơn hổ; chúng ta nên tránh chính sách làm khổ dân."}],"level":"p2"},
{"word":"小国寡民","reading":"しょうこくかみん","meaning":"nước nhỏ dân ít; xã hội lý tưởng giản dị theo Lão Tử.","hanviet":"tiểu quốc quả dân","note":"📜 Lịch sử: Lão Tử - chương 80: «Tiểu quốc quả dân, sử hữu thập bá chi khí nhi bất dụng» (小國寡民，使有什伯之器而不用): nước nhỏ dân ít, có dụng cụ gấp chục gấp trăm mà không dùng; dân coi trọng cái chết nên không đi xa; nghe tiếng gà chó của nhau mà đến già chết cũng không qua lại. 💡 Thú vị: Hình ảnh này gần với «Đào hoa nguyên» của Đào Uyên Minh và thường được nhắc khi bàn về lối sống giản dị, tự cung tự cấp.","chars":[{"c":"小","h":"tiểu"},{"c":"国","h":"quốc"},{"c":"寡","h":"quả"},{"c":"民","h":"dân"}],"poem":{"han":"雞犬相聞民老死／不相往來樂安居","hv":"Kê khuyển tương văn dân lão tử / Bất tương vãng lai lạc an cư","vi":"Nghe tiếng gà chó nhau, dân già chết; chẳng qua lại mà vui an cư."},"example":"小さな村の暮らしは小国寡民を思わせる。","example_reading":"ちいさなむらのくらしはしょうこくかみんをおもわせる。","example_meaning":"Cuộc sống ở ngôi làng nhỏ gợi nhớ nước nhỏ dân ít.","examples":[{"example":"小さな村の暮らしは小国寡民を思わせる。","example_reading":"ちいさなむらのくらしはしょうこくかみんをおもわせる。","example_meaning":"Cuộc sống ở ngôi làng nhỏ gợi nhớ nước nhỏ dân ít."},{"example":"小国寡民は、老子が描いた理想の社会だ。","example_reading":"しょうこくかみんは、ろうしがえがいたりそうのしゃかいだ。","example_meaning":"Nước nhỏ dân ít là xã hội lý tưởng do Lão Tử vẽ ra."}],"level":"p2"},
{"word":"和光同塵","reading":"わこうどうじん","meaning":"che bớt ánh sáng, hòa vào bụi đời; người tài đức sống khiêm tốn, hòa đồng với người thường.","hanviet":"hòa quang đồng trần","note":"📜 Lịch sử: Lão Tử - chương 4 và chương 56: «Hòa kỳ quang, đồng kỳ trần» (和其光，同其塵): làm dịu ánh sáng của mình, hòa cùng bụi đời. Ý là bậc trí giả không phô trương tài năng. 💡 Thú vị: Ở Nhật, 和光同塵 còn mang nghĩa thần Phật tạm hiện thân dưới dạng thần linh để cứu độ chúng sinh (tư tưởng 本地垂迹).","chars":[{"c":"和","h":"hòa"},{"c":"光","h":"quang"},{"c":"同","h":"đồng"},{"c":"塵","h":"trần"}],"poem":{"han":"韜光晦跡混塵世／大智如愚不炫奇","hv":"Thao quang hối tích hỗn trần thế / Đại trí như ngu bất huyễn kỳ","vi":"Giấu sáng ẩn dấu vết, hòa vào trần thế; đại trí như ngu, chẳng khoe điều lạ."},"example":"彼は才能がありながら和光同塵の生き方を選んだ。","example_reading":"かれはさいのうがありながらわこうどうじんのいきかたをえらんだ。","example_meaning":"Anh ấy có tài nhưng chọn lối sống khiêm tốn, hòa đồng.","examples":[{"example":"彼は才能がありながら和光同塵の生き方を選んだ。","example_reading":"かれはさいのうがありながらわこうどうじんのいきかたをえらんだ。","example_meaning":"Anh ấy có tài nhưng chọn lối sống khiêm tốn, hòa đồng."},{"example":"和光同塵の精神で、地域の人々と共に暮らす。","example_reading":"わこうどうじんのせいしんで、ちいきのひとびととともにくらす。","example_meaning":"Tôi sống cùng mọi người trong vùng với tinh thần hòa mình."}],"level":"p2"},
{"word":"朝菌晦朔","reading":"ちょうきんかいさく","meaning":"nấm sớm không biết cuối tháng đầu tháng; sinh vật sống quá ngắn, không hiểu thế giới lớn hơn mình.","hanviet":"triêu khuẩn hối sóc","note":"📜 Lịch sử: Trang Tử - Tiêu dao du: «Triêu khuẩn bất tri hối sóc, huệ cô bất tri xuân thu» (朝菌不知晦朔，蟪蛄不知春秋): nấm sớm sống một buổi sáng nên không biết ngày cuối và ngày đầu tháng, ve sầu mùa hè không biết xuân thu. Trang Tử dùng để nói cái «tiểu niên» không sánh được với «đại niên». 💡 Thú vị: Cũng trong thiên này có chuyện chim Bằng bay chín vạn dặm, đối lập với con ve và chim cưu cười nhạo.","chars":[{"c":"朝","h":"triêu"},{"c":"菌","h":"khuẩn"},{"c":"晦","h":"hối"},{"c":"朔","h":"sóc"}],"poem":{"han":"朝菌不識晦與朔／蟪蛄安知春復秋","hv":"Triêu khuẩn bất thức hối dữ sóc / Huệ cô an tri xuân phục thu","vi":"Nấm sớm chẳng biết cuối và đầu tháng; ve sầu sao biết xuân lại thu."},"example":"短い経験で語るのは朝菌晦朔のようなものだ。","example_reading":"みじかいけいけんでかたるのはちょうきんかいさくのようなものだ。","example_meaning":"Nói dựa trên kinh nghiệm ngắn ngủi giống như nấm sớm không biết hối sóc.","examples":[{"example":"短い経験で語るのは朝菌晦朔のようなものだ。","example_reading":"みじかいけいけんでかたるのはちょうきんかいさくのようなものだ。","example_meaning":"Nói dựa trên kinh nghiệm ngắn ngủi giống như nấm sớm không biết hối sóc."},{"example":"私たちの知識は朝菌晦朔にすぎないのかもしれない。","example_reading":"わたしたちのちしきはちょうきんかいさくにすぎないのかもしれない。","example_meaning":"Có thể kiến thức của chúng ta chỉ như nấm sớm."}],"level":"p2"},
{"word":"鵬程万里","reading":"ほうていばんり","meaning":"đường bay muôn dặm của chim Bằng; tiền đồ rộng mở, xa xôi.","hanviet":"bằng trình vạn lý","note":"📜 Lịch sử: Trang Tử - Tiêu dao du: ở Bắc Minh có cá tên Côn, hóa thành chim Bằng, lưng rộng không biết mấy nghìn dặm; khi bay, cánh như mây rủ chân trời, vỗ nước ba nghìn dặm, lượn theo gió lên chín vạn dặm. 💡 Thú vị: Trong tiếng Nhật, 鵬程万里 hay dùng để chúc cho người tốt nghiệp hoặc người sắp đi xa, đi du học.","chars":[{"c":"鵬","h":"bằng"},{"c":"程","h":"trình"},{"c":"万","h":"vạn"},{"c":"里","h":"lý"}],"poem":{"han":"北冥有魚化為鵬／扶搖直上九萬程","hv":"Bắc Minh hữu ngư hóa vi bằng / Phù dao trực thượng cửu vạn trình","vi":"Bắc Minh có cá hóa thành chim Bằng; lượn gió bay thẳng lên chín vạn dặm."},"example":"卒業生の鵬程万里を祈ります。","example_reading":"そつぎょうせいのほうていばんりをいのります。","example_meaning":"Tôi chúc các em tốt nghiệp tiền đồ rộng mở.","examples":[{"example":"卒業生の鵬程万里を祈ります。","example_reading":"そつぎょうせいのほうていばんりをいのります。","example_meaning":"Tôi chúc các em tốt nghiệp tiền đồ rộng mở."},{"example":"海外へ旅立つ彼に、鵬程万里の言葉を贈った。","example_reading":"かいがいへたびだつかれに、ほうていばんりのことばをおくった。","example_meaning":"Tôi gửi lời chúc tiền đồ rộng mở cho anh ấy khi anh lên đường ra nước ngoài."}],"level":"p2"},
{"word":"涸轍之鮒","reading":"こてつのふな","meaning":"cá diếc trong vệt bánh xe cạn nước; người đang trong cảnh nguy cấp, cần được cứu gấp.","hanviet":"hạc triệt chi phụ","note":"📜 Lịch sử: Trang Tử - Ngoại vật: Trang Chu nghèo đến vay lương nhà Giám Hà hầu; ông ta hẹn sẽ cho ba trăm lạng vàng khi thu thuế xong. Trang Chu kể: trên đường nghe có tiếng gọi, thấy một con cá diếc nằm trong vệt bánh xe cạn xin chút nước để sống. Ông hứa sẽ dẫn nước sông Tây Giang đến, cá giận đáp: «Đến lúc đó thì thà tìm ta ở hàng cá khô còn hơn». 💡 Thú vị: Tiếng Việt có câu «nước xa không cứu được lửa gần» cùng ý.","chars":[{"c":"涸","h":"hạc"},{"c":"轍","h":"triệt"},{"c":"之","h":"chi"},{"c":"鮒","h":"phụ"}],"poem":{"han":"轍中枯鮒求升水／遠水難救近渴人","hv":"Triệt trung khô phụ cầu thăng thủy / Viễn thủy nan cứu cận khát nhân","vi":"Cá khô trong vệt xe xin một thăng nước; nước xa khó cứu người đang khát."},"example":"涸轍の鮒のように、一刻の猶予もなかった。","example_reading":"こてつのふなのように、いっこくのゆうよもなかった。","example_meaning":"Như cá diếc trong vệt bánh xe cạn, không còn chút thời gian nào.","examples":[{"example":"涸轍の鮒のように、一刻の猶予もなかった。","example_reading":"こてつのふなのように、いっこくのゆうよもなかった。","example_meaning":"Như cá diếc trong vệt bánh xe cạn, không còn chút thời gian nào."},{"example":"資金難の彼らは涸轍の鮒の状態だった。","example_reading":"しきんなんのかれらはこてつのふなのじょうたいだった。","example_meaning":"Họ thiếu vốn, đang trong tình cảnh nguy cấp."}],"level":"p2"},
{"word":"以卵投石","reading":"いらんとうせき","meaning":"lấy trứng chọi đá; không lượng sức, chắc chắn thất bại.","hanviet":"dĩ noãn đầu thạch","note":"📜 Lịch sử: Mặc Tử - Quý nghĩa: Mặc Tử nói với một người nước Lỗ rằng lấy trứng ném đá, dù ném hết trứng trong thiên hạ, đá vẫn nguyên như cũ (以卵投石，盡天下之卵，其石猶是也). 💡 Thú vị: Tiếng Việt có câu «trứng chọi đá» với đúng ý này; Mặc Tử dùng ví dụ để nói về việc không thể thắng người mạnh bằng cách thiếu sức.","chars":[{"c":"以","h":"dĩ"},{"c":"卵","h":"noãn"},{"c":"投","h":"đầu"},{"c":"石","h":"thạch"}],"poem":{"han":"以卵擊石卵先碎／石自巋然不動搖","hv":"Dĩ noãn kích thạch noãn tiên toái / Thạch tự quy nhiên bất động dao","vi":"Lấy trứng đập đá, trứng vỡ trước; đá vẫn sừng sững chẳng lay."},"example":"大企業に挑むのは以卵投石かもしれない。","example_reading":"だいきぎょうにいどむのはいらんとうせきかもしれない。","example_meaning":"Thách đấu tập đoàn lớn có lẽ là trứng chọi đá.","examples":[{"example":"大企業に挑むのは以卵投石かもしれない。","example_reading":"だいきぎょうにいどむのはいらんとうせきかもしれない。","example_meaning":"Thách đấu tập đoàn lớn có lẽ là trứng chọi đá."},{"example":"準備なしの挑戦は以卵投石に終わる。","example_reading":"じゅんびなしのちょうせんはいらんとうせきにおわる。","example_meaning":"Thử thách mà không chuẩn bị chỉ kết thúc bằng trứng chọi đá."}],"level":"p2"},
{"word":"兵貴神速","reading":"へいきしんそく","meaning":"dùng binh quý ở chỗ thần tốc; hành động phải nhanh chóng, kịp thời.","hanviet":"binh quý thần tốc","note":"📜 Lịch sử: Tam quốc chí - Ngụy thư - Quách Gia truyện: Quách Gia khuyên Tào Tháo đánh Ô Hoàn ở xa: «Binh quý thần tốc», nên bỏ bớt quân nhu nặng nề, chọn tinh binh đi nhẹ, đánh bất ngờ. Tào Tháo nghe theo và thắng ở núi Bạch Lang (năm 207). 💡 Thú vị: Tôn Tử cũng đề cao tốc độ với câu «binh quý thắng bất quý cửu» (đánh quý ở thắng nhanh, không quý ở kéo dài).","chars":[{"c":"兵","h":"binh"},{"c":"貴","h":"quý"},{"c":"神","h":"thần"},{"c":"速","h":"tốc"}],"poem":{"han":"輕兵疾進越千里／兵貴神速破烏桓","hv":"Khinh binh tật tiến việt thiên lý / Binh quý thần tốc phá Ô Hoàn","vi":"Quân nhẹ tiến nhanh vượt nghìn dặm; binh quý thần tốc, phá Ô Hoàn."},"example":"兵は神速を貴ぶ、すぐに行動に移そう。","example_reading":"へいはしんそくをたっとぶ、すぐにこうどうにうつそう。","example_meaning":"Binh quý thần tốc, hãy hành động ngay.","examples":[{"example":"兵は神速を貴ぶ、すぐに行動に移そう。","example_reading":"へいはしんそくをたっとぶ、すぐにこうどうにうつそう。","example_meaning":"Binh quý thần tốc, hãy hành động ngay."},{"example":"競争が激しい市場では兵貴神速が求められる。","example_reading":"きょうそうがはげしいしじょうではへいきしんそくがもとめられる。","example_meaning":"Thị trường cạnh tranh gay gắt đòi hỏi sự nhanh chóng."}],"level":"p2"},
{"word":"声東撃西","reading":"せいとうげきせい","meaning":"tiếng đông đánh tây; làm ra vẻ đánh phía đông nhưng thực ra đánh phía tây, tức nghi binh.","hanviet":"thanh đông kích tây","note":"📜 Lịch sử: Thông điển - Binh điển (Đỗ Hữu, đời Đường) có ý: giả vờ nói đánh phía đông mà thực ra đánh phía tây. Về sau cụm này được xếp vào Tam thập lục kế. 💡 Thú vị: Đây là kế thứ 6 trong 36 kế, dùng để đánh lạc hướng đối phương, cả trong quân sự lẫn đàm phán và kinh doanh.","chars":[{"c":"声","h":"thanh"},{"c":"東","h":"đông"},{"c":"撃","h":"kích"},{"c":"西","h":"tây"}],"poem":{"han":"揚言擊東暗襲西／敵不及防我已臨","hv":"Dương ngôn kích đông ám tập tây / Địch bất cập phòng ngã dĩ lâm","vi":"Rêu rao đánh đông, ngầm đánh tây; địch chưa kịp phòng, ta đã tới nơi."},"example":"声東撃西の作戦で相手を混乱させた。","example_reading":"せいとうげきせいのさくせんであいてをこんらんさせた。","example_meaning":"Chúng tôi làm đối thủ rối loạn bằng chiến thuật nghi binh.","examples":[{"example":"声東撃西の作戦で相手を混乱させた。","example_reading":"せいとうげきせいのさくせんであいてをこんらんさせた。","example_meaning":"Chúng tôi làm đối thủ rối loạn bằng chiến thuật nghi binh."},{"example":"声東撃西で、別の議題に注意を向けさせた。","example_reading":"せいとうげきせいで、べつのぎだいにちゅういをむけさせた。","example_meaning":"Họ lái sự chú ý sang chủ đề khác để đánh lạc hướng."}],"level":"p2"},
{"word":"水落石出","reading":"すいらくせきしゅつ","meaning":"nước rút đá lộ ra; sự thật phơi bày khi mọi thứ lắng xuống.","hanviet":"thủy lạc thạch xuất","note":"📜 Lịch sử: Tô Thức - Hậu Xích Bích phú (năm 1082): «Sơn cao nguyệt tiểu, thủy lạc thạch xuất» (山高月小，水落石出): núi cao trăng nhỏ lại, nước rút đá lộ ra. Âu Dương Tu trong «Túy Ông đình ký» cũng có câu «thủy lạc nhi thạch xuất» để tả cảnh bốn mùa. 💡 Thú vị: Cảnh sông thu lạnh trong Hậu Xích Bích phú là bối cảnh nổi tiếng trong thơ văn Đông Á.","chars":[{"c":"水","h":"thủy"},{"c":"落","h":"lạc"},{"c":"石","h":"thạch"},{"c":"出","h":"xuất"}],"poem":{"han":"山高月小江流響／水落石出見真形","hv":"Sơn cao nguyệt tiểu giang lưu hưởng / Thủy lạc thạch xuất kiến chân hình","vi":"Núi cao trăng nhỏ, tiếng sông reo; nước rút đá lộ, thấy hình thật."},"example":"調査が進み、事件は水落石出となった。","example_reading":"ちょうさがすすみ、じけんはすいらくせきしゅつとなった。","example_meaning":"Cuộc điều tra tiến triển, vụ án đã được làm sáng tỏ.","examples":[{"example":"調査が進み、事件は水落石出となった。","example_reading":"ちょうさがすすみ、じけんはすいらくせきしゅつとなった。","example_meaning":"Cuộc điều tra tiến triển, vụ án đã được làm sáng tỏ."},{"example":"時間がたてば、真相は水落石出するはずだ。","example_reading":"じかんがたてば、しんそうはすいらくせきしゅつするはずだ。","example_meaning":"Thời gian trôi qua, sự thật hẳn sẽ lộ ra."}],"level":"p2"},
{"word":"疑鄰窃斧","reading":"ぎりんせっぷ","meaning":"ngờ hàng xóm ăn trộm rìu; đã có định kiến thì nhìn gì cũng thấy đáng ngờ.","hanviet":"nghi lân thiết phủ","note":"📜 Lịch sử: Liệt Tử - Thuyết phù: người mất rìu nghi con nhà hàng xóm, nhìn dáng đi, nét mặt, lời nói đều thấy giống kẻ trộm. Ít lâu sau đào ruộng tìm được rìu, nhìn lại con nhà hàng xóm thì không thấy giống kẻ trộm nữa. 💡 Thú vị: Thành ngữ 疑心暗鬼を生ず cũng bắt nguồn từ sách Liệt Tử, cùng tinh thần với tích này.","chars":[{"c":"疑","h":"nghi"},{"c":"鄰","h":"lân"},{"c":"窃","h":"thiết"},{"c":"斧","h":"phủ"}],"poem":{"han":"失斧疑鄰觀舉止／得斧再看已無疑","hv":"Thất phủ nghi lân quan cử chỉ / Đắc phủ tái khán dĩ vô nghi","vi":"Mất rìu ngờ hàng xóm, xem cử chỉ; tìm được rìu, nhìn lại chẳng còn ngờ."},"example":"先入観が強いと疑鄰窃斧に陥りやすい。","example_reading":"せんにゅうかんがつよいとぎりんせっぷにおちいりやすい。","example_meaning":"Định kiến mạnh thì dễ rơi vào cảnh ngờ vực người.","examples":[{"example":"先入観が強いと疑鄰窃斧に陥りやすい。","example_reading":"せんにゅうかんがつよいとぎりんせっぷにおちいりやすい。","example_meaning":"Định kiến mạnh thì dễ rơi vào cảnh ngờ vực người."},{"example":"彼を疑ったのは疑鄰窃斧だった。","example_reading":"かれをうたがったのはぎりんせっぷだった。","example_meaning":"Việc tôi nghi anh ấy hóa ra chỉ là định kiến."}],"level":"p2"},
{"word":"伯牙絶絃","reading":"はくがぜつげん","meaning":"bá Nha đứt dây đàn; mất người bạn tri âm, thương tiếc người bạn thân.","hanviet":"Bá Nha tuyệt huyền","note":"📜 Lịch sử: Lã thị Xuân Thu - Bản vị: Chung Tử Kỳ mất, Bá Nha bẻ đàn, đứt dây, suốt đời không gảy đàn nữa vì cho rằng không còn ai đáng để gảy cho nghe. 💡 Thú vị: Từ «tri âm» (知音), tức người hiểu tiếng lòng mình, bắt nguồn từ tích Bá Nha - Tử Kỳ này.","chars":[{"c":"伯","h":"Bá"},{"c":"牙","h":"Nha"},{"c":"絶","h":"tuyệt"},{"c":"絃","h":"huyền"}],"poem":{"han":"子期一逝琴弦斷／終世無人解我音","hv":"Tử Kỳ nhất thệ cầm huyền đoạn / Chung thế vô nhân giải ngã âm","vi":"Tử Kỳ mất rồi, dây đàn đứt; cả đời không ai hiểu tiếng ta."},"example":"親友を亡くし、伯牙絶絃の思いだった。","example_reading":"しんゆうをなくし、はくがぜつげんのおもいだった。","example_meaning":"Mất bạn thân, tôi như Bá Nha đứt dây đàn.","examples":[{"example":"親友を亡くし、伯牙絶絃の思いだった。","example_reading":"しんゆうをなくし、はくがぜつげんのおもいだった。","example_meaning":"Mất bạn thân, tôi như Bá Nha đứt dây đàn."},{"example":"伯牙絶絃のように、彼は筆を折った。","example_reading":"はくがぜつげんのように、かれはふでをおった。","example_meaning":"Như Bá Nha đứt dây đàn, ông ấy gác bút."}],"level":"p2"},
{"word":"莫逆之友","reading":"ばくぎゃくのとも","meaning":"người bạn không có gì trái ý nhau; bạn tâm giao.","hanviet":"mạc nghịch chi hữu","note":"📜 Lịch sử: Trang Tử - Đại tông sư: bốn người Tử Tự, Tử Dư, Tử Lê, Tử Lai nhìn nhau mà cười, «mạc nghịch ư tâm, toại dữ vi hữu» (莫逆於心，遂相與為友): lòng không trái nhau nên kết làm bạn. Họ coi sống chết như một thể. 💡 Thú vị: Tiếng Việt cũng dùng «mạc nghịch chi giao» để nói về tình bạn tâm đầu ý hợp.","chars":[{"c":"莫","h":"mạc"},{"c":"逆","h":"nghịch"},{"c":"之","h":"chi"},{"c":"友","h":"hữu"}],"poem":{"han":"四人相視莫逆笑／生死一體友誼成","hv":"Tứ nhân tương thị mạc nghịch tiếu / Sinh tử nhất thể hữu nghị thành","vi":"Bốn người nhìn nhau cười, lòng không trái; sống chết một thể, tình bạn nên."},"example":"彼とは莫逆の友で、何でも話せる。","example_reading":"かれとはばくぎゃくのともで、なんでもはなせる。","example_meaning":"Tôi với anh ấy là bạn tâm giao, nói được mọi chuyện.","examples":[{"example":"彼とは莫逆の友で、何でも話せる。","example_reading":"かれとはばくぎゃくのともで、なんでもはなせる。","example_meaning":"Tôi với anh ấy là bạn tâm giao, nói được mọi chuyện."},{"example":"莫逆之友に出会えたのは人生の宝だ。","example_reading":"ばくぎゃくのともにであえたのはじんせいのたからだ。","example_meaning":"Gặp được bạn tâm giao là báu vật của đời."}],"level":"p2"},
{"word":"鑿壁偸光","reading":"さくへきとうこう","meaning":"khoét tường lấy ánh sáng; khổ học trong nghèo khó.","hanviet":"tạc bích thâu quang","note":"📜 Lịch sử: Tây Kinh tạp ký: Khuông Hành (đời Hán) nhà nghèo không có đèn, nhưng nhà hàng xóm có đèn; ông khoét thủng tường để lấy ánh sáng đọc sách. Về sau ông làm đến thừa tướng. 💡 Thú vị: Ông còn từng làm việc không lấy công cho một nhà giàu, chỉ xin được đọc sách của họ; tích này thường đi cùng 蛍雪之功 và 懸頭刺股 như ba tấm gương khổ học.","chars":[{"c":"鑿","h":"tạc"},{"c":"壁","h":"bích"},{"c":"偸","h":"thâu"},{"c":"光","h":"quang"}],"poem":{"han":"壁穿引得鄰燈火／夜夜書聲到五更","hv":"Bích xuyên dẫn đắc lân đăng hỏa / Dạ dạ thư thanh đáo ngũ canh","vi":"Khoét tường mượn ánh đèn hàng xóm; đêm đêm tiếng đọc sách đến canh năm."},"example":"鑿壁偸光の精神で、図書館に通い詰めた。","example_reading":"さくへきとうこうのせいしんで、としょかんにかよいつめた。","example_meaning":"Với tinh thần khoét tường lấy sáng, tôi đến thư viện liên tục.","examples":[{"example":"鑿壁偸光の精神で、図書館に通い詰めた。","example_reading":"さくへきとうこうのせいしんで、としょかんにかよいつめた。","example_meaning":"Với tinh thần khoét tường lấy sáng, tôi đến thư viện liên tục."},{"example":"貧しい中で学んだ鑿壁偸光の話は有名だ。","example_reading":"まずしいなかでまなんださくへきとうこうのはなしはゆうめいだ。","example_meaning":"Chuyện khoét tường lấy sáng học trong nghèo khó rất nổi tiếng."}],"level":"p2"},
{"word":"鉄杵磨針","reading":"てっしょましん","meaning":"mài chày sắt thành kim; kiên trì thì việc khó cũng thành.","hanviet":"thiết chử ma châm","note":"📜 Lịch sử: Phương dư thắng lãm (đời Tống): Lý Bạch lúc nhỏ bỏ học đi chơi, gặp một bà lão mài chày sắt bên suối. Hỏi ra, bà đáp mài để thành cây kim thêu. Lý Bạch hổ thẹn, quay về chăm học. 💡 Thú vị: Tiếng Việt có câu «có công mài sắt có ngày nên kim» cùng ý.","chars":[{"c":"鉄","h":"thiết"},{"c":"杵","h":"chử"},{"c":"磨","h":"ma"},{"c":"針","h":"châm"}],"poem":{"han":"老嫗溪邊磨鐵杵／太白慚歸讀古書","hv":"Lão ẩu khê biên ma thiết chử / Thái Bạch tàm quy độc cổ thư","vi":"Bà lão bên suối mài chày sắt; Thái Bạch hổ thẹn, về đọc sách cổ."},"example":"鉄杵磨針、努力を続ければ必ず成就する。","example_reading":"てっしょましん、どりょくをつづければかならずじょうじゅする。","example_meaning":"Mài chày sắt thành kim, cứ cố gắng thì ắt thành.","examples":[{"example":"鉄杵磨針、努力を続ければ必ず成就する。","example_reading":"てっしょましん、どりょくをつづければかならずじょうじゅする。","example_meaning":"Mài chày sắt thành kim, cứ cố gắng thì ắt thành."},{"example":"鉄杵磨針の心で毎日練習した。","example_reading":"てっしょましんのこころでまいにちれんしゅうした。","example_meaning":"Tôi luyện tập mỗi ngày với tinh thần mài sắt thành kim."}],"level":"p2"},
{"word":"登高自卑","reading":"とうこうじひ","meaning":"leo cao bắt đầu từ chỗ thấp; việc lớn phải khởi đầu từ cái gần, cái nhỏ.","hanviet":"đăng cao tự ti","note":"📜 Lịch sử: Trung dung chương 15: «Quân tử chi đạo, thí như hành viễn tất tự nhĩ, thí như đăng cao tất tự ti» (君子之道，辟如行遠必自邇，辟如登高必自卑): đạo quân tử ví như đi xa phải bắt đầu từ gần, như leo cao phải bắt đầu từ chỗ thấp. 💡 Thú vị: Tiếng Việt có câu «đi xa bắt đầu từ bước đầu» cùng tinh thần.","chars":[{"c":"登","h":"đăng"},{"c":"高","h":"cao"},{"c":"自","h":"tự"},{"c":"卑","h":"ti"}],"poem":{"han":"行遠必先從近始／登高須自下層升","hv":"Hành viễn tất tiên tòng cận thủy / Đăng cao tu tự hạ tằng thăng","vi":"Đi xa ắt phải từ gần bắt đầu; leo cao phải từ tầng thấp lên."},"example":"基礎から積み上げる登高自卑の姿勢が大切だ。","example_reading":"きそからつみあげるとうこうじひのしせいがたいせつだ。","example_meaning":"Thái độ tích lũy từ nền tảng, leo cao từ chỗ thấp là quan trọng.","examples":[{"example":"基礎から積み上げる登高自卑の姿勢が大切だ。","example_reading":"きそからつみあげるとうこうじひのしせいがたいせつだ。","example_meaning":"Thái độ tích lũy từ nền tảng, leo cao từ chỗ thấp là quan trọng."},{"example":"登高自卑で、まずは小さな目標から始めよう。","example_reading":"とうこうじひで、まずはちいさなもくひょうからはじめよう。","example_meaning":"Leo cao từ chỗ thấp, hãy bắt đầu từ mục tiêu nhỏ."}],"level":"p2"},
{"word":"格物致知","reading":"かくぶつちち","meaning":"xét sự vật để đạt tri thức; tìm hiểu đến cùng sự vật để có hiểu biết chân chính.","hanviet":"cách vật trí tri","note":"📜 Lịch sử: Đại học (trong Lễ ký): «Dục thành kỳ ý giả, tiên trí kỳ tri; trí tri tại cách vật» (致知在格物). Đây là bước đầu trong «bát điều mục»: cách vật, trí tri, thành ý, chính tâm, tu thân, tề gia, trị quốc, bình thiên hạ. 💡 Thú vị: Chu Hy giải «cách vật» là xét cái lý của sự vật, còn Vương Dương Minh lại giải theo hướng chính tâm; đó là một trong những tranh luận lớn của Tống Nho và Minh Nho.","chars":[{"c":"格","h":"cách"},{"c":"物","h":"vật"},{"c":"致","h":"trí"},{"c":"知","h":"tri"}],"poem":{"han":"窮理格物求真知／八目始端此一階","hv":"Cùng lý cách vật cầu chân tri / Bát mục thủy đoan thử nhất giai","vi":"Cùng lý xét vật để cầu hiểu biết thật; bước đầu của tám điều mục là đây."},"example":"格物致知の精神で、現場を丁寧に調べた。","example_reading":"かくぶつちちのせいしんで、げんばをていねいにしらべた。","example_meaning":"Với tinh thần cách vật trí tri, tôi điều tra kỹ hiện trường.","examples":[{"example":"格物致知の精神で、現場を丁寧に調べた。","example_reading":"かくぶつちちのせいしんで、げんばをていねいにしらべた。","example_meaning":"Với tinh thần cách vật trí tri, tôi điều tra kỹ hiện trường."},{"example":"朱子学では格物致知が重んじられた。","example_reading":"しゅしがくではかくぶつちちがおもんじられた。","example_meaning":"Trong Chu Tử học, cách vật trí tri được coi trọng."}],"level":"p2"},
{"word":"亢竜有悔","reading":"こうりゅうくいあり","meaning":"rồng bay quá cao sẽ có điều hối hận; ở đỉnh cao quyền lực thì dễ sa sút, cần biết dừng.","hanviet":"kháng long hữu hối","note":"📜 Lịch sử: Kinh Dịch - quẻ Càn, thượng cửu: «Kháng long hữu hối» (亢龍有悔): rồng lên quá cao, không còn đường tiến, ắt có hối hận. Ý nhắc người ở đỉnh cao đừng kiêu ngạo. 💡 Thú vị: Trong tiểu thuyết kiếm hiệp Kim Dung, «Kháng long hữu hối» là chiêu thức nổi tiếng của Giáng Long Thập Bát Chưởng nên cụm từ này khá quen với độc giả Việt Nam.","chars":[{"c":"亢","h":"kháng"},{"c":"竜","h":"long"},{"c":"有","h":"hữu"},{"c":"悔","h":"hối"}],"poem":{"han":"龍飛九五位已極／再進難容悔自生","hv":"Long phi cửu ngũ vị dĩ cực / Tái tiến nan dung hối tự sinh","vi":"Rồng bay đến ngôi cửu ngũ là cực điểm; tiến thêm thì khó dung, hối hận tự sinh."},"example":"絶頂期こそ、亢竜有悔を戒めるべきだ。","example_reading":"ぜっちょうきこそ、こうりゅうくいありをいましめるべきだ。","example_meaning":"Chính lúc đỉnh cao càng phải nhớ rồng lên cao thì có hối.","examples":[{"example":"絶頂期こそ、亢竜有悔を戒めるべきだ。","example_reading":"ぜっちょうきこそ、こうりゅうくいありをいましめるべきだ。","example_meaning":"Chính lúc đỉnh cao càng phải nhớ rồng lên cao thì có hối."},{"example":"成功に驕れば亢竜有悔となる。","example_reading":"せいこうにおごればこうりゅうくいありとなる。","example_meaning":"Kiêu ngạo khi thành công thì sẽ có ngày hối hận."}],"level":"p2"},
{"word":"自強不息","reading":"じきょうふそく","meaning":"tự mình cố gắng không ngừng.","hanviet":"tự cường bất tức","note":"📜 Lịch sử: Kinh Dịch - quẻ Càn, Đại tượng truyện: «Thiên hành kiện, quân tử dĩ tự cường bất tức» (天行健，君子以自強不息): trời vận hành mạnh mẽ, quân tử noi theo mà tự cường không nghỉ. 💡 Thú vị: Câu này cùng với «hậu đức tải vật» (từ quẻ Khôn) là phương châm của Đại học Thanh Hoa (Trung Quốc).","chars":[{"c":"自","h":"tự"},{"c":"強","h":"cường"},{"c":"不","h":"bất"},{"c":"息","h":"tức"}],"poem":{"han":"天行剛健無窮已／君子自強奮不休","hv":"Thiên hành cương kiện vô cùng dĩ / Quân tử tự cường phấn bất hưu","vi":"Trời vận hành cương kiện, chẳng cùng tận; quân tử tự cường, phấn đấu không ngơi."},"example":"自強不息の精神で、夢に向かって努力する。","example_reading":"じきょうふそくのせいしんで、ゆめにむかってどりょくする。","example_meaning":"Tôi nỗ lực vì giấc mơ với tinh thần tự cường không ngừng.","examples":[{"example":"自強不息の精神で、夢に向かって努力する。","example_reading":"じきょうふそくのせいしんで、ゆめにむかってどりょくする。","example_meaning":"Tôi nỗ lực vì giấc mơ với tinh thần tự cường không ngừng."},{"example":"彼の自強不息の姿に励まされた。","example_reading":"かれのじきょうふそくのすがたにはげまされた。","example_meaning":"Hình ảnh tự cường không nghỉ của anh ấy đã khích lệ tôi."}],"level":"p2"},
{"word":"窈窕淑女","reading":"ようちょうしゅくじょ","meaning":"người con gái hiền thục, đoan trang.","hanviet":"yểu điệu thục nữ","note":"📜 Lịch sử: Kinh Thi - Chu nam - Quan thư, bài mở đầu cả Kinh Thi: «Quan quan thư cưu, tại hà chi châu; yểu điệu thục nữ, quân tử hảo cầu» (關關雎鳩，在河之洲；窈窕淑女，君子好逑). Bài thơ nói chàng trai trằn trọc nhớ cô gái hiền thục. 💡 Thú vị: Trong tiếng Việt hiện nay, «yểu điệu» chủ yếu chỉ dáng thướt tha, còn nghĩa gốc là «hiền thục, đoan trang».","chars":[{"c":"窈","h":"yểu"},{"c":"窕","h":"điệu"},{"c":"淑","h":"thục"},{"c":"女","h":"nữ"}],"poem":{"han":"關關雎鳩河洲上／窈窕淑女君子求","hv":"Quan quan thư cưu hà châu thượng / Yểu điệu thục nữ quân tử cầu","vi":"Quan quan chim thư cưu trên bãi sông; thục nữ hiền thục, quân tử tìm cầu."},"example":"窈窕淑女は君子の好逑と言われる。","example_reading":"ようちょうしゅくじょはくんしのこうきゅうといわれる。","example_meaning":"Thục nữ yểu điệu được coi là người bạn đời tốt của quân tử.","examples":[{"example":"窈窕淑女は君子の好逑と言われる。","example_reading":"ようちょうしゅくじょはくんしのこうきゅうといわれる。","example_meaning":"Thục nữ yểu điệu được coi là người bạn đời tốt của quân tử."},{"example":"彼女は窈窕淑女と呼ぶにふさわしい人だ。","example_reading":"かのじょはようちょうしゅくじょとよぶにふさわしいひとだ。","example_meaning":"Cô ấy xứng đáng được gọi là thục nữ."}],"level":"p2"},
{"word":"道不拾遺","reading":"どうふしゅうい（みちにおちたるをひろわず）","meaning":"của rơi trên đường không ai nhặt; xã hội thanh bình, dân chúng liêm khiết.","hanviet":"đạo bất thập di","note":"📜 Lịch sử: Sử ký - Thương Quân liệt truyện: sau khi biến pháp mười năm, nước Tần được mô tả là «đạo bất thập di, sơn vô đạo tặc» (道不拾遺，山無盜賊): của rơi trên đường không ai nhặt, trong núi không có giặc cướp. 💡 Thú vị: Nhật Bản đôi khi được ca ngợi là nơi đồ đánh rơi dễ tìm lại được, ý này gần với tinh thần của thành ngữ.","chars":[{"c":"道","h":"đạo"},{"c":"不","h":"bất"},{"c":"拾","h":"thập"},{"c":"遺","h":"di"}],"poem":{"han":"令行十載民知法／路不拾遺山絕奸","hv":"Lệnh hành thập tải dân tri pháp / Lộ bất thập di sơn tuyệt gian","vi":"Lệnh ban mười năm, dân biết phép; của rơi không nhặt, trong núi hết gian."},"example":"道に落ちたるを拾わずと言われるほど、治安のよい国だ。","example_reading":"みちにおちたるをひろわずといわれるほど、ちあんのよいくにだ。","example_meaning":"Đất nước trị an tốt đến mức được ví như của rơi không ai nhặt.","examples":[{"example":"道に落ちたるを拾わずと言われるほど、治安のよい国だ。","example_reading":"みちにおちたるをひろわずといわれるほど、ちあんのよいくにだ。","example_meaning":"Đất nước trị an tốt đến mức được ví như của rơi không ai nhặt."},{"example":"道不拾遺の社会を理想とする。","example_reading":"どうふしゅういのしゃかいをりそうとする。","example_meaning":"Tôi coi xã hội của rơi không ai nhặt là lý tưởng."}],"level":"p2"},
{"word":"明眸皓歯","reading":"めいぼうこうし","meaning":"mắt sáng răng trắng; người đẹp, thường chỉ giai nhân.","hanviet":"minh mâu hạo xỉ","note":"📜 Lịch sử: Đỗ Phủ - Ai Giang đầu: «Minh mâu hạo xỉ kim hà tại, huyết ô du hồn quy bất đắc» (明眸皓齒今何在，血污遊魂歸不得): mắt sáng răng trắng nay đâu rồi, hồn vất vưởng nhuốm máu không về được; nói về Dương Quý Phi sau loạn An Lộc Sơn. 💡 Thú vị: Câu thơ vốn mang nỗi xót thương mất mát hơn là ca ngợi nhan sắc, nhưng ngày nay cụm từ thường được dùng để khen người đẹp.","chars":[{"c":"明","h":"minh"},{"c":"眸","h":"mâu"},{"c":"皓","h":"hạo"},{"c":"歯","h":"xỉ"}],"poem":{"han":"明眸皓齒如花貌／薄命紅顏淚自流","hv":"Minh mâu hạo xỉ như hoa mạo / Bạc mệnh hồng nhan lệ tự lưu","vi":"Mắt sáng răng trắng dung nhan như hoa; hồng nhan bạc mệnh, lệ tự rơi."},"example":"彼女は明眸皓歯の美人だった。","example_reading":"かのじょはめいぼうこうしのびじんだった。","example_meaning":"Cô ấy là một mỹ nhân mắt sáng răng trắng.","examples":[{"example":"彼女は明眸皓歯の美人だった。","example_reading":"かのじょはめいぼうこうしのびじんだった。","example_meaning":"Cô ấy là một mỹ nhân mắt sáng răng trắng."},{"example":"明眸皓歯という言葉は、美しい女性を指す。","example_reading":"めいぼうこうしということばは、うつくしいじょせいをさす。","example_meaning":"Từ «minh mâu hạo xỉ» chỉ người phụ nữ xinh đẹp."}],"level":"p2"},
{"word":"汗牛充棟","reading":"かんぎゅうじゅうとう","meaning":"sách nhiều đến mức chở thì trâu đổ mồ hôi, chất lại thì đầy tới xà nhà.\n(Chỉ số lượng sách vở khổng lồ.)","hanviet":"hãn ngưu sung đống","note":"📜 Lịch sử: Liễu Tông Nguyên (nhà Đường) - Lục Văn Thông tiên sinh mộ biểu: khi nói về số sách chú giải Xuân Thu, ông viết rằng ở nhà thì chất đầy xà nhà, đem ra thì khiến trâu ngựa đổ mồ hôi. 💡 Thú vị: Hai vế tạo thành một cặp đối rất đẹp của văn biền ngẫu: 汗牛 (trâu đổ mồ hôi) đối với 充棟 (đầy tới xà). 棟 là đòn nóc, xà cao nhất của nhà. Tiếng Nhật dùng nó cho thư viện, thư phòng lớn của học giả.","chars":[{"c":"汗","h":"hãn"},{"c":"牛","h":"ngưu"},{"c":"充","h":"sung"},{"c":"棟","h":"đống"}],"poem":{"han":"藏書出則牛馬汗／積卷歸來棟宇充","hv":"Tàng thư xuất tắc ngưu mã hãn / Tích quyển quy lai đống vũ sung","vi":"Sách chở ra thì trâu ngựa đổ mồ hôi; chất cuốn đem về thì đầy ắp xà nhà."},"example":"先生の書斎は、汗牛充棟の蔵書でいっぱいだ。","example_reading":"せんせいのしょさいは、かんぎゅうじゅうとうのぞうしょでいっぱいだ。","example_meaning":"Thư phòng của thầy chất đầy sách cao tới xà.","examples":[{"example":"先生の書斎は、汗牛充棟の蔵書でいっぱいだ。","example_reading":"せんせいのしょさいは、かんぎゅうじゅうとうのぞうしょでいっぱいだ。","example_meaning":"Thư phòng của thầy chất đầy sách cao tới xà."},{"example":"古い図書館には汗牛充棟の資料が眠っている。","example_reading":"ふるいとしょかんにはかんぎゅうじゅうとうのしりょうがねむっている。","example_meaning":"Thư viện cũ có vô số tài liệu chất cao như núi đang nằm yên."}],"level":"p3"},
{"word":"韋編三絶","reading":"いへんさんぜつ","meaning":"dây da đóng sách đứt ba lần; đọc sách chăm chỉ, đọc đi đọc lại không chán.\n(Lời khen thái độ say mê học tập.)","hanviet":"vi biên tam tuyệt","note":"📜 Lịch sử: Sử ký - Khổng Tử thế gia: về già Khổng Tử ham đọc Kinh Dịch đến mức dây da (韋) xâu các thẻ tre bị đứt ba lần. Ông còn nói «giá cho ta thêm vài năm nữa thì ta học Dịch». 💡 Thú vị: Sách thời cổ là các thẻ tre (簡) xâu bằng dây da hoặc dây gai rồi cuộn lại. Các chữ 編 (biên) trong 編集, 篇 (thiên) trong 一篇 đều bắt nguồn từ cách xâu thẻ này. 三 ở đây nghĩa là 'nhiều lần'.","chars":[{"c":"韋","h":"vi"},{"c":"編","h":"biên"},{"c":"三","h":"tam"},{"c":"絶","h":"tuyệt"}],"poem":{"han":"讀易燈前韋屢斷／聖人猶自惜寸陰","hv":"Độc Dịch đăng tiền vi lũ đoạn / Thánh nhân do tự tích thốn âm","vi":"Đọc Kinh Dịch trước đèn, dây da đứt nhiều lần; bậc thánh còn tiếc từng tấc bóng thời gian."},"example":"彼は韋編三絶の努力で、難しい古典を読み通した。","example_reading":"かれはいへんさんぜつのどりょくで、むずかしいこてんをよみとおした。","example_meaning":"Anh ấy đọc suốt cuốn kinh điển khó nhờ nỗ lực đọc đi đọc lại.","examples":[{"example":"彼は韋編三絶の努力で、難しい古典を読み通した。","example_reading":"かれはいへんさんぜつのどりょくで、むずかしいこてんをよみとおした。","example_meaning":"Anh ấy đọc suốt cuốn kinh điển khó nhờ nỗ lực đọc đi đọc lại."},{"example":"韋編三絶というほど、その本を何度も読んだ。","example_reading":"いへんさんぜつというほど、そのほんをなんどもよんだ。","example_meaning":"Tôi đã đọc cuốn sách đó nhiều lần đến mức sờn cả gáy."}],"level":"p3"},
{"word":"鼓腹撃壌","reading":"こふくげきじょう","meaning":"vỗ bụng, gõ đất mà hát; thời thái bình, dân sống yên vui tự tại.\n(Hình ảnh lý tưởng về chính trị tốt: dân chẳng cảm thấy sức vua.)","hanviet":"cổ phúc kích nhưỡng","note":"📜 Lịch sử: Thập bát sử lược - Đế Nghiêu: vua Nghiêu cải trang đi xem dân, gặp ông già vừa vỗ bụng vừa gõ nhịp xuống đất hát «mặt trời mọc thì làm, lặn thì nghỉ, đào giếng mà uống, cày ruộng mà ăn, sức vua có can hệ gì với ta». 💡 Thú vị: Ý hay ở chỗ chính trị tốt nhất là chính trị mà dân không cảm thấy sự hiện diện của nhà cầm quyền, gần với tư tưởng 'vô vi' của Lão Tử. Bài hát này gọi là «Kích nhưỡng ca».","chars":[{"c":"鼓","h":"cổ"},{"c":"腹","h":"phúc"},{"c":"撃","h":"kích"},{"c":"壌","h":"nhưỡng"}],"poem":{"han":"日出而耕鼓腹樂／帝力於我有何加","hv":"Nhật xuất nhi canh cổ phúc lạc / Đế lực ư ngã hữu hà gia","vi":"Mặt trời mọc thì cày, vỗ bụng vui ca; sức vua với ta có thêm gì đâu."},"example":"戦争のない鼓腹撃壌の世が続くことを願う。","example_reading":"せんそうのないこふくげきじょうのよがつづくことをねがう。","example_meaning":"Mong cảnh thái bình, dân sống yên vui không có chiến tranh sẽ kéo dài.","examples":[{"example":"戦争のない鼓腹撃壌の世が続くことを願う。","example_reading":"せんそうのないこふくげきじょうのよがつづくことをねがう。","example_meaning":"Mong cảnh thái bình, dân sống yên vui không có chiến tranh sẽ kéo dài."},{"example":"鼓腹撃壌の時代には、人々は政治を意識せずに暮らした。","example_reading":"こふくげきじょうのじだいには、ひとびとはせいじをいしきせずにくらした。","example_meaning":"Thời thái bình ấy, người ta sống mà chẳng nghĩ đến chính trị."}],"level":"p3"},
{"word":"魑魅魍魎","reading":"ちみもうりょう","meaning":"yêu ma quỷ quái các loại, thủy quái sơn tinh.\n(Nghĩa bóng: lũ người xảo quyệt, thế lực đen tối ẩn trong xã hội.)","hanviet":"ly mị võng lượng","note":"📜 Lịch sử: Tả truyện - Tuyên công năm 3: thời nhà Hạ, người ta đúc hình các loài quái vật lên chiếc đỉnh đồng để dân biết mà tránh, nên khi vào núi đầm không gặp phải ma quái (螭魅罔両). 💡 Thú vị: Bốn chữ đều có bộ 鬼 hoặc 虫 chỉ các loại yêu quái: 魑 (quái núi), 魅 (vật hóa tinh), 魍魎 (quái nước, bóng sông núi). Trong văn hóa Nhật, nó xuất hiện nhiều trong truyện kinh dị, như tiểu thuyết 魍魎の匣 của Kyōgoku Natsuhiko.","chars":[{"c":"魑","h":"ly"},{"c":"魅","h":"mị"},{"c":"魍","h":"võng"},{"c":"魎","h":"lượng"}],"poem":{"han":"山精水怪藏幽谷／鼎象分明避不遭","hv":"Sơn tinh thủy quái tàng u cốc / Đỉnh tượng phân minh tị bất tao","vi":"Tinh núi quái nước ẩn nơi thung sâu; hình vẽ trên vạc chỉ rõ để tránh khỏi gặp phải."},"example":"夜の山道には魑魅魍魎が出そうで怖い。","example_reading":"よるのやまみちにはちみもうりょうがでそうでこわい。","example_meaning":"Đường núi ban đêm sợ như có yêu ma hiện ra.","examples":[{"example":"夜の山道には魑魅魍魎が出そうで怖い。","example_reading":"よるのやまみちにはちみもうりょうがでそうでこわい。","example_meaning":"Đường núi ban đêm sợ như có yêu ma hiện ra."},{"example":"政界には魑魅魍魎が棲むと言われる。","example_reading":"せいかいにはちみもうりょうがすむといわれる。","example_meaning":"Người ta nói giới chính trị là nơi quỷ quái trú ngụ."}],"level":"p3"},
{"word":"唇歯輔車","reading":"しんしほしゃ","meaning":"môi răng, má và hàm; hai bên nương tựa, liên hệ mật thiết, mất một thì hại cả hai.\n(Dùng cho quốc gia, tổ chức có quan hệ sống còn với nhau.)","hanviet":"thần xỉ phụ xa","note":"📜 Lịch sử: Tả truyện - Hy công năm 5: Cung Chi Kỳ khuyên vua Ngu đừng cho nước Tấn mượn đường đánh Quắc, vì Quắc và Ngu như «má và hàm», môi mất thì răng lạnh. Vua Ngu không nghe, Tấn diệt Quắc rồi tiện đường diệt luôn Ngu. 💡 Thú vị: Từ chuyện này sinh ra thành ngữ 唇亡歯寒 (môi hở răng lạnh) và kế 仮道伐虢 (mượn đường diệt Quắc), một trong Tam thập lục kế. Tiếng Việt có câu «môi hở răng lạnh» rất gần.","chars":[{"c":"唇","h":"thần"},{"c":"歯","h":"xỉ"},{"c":"輔","h":"phụ"},{"c":"車","h":"xa"}],"poem":{"han":"唇亡齒必寒相及／輔車依倚共安危","hv":"Thần vong xỉ tất hàn tương cập / Phụ xa y ỷ cộng an nguy","vi":"Môi mất thì răng ắt lạnh, họa lan sang nhau; má và xương hàm nương tựa, cùng chung an nguy."},"example":"両国は唇歯輔車の関係にある。","example_reading":"りょうこくはしんしほしゃのかんけいにある。","example_meaning":"Hai nước có quan hệ môi hở răng lạnh.","examples":[{"example":"両国は唇歯輔車の関係にある。","example_reading":"りょうこくはしんしほしゃのかんけいにある。","example_meaning":"Hai nước có quan hệ môi hở răng lạnh."},{"example":"親会社と子会社は唇歯輔車で、一方が倒れれば他方も危ない。","example_reading":"おやがいしゃとこがいしゃはしんしほしゃで、いっぽうがたおれればたほうもあぶない。","example_meaning":"Công ty mẹ và con liên hệ mật thiết, một bên đổ thì bên kia cũng nguy."}],"level":"p3"},
{"word":"多岐亡羊","reading":"たきぼうよう","meaning":"đường rẽ nhiều thì mất dê; học vấn, con đường quá nhiều ngã thì khó tìm chân lý.\n(Cảnh báo: làm việc phân tán, học nhiều hướng thì dễ lạc.)","hanviet":"đa kỳ vong dương","note":"📜 Lịch sử: Liệt Tử - Thuyết phù: nhà hàng xóm của Dương Chu mất dê, kéo cả nhà và người hầu của Dương Chu đi tìm nhưng không thấy vì đường nhiều ngã rẽ. Dương Chu nghe thế buồn bã, cả ngày không cười. 💡 Thú vị: Dương Chu thấy chuyện mất dê giống việc theo đuổi học thuật: đường nhiều ngã rẽ thì người ta lạc mất bản chất. Trong tiếng Nhật, nó còn dùng cho học vấn nhiều ngành khiến người ta khó nắm được cốt lõi.","chars":[{"c":"多","h":"đa"},{"c":"岐","h":"kỳ"},{"c":"亡","h":"vong"},{"c":"羊","h":"dương"}],"poem":{"han":"歧路紛紛羊失跡／學途岐岐道難尋","hv":"Kỳ lộ phân phân dương thất tích / Học đồ kỳ kỳ đạo nan tầm","vi":"Đường rẽ ngổn ngang, dê mất dấu; đường học nhiều lối, đạo khó tìm."},"example":"研究テーマを広げすぎて、多岐亡羊になってしまった。","example_reading":"けんきゅうテーマをひろげすぎて、たきぼうようになってしまった。","example_meaning":"Mở rộng đề tài nghiên cứu quá mức nên bị lạc hướng.","examples":[{"example":"研究テーマを広げすぎて、多岐亡羊になってしまった。","example_reading":"けんきゅうテーマをひろげすぎて、たきぼうようになってしまった。","example_meaning":"Mở rộng đề tài nghiên cứu quá mức nên bị lạc hướng."},{"example":"習い事が多すぎると多岐亡羊で、どれも身につかない。","example_reading":"ならいごとがおおすぎるとたきぼうようで、どれもみにつかない。","example_meaning":"Học quá nhiều thứ thì bị phân tán, chẳng cái nào thạo."}],"level":"p3"},
{"word":"一視同仁","reading":"いっしどうじん","meaning":"nhìn mọi người như nhau, đối xử bình đẳng, thương đều.\n(Dùng cho thái độ công bằng, không phân biệt thân sơ.)","hanviet":"nhất thị đồng nhân","note":"📜 Lịch sử: Hàn Dũ - Nguyên nhân: «thánh nhân nhất thị nhi đồng nhân, đốc cận nhi cử viễn» (bậc thánh nhìn mọi người như nhau mà thương, trọng người gần rồi mới nâng đỡ người xa). 💡 Thú vị: Ý của Hàn Dũ là thương đều nhưng vẫn từ gần đến xa, khác với «kiêm ái» (兼愛) của Mặc Tử là yêu tất cả không phân biệt. Chữ 仁 (nhân) ở đây là lòng thương người.","chars":[{"c":"一","h":"nhất"},{"c":"視","h":"thị"},{"c":"同","h":"đồng"},{"c":"仁","h":"nhân"}],"poem":{"han":"聖人一視同仁愛／萬物沾恩各得安","hv":"Thánh nhân nhất thị đồng nhân ái / Vạn vật triêm ân các đắc an","vi":"Bậc thánh nhìn mọi người như nhau, thương đều; muôn vật thấm ơn, ai cũng được yên."},"example":"先生は誰に対しても一視同仁の態度で接する。","example_reading":"せんせいはだれにたいしてもいっしどうじんのたいどでせっする。","example_meaning":"Thầy đối xử với ai cũng công bằng như nhau.","examples":[{"example":"先生は誰に対しても一視同仁の態度で接する。","example_reading":"せんせいはだれにたいしてもいっしどうじんのたいどでせっする。","example_meaning":"Thầy đối xử với ai cũng công bằng như nhau."},{"example":"患者を一視同仁に扱うのが医師の務めだ。","example_reading":"かんじゃをいっしどうじんにあつかうのがいしのつとめだ。","example_meaning":"Đối xử bình đẳng với bệnh nhân là bổn phận của bác sĩ."}],"level":"p3"},
{"word":"曲学阿世","reading":"きょくがくあせい","meaning":"bẻ cong học vấn để nịnh thời thế; học giả bán rẻ chân lý để lấy lòng quyền lực.\n(Dùng để chê giới trí thức a dua.)","hanviet":"khúc học a thế","note":"📜 Lịch sử: Sử ký - Nho lâm liệt truyện: nhà nho Viên Cố Sinh dặn Công Tôn Hoằng rằng hãy nói theo chính học, đừng bẻ cong học thuật để nịnh đời. 💡 Thú vị: Năm 1950, Thủ tướng Yoshida Shigeru dùng đúng cụm này (曲学阿世の徒) để công kích giáo sư Nanbara Shigeru, hiệu trưởng Đại học Tokyo, người đòi hòa ước toàn diện thay vì chỉ ký với phe phương Tây. Sự kiện khiến cụm từ trở nên rất nổi tiếng.","chars":[{"c":"曲","h":"khúc"},{"c":"学","h":"học"},{"c":"阿","h":"a"},{"c":"世","h":"thế"}],"poem":{"han":"曲學阿世求榮寵／正道無言自挺然","hv":"Khúc học a thế cầu vinh sủng / Chính đạo vô ngôn tự đĩnh nhiên","vi":"Bẻ cong học thuật nịnh đời để cầu vinh sủng; chính đạo chẳng nói mà tự đứng thẳng."},"example":"権力に迎合する学者は「曲学阿世」だと批判された。","example_reading":"けんりょくにげいごうするがくしゃは「きょくがくあせい」だとひはんされた。","example_meaning":"Học giả xu nịnh quyền lực bị chê là kẻ bẻ cong học vấn để nịnh đời.","examples":[{"example":"権力に迎合する学者は「曲学阿世」だと批判された。","example_reading":"けんりょくにげいごうするがくしゃは「きょくがくあせい」だとひはんされた。","example_meaning":"Học giả xu nịnh quyền lực bị chê là kẻ bẻ cong học vấn để nịnh đời."},{"example":"真実を曲げるのは曲学阿世で、学者として恥ずかしい。","example_reading":"しんじつをまげるのはきょくがくあせいで、がくしゃとしてはずかしい。","example_meaning":"Bóp méo sự thật để nịnh đời là điều đáng xấu hổ với học giả."}],"level":"p3"},
{"word":"精神一到","reading":"せいしんいっとう","meaning":"dồn hết tinh thần vào một việc thì không gì không làm nổi.\n(Thường đi với 何事か成らざらん: 'việc gì mà chẳng thành'.)","hanviet":"tinh thần nhất đáo","note":"📜 Lịch sử: Chu Tử ngữ loại (Chu Hy, nhà Tống): «dương khí phát xứ, kim thạch diệc thấu; tinh thần nhất đáo, hà sự bất thành» (nơi dương khí phát ra, vàng đá cũng xuyên; tinh thần dồn một chỗ thì việc gì chẳng nên). 💡 Thú vị: Câu này thường đi kèm chuyện Lý Quảng bắn đá trong Sử ký: ông tưởng tảng đá là con hổ nên bắn mũi tên cắm sâu vào đá, nhưng nhận ra là đá rồi thì bắn mãi không thủng. Tiếng Nhật hay dùng dạng 精神一到何事か成らざらん.","chars":[{"c":"精","h":"tinh"},{"c":"神","h":"thần"},{"c":"一","h":"nhất"},{"c":"到","h":"đáo"}],"poem":{"han":"精神一到金石透／何事難成志不移","hv":"Tinh thần nhất đáo kim thạch thấu / Hà sự nan thành chí bất di","vi":"Dồn hết tinh thần thì vàng đá cũng xuyên; việc gì khó thành nếu chí không lay."},"example":"精神一到何事か成らざらん。最後まで頑張ろう。","example_reading":"せいしんいっとうなにごとかならざらん。さいごまでがんばろう。","example_meaning":"Dồn hết tinh thần thì việc gì chẳng thành. Cố gắng đến cùng nhé.","examples":[{"example":"精神一到何事か成らざらん。最後まで頑張ろう。","example_reading":"せいしんいっとうなにごとかならざらん。さいごまでがんばろう。","example_meaning":"Dồn hết tinh thần thì việc gì chẳng thành. Cố gắng đến cùng nhé."},{"example":"精神一到で練習し、ついに記録を更新した。","example_reading":"せいしんいっとうでれんしゅうし、ついにきろくをこうしんした。","example_meaning":"Dồn hết tâm sức luyện tập, cuối cùng anh ấy đã phá kỷ lục."}],"level":"p3"},
{"word":"愚公移山","reading":"ぐこういざん","meaning":"ông lão ngu dời núi; kiên trì bền bỉ, việc khó đến mấy cũng làm được.\n(Biểu tượng cho ý chí lấy sức người thắng thiên nhiên qua nhiều đời.)","hanviet":"ngu công di sơn","note":"📜 Lịch sử: Liệt Tử - Thang vấn: Ngu Công gần 90 tuổi muốn dời hai ngọn núi Thái Hàng và Vương Ốc chắn trước nhà. Bị Trí Tẩu chê là ngu, ông đáp: ta chết còn con, con sinh cháu, cháu sinh con nữa, còn núi thì không cao thêm. Thiên đế cảm động bèn sai thần dời núi. 💡 Thú vị: Năm 1945, Mao Trạch Đông dùng chuyện này trong bài «Ngu Công di sơn», khiến nó nổi tiếng khắp Trung Quốc. Ý nghĩa gần với tục ngữ 継続は力なり (đã có ở chủ đề ことわざ).","chars":[{"c":"愚","h":"ngu"},{"c":"公","h":"công"},{"c":"移","h":"di"},{"c":"山","h":"sơn"}],"poem":{"han":"愚公白首移山志／子子孫孫鑿不休","hv":"Ngu Công bạch thủ di sơn chí / Tử tử tôn tôn tạc bất hưu","vi":"Ngu Công đầu bạc vẫn giữ chí dời núi; con cháu đời đời đào mãi không ngừng."},"example":"愚公移山の精神で、小さな努力を続けている。","example_reading":"ぐこういざんのせいしんで、ちいさなどりょくをつづけている。","example_meaning":"Tôi tiếp tục những nỗ lực nhỏ với tinh thần Ngu Công dời núi.","examples":[{"example":"愚公移山の精神で、小さな努力を続けている。","example_reading":"ぐこういざんのせいしんで、ちいさなどりょくをつづけている。","example_meaning":"Tôi tiếp tục những nỗ lực nhỏ với tinh thần Ngu Công dời núi."},{"example":"不可能に見える計画も、愚公移山の覚悟で進めた。","example_reading":"ふかのうにみえるけいかくも、ぐこういざんのかくごですすめた。","example_meaning":"Kế hoạch tưởng chừng bất khả thi vẫn được thúc đẩy với quyết tâm Ngu Công dời núi."}],"level":"p3"},
{"word":"月下氷人","reading":"げっかひょうじん","meaning":"ông Nguyệt dưới trăng và người trên băng; người làm mối, mai mối nên duyên vợ chồng.\n(Dùng cho 'ông tơ bà nguyệt', người làm mai cho đám cưới.)","hanviet":"nguyệt hạ băng nhân","note":"📜 Lịch sử: Ghép từ hai điển: (1) «Tục U quái lục» đời Đường: Vi Cố gặp ông lão dưới trăng đang xem sách, dùng sợi chỉ đỏ buộc chân đôi nam nữ đã định làm vợ chồng (月下老人). (2) Tấn thư - Nghệ thuật truyện: Tác Đam giải mộng thấy người đứng trên băng nói chuyện với người dưới băng, bảo đó là điềm đi làm mai (氷人). 💡 Thú vị: Hình ảnh 'sợi chỉ đỏ' (赤い糸) của văn hóa Nhật có liên hệ với truyền thuyết Nguyệt Lão này. Trong tiếng Nhật, người làm mai còn gọi là 仲人 (なこうど), và 月下氷人 là cách nói cổ, trang trọng hơn.","chars":[{"c":"月","h":"nguyệt"},{"c":"下","h":"hạ"},{"c":"氷","h":"băng"},{"c":"人","h":"nhân"}],"poem":{"han":"月下老人牽赤繩／氷人傳語結良緣","hv":"Nguyệt hạ lão nhân khiên xích thằng / Băng nhân truyền ngữ kết lương duyên","vi":"Ông lão dưới trăng se sợi chỉ đỏ; người trên băng truyền lời, kết nên duyên lành."},"example":"私たちの結婚は、先輩が月下氷人を務めてくれた。","example_reading":"わたしたちのけっこんは、せんぱいがげっかひょうじんをつとめてくれた。","example_meaning":"Đám cưới của chúng tôi do đàn anh làm người mai mối.","examples":[{"example":"私たちの結婚は、先輩が月下氷人を務めてくれた。","example_reading":"わたしたちのけっこんは、せんぱいがげっかひょうじんをつとめてくれた。","example_meaning":"Đám cưới của chúng tôi do đàn anh làm người mai mối."},{"example":"月下氷人の役を頼まれて、緊張している。","example_reading":"げっかひょうじんのやくをたのまれて、きんちょうしている。","example_meaning":"Được nhờ làm mai mối, tôi thấy căng thẳng."}],"level":"p3"},
{"word":"三人成虎","reading":"さんにんせいこ","meaning":"ba người nói có hổ giữa chợ thì người ta tin là có thật; lời đồn lặp đi lặp lại thành 'sự thật'.\n(Cảnh báo sức mạnh của tin đồn.)","hanviet":"tam nhân thành hổ","note":"📜 Lịch sử: Chiến quốc sách - Ngụy sách: Bàng Thông sắp theo thái tử sang Hàm Đan làm con tin, hỏi vua Ngụy: một người nói giữa chợ có hổ thì ngài tin không? Không. Hai người? Còn ngờ. Ba người? Tin. Ông cảnh báo rằng khi ông vắng mặt, sẽ có nhiều kẻ nói xấu mình. 💡 Thú vị: Về sau đúng như ông lo: vua nghe lời gièm pha và không cho ông gặp lại. Cụm này thường được dùng để nói về tin giả và tin đồn trên mạng xã hội, rất hợp thời đại.","chars":[{"c":"三","h":"tam"},{"c":"人","h":"nhân"},{"c":"成","h":"thành"},{"c":"虎","h":"hổ"}],"poem":{"han":"市無虎處三言有／衆口成真惑聽人","hv":"Thị vô hổ xứ tam ngôn hữu / Chúng khẩu thành chân hoặc thính nhân","vi":"Chợ chẳng có hổ, nhưng ba người nói là có; nhiều miệng nói thành thật, làm người nghe lầm."},"example":"噂は三人成虎で、嘘が本当になってしまう。","example_reading":"うわさはさんにんせいこで、うそがほんとうになってしまう。","example_meaning":"Tin đồn thì ba người nói thành thật, lời nói dối hóa thành sự thật.","examples":[{"example":"噂は三人成虎で、嘘が本当になってしまう。","example_reading":"うわさはさんにんせいこで、うそがほんとうになってしまう。","example_meaning":"Tin đồn thì ba người nói thành thật, lời nói dối hóa thành sự thật."},{"example":"三人成虎と言うように、SNSのデマは広まりやすい。","example_reading":"さんにんせいこというように、エスエヌエスのデマはひろまりやすい。","example_meaning":"Như người ta nói ba người thành hổ, tin giả trên mạng xã hội dễ lan truyền."}],"level":"p3"},
{"word":"杯弓蛇影","reading":"はいきゅうだえい","meaning":"bóng cung trong chén tưởng là rắn; nghi ngờ vô cớ, tự dọa mình.\n(Dùng khi lo sợ vì ảo giác hoặc việc không có thật.)","hanviet":"bôi cung xà ảnh","note":"📜 Lịch sử: «Phong tục thông nghĩa» của Ứng Thiệu kể chuyện Đỗ Tuyên; «Tấn thư - Nhạc Quảng truyện» kể bản tương tự: người bạn thấy 'con rắn' trong chén rượu rồi sinh bệnh, Nhạc Quảng nhận ra đó là bóng chiếc cung treo trên tường, mời bạn uống lại thì bệnh khỏi. 💡 Thú vị: Cụm này gần nghĩa với 疑心暗鬼 (đã có ở chủ đề 四字熟語). Điều thú vị là nó cho thấy người xưa đã nhận ra bệnh có thể xuất phát từ tâm lý, như một ví dụ sớm về 'bệnh do lo nghĩ'.","chars":[{"c":"杯","h":"bôi"},{"c":"弓","h":"cung"},{"c":"蛇","h":"xà"},{"c":"影","h":"ảnh"}],"poem":{"han":"杯中弓影疑蛇動／一飲驚心病日深","hv":"Bôi trung cung ảnh nghi xà động / Nhất ẩm kinh tâm bệnh nhật thâm","vi":"Bóng cung trong chén ngỡ rắn động, vừa uống đã kinh tâm, bệnh ngày một nặng."},"example":"物音にも怯えるのは、杯弓蛇影のようなものだ。","example_reading":"ものおとにもおびえるのは、はいきゅうだえいのようなものだ。","example_meaning":"Sợ cả tiếng động nhỏ cũng giống như ngỡ bóng cung là rắn.","examples":[{"example":"物音にも怯えるのは、杯弓蛇影のようなものだ。","example_reading":"ものおとにもおびえるのは、はいきゅうだえいのようなものだ。","example_meaning":"Sợ cả tiếng động nhỏ cũng giống như ngỡ bóng cung là rắn."},{"example":"彼女は杯弓蛇影で、誰かに見られている気がしてならない。","example_reading":"かのじょははいきゅうだえいで、だれかにみられているきがしてならない。","example_meaning":"Cô ấy tự dọa mình, cứ cảm thấy như bị ai đó nhìn."}],"level":"p3"},
{"word":"呉牛喘月","reading":"ごぎゅうぜんげつ","meaning":"trâu đất Ngô thấy trăng mà thở hổn hển; sợ hãi quá mức vì từng trải qua việc tương tự, nhìn gì cũng giật mình.\n(Dùng khi từng bị tổn thương nên phản ứng thái quá trước điều tương tự.)","hanviet":"ngô ngưu suyễn nguyệt","note":"📜 Lịch sử: Thế thuyết tân ngữ - Ngôn ngữ: đại thần Mãn Phấn vốn sợ gió. Một lần ngồi chầu Tấn Vũ Đế, ông thấy cửa sổ bắc lắp tấm lưu ly trông như hở mà thực kín, nhưng vẫn lộ vẻ khó chịu; vua cười, ông đáp: «thần như trâu đất Ngô, thấy trăng mà thở dốc». 💡 Thú vị: Ở vùng Ngô nóng bức, trâu sợ nắng nên thấy mặt trăng cũng tưởng là mặt trời. Đây là lời tự giễu dí dỏm trước mặt vua. Gần nghĩa 杯弓蛇影, nhưng 呉牛喘月 nhấn mạnh phản xạ sợ hãi sinh ra từ trải nghiệm cũ.","chars":[{"c":"呉","h":"ngô"},{"c":"牛","h":"ngưu"},{"c":"喘","h":"suyễn"},{"c":"月","h":"nguyệt"}],"poem":{"han":"呉地炎牛疑月日／驚魂未定喘難休","hv":"Ngô địa viêm ngưu nghi nguyệt nhật / Kinh hồn vị định suyễn nan hưu","vi":"Trâu đất Ngô nóng bức ngờ trăng là mặt trời; hồn kinh chưa định, thở dốc chẳng thôi."},"example":"一度失敗してから、呉牛喘月で新しい挑戦が怖くなった。","example_reading":"いちどしっぱいしてから、ごぎゅうぜんげつであたらしいちょうせんがこわくなった。","example_meaning":"Từ khi thất bại một lần, tôi sợ cả những thử thách mới như trâu thấy trăng đã thở dốc.","examples":[{"example":"一度失敗してから、呉牛喘月で新しい挑戦が怖くなった。","example_reading":"いちどしっぱいしてから、ごぎゅうぜんげつであたらしいちょうせんがこわくなった。","example_meaning":"Từ khi thất bại một lần, tôi sợ cả những thử thách mới như trâu thấy trăng đã thở dốc."},{"example":"事故のあと、呉牛喘月で車の音にも敏感になった。","example_reading":"じこのあと、ごぎゅうぜんげつでくるまのおとにもびんかんになった。","example_meaning":"Sau tai nạn, tôi trở nên nhạy cảm cả với tiếng xe."}],"level":"p3"},
{"word":"尾生之信","reading":"びせいのしん","meaning":"chữ tín của Vĩ Sinh; giữ lời một cách cứng nhắc, ngốc nghếch (cũng dùng để khen giữ chữ tín tuyệt đối).","hanviet":"Vĩ Sinh chi tín","note":"📜 Lịch sử: Trang Tử - Đạo Chích: Vĩ Sinh hẹn gặp một người con gái dưới cầu; nước dâng lên, nàng không đến, anh không chịu bỏ đi, ôm chặt cột cầu mà chết đuối. Trang Tử dùng để chê là chết vô ích. 💡 Thú vị: Trong Chiến quốc sách, Tô Tần lại dùng Vĩ Sinh làm hình mẫu của chữ tín, nên cùng một người mà vừa bị chê vừa được khen.","chars":[{"c":"尾","h":"Vĩ"},{"c":"生","h":"Sinh"},{"c":"之","h":"chi"},{"c":"信","h":"tín"}],"poem":{"han":"橋下候人潮漸滿／抱梁溺死守前盟","hv":"Kiều hạ hậu nhân triều tiệm mãn / Bão lương nịch tử thủ tiền minh","vi":"Chờ người dưới cầu, nước triều dâng đầy; ôm cột chết đuối vẫn giữ lời hẹn."},"example":"彼の尾生の信は立派だが、融通が利かない面もある。","example_reading":"かれのびせいのしんはりっぱだが、ゆうずうがきかないめんもある。","example_meaning":"Chữ tín của anh ấy rất đáng khen nhưng cũng có phần cứng nhắc.","examples":[{"example":"彼の尾生の信は立派だが、融通が利かない面もある。","example_reading":"かれのびせいのしんはりっぱだが、ゆうずうがきかないめんもある。","example_meaning":"Chữ tín của anh ấy rất đáng khen nhưng cũng có phần cứng nhắc."},{"example":"約束を守りすぎて損をする彼は、尾生の信そのものだ。","example_reading":"やくそくをまもりすぎてそんをするかれは、びせいのしんそのものだ。","example_meaning":"Anh ta giữ lời quá mức đến chịu thiệt, đúng là Vĩ Sinh."}],"level":"p3"},
{"word":"屋烏之愛","reading":"おくうのあい","meaning":"yêu ai thì yêu cả con quạ đậu trên nhà người đó; yêu người nào thì yêu luôn mọi thứ thuộc về người ấy.","hanviet":"ốc ô chi ái","note":"📜 Lịch sử: Thượng thư đại truyện: Chu Vũ Vương diệt Ân rồi hỏi Thái Công Vọng nên xử trí quân Ân thế nào. Thái Công đáp: ta nghe nói yêu người nào thì yêu cả con quạ đậu trên nhà người ấy, ghét người nào thì ghét cả bức tường rào của họ. 💡 Thú vị: Tiếng Việt có câu «yêu nhau yêu cả đường đi, ghét nhau ghét cả tông ti họ hàng» cùng ý.","chars":[{"c":"屋","h":"ốc"},{"c":"烏","h":"ô"},{"c":"之","h":"chi"},{"c":"愛","h":"ái"}],"poem":{"han":"愛屋及烏情更篤／連枝同愛不分差","hv":"Ái ốc cập ô tình cánh đốc / Liên chi đồng ái bất phân sai","vi":"Yêu nhà yêu cả quạ, tình càng thêm đậm; cành liền cùng yêu, không phân sai biệt."},"example":"彼女の好きなものはなんでも好きになる、屋烏の愛だ。","example_reading":"かのじょのすきなものはなんでもすきになる、おくうのあいだ。","example_meaning":"Cái gì cô ấy thích tôi cũng thích lây, đúng là yêu ai yêu cả đường đi.","examples":[{"example":"彼女の好きなものはなんでも好きになる、屋烏の愛だ。","example_reading":"かのじょのすきなものはなんでもすきになる、おくうのあいだ。","example_meaning":"Cái gì cô ấy thích tôi cũng thích lây, đúng là yêu ai yêu cả đường đi."},{"example":"孫への屋烏の愛で、祖父は孫の友人にも優しい。","example_reading":"まごへのおくうのあいで、そふはまごのゆうじんにもやさしい。","example_meaning":"Ông yêu cháu nên cũng thương cả bạn của cháu."}],"level":"p3"},
{"word":"食指大動","reading":"しょくしだいどう","meaning":"ngón trỏ giật mạnh; thèm ăn, hoặc hứng thú, muốn làm khi thấy thứ hấp dẫn.","hanviet":"thực chỉ đại động","note":"📜 Lịch sử: Tả truyện - Tuyên công năm 4: công tử Tống (Tử Công) cùng Tử Gia vào chầu vua Trịnh. Ngón trỏ của Tử Công giật, ông bảo Tử Gia: «Lần nào thế này thì ắt được nếm của lạ». Vào cung thấy bếp đang nấu thịt ba ba, nhưng vua Trịnh đãi mọi người mà cố tình không cho ông. Ông giận, chấm ngón tay vào vạc nếm rồi bỏ đi, về sau cùng Tử Gia giết vua. 💡 Thú vị: Trong tiếng Nhật, 食指が動く cũng có nghĩa là có hứng thú muốn làm, không chỉ nói thèm ăn.","chars":[{"c":"食","h":"thực"},{"c":"指","h":"chỉ"},{"c":"大","h":"đại"},{"c":"動","h":"động"}],"poem":{"han":"食指忽動知嘗異／一鼎黿羹釀禍端","hv":"Thực chỉ hốt động tri thường dị / Nhất đỉnh nguyên canh nhưỡng họa đoan","vi":"Ngón trỏ chợt giật, biết sắp nếm của lạ; một vạc canh ba ba gây mầm họa."},"example":"新しい企画に食指が動いた。","example_reading":"あたらしいきかくにしょくしがうごいた。","example_meaning":"Dự án mới khiến tôi hứng thú.","examples":[{"example":"新しい企画に食指が動いた。","example_reading":"あたらしいきかくにしょくしがうごいた。","example_meaning":"Dự án mới khiến tôi hứng thú."},{"example":"高級寿司の写真に食指大動した。","example_reading":"こうきゅうすしのしゃしんにしょくしだいどうした。","example_meaning":"Tôi thèm thuồng khi nhìn ảnh sushi cao cấp."}],"level":"p3"},
{"word":"抜山蓋世","reading":"ばつざんがいせい","meaning":"sức nhổ núi, khí phủ trùm đời; sức mạnh và khí phách phi thường.","hanviet":"bạt sơn cái thế","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ: bị vây ở Cai Hạ, Hạng Vũ làm bài «Cai Hạ ca»: «Lực bạt sơn hề khí cái thế, thời bất lợi hề chuy bất thệ…» (力拔山兮氣蓋世，時不利兮騅不逝), nghĩa là sức nhổ núi, khí trùm đời, gặp thời không thuận, ngựa Chuy chẳng chạy. 💡 Thú vị: Cùng cảnh này sinh ra 四面楚歌; sau bài ca, Ngu Cơ tự vẫn và Hạng Vũ cũng tự tận bên sông Ô Giang.","chars":[{"c":"抜","h":"bạt"},{"c":"山","h":"sơn"},{"c":"蓋","h":"cái"},{"c":"世","h":"thế"}],"poem":{"han":"拔山力盡英雄氣／蓋世名傳霸王悲","hv":"Bạt sơn lực tận anh hùng khí / Cái thế danh truyền Bá Vương bi","vi":"Sức nhổ núi đã cạn, khí anh hùng còn đó; tiếng trùm đời lưu truyền nỗi bi của Bá Vương."},"example":"抜山蓋世の勢いで、彼は敵を圧倒した。","example_reading":"ばつざんがいせいのいきおいで、かれはてきをあっとうした。","example_meaning":"Với khí thế bạt sơn cái thế, anh ấy áp đảo đối thủ.","examples":[{"example":"抜山蓋世の勢いで、彼は敵を圧倒した。","example_reading":"ばつざんがいせいのいきおいで、かれはてきをあっとうした。","example_meaning":"Với khí thế bạt sơn cái thế, anh ấy áp đảo đối thủ."},{"example":"抜山蓋世と称された力士が引退した。","example_reading":"ばつざんがいせいとしょうされたりきしがいんたいした。","example_meaning":"Võ sĩ sumo từng được ca ngợi là sức nhổ núi đã giải nghệ."}],"level":"p3"},
{"word":"問鼎軽重","reading":"かなえのけいちょうをとう","meaning":"hỏi đỉnh nặng nhẹ; nghi ngờ địa vị, năng lực của người trên, có ý muốn thay thế.\n(Thường dùng 鼎の軽重を問う.)","hanviet":"vấn đỉnh khinh trọng","note":"📜 Lịch sử: Tả truyện - Tuyên công năm 3: Sở Trang vương đánh Lục Hồn rồi duyệt binh sát biên giới nhà Chu; vua Chu sai Vương Tôn Mãn đến úy lạo. Sở vương hỏi về kích cỡ và nặng nhẹ của cửu đỉnh, ngầm có ý đoạt thiên hạ. Vương Tôn Mãn đáp: «Ở đức chứ không ở đỉnh». 💡 Thú vị: Cửu đỉnh là biểu tượng quyền lực thiên hạ từ thời Hạ Vũ; trong tiếng Nhật hiện đại, cụm này thường dùng khi người ta nghi ngờ năng lực của người lãnh đạo.","chars":[{"c":"問","h":"vấn"},{"c":"鼎","h":"đỉnh"},{"c":"軽","h":"khinh"},{"c":"重","h":"trọng"}],"poem":{"han":"楚子觀兵問九鼎／王孫答以德非鼎","hv":"Sở tử quan binh vấn cửu đỉnh / Vương Tôn đáp dĩ đức phi đỉnh","vi":"Vua Sở duyệt binh hỏi chín đỉnh; Vương Tôn đáp rằng ở đức chứ không phải đỉnh."},"example":"新任の社長の力量に、周囲は鼎の軽重を問うような視線を向けた。","example_reading":"しんにんのしゃちょうのりきりょうに、しゅういはかなえのけいちょうをとうようなしせんをむけた。","example_meaning":"Mọi người nhìn vị giám đốc mới với ánh mắt dò xét năng lực.","examples":[{"example":"新任の社長の力量に、周囲は鼎の軽重を問うような視線を向けた。","example_reading":"しんにんのしゃちょうのりきりょうに、しゅういはかなえのけいちょうをとうようなしせんをむけた。","example_meaning":"Mọi người nhìn vị giám đốc mới với ánh mắt dò xét năng lực."},{"example":"鼎の軽重を問われる事態になった。","example_reading":"かなえのけいちょうをとわれるじたいになった。","example_meaning":"Tình hình đã đến mức bị nghi ngờ năng lực của người lãnh đạo."}],"level":"p3"},
{"word":"前車覆轍","reading":"ぜんしゃふくてつ","meaning":"vết bánh xe đổ của chiếc xe đi trước; thất bại của người trước là bài học răn cho người sau.","hanviet":"tiền xa phúc triệt","note":"📜 Lịch sử: Hán thư - Giả Nghị truyện (Trị an sách): «Tiền xa phúc, hậu xa giới» (前車覆，後車戒), nghĩa là xe trước đổ thì xe sau phải lấy làm răn. Giả Nghị dùng để khuyên triều đình nên nhìn vào vết xe đổ của nhà Tần. 💡 Thú vị: Tiếng Nhật có dạng ngược nghĩa 前車の轍を踏む (đi vào vết xe đổ), tức lặp lại sai lầm của người trước.","chars":[{"c":"前","h":"tiền"},{"c":"車","h":"xa"},{"c":"覆","h":"phúc"},{"c":"轍","h":"triệt"}],"poem":{"han":"前車已覆車轍在／後車切勿再相循","hv":"Tiền xa dĩ phúc xa triệt tại / Hậu xa thiết vật tái tương tuần","vi":"Xe trước đã đổ, vệt bánh còn đó; xe sau chớ lại đi theo vết cũ."},"example":"前車の轍を踏まないよう、過去の失敗を分析した。","example_reading":"ぜんしゃのてつをふまないよう、かこのしっぱいをぶんせきした。","example_meaning":"Để khỏi đi vào vết xe đổ, tôi đã phân tích các thất bại trong quá khứ.","examples":[{"example":"前車の轍を踏まないよう、過去の失敗を分析した。","example_reading":"ぜんしゃのてつをふまないよう、かこのしっぱいをぶんせきした。","example_meaning":"Để khỏi đi vào vết xe đổ, tôi đã phân tích các thất bại trong quá khứ."},{"example":"前車の覆るを見て後車の戒めとする。","example_reading":"ぜんしゃのくつがえるをみてこうしゃのいましめとする。","example_meaning":"Thấy xe trước đổ, xe sau lấy đó làm răn."}],"level":"p3"},
{"word":"梁上君子","reading":"りょうじょうのくんし","meaning":"quân tử trên xà nhà; tên trộm (cách nói hài hước, nho nhã).","hanviet":"lương thượng quân tử","note":"📜 Lịch sử: Hậu Hán thư - Trần Thực truyện: Trần Thực thấy một kẻ trộm nấp trên xà nhà, bèn gọi con cháu đến dạy rằng người xấu không phải sinh ra đã xấu mà do thói quen mà thành, rồi chỉ lên nói: «quân tử trên xà kia là thế». Tên trộm hoảng sợ xuống dập đầu tạ tội, ông cho hai tấm lụa; từ đó trong làng bớt hẳn nạn trộm cắp. 💡 Thú vị: Tiếng Việt hay nói «quân tử trên xà» hay «quân tử Tàu» đùa chỉ kẻ trộm.","chars":[{"c":"梁","h":"lương"},{"c":"上","h":"thượng"},{"c":"君","h":"quân"},{"c":"子","h":"tử"}],"poem":{"han":"梁上潛身非本惡／一言感化變良民","hv":"Lương thượng tiềm thân phi bản ác / Nhất ngôn cảm hóa biến lương dân","vi":"Nấp trên xà nhà vốn chẳng bản chất ác; một lời cảm hóa, thành người lương thiện."},"example":"昨夜、家に梁上の君子が入ったらしい。","example_reading":"さくや、いえにりょうじょうのくんしがはいったらしい。","example_meaning":"Nghe nói đêm qua nhà có trộm vào.","examples":[{"example":"昨夜、家に梁上の君子が入ったらしい。","example_reading":"さくや、いえにりょうじょうのくんしがはいったらしい。","example_meaning":"Nghe nói đêm qua nhà có trộm vào."},{"example":"梁上の君子にご用心、戸締まりを忘れずに。","example_reading":"りょうじょうのくんしにごようじん、とじまりをわすれずに。","example_meaning":"Cẩn thận trộm cắp, đừng quên khóa cửa."}],"level":"p3"},
{"word":"漱石枕流","reading":"そうせきちんりゅう","meaning":"súc miệng bằng đá, gối đầu lên dòng suối; nói nhầm mà vẫn cãi cố, nhận sai không chịu; người cứng đầu, thích cãi lý.","hanviet":"thấu thạch chẩm lưu","note":"📜 Lịch sử: Thế thuyết tân ngữ - Giả quyết (và Tấn thư - Tôn Sở truyện): Tôn Sở muốn đi ở ẩn, nói nhầm «súc thạch chẩm lưu» thay vì «chẩm thạch súc lưu» (gối đá súc suối). Vương Tế hỏi: «Suối sao gối được, đá sao súc miệng được?» Tôn Sở chống chế: «Gối suối là để rửa tai, súc đá là để mài răng». 💡 Thú vị: Nhà văn Natsume Sōseki (夏目漱石) lấy bút danh từ điển tích này, tự trào tính cứng đầu của mình.","chars":[{"c":"漱","h":"thấu"},{"c":"石","h":"thạch"},{"c":"枕","h":"chẩm"},{"c":"流","h":"lưu"}],"poem":{"han":"枕石漱流言誤倒／強辭洗耳礪牙關","hv":"Chẩm thạch thấu lưu ngôn ngộ đảo / Cưỡng từ tẩy nhĩ lệ nha quan","vi":"Gối đá súc suối nói ngược; cãi cố rằng rửa tai, mài răng."},"example":"夏目漱石の筆名は漱石枕流の故事に由来する。","example_reading":"なつめそうせきのひつめいはそうせきちんりゅうのこじにゆらいする。","example_meaning":"Bút danh Natsume Sōseki bắt nguồn từ điển tích Súc thạch chẩm lưu.","examples":[{"example":"夏目漱石の筆名は漱石枕流の故事に由来する。","example_reading":"なつめそうせきのひつめいはそうせきちんりゅうのこじにゆらいする。","example_meaning":"Bút danh Natsume Sōseki bắt nguồn từ điển tích Súc thạch chẩm lưu."},{"example":"間違いを認めず言い訳するのは、漱石枕流のようだ。","example_reading":"まちがいをみとめずいいわけするのは、そうせきちんりゅうのようだ。","example_meaning":"Không nhận sai mà cứ chống chế thì chẳng khác Tôn Sở."}],"level":"p3"},
{"word":"無用之用","reading":"むようのよう","meaning":"cái dụng của cái vô dụng; thứ tưởng vô ích lại có giá trị lớn.","hanviet":"vô dụng chi dụng","note":"📜 Lịch sử: Trang Tử - Nhân gian thế: «Ai cũng biết cái dụng của cái hữu dụng, mà chẳng ai biết cái dụng của cái vô dụng» (人皆知有用之用，而莫知無用之用也). Trang Tử kể thợ mộc Thạch thấy cây sồi lớn làm đền thờ, gỗ tồi nên không ai đốn, nhờ vô dụng mà sống thọ. 💡 Thú vị: Lão Tử chương 11 có cùng ý: ba mươi nan hoa chung một bầu, chính chỗ trống ở giữa mới làm nên công dụng của bánh xe.","chars":[{"c":"無","h":"vô"},{"c":"用","h":"dụng"},{"c":"之","h":"chi"},{"c":"用","h":"dụng"}],"poem":{"han":"櫟社無材終得壽／空虛反作有用基","hv":"Lịch xã vô tài chung đắc thọ / Không hư phản tác hữu dụng cơ","vi":"Cây sồi đền xã vô dụng nên sống thọ; cái trống rỗng lại là nền của công dụng."},"example":"余白は無用の用で、デザインを引き立てる。","example_reading":"よはくはむようのようで、デザインをひきたてる。","example_meaning":"Khoảng trắng tưởng vô ích nhưng lại làm nổi bật thiết kế.","examples":[{"example":"余白は無用の用で、デザインを引き立てる。","example_reading":"よはくはむようのようで、デザインをひきたてる。","example_meaning":"Khoảng trắng tưởng vô ích nhưng lại làm nổi bật thiết kế."},{"example":"休憩は一見無駄でも、無用の用として仕事の質を高める。","example_reading":"きゅうけいはいっけんむだでも、むようのようとしてしごとのしつをたかめる。","example_meaning":"Giờ nghỉ nhìn qua tưởng phí nhưng lại nâng chất lượng công việc."}],"level":"p3"},
{"word":"管中窺豹","reading":"かんちゅうきひょう","meaning":"nhìn con báo qua ống tre; chỉ thấy một phần nhỏ, kiến thức phiến diện.\n(Cũng dùng khen khéo: thấy một đốm đoán ra cả vằn.)","hanviet":"quản trung khuy báo","note":"📜 Lịch sử: Tấn thư - Vương Hiến Chi truyện: lúc nhỏ, Hiến Chi xem các môn sinh nhà họ Vương chơi cờ bạc, nói «người này sắp thua». Môn sinh coi thường, bảo «đứa bé này như nhìn báo qua ống, chỉ thấy một đốm». Hiến Chi giận bỏ đi. 💡 Thú vị: Nghĩa gốc là chê hiểu biết hạn hẹp, nhưng cách nói 可見一斑 (thấy một đốm) ngày nay lại dùng trung tính để nói nhìn một phần mà biết được toàn bộ.","chars":[{"c":"管","h":"quản"},{"c":"中","h":"trung"},{"c":"窺","h":"khuy"},{"c":"豹","h":"báo"}],"poem":{"han":"管中窺豹惟斑點／一瞥難知全體文","hv":"Quản trung khuy báo duy ban điểm / Nhất miết nan tri toàn thể văn","vi":"Nhìn báo qua ống chỉ thấy đốm; liếc một cái khó biết cả vằn."},"example":"一部の資料だけで判断するのは管中窺豹だ。","example_reading":"いちぶのしりょうだけではんだんするのはかんちゅうきひょうだ。","example_meaning":"Chỉ phán đoán bằng một phần tài liệu là nhìn báo qua ống.","examples":[{"example":"一部の資料だけで判断するのは管中窺豹だ。","example_reading":"いちぶのしりょうだけではんだんするのはかんちゅうきひょうだ。","example_meaning":"Chỉ phán đoán bằng một phần tài liệu là nhìn báo qua ống."},{"example":"それは管中窺豹の見解にすぎない。","example_reading":"それはかんちゅうきひょうのけんかいにすぎない。","example_meaning":"Đó chỉ là cách nhìn phiến diện."}],"level":"p3"},
{"word":"尸位素餐","reading":"しいそさん","meaning":"chiếm chức mà không làm việc, ăn lương không; quan lại, nhân viên vô tích sự.","hanviet":"thi vị tố san","note":"📜 Lịch sử: Hán thư - Chu Vân truyện: Chu Vân xin vua Thành đế cho kiếm trảm mã để chém một nịnh thần, nói rằng nay đại thần trên không giúp được chủ, dưới không có ích cho dân, đều là «thi vị tố san». Vua giận định giết, Chu Vân bám chặt lan can điện đến gãy. 💡 Thú vị: Sau đó vua giữ nguyên lan can gãy để ghi nhớ lời can; chuyện «chiết hạm» (折檻, bẻ gãy lan can) cũng từ đây.","chars":[{"c":"尸","h":"thi"},{"c":"位","h":"vị"},{"c":"素","h":"tố"},{"c":"餐","h":"san"}],"poem":{"han":"居官不事徒尸位／食祿無功愧素餐","hv":"Cư quan bất sự đồ thi vị / Thực lộc vô công quý tố san","vi":"Làm quan chẳng làm gì, chỉ chiếm chỗ; ăn lộc không công, thẹn với bữa cơm suông."},"example":"役職だけで何もしない人は尸位素餐と言われる。","example_reading":"やくしょくだけでなにもしないひとはしいそさんといわれる。","example_meaning":"Người chỉ giữ chức mà chẳng làm gì bị gọi là ăn không ngồi rồi.","examples":[{"example":"役職だけで何もしない人は尸位素餐と言われる。","example_reading":"やくしょくだけでなにもしないひとはしいそさんといわれる。","example_meaning":"Người chỉ giữ chức mà chẳng làm gì bị gọi là ăn không ngồi rồi."},{"example":"尸位素餐の議員に、有権者の批判が集まった。","example_reading":"しいそさんのぎいんに、ゆうけんしゃのひはんがあつまった。","example_meaning":"Cử tri chỉ trích mạnh các nghị sĩ ăn lương mà vô dụng."}],"level":"p3"},
{"word":"断腸之思","reading":"だんちょうのおもい","meaning":"nỗi đau đứt ruột; nỗi đau buồn tột cùng, nhất là khi chia lìa.","hanviet":"đoạn trường chi tư","note":"📜 Lịch sử: Thế thuyết tân ngữ - Truất miễn: Hoàn Ôn đi vào Thục, đến Tam Hiệp thì quân sĩ bắt được một con vượn con. Vượn mẹ chạy theo bờ sông kêu thảm thiết hơn trăm dặm rồi nhảy lên thuyền và chết; mổ bụng ra thấy ruột đứt từng khúc. Hoàn Ôn nổi giận, cho đuổi người bắt vượn. 💡 Thú vị: Chữ «đoạn trường» trong tên Truyện Kiều «Đoạn trường tân thanh» cũng bắt nguồn từ tích này.","chars":[{"c":"断","h":"đoạn"},{"c":"腸","h":"trường"},{"c":"之","h":"chi"},{"c":"思","h":"tư"}],"poem":{"han":"峽猿哀叫追舟逝／腸斷寸寸痛母心","hv":"Hiệp viên ai khiếu truy chu thệ / Trường đoạn thốn thốn thống mẫu tâm","vi":"Vượn khe núi kêu thương đuổi theo thuyền; ruột đứt từng khúc, đau lòng mẹ."},"example":"断腸の思いで、愛犬を手放した。","example_reading":"だんちょうのおもいで、あいけんをてばなした。","example_meaning":"Tôi đau đứt ruột phải chia tay chú chó cưng.","examples":[{"example":"断腸の思いで、愛犬を手放した。","example_reading":"だんちょうのおもいで、あいけんをてばなした。","example_meaning":"Tôi đau đứt ruột phải chia tay chú chó cưng."},{"example":"断腸の思いで退職を決意した。","example_reading":"だんちょうのおもいでたいしょくをけついした。","example_meaning":"Tôi quyết định nghỉ việc trong nỗi đau xé lòng."}],"level":"p3"},
{"word":"先従隗始","reading":"まずかいよりはじめよ","meaning":"hãy bắt đầu từ Ôi; muốn làm việc lớn thì bắt đầu từ chính mình, từ việc gần; hoặc cách cầu hiền: đãi người thường trước để người tài kéo đến.","hanviet":"tiên tùng Ôi thủy","note":"📜 Lịch sử: Chiến quốc sách - Yên sách: Yên Chiêu vương hỏi Quách Ôi cách cầu hiền sĩ; Quách Ôi kể chuyện vua mua xương ngựa chết với giá ngàn vàng, ba năm sau ngựa tốt kéo đến, rồi nói: «Nếu muốn cầu hiền sĩ, xin cứ bắt đầu từ Ôi này». Vua xây cung cho Quách Ôi, sau đó Nhạc Nghị, Trâu Diễn đều kéo đến. 💡 Thú vị: Trong tiếng Nhật, 隗より始めよ thường dùng với nghĩa người đề xướng phải làm gương trước.","chars":[{"c":"先","h":"tiên"},{"c":"従","h":"tùng"},{"c":"隗","h":"Ôi"},{"c":"始","h":"thủy"}],"poem":{"han":"千金買骨招良駿／先自郭隗築館開","hv":"Thiên kim mãi cốt chiêu lương tuấn / Tiên tự Quách Ôi trúc quán khai","vi":"Nghìn vàng mua xương mời ngựa tốt; trước hết dựng quán cho Quách Ôi."},"example":"改革は、まず隗より始めよで、役員の報酬削減から行う。","example_reading":"かいかくは、まずかいよりはじめよで、やくいんのほうしゅうさくげんからおこなう。","example_meaning":"Cải cách bắt đầu từ chính mình, trước hết cắt giảm thù lao ban lãnh đạo.","examples":[{"example":"改革は、まず隗より始めよで、役員の報酬削減から行う。","example_reading":"かいかくは、まずかいよりはじめよで、やくいんのほうしゅうさくげんからおこなう。","example_meaning":"Cải cách bắt đầu từ chính mình, trước hết cắt giảm thù lao ban lãnh đạo."},{"example":"環境保護は隗より始めよと、まず自宅の節電から始めた。","example_reading":"かんきょうほごはかいよりはじめよと、まずじたくのせつでんからはじめた。","example_meaning":"Bảo vệ môi trường bắt đầu từ mình, tôi bắt đầu tiết kiệm điện ở nhà trước."}],"level":"p3"},
{"word":"吐哺握髪","reading":"とほあくはつ","meaning":"nhả cơm, nắm tóc; tiếp đãi người hiền hết lòng, hết sức coi trọng nhân tài.","hanviet":"thổ bộ ác phát","note":"📜 Lịch sử: Sử ký - Lỗ Chu công thế gia: Chu Công Đán dặn con là Bá Cầm (người đi trấn đất Lỗ): «Ta tắm một lần ba lần vắt tóc, ăn một bữa ba lần nhả cơm để đứng dậy tiếp kẻ sĩ, mà vẫn sợ mất người hiền trong thiên hạ». 💡 Thú vị: Tào Tháo mượn ý này trong «Đoản ca hành» với câu «Chu Công thổ bộ, thiên hạ quy tâm» để tỏ ý chiêu hiền.","chars":[{"c":"吐","h":"thổ"},{"c":"哺","h":"bộ"},{"c":"握","h":"ác"},{"c":"髪","h":"phát"}],"poem":{"han":"沐髮三握餐三吐／待士唯恐失賢良","hv":"Mộc phát tam ác san tam thổ / Đãi sĩ duy khủng thất hiền lương","vi":"Gội đầu ba lần nắm tóc, ăn ba lần nhả cơm; đãi sĩ chỉ sợ mất người hiền."},"example":"社長は吐哺握髪の思いで優秀な人材を迎えた。","example_reading":"しゃちょうはとほあくはつのおもいでゆうしゅうなじんざいをむかえた。","example_meaning":"Giám đốc tiếp đón nhân tài với tấm lòng cầu hiền hết sức.","examples":[{"example":"社長は吐哺握髪の思いで優秀な人材を迎えた。","example_reading":"しゃちょうはとほあくはつのおもいでゆうしゅうなじんざいをむかえた。","example_meaning":"Giám đốc tiếp đón nhân tài với tấm lòng cầu hiền hết sức."},{"example":"周公の吐哺握髪の故事は、人材を大切にする心を教える。","example_reading":"しゅうこうのとほあくはつのこじは、じんざいをたいせつにするこころをおしえる。","example_meaning":"Điển tích Chu Công dạy ta tấm lòng trân trọng nhân tài."}],"level":"p3"},
{"word":"修身斉家","reading":"しゅうしんせいか","meaning":"sửa mình, chỉnh đốn gia đình; nền tảng để trị nước, bình thiên hạ.","hanviet":"tu thân tề gia","note":"📜 Lịch sử: Đại học: «Dục tề kỳ gia giả, tiên tu kỳ thân» (欲齊其家者，先修其身): muốn chỉnh đốn gia đình thì trước hết phải sửa mình. Chuỗi nổi tiếng: tu thân, tề gia, trị quốc, bình thiên hạ. 💡 Thú vị: Chuỗi này là khuôn mẫu tư duy của Nho gia ở Việt Nam, Nhật Bản và Hàn Quốc, nhấn mạnh phải bắt đầu từ chính mình.","chars":[{"c":"修","h":"tu"},{"c":"身","h":"thân"},{"c":"斉","h":"tề"},{"c":"家","h":"gia"}],"poem":{"han":"欲平天下先治國／治國須先家有規","hv":"Dục bình thiên hạ tiên trị quốc / Trị quốc tu tiên gia hữu quy","vi":"Muốn bình thiên hạ trước trị nước; trị nước cần trước hết nhà có phép tắc."},"example":"修身斉家は、リーダーに求められる基本だ。","example_reading":"しゅうしんせいかは、リーダーにもとめられるきほんだ。","example_meaning":"Tu thân tề gia là điều cơ bản người lãnh đạo cần có.","examples":[{"example":"修身斉家は、リーダーに求められる基本だ。","example_reading":"しゅうしんせいかは、リーダーにもとめられるきほんだ。","example_meaning":"Tu thân tề gia là điều cơ bản người lãnh đạo cần có."},{"example":"まず修身斉家から始めるべきだ。","example_reading":"まずしゅうしんせいかからはじめるべきだ。","example_meaning":"Trước hết nên bắt đầu từ tu thân tề gia."}],"level":"p3"},
{"word":"履霜堅氷","reading":"りそうけんぴょう","meaning":"giẫm sương rồi băng cứng sẽ đến; điềm nhỏ báo trước sự việc lớn, nên đề phòng sớm.","hanviet":"lý sương kiên băng","note":"📜 Lịch sử: Kinh Dịch - quẻ Khôn, sơ lục: «Lý sương, kiên băng chí» (履霜，堅冰至): giẫm lên sương thì băng cứng sắp đến. Ý là từ dấu hiệu nhỏ phải nhìn ra xu hướng lớn. 💡 Thú vị: Tinh thần gần với thành ngữ 防微杜漸 (phòng ngừa từ lúc mới manh nha).","chars":[{"c":"履","h":"lý"},{"c":"霜","h":"sương"},{"c":"堅","h":"kiên"},{"c":"氷","h":"băng"}],"poem":{"han":"履霜初覺寒侵履／漸見堅冰滿路來","hv":"Lý sương sơ giác hàn xâm lý / Tiệm kiến kiên băng mãn lộ lai","vi":"Giẫm sương vừa thấy lạnh thấm giày; dần thấy băng cứng phủ đầy đường."},"example":"小さな不正を見逃すと、履霜堅氷の結果を招く。","example_reading":"ちいさなふせいをみのがすと、りそうけんぴょうのけっかをまねく。","example_meaning":"Bỏ qua sai phạm nhỏ sẽ dẫn tới hậu quả lớn.","examples":[{"example":"小さな不正を見逃すと、履霜堅氷の結果を招く。","example_reading":"ちいさなふせいをみのがすと、りそうけんぴょうのけっかをまねく。","example_meaning":"Bỏ qua sai phạm nhỏ sẽ dẫn tới hậu quả lớn."},{"example":"履霜堅氷、早めの対策が肝心だ。","example_reading":"りそうけんぴょう、はやめのたいさくがかんじんだ。","example_meaning":"Điềm nhỏ báo việc lớn, đối phó sớm là then chốt."}],"level":"p3"},
{"word":"積善余慶","reading":"せきぜんのよけい","meaning":"tích điều thiện sẽ còn phúc dư cho con cháu.","hanviet":"tích thiện dư khánh","note":"📜 Lịch sử: Kinh Dịch - quẻ Khôn, Văn ngôn: «Tích thiện chi gia, tất hữu dư khánh; tích bất thiện chi gia, tất hữu dư ương» (積善之家，必有餘慶；積不善之家，必有餘殃). 💡 Thú vị: Câu này có vế đối là «dư ương» (tai họa để lại), nhắc rằng việc thiện ác của một đời có thể ảnh hưởng đến con cháu.","chars":[{"c":"積","h":"tích"},{"c":"善","h":"thiện"},{"c":"余","h":"dư"},{"c":"慶","h":"khánh"}],"poem":{"han":"積善之家餘慶遠／福澤綿延及子孫","hv":"Tích thiện chi gia dư khánh viễn / Phúc trạch miên diên cập tử tôn","vi":"Nhà tích thiện phúc dư xa mãi; phúc trạch kéo dài đến con cháu."},"example":"積善の家に余慶ありというが、祖父の徳が今も私たちを支えている。","example_reading":"せきぜんのいえによけいありというが、そふのとくがいまもわたしたちをささえている。","example_meaning":"Người ta nói nhà tích thiện có phúc dư, đức của ông vẫn nâng đỡ chúng tôi.","examples":[{"example":"積善の家に余慶ありというが、祖父の徳が今も私たちを支えている。","example_reading":"せきぜんのいえによけいありというが、そふのとくがいまもわたしたちをささえている。","example_meaning":"Người ta nói nhà tích thiện có phúc dư, đức của ông vẫn nâng đỡ chúng tôi."},{"example":"積善余慶を信じて、人に親切にする。","example_reading":"せきぜんよけいをしんじて、ひとにしんせつにする。","example_meaning":"Tin vào tích thiện có phúc, tôi đối xử tốt với người khác."}],"level":"p3"},
{"word":"玩物喪志","reading":"がんぶつそうし","meaning":"mải chơi vật thú mà mất chí lớn.","hanviet":"ngoạn vật táng chí","note":"📜 Lịch sử: Thượng thư - Lữ Ngao: «Ngoạn nhân táng đức, ngoạn vật táng chí» (玩人喪德，玩物喪志): đùa bỡn người thì mất đức, mải mê vật thì mất chí. Thiệu Công can Vũ Vương không nên nhận con chó ngao quý do người Tây Lữ cống. 💡 Thú vị: Ngày nay cụm từ này hay được dẫn khi nói về việc mải mê sưu tầm, giải trí đến mức bỏ bê mục tiêu.","chars":[{"c":"玩","h":"ngoạn"},{"c":"物","h":"vật"},{"c":"喪","h":"táng"},{"c":"志","h":"chí"}],"poem":{"han":"西旅貢獒王不納／玩物喪志古人箴","hv":"Tây Lữ cống ngao vương bất nạp / Ngoạn vật táng chí cổ nhân châm","vi":"Tây Lữ dâng chó ngao, vua không nhận; mải vật mất chí là lời răn người xưa."},"example":"ゲームに熱中しすぎて玩物喪志にならないように。","example_reading":"ゲームにねっちゅうしすぎてがんぶつそうしにならないように。","example_meaning":"Đừng mải mê trò chơi đến mức mất chí lớn.","examples":[{"example":"ゲームに熱中しすぎて玩物喪志にならないように。","example_reading":"ゲームにねっちゅうしすぎてがんぶつそうしにならないように。","example_meaning":"Đừng mải mê trò chơi đến mức mất chí lớn."},{"example":"収集癖が高じて玩物喪志に陥った。","example_reading":"しゅうしゅうへきがこうじてがんぶつそうしにおちいった。","example_meaning":"Thói sưu tầm quá đà khiến anh ta mất chí hướng."}],"level":"p3"},
{"word":"道路以目","reading":"どうろもくをもってす","meaning":"người trên đường chỉ dám nhìn nhau bằng mắt; chính sách áp bức đến mức dân không dám nói.","hanviet":"đạo lộ dĩ mục","note":"📜 Lịch sử: Quốc ngữ - Chu ngữ thượng: Chu Lệ vương tàn bạo, cấm dân chê bai, cho vu giám sát; dân không dám nói, gặp nhau trên đường chỉ nháy mắt ra hiệu. Triệu Công can rằng chặn miệng dân còn khó hơn chặn sông. Ba năm sau dân nổi dậy đuổi Lệ vương. 💡 Thú vị: Câu «phòng dân chi khẩu, thậm ư phòng xuyên» (chặn miệng dân khó hơn ngăn sông) cũng bắt nguồn từ lần can ngăn này.","chars":[{"c":"道","h":"đạo"},{"c":"路","h":"lộ"},{"c":"以","h":"dĩ"},{"c":"目","h":"mục"}],"poem":{"han":"衛巫監謗民莫語／道路相逢只目傳","hv":"Vệ vu giám báng dân mạc ngữ / Đạo lộ tương phùng chỉ mục truyền","vi":"Vu giám sát lời chê, dân không dám nói; gặp nhau trên đường chỉ truyền bằng mắt."},"example":"言論統制の厳しい国では道路以目の状態になる。","example_reading":"げんろんとうせいのきびしいくにではどうろもくをもってすのじょうたいになる。","example_meaning":"Ở nước kiểm soát ngôn luận gắt gao, người dân chỉ dám trao đổi bằng mắt.","examples":[{"example":"言論統制の厳しい国では道路以目の状態になる。","example_reading":"げんろんとうせいのきびしいくにではどうろもくをもってすのじょうたいになる。","example_meaning":"Ở nước kiểm soát ngôn luận gắt gao, người dân chỉ dám trao đổi bằng mắt."},{"example":"道路以目の恐怖政治が続いた。","example_reading":"どうろもくをもってすのきょうふせいじがつづいた。","example_meaning":"Chế độ khủng bố khiến người dân chỉ dám nhìn nhau vẫn tiếp diễn."}],"level":"p3"},
{"word":"泰山北斗","reading":"たいざんほくと","meaning":"núi Thái, sao Bắc Đẩu; người được ngưỡng mộ, tôn kính như bậc thầy hàng đầu trong lĩnh vực của mình.\n(Rút gọn là 泰斗.)","hanviet":"Thái sơn Bắc đẩu","note":"📜 Lịch sử: Tân Đường thư - Hàn Dũ truyện (phần tán): từ khi Hàn Dũ mất, các học giả ngưỡng mộ ông như núi Thái Sơn và sao Bắc Đẩu. Hàn Dũ vực dậy lối văn cổ, được xem là bậc thầy của văn chương Đường Tống. 💡 Thú vị: Trong tiếng Nhật, dạng rút gọn 泰斗 (たいと) rất thông dụng, như 学界の泰斗 (bậc thầy của giới học thuật).","chars":[{"c":"泰","h":"Thái"},{"c":"山","h":"sơn"},{"c":"北","h":"Bắc"},{"c":"斗","h":"đẩu"}],"poem":{"han":"文章起衰追八代／學者仰之如北斗","hv":"Văn chương khởi suy truy bát đại / Học giả ngưỡng chi như bắc đẩu","vi":"Văn chương vực dậy cái suy, đuổi kịp tám đời; học giả ngưỡng mộ như sao Bắc Đẩu."},"example":"彼はこの分野の泰山北斗として尊敬されている。","example_reading":"かれはこのぶんやのたいざんほくととしてそんけいされている。","example_meaning":"Ông được kính trọng như bậc thái sơn bắc đẩu của lĩnh vực này.","examples":[{"example":"彼はこの分野の泰山北斗として尊敬されている。","example_reading":"かれはこのぶんやのたいざんほくととしてそんけいされている。","example_meaning":"Ông được kính trọng như bậc thái sơn bắc đẩu của lĩnh vực này."},{"example":"泰山北斗と仰がれた学者が亡くなった。","example_reading":"たいざんほくととあおがれたがくしゃがなくなった。","example_meaning":"Vị học giả được tôn như thái sơn bắc đẩu đã qua đời."}],"level":"p3"},
{"word":"無為自然","reading":"むいしぜん","meaning":"không làm gượng ép, thuận theo tự nhiên; lý tưởng sống của Lão Trang.","hanviet":"vô vi tự nhiên","note":"📜 Lịch sử: Lão Tử - chương 37: «Đạo thường vô vi nhi vô bất vi» (道常無為而無不為): đạo thường không làm mà không gì không làm được; chương 25: «Đạo pháp tự nhiên». 💡 Thú vị: «Vô vi» không có nghĩa là không làm gì, mà là không ép buộc theo ý riêng, để mọi việc thuận theo tự nhiên mà thành.","chars":[{"c":"無","h":"vô"},{"c":"為","h":"vi"},{"c":"自","h":"tự"},{"c":"然","h":"nhiên"}],"poem":{"han":"道法自然無所為／順時應物不強求","hv":"Đạo pháp tự nhiên vô sở vi / Thuận thời ứng vật bất cưỡng cầu","vi":"Đạo noi theo tự nhiên, không cố làm; thuận thời ứng vật, chẳng cưỡng cầu."},"example":"無為自然の生き方に憧れる。","example_reading":"むいしぜんのいきかたにあこがれる。","example_meaning":"Tôi ngưỡng mộ lối sống thuận theo tự nhiên.","examples":[{"example":"無為自然の生き方に憧れる。","example_reading":"むいしぜんのいきかたにあこがれる。","example_meaning":"Tôi ngưỡng mộ lối sống thuận theo tự nhiên."},{"example":"彼は無為自然を信条に、田舎で暮らしている。","example_reading":"かれはむいしぜんをしんじょうに、いなかでくらしている。","example_meaning":"Anh ấy sống ở quê với niềm tin vô vi tự nhiên."}],"level":"p3"},
{"word":"迂直之計","reading":"うちょくのけい","meaning":"kế đi vòng mà hóa thẳng; đi đường vòng mà đến nơi trước, biến đường xa thành đường gần.","hanviet":"vu trực chi kế","note":"📜 Lịch sử: Tôn Tử - Quân tranh: «Quân tranh chi nan giả, dĩ vu vi trực, dĩ hoạn vi lợi» (軍爭之難者，以迂為直，以患為利): cái khó của việc tranh thế là biến đường vòng thành đường thẳng, biến điều bất lợi thành có lợi. Dùng mồi nhử đi đường vòng, xuất phát sau mà tới trước. 💡 Thú vị: Trong tiếng Nhật, cụm 迂直の計 hay dùng trong kinh doanh với ý «đi đường vòng lại là nhanh nhất».","chars":[{"c":"迂","h":"vu"},{"c":"直","h":"trực"},{"c":"之","h":"chi"},{"c":"計","h":"kế"}],"poem":{"han":"以迂為直誘敵處／後發先至勝機存","hv":"Dĩ vu vi trực dụ địch xử / Hậu phát tiên chí thắng cơ tồn","vi":"Lấy vòng làm thẳng, nhử địch vào chỗ ấy; đi sau tới trước, thắng cơ còn đó."},"example":"遠回りに見えて、迂直之計で結果的に早く着いた。","example_reading":"とおまわりにみえて、うちょくのけいでけっかてきにはやくついた。","example_meaning":"Trông như đi vòng nhưng nhờ kế vu trực mà rốt cuộc đến sớm.","examples":[{"example":"遠回りに見えて、迂直之計で結果的に早く着いた。","example_reading":"とおまわりにみえて、うちょくのけいでけっかてきにはやくついた。","example_meaning":"Trông như đi vòng nhưng nhờ kế vu trực mà rốt cuộc đến sớm."},{"example":"迂直の計を使い、競合の先を行った。","example_reading":"うちょくのけいをつかい、きょうごうのさきをいった。","example_meaning":"Dùng kế đi vòng để vượt lên trước đối thủ."}],"level":"p3"},
{"word":"水清無魚","reading":"すいせいむぎょ","meaning":"nước trong quá thì không có cá; người quá khắt khe thì không ai gần gũi.\n(Tiếng Nhật: 水清ければ魚棲まず.)","hanviet":"thủy thanh vô ngư","note":"📜 Lịch sử: Hán thư - Đông Phương Sóc truyện (Giới tử): «Thủy chí thanh tắc vô ngư, nhân chí sát tắc vô đồ» (水至清則無魚，人至察則無徒): nước quá trong thì không có cá, người xét nét quá thì không có bạn. 💡 Thú vị: Câu này thường dùng để khuyên người lãnh đạo biết du di một chút, đừng soi xét từng li từng tí.","chars":[{"c":"水","h":"thủy"},{"c":"清","h":"thanh"},{"c":"無","h":"vô"},{"c":"魚","h":"ngư"}],"poem":{"han":"水至清時魚不住／人能察盡友難留","hv":"Thủy chí thanh thời ngư bất trụ / Nhân năng sát tận hữu nan lưu","vi":"Nước trong đến cực thì cá không ở; người xét hết thì bạn khó giữ."},"example":"厳しすぎる上司には人が寄りつかず、水清無魚だ。","example_reading":"きびしすぎるじょうしにはひとがよりつかず、すいせいむぎょだ。","example_meaning":"Sếp quá khắt khe thì chẳng ai lại gần, đúng là nước trong không cá.","examples":[{"example":"厳しすぎる上司には人が寄りつかず、水清無魚だ。","example_reading":"きびしすぎるじょうしにはひとがよりつかず、すいせいむぎょだ。","example_meaning":"Sếp quá khắt khe thì chẳng ai lại gần, đúng là nước trong không cá."},{"example":"水清ければ魚棲まず、少しは大目に見よう。","example_reading":"みずきよければうおすまず、すこしはおおめにみよう。","example_meaning":"Nước trong thì cá không ở, hãy du di một chút."}],"level":"p3"},
{"word":"衆口鑠金","reading":"しゅうこうしゃくきん","meaning":"lời của nhiều người nấu chảy cả vàng; dư luận đông người có sức mạnh làm thay đổi sự thật.","hanviet":"chúng khẩu thước kim","note":"📜 Lịch sử: Quốc ngữ - Chu ngữ hạ: «Chúng tâm thành thành, chúng khẩu thước kim» (眾心成城，眾口鑠金): lòng của nhiều người hợp lại thành tường thành, miệng của nhiều người có thể nấu chảy vàng. 💡 Thú vị: Có thành ngữ đi cùng là 積毀銷骨 (lời chê tích tụ làm tiêu cả xương), cùng nói về sức mạnh đáng sợ của dư luận.","chars":[{"c":"衆","h":"chúng"},{"c":"口","h":"khẩu"},{"c":"鑠","h":"thước"},{"c":"金","h":"kim"}],"poem":{"han":"眾心成城堅不破／眾口鑠金力可驚","hv":"Chúng tâm thành thành kiên bất phá / Chúng khẩu thước kim lực khả kinh","vi":"Lòng đông thành tường, bền chẳng phá; miệng đông nấu vàng, sức đáng kinh."},"example":"噂も衆口鑠金で、真実のように広まる。","example_reading":"うわさもしゅうこうしゃくきんで、しんじつのようにひろまる。","example_meaning":"Tin đồn có sức mạnh của miệng đời, lan ra như sự thật.","examples":[{"example":"噂も衆口鑠金で、真実のように広まる。","example_reading":"うわさもしゅうこうしゃくきんで、しんじつのようにひろまる。","example_meaning":"Tin đồn có sức mạnh của miệng đời, lan ra như sự thật."},{"example":"衆口鑠金、世論の力は侮れない。","example_reading":"しゅうこうしゃくきん、よろんのちからはあなどれない。","example_meaning":"Miệng người nấu chảy vàng, sức mạnh dư luận không thể coi thường."}],"level":"p3"},
{"word":"項荘舞剣","reading":"こうそうぶけん","meaning":"hạng Trang múa kiếm; ngoài mặt múa vui, thực chất nhắm giết người; hành động bề ngoài che ý đồ thật.","hanviet":"Hạng Trang vũ kiếm","note":"📜 Lịch sử: Sử ký - Hạng Vũ bản kỷ (Hồng Môn yến, năm 206 TCN): Phạm Tăng dặn Hạng Trang xin múa kiếm trong tiệc để nhân đó giết Bái công (Lưu Bang). Hạng Bá cũng rút kiếm múa theo để che chở cho Lưu Bang, sau đó Phàn Khoái xông vào hộ giá. 💡 Thú vị: Nguồn gốc của câu «Hạng Trang vũ kiếm, ý tại Bái công» (項莊舞劍，意在沛公), tương tự câu «túy ông chi ý bất tại tửu».","chars":[{"c":"項","h":"Hạng"},{"c":"荘","h":"Trang"},{"c":"舞","h":"vũ"},{"c":"剣","h":"kiếm"}],"poem":{"han":"鴻門宴上劍光閃／意在沛公不在歌","hv":"Hồng Môn yến thượng kiếm quang thiểm / Ý tại Bái công bất tại ca","vi":"Trên tiệc Hồng Môn ánh kiếm lóe; ý ở Bái công chứ chẳng ở điệu múa."},"example":"彼の提案は項荘舞剣で、真の狙いは別にある。","example_reading":"かれのていあんはこうそうぶけんで、しんのねらいはべつにある。","example_meaning":"Đề xuất của anh ta chỉ là bề ngoài, mục đích thật nằm nơi khác.","examples":[{"example":"彼の提案は項荘舞剣で、真の狙いは別にある。","example_reading":"かれのていあんはこうそうぶけんで、しんのねらいはべつにある。","example_meaning":"Đề xuất của anh ta chỉ là bề ngoài, mục đích thật nằm nơi khác."},{"example":"表向きの親切は項荘舞剣かもしれない。","example_reading":"おもてむきのしんせつはこうそうぶけんかもしれない。","example_meaning":"Sự tử tế bề ngoài có thể che giấu ý đồ khác."}],"level":"p3"},
{"word":"烏合之衆","reading":"うごうのしゅう","meaning":"đám quạ tụ họp; đám đông tụ tập bừa bãi, không có kỷ luật.","hanviet":"ô hợp chi chúng","note":"📜 Lịch sử: Thành ngữ xuất hiện trong Hán thư và Hậu Hán thư, như trong lời bàn về việc đánh Vương Lang ở Hàm Đan, cho rằng quân của đối phương chỉ là đám ô hợp, gặp quân tinh nhuệ thì tan ngay. 💡 Thú vị: Quạ tụ rồi tản không theo hàng lối, nên hình ảnh «quạ họp» được dùng để chỉ đám đông thiếu tổ chức.","chars":[{"c":"烏","h":"ô"},{"c":"合","h":"hợp"},{"c":"之","h":"chi"},{"c":"衆","h":"chúng"}],"poem":{"han":"烏鴉聚散無號令／一擊即潰不成師","hv":"Ô nha tụ tán vô hiệu lệnh / Nhất kích tức hội bất thành sư","vi":"Quạ tụ rồi tan, không hiệu lệnh; một đòn là vỡ, chẳng thành quân."},"example":"寄せ集めのチームは烏合の衆だった。","example_reading":"よせあつめのチームはうごうのしゅうだった。","example_meaning":"Đội gom góp tạm bợ chỉ là đám ô hợp.","examples":[{"example":"寄せ集めのチームは烏合の衆だった。","example_reading":"よせあつめのチームはうごうのしゅうだった。","example_meaning":"Đội gom góp tạm bợ chỉ là đám ô hợp."},{"example":"烏合の衆では、強豪には勝てない。","example_reading":"うごうのしゅうでは、きょうごうにはかてない。","example_meaning":"Đám ô hợp thì không thể thắng đội mạnh."}],"level":"p3"},
{"word":"肝胆相照","reading":"かんたんあいてらす","meaning":"gan mật soi nhau; chân thành tâm giao, không giấu giếm điều gì.","hanviet":"can đảm tương chiếu","note":"📜 Lịch sử: Hàn Dũ - Liễu Tử Hậu mộ chí minh: ông tả những kẻ bạn bè nơi yên ổn thì «nắm tay phô gan phổi cho nhau xem, chỉ trời thề sống chết không phụ nhau», nhưng khi gặp hoạn nạn thì quay lưng. Cụm 肝胆相照 gắn với tinh thần này. 💡 Thú vị: Hàn Dũ dùng hình ảnh ấy để chê bạn bè thiếu chung thủy, nhưng ngày nay cụm từ được dùng với nghĩa tốt: bạn bè chân thành tuyệt đối.","chars":[{"c":"肝","h":"can"},{"c":"胆","h":"đảm"},{"c":"相","h":"tương"},{"c":"照","h":"chiếu"}],"poem":{"han":"握手相示肝肺膽／指天誓死不相違","hv":"Ác thủ tương thị can phế đảm / Chỉ thiên thệ tử bất tương vi","vi":"Nắm tay phô gan phổi mật; chỉ trời thề chết chẳng phụ nhau."},"example":"彼とは肝胆相照らす仲だ。","example_reading":"かれとはかんたんあいてらすなかだ。","example_meaning":"Tôi và anh ấy là bạn tâm giao.","examples":[{"example":"彼とは肝胆相照らす仲だ。","example_reading":"かれとはかんたんあいてらすなかだ。","example_meaning":"Tôi và anh ấy là bạn tâm giao."},{"example":"肝胆相照らす友がいれば心強い。","example_reading":"かんたんあいてらすともがいればこころづよい。","example_meaning":"Có người bạn tâm giao thì thật vững lòng."}],"level":"p3"},
{"word":"酔翁之意","reading":"すいおうのい","meaning":"ý của ông say không ở rượu; ý thật không nằm ở việc đang làm, mà ở chỗ khác (thưởng cảnh, thú vui).","hanviet":"túy ông chi ý","note":"📜 Lịch sử: Âu Dương Tu - Túy Ông đình ký (năm 1046): «Túy ông chi ý bất tại tửu, tại hồ sơn thủy chi gian dã» (醉翁之意不在酒，在乎山水之間也): ý của ông say không ở rượu mà ở giữa non nước. Ông bị biếm ra Trừ Châu, tự xưng Túy Ông. 💡 Thú vị: Ngày nay câu «醉翁之意不在酒» thường được dùng với ý nghi ngờ: người ta làm việc này nhưng ý đồ thật nằm ở nơi khác.","chars":[{"c":"酔","h":"túy"},{"c":"翁","h":"ông"},{"c":"之","h":"chi"},{"c":"意","h":"ý"}],"poem":{"han":"醉翁之意非在酒／山水之間樂趣深","hv":"Túy ông chi ý phi tại tửu / Sơn thủy chi gian lạc thú thâm","vi":"Ý của ông say chẳng ở rượu; giữa non nước, thú vui sâu xa."},"example":"彼の親切には酔翁の意があるようだ。","example_reading":"かれのしんせつにはすいおうのいがあるようだ。","example_meaning":"Sự tử tế của anh ta dường như có ý đồ khác.","examples":[{"example":"彼の親切には酔翁の意があるようだ。","example_reading":"かれのしんせつにはすいおうのいがあるようだ。","example_meaning":"Sự tử tế của anh ta dường như có ý đồ khác."},{"example":"酔翁の意は酒にあらず、景色を楽しむことにあった。","example_reading":"すいおうのいはさけにあらず、けしきをたのしむことにあった。","example_meaning":"Ý của ông say không ở rượu mà ở việc thưởng ngoạn cảnh sắc."}],"level":"p3"},
{"word":"世外桃源","reading":"せがいのとうげん","meaning":"đào nguyên ngoài thế gian; nơi yên bình xa cách trần tục.","hanviet":"thế ngoại đào nguyên","note":"📜 Lịch sử: Đào Uyên Minh - Đào hoa nguyên ký: một ngư phủ ở Vũ Lăng theo dòng suối lạc vào rừng hoa đào, tìm thấy một ngôi làng của những người tránh loạn nhà Tần, sống yên ổn nhiều đời. Khi ra về, anh đánh dấu đường nhưng sau tìm lại thì không thấy nữa. 💡 Thú vị: Từ 桃源郷 (とうげんきょう) trong tiếng Nhật chỉ nơi sống lý tưởng như thiên đường, cũng từ tích này.","chars":[{"c":"世","h":"thế"},{"c":"外","h":"ngoại"},{"c":"桃","h":"đào"},{"c":"源","h":"nguyên"}],"poem":{"han":"武陵漁子溪邊入／桃花林盡見仙居","hv":"Vũ Lăng ngư tử khê biên nhập / Đào hoa lâm tận kiến tiên cư","vi":"Ngư phủ Vũ Lăng vào theo bờ suối; hết rừng hoa đào, thấy nơi tiên ở."},"example":"山奥の村はまるで世外桃源のようだった。","example_reading":"やまおくのむらはまるでせがいとうげんのようだった。","example_meaning":"Ngôi làng sâu trong núi chẳng khác nơi đào nguyên.","examples":[{"example":"山奥の村はまるで世外桃源のようだった。","example_reading":"やまおくのむらはまるでせがいとうげんのようだった。","example_meaning":"Ngôi làng sâu trong núi chẳng khác nơi đào nguyên."},{"example":"世外桃源を求めて田舎に移住した。","example_reading":"せがいとうげんをもとめていなかにいじゅうした。","example_meaning":"Tôi chuyển về quê để tìm một chốn đào nguyên."}],"level":"p3"},
{"word":"蜀犬吠日","reading":"しょっけんはいじつ","meaning":"chó đất Thục sủa mặt trời; thiếu hiểu biết nên thấy điều bình thường là lạ, ngạc nhiên vô cớ.","hanviet":"Thục khuyển phệ nhật","note":"📜 Lịch sử: Liễu Tông Nguyên - Đáp Vi Trung Lập luận sư đạo thư: ở phía nam đất Thục thường mưa ít nắng, nên khi mặt trời ló ra thì chó sủa. Ông dùng hình ảnh này để nói người ít hiểu biết gặp điều lạ thì kinh ngạc, chê bai. 💡 Thú vị: Hàn Dũ lúc ấy bị nhiều người chê cười vì dám làm thầy dạy học, nên ví dụ này được Liễu Tông Nguyên dùng để biện hộ cho ông.","chars":[{"c":"蜀","h":"Thục"},{"c":"犬","h":"khuyển"},{"c":"吠","h":"phệ"},{"c":"日","h":"nhật"}],"poem":{"han":"蜀地多陰日罕見／群犬驚吠笑愚情","hv":"Thục địa đa âm nhật hãn kiến / Quần khuyển kinh phệ tiếu ngu tình","vi":"Đất Thục nhiều mây, ít thấy mặt trời; bầy chó sủa kinh ngạc, đáng cười cái ngu."},"example":"新しい考えに反発するのは蜀犬吠日のようだ。","example_reading":"あたらしいかんがえにはんぱつするのはしょっけんはいじつのようだ。","example_meaning":"Phản đối ý tưởng mới chẳng khác chó Thục sủa mặt trời.","examples":[{"example":"新しい考えに反発するのは蜀犬吠日のようだ。","example_reading":"あたらしいかんがえにはんぱつするのはしょっけんはいじつのようだ。","example_meaning":"Phản đối ý tưởng mới chẳng khác chó Thục sủa mặt trời."},{"example":"蜀犬吠日、知らないから驚くのだ。","example_reading":"しょっけんはいじつ、しらないからおどろくのだ。","example_meaning":"Chó Thục sủa mặt trời, vì không biết nên ngạc nhiên."}],"level":"p3"},
{"word":"黔驢技窮","reading":"けんろのぎきゅうす","meaning":"con lừa đất Kiềm hết chiêu; chỉ có vẻ ngoài, bản lĩnh hạn chế, bị vạch trần thì hết cách.","hanviet":"Kiềm lư kỹ cùng","note":"📜 Lịch sử: Liễu Tông Nguyên - Tam giới (Kiềm chi lư): đất Kiềm vốn không có lừa, có người chở một con lừa đến rồi thả ở núi. Hổ thấy con vật to lớn tưởng là thần, rình xem; lừa kêu một tiếng, hổ sợ chạy. Dần nghe quen, hổ thử trêu chọc, lừa chỉ biết đá; hổ mừng nói «chỉ có thế thôi» rồi nhảy vào ăn thịt. 💡 Thú vị: Tiếng Việt cũng có cách nói «lừa Kiềm hết kế» cho người chỉ có vẻ bề ngoài.","chars":[{"c":"黔","h":"Kiềm"},{"c":"驢","h":"lư"},{"c":"技","h":"kỹ"},{"c":"窮","h":"cùng"}],"poem":{"han":"黔驢龐大初驚虎／一蹄之後技窮傾","hv":"Kiềm lư bàng đại sơ kinh hổ / Nhất đề chi hậu kỹ cùng khuynh","vi":"Lừa đất Kiềm to lớn làm hổ giật mình; sau một cú đá thì hết chiêu, đổ gục."},"example":"威張っていた彼も、黔驢技窮で何も言えなくなった。","example_reading":"いばっていたかれも、けんろのぎきゅうすでなにもいえなくなった。","example_meaning":"Anh ta từng ra oai, giờ hết chiêu không nói được gì.","examples":[{"example":"威張っていた彼も、黔驢技窮で何も言えなくなった。","example_reading":"いばっていたかれも、けんろのぎきゅうすでなにもいえなくなった。","example_meaning":"Anh ta từng ra oai, giờ hết chiêu không nói được gì."},{"example":"黔驢の技が尽きて、真の実力が露呈した。","example_reading":"けんろのぎがつきて、しんのじつりょくがろていした。","example_meaning":"Hết chiêu, thực lực thật của anh ta lộ ra."}],"level":"p3"},
{"word":"伯楽一顧","reading":"はくらくいっこ","meaning":"bá Nhạc ngoảnh lại nhìn một lần; được người tinh mắt để ý thì giá trị lập tức được công nhận.","hanviet":"Bá Nhạc nhất cố","note":"📜 Lịch sử: Chiến quốc sách - Yên sách (Tô Đại): người bán ngựa tốt đứng ba ngày ở chợ mà không ai hỏi mua; nhờ Bá Nhạc đến ngoảnh lại nhìn rồi bỏ đi, giá ngựa tăng gấp mười lần. Hàn Dũ - Tạp thuyết cũng viết «Thế hữu Bá Nhạc, nhiên hậu hữu thiên lý mã» (世有伯樂，然後有千里馬). 💡 Thú vị: Trong tiếng Nhật, 伯楽 còn chỉ người giỏi nhìn ra và đào tạo nhân tài, hoặc người buôn ngựa.","chars":[{"c":"伯","h":"Bá"},{"c":"楽","h":"Nhạc"},{"c":"一","h":"nhất"},{"c":"顧","h":"cố"}],"poem":{"han":"良駒立市三朝寂／伯樂回眸價十倍","hv":"Lương câu lập thị tam triêu tịch / Bá Nhạc hồi mâu giá thập bội","vi":"Ngựa tốt đứng chợ ba ngày vắng; Bá Nhạc ngoảnh nhìn, giá gấp mười."},"example":"彼の才能は、伯楽一顧のおかげで世に出た。","example_reading":"かれのさいのうは、はくらくいっこのおかげでよにでた。","example_meaning":"Tài năng của anh ấy ra mắt đời nhờ được người sành sỏi để mắt.","examples":[{"example":"彼の才能は、伯楽一顧のおかげで世に出た。","example_reading":"かれのさいのうは、はくらくいっこのおかげでよにでた。","example_meaning":"Tài năng của anh ấy ra mắt đời nhờ được người sành sỏi để mắt."},{"example":"優れた上司は伯楽のように部下の才能を見抜く。","example_reading":"すぐれたじょうしははくらくのようにぶかのさいのうをみぬく。","example_meaning":"Sếp giỏi nhìn ra tài năng của cấp dưới như Bá Nhạc."}],"level":"p3"},
{"word":"滄浪之水","reading":"そうろうのみず","meaning":"nước Thương Lang; tùy thời cuộc mà ứng xử, nước trong thì rửa dây mũ, nước đục thì rửa chân.","hanviet":"Thương Lang chi thủy","note":"📜 Lịch sử: Sở từ - Ngư phủ: Khuất Nguyên bị đày, gặp ông chài; ông chài khuyên bậc thánh nhân không cố chấp mà theo thế gian đổi thay, rồi gõ mái chèo hát rằng nước Thương Lang trong thì rửa dây mũ, nước đục thì rửa chân. Khuất Nguyên đáp thà nhảy xuống dòng sông còn hơn để thân trong sạch dính bụi. 💡 Thú vị: Mạnh Tử - Ly Lâu thượng cũng trích lời bài ca này để nói về việc con người tự chuốc lấy kết quả của mình.","chars":[{"c":"滄","h":"Thương"},{"c":"浪","h":"Lang"},{"c":"之","h":"chi"},{"c":"水","h":"thủy"}],"poem":{"han":"滄浪清濁隨時用／屈子不隨寧葬魚","hv":"Thương Lang thanh trọc tùy thời dụng / Khuất tử bất tùy ninh táng ngư","vi":"Nước Thương Lang trong đục tùy thời mà dùng; Khuất tử không theo, thà chôn thân trong bụng cá."},"example":"清濁併せ呑む滄浪の水のような柔軟さを学びたい。","example_reading":"せいだくあわせのむそうろうのみずのようなじゅうなんさをまなびたい。","example_meaning":"Tôi muốn học sự mềm dẻo như nước Thương Lang dung hợp cả trong lẫn đục.","examples":[{"example":"清濁併せ呑む滄浪の水のような柔軟さを学びたい。","example_reading":"せいだくあわせのむそうろうのみずのようなじゅうなんさをまなびたい。","example_meaning":"Tôi muốn học sự mềm dẻo như nước Thương Lang dung hợp cả trong lẫn đục."},{"example":"時勢に応じて動くのは、滄浪の水の教えだ。","example_reading":"じせいにおうじてうごくのは、そうろうのみずのおしえだ。","example_meaning":"Hành động theo thời thế là bài học của nước Thương Lang."}],"level":"p3"},
{"word":"曲高和寡","reading":"きょっこうわか","meaning":"khúc cao ít người họa theo; tác phẩm, tư tưởng cao siêu ít người hiểu.","hanviet":"khúc cao họa quả","note":"📜 Lịch sử: Tống Ngọc - Đối Sở vương vấn: Sở Tương vương hỏi sao dân ít khen Tống Ngọc. Ông kể có người hát ở đất Dĩnh: hát khúc «Hạ lý Ba nhân» thì mấy nghìn người họa theo, hát khúc «Dương xuân Bạch tuyết» thì chỉ vài chục người, đến điệu cao hơn nữa chỉ còn vài người. 💡 Thú vị: «Dương xuân Bạch tuyết» thành từ chỉ nghệ thuật cao nhã, còn «Hạ lý Ba nhân» chỉ nghệ thuật đại chúng.","chars":[{"c":"曲","h":"khúc"},{"c":"高","h":"cao"},{"c":"和","h":"họa"},{"c":"寡","h":"quả"}],"poem":{"han":"巴人下里千人和／白雪陽春數子聽","hv":"Ba nhân hạ lý thiên nhân họa / Bạch tuyết dương xuân sổ tử thính","vi":"Khúc Ba nhân hạ lý nghìn người họa; Bạch tuyết dương xuân vài người nghe."},"example":"高度な芸術は曲高和寡で、理解者が少ない。","example_reading":"こうどなげいじゅつはきょっこうわかで、りかいしゃがすくない。","example_meaning":"Nghệ thuật cao siêu thì khúc cao họa ít, ít người hiểu.","examples":[{"example":"高度な芸術は曲高和寡で、理解者が少ない。","example_reading":"こうどなげいじゅつはきょっこうわかで、りかいしゃがすくない。","example_meaning":"Nghệ thuật cao siêu thì khúc cao họa ít, ít người hiểu."},{"example":"彼の音楽は曲高和寡だが、熱心なファンがいる。","example_reading":"かれのおんがくはきょっこうわかだが、ねっしんなファンがいる。","example_meaning":"Âm nhạc của anh ấy ít người hiểu nhưng có người hâm mộ nhiệt thành."}],"level":"p3"},
{"word":"青出於藍","reading":"せいしゅつおらん","meaning":"xanh từ cây chàm mà đậm hơn chàm; học trò giỏi hơn thầy.","hanviet":"thanh xuất ư lam","note":"📜 Lịch sử: Tuân Tử - Khuyến học: «Thanh thủ chi ư lam nhi thanh ư lam; băng thủy vi chi nhi hàn ư thủy» (青取之於藍而青於藍；冰水為之而寒於水): màu xanh lấy từ cây chàm mà xanh hơn chàm, băng do nước tạo thành mà lạnh hơn nước. 💡 Thú vị: Tiếng Nhật còn có cách nói 出藍の誉れ (しゅつらんのほまれ) khen học trò vượt thầy, cũng từ đây.","chars":[{"c":"青","h":"thanh"},{"c":"出","h":"xuất"},{"c":"於","h":"ư"},{"c":"藍","h":"lam"}],"poem":{"han":"青取於藍青勝藍／冰由水結冷於水","hv":"Thanh thủ ư lam thanh thắng lam / Băng do thủy kết lãnh ư thủy","vi":"Xanh lấy từ chàm lại hơn chàm; băng do nước kết lại lạnh hơn nước."},"example":"弟子が師匠を超える、青出於藍の例だ。","example_reading":"でしがししょうをこえる、せいしゅつおらんのれいだ。","example_meaning":"Đây là ví dụ học trò vượt thầy.","examples":[{"example":"弟子が師匠を超える、青出於藍の例だ。","example_reading":"でしがししょうをこえる、せいしゅつおらんのれいだ。","example_meaning":"Đây là ví dụ học trò vượt thầy."},{"example":"青は藍より出でて藍より青しというように、彼は師を超えた。","example_reading":"あおはあいよりいでてあいよりあおしというように、かれはしをこえた。","example_meaning":"Như câu xanh từ chàm mà xanh hơn chàm, anh đã vượt qua thầy."}],"level":"p3"},
{"word":"蓬生麻中","reading":"ほうせいまちゅう","meaning":"cỏ bồng mọc giữa đám gai dầu; môi trường tốt thì người cũng tốt lên theo.","hanviet":"bồng sinh ma trung","note":"📜 Lịch sử: Tuân Tử - Khuyến học: «Bồng sinh ma trung, bất phù nhi trực; bạch sa tại niết, dữ chi câu hắc» (蓬生麻中，不扶而直；白沙在涅，與之俱黑): cỏ bồng mọc giữa đám gai dầu không cần nâng cũng thẳng; cát trắng ở trong bùn đen thì cùng đen. 💡 Thú vị: Tiếng Việt có câu «gần mực thì đen, gần đèn thì sáng» cùng ý.","chars":[{"c":"蓬","h":"bồng"},{"c":"生","h":"sinh"},{"c":"麻","h":"ma"},{"c":"中","h":"trung"}],"poem":{"han":"蓬生麻中不扶直／白沙在涅染成黑","hv":"Bồng sinh ma trung bất phù trực / Bạch sa tại niết nhiễm thành hắc","vi":"Cỏ bồng mọc trong gai, chẳng cần nâng cũng thẳng; cát trắng trong bùn, nhuộm thành đen."},"example":"良い環境に身を置けば蓬生麻中で成長できる。","example_reading":"よいかんきょうにみをおけばほうせいまちゅうでせいちょうできる。","example_meaning":"Đặt mình vào môi trường tốt thì tự nhiên trưởng thành.","examples":[{"example":"良い環境に身を置けば蓬生麻中で成長できる。","example_reading":"よいかんきょうにみをおけばほうせいまちゅうでせいちょうできる。","example_meaning":"Đặt mình vào môi trường tốt thì tự nhiên trưởng thành."},{"example":"蓬生麻中というように、友達選びは大切だ。","example_reading":"ほうせいまちゅうというように、ともだちえらびはたいせつだ。","example_meaning":"Như câu gần đèn thì sáng, chọn bạn rất quan trọng."}],"level":"p3"},
{"word":"掩耳盗鈴","reading":"えんじとうれい","meaning":"bịt tai trộm chuông; tự lừa dối mình, cho rằng người khác cũng không biết.","hanviet":"yểm nhĩ đạo linh","note":"📜 Lịch sử: Lã thị Xuân Thu - Tự tri: nhà họ Phạm bị diệt, có người muốn trộm chiếc chuông của họ, nhưng chuông quá lớn khó vác. Anh ta định đập vỡ ra thì chuông kêu vang, sợ người nghe thấy nên bịt tai mình lại mà đập. 💡 Thú vị: Tiếng Việt có câu «bịt tai trộm chuông» cùng ý.","chars":[{"c":"掩","h":"yểm"},{"c":"耳","h":"nhĩ"},{"c":"盗","h":"đạo"},{"c":"鈴","h":"linh"}],"poem":{"han":"鐘大難負椎碎響／自掩雙耳以為安","hv":"Chung đại nan phụ chuy toái hưởng / Tự yểm song nhĩ dĩ vi an","vi":"Chuông lớn khó vác, búa đập kêu vang; tự bịt hai tai, tưởng là yên."},"example":"問題を隠すのは掩耳盗鈴にすぎない。","example_reading":"もんだいをかくすのはえんじとうれいにすぎない。","example_meaning":"Giấu vấn đề chỉ là bịt tai trộm chuông.","examples":[{"example":"問題を隠すのは掩耳盗鈴にすぎない。","example_reading":"もんだいをかくすのはえんじとうれいにすぎない。","example_meaning":"Giấu vấn đề chỉ là bịt tai trộm chuông."},{"example":"不正を隠したつもりが掩耳盗鈴だった。","example_reading":"ふせいをかくしたつもりがえんじとうれいだった。","example_meaning":"Tưởng đã che giấu gian lận nhưng hóa ra là bịt tai trộm chuông."}],"level":"p3"},
{"word":"一字千金","reading":"いちじせんきん","meaning":"một chữ đáng nghìn vàng; văn chương xuất sắc, rất có giá trị.","hanviet":"nhất tự thiên kim","note":"📜 Lịch sử: Sử ký - Lã Bất Vi liệt truyện: Lã Bất Vi cho môn khách soạn «Lã thị Xuân Thu», xong thì treo ở cửa thành Hàm Dương, treo thưởng nghìn lượng vàng cho ai thêm bớt được dù chỉ một chữ; không ai dám. 💡 Thú vị: Có lẽ nhiều người không dám sửa vì sợ quyền thế của Lã Bất Vi hơn là vì văn chương hoàn hảo.","chars":[{"c":"一","h":"nhất"},{"c":"字","h":"tự"},{"c":"千","h":"thiên"},{"c":"金","h":"kim"}],"poem":{"han":"呂覽懸金咸陽市／增損一字予千金","hv":"Lã lãm huyền kim Hàm Dương thị / Tăng tổn nhất tự dữ thiên kim","vi":"Lã lãm treo vàng ở chợ Hàm Dương; thêm bớt một chữ thưởng nghìn vàng."},"example":"彼の文章は一字千金の重みがある。","example_reading":"かれのぶんしょうはいちじせんきんのおもみがある。","example_meaning":"Văn của anh ấy có sức nặng một chữ nghìn vàng.","examples":[{"example":"彼の文章は一字千金の重みがある。","example_reading":"かれのぶんしょうはいちじせんきんのおもみがある。","example_meaning":"Văn của anh ấy có sức nặng một chữ nghìn vàng."},{"example":"一字千金、校正は丁寧に行おう。","example_reading":"いちじせんきん、こうせいはていねいにおこなおう。","example_meaning":"Một chữ nghìn vàng, hãy hiệu đính cẩn thận."}],"level":"p3"},
{"word":"奇貨可居","reading":"きかおくべし","meaning":"hàng lạ nên giữ; thấy cơ hội hiếm có thì nên nắm lấy, đầu tư dài hạn.","hanviet":"kỳ hóa khả cư","note":"📜 Lịch sử: Sử ký - Lã Bất Vi liệt truyện: thương nhân Lã Bất Vi ở Hàm Đan gặp công tử Dị Nhân (Tử Sở) của nước Tần đang làm con tin ở Triệu, nói «kỳ hóa khả cư» (奇貨可居, hàng lạ nên giữ lại), bèn bỏ vốn lớn giúp ông về nước. Về sau Dị Nhân lên ngôi, Lã Bất Vi làm tướng quốc. 💡 Thú vị: Trong tiếng Nhật, cách nói 奇貨として hay dùng để chỉ việc coi điều gì đó là cơ hội để lợi dụng, đôi khi mang ý trục lợi.","chars":[{"c":"奇","h":"kỳ"},{"c":"貨","h":"hóa"},{"c":"可","h":"khả"},{"c":"居","h":"cư"}],"poem":{"han":"邯鄲質子逢商賈／奇貨可居志在謀","hv":"Hàm Đan chất tử phùng thương cổ / Kỳ hóa khả cư chí tại mưu","vi":"Hàm Đan con tin gặp thương nhân; hàng lạ nên giữ, chí ở mưu lớn."},"example":"彼はその新技術を奇貨として、事業を広げた。","example_reading":"かれはそのしんぎじゅつをきかとして、じぎょうをひろげた。","example_meaning":"Anh ta coi công nghệ mới là cơ hội hiếm có và mở rộng kinh doanh.","examples":[{"example":"彼はその新技術を奇貨として、事業を広げた。","example_reading":"かれはそのしんぎじゅつをきかとして、じぎょうをひろげた。","example_meaning":"Anh ta coi công nghệ mới là cơ hội hiếm có và mở rộng kinh doanh."},{"example":"奇貨居くべしと、すぐに投資を決めた。","example_reading":"きかおくべしと、すぐにとうしをきめた。","example_meaning":"Cho rằng hàng hiếm nên giữ, tôi quyết định đầu tư ngay."}],"level":"p3"},
{"word":"採菊東籬","reading":"さいぎくとうり","meaning":"hái cúc bên rào đông; cuộc sống ẩn dật, thanh nhàn.","hanviet":"thái cúc đông ly","note":"📜 Lịch sử: Đào Uyên Minh - Ẩm tửu (bài 5): «Thái cúc đông ly hạ, du nhiên kiến Nam sơn» (採菊東籬下，悠然見南山): hái cúc dưới rào đông, thong thả thấy núi Nam. 💡 Thú vị: Đào Uyên Minh từ quan vì không muốn «vì năm đấu gạo mà khom lưng» (五斗米折腰), một câu nói nổi tiếng khác gắn với ông.","chars":[{"c":"採","h":"thái"},{"c":"菊","h":"cúc"},{"c":"東","h":"đông"},{"c":"籬","h":"ly"}],"poem":{"han":"籬下採菊心自適／悠然南嶺入詩篇","hv":"Ly hạ thái cúc tâm tự thích / Du nhiên Nam lĩnh nhập thi thiên","vi":"Dưới rào hái cúc, lòng tự thích; thong thả núi Nam vào thơ."},"example":"定年後は採菊東籬の暮らしを送りたい。","example_reading":"ていねんごはさいぎくとうりのくらしをおくりたい。","example_meaning":"Sau khi nghỉ hưu tôi muốn sống đời ẩn dật hái cúc.","examples":[{"example":"定年後は採菊東籬の暮らしを送りたい。","example_reading":"ていねんごはさいぎくとうりのくらしをおくりたい。","example_meaning":"Sau khi nghỉ hưu tôi muốn sống đời ẩn dật hái cúc."},{"example":"彼は採菊東籬の心境で田舎に隠棲した。","example_reading":"かれはさいぎくとうりのしんきょうでいなかにいんせいした。","example_meaning":"Ông ẩn cư ở quê với tâm cảnh hái cúc bên rào đông."}],"level":"p3"},
{"word":"積土成山","reading":"せきどせいざん","meaning":"tích đất thành núi; việc nhỏ tích lũy sẽ thành lớn.","hanviet":"tích thổ thành sơn","note":"📜 Lịch sử: Tuân Tử - Khuyến học: «Tích thổ thành sơn, phong vũ hưng yên; tích thủy thành uyên, giao long sinh yên» (積土成山，風雨興焉；積水成淵，蛟龍生焉): tích đất thành núi thì mưa gió nổi lên, tích nước thành vực thì giao long sinh ra. 💡 Thú vị: Tiếng Nhật có câu tục ngữ tương đương 塵も積もれば山となる.","chars":[{"c":"積","h":"tích"},{"c":"土","h":"thổ"},{"c":"成","h":"thành"},{"c":"山","h":"sơn"}],"poem":{"han":"積土成山風雨起／積水成淵蛟龍生","hv":"Tích thổ thành sơn phong vũ khởi / Tích thủy thành uyên giao long sinh","vi":"Tích đất thành núi, mưa gió nổi; tích nước thành vực, giao long sinh."},"example":"毎日の積み重ねが積土成山となる。","example_reading":"まいにちのつみかさねがせきどせいざんとなる。","example_meaning":"Tích lũy mỗi ngày sẽ thành núi.","examples":[{"example":"毎日の積み重ねが積土成山となる。","example_reading":"まいにちのつみかさねがせきどせいざんとなる。","example_meaning":"Tích lũy mỗi ngày sẽ thành núi."},{"example":"積土成山、小さな努力を軽く見てはいけない。","example_reading":"せきどせいざん、ちいさなどりょくをかるくみてはいけない。","example_meaning":"Tích đất thành núi, đừng xem nhẹ nỗ lực nhỏ."}],"level":"p3"},
{"word":"羊質虎皮","reading":"ようしつこひ","meaning":"bản chất là dê mà khoác da hổ; bên ngoài oai phong, bên trong yếu hèn.","hanviet":"dương chất hổ bì","note":"📜 Lịch sử: Dương Hùng - Pháp ngôn: «Dương chất nhi hổ bì, kiến thảo nhi thuyết, kiến sài nhi chiến, vong kỳ bì chi hổ dã» (羊質而虎皮，見草而說，見豺而戰，忘其皮之虎也): dê khoác da hổ, thấy cỏ thì mừng, thấy chó sói thì run, quên mất mình đang khoác da hổ. 💡 Thú vị: Gần với «cáo mượn oai hùm» (狐仮虎威) nhưng khác ở chỗ con dê này tự khoác vẻ ngoài chứ không mượn oai ai.","chars":[{"c":"羊","h":"dương"},{"c":"質","h":"chất"},{"c":"虎","h":"hổ"},{"c":"皮","h":"bì"}],"poem":{"han":"羊披虎皮裝威猛／遇豺股栗露真形","hv":"Dương phi hổ bì trang uy mãnh / Ngộ sài cổ lật lộ chân hình","vi":"Dê khoác da hổ giả oai mãnh; gặp sói đùi run, lộ nguyên hình."},"example":"肩書きだけ立派な彼は羊質虎皮だ。","example_reading":"かたがきだけりっぱなかれはようしつこひだ。","example_meaning":"Anh ta chỉ có chức danh lớn mà thực chất yếu kém.","examples":[{"example":"肩書きだけ立派な彼は羊質虎皮だ。","example_reading":"かたがきだけりっぱなかれはようしつこひだ。","example_meaning":"Anh ta chỉ có chức danh lớn mà thực chất yếu kém."},{"example":"羊質虎皮では、いざという時に役に立たない。","example_reading":"ようしつこひでは、いざというときにやくにたたない。","example_meaning":"Chỉ có vẻ ngoài thì lúc cần chẳng được việc."}],"level":"p3"}
],
"grammar": []
};
